import fs from 'fs';
import os from 'os';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const projectRoot = path.resolve(__dirname, '..');

export const EMBEDDED_CONTENT = {"content/protocols/01-water-purification.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"흙탕물을 깨끗한 마실 물로 바꾸는 법 (숯과 모래로 만드는 자연 정수기)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[필수 생존]\",\n  \"summary\": \"야생에서 더러운 흙탕물을 그냥 마시면 심한 배탈과 설사가 나서 탈수로 쓰러집니다. 나뭇가지 삼발이에 고깔을 달고 숯, 모래, 자갈을 차례로 쌓으면 흙탕물이 투명하게 걸러집니다. 여기에 모닥불로 큰 거품이 콸콸 솟구치도록 3분 동안 펄펄 끓여주면 배 아프게 만드는 눈에 안 보이는 나쁜 벌레(세균)까지 완전히 사라져 안심하고 마실 수 있습니다.\",\n  \"timeRequired\": \"25분 (물 거르기 15분 + 불에 끓이기 10분)\",\n  \"successRate\": \"99.9% (차례대로 쌓아 거른 뒤 3분 이상 끓일 때)\",\n  \"difficulty\": \"쉬움 (주변 자연물로 누구나 제작 가능)\",\n  \"outputPerHour\": \"1시간에 깨끗한 물 1.5 ~ 2리터 생산\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"모닥불에서 꺼낸 까만 참나무 숯 (콩알 크기 두 줌)\",\n      \"desc\": \"스펀지 구멍처럼 물속의 나쁜 냄새와 더러운 찌꺼기를 쏙 빨아들여 줍니다. 쌀알보다 크고 콩알만 한 크기(5~8mm)로 부수어 준비합니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"냇물에 깨끗이 헹군 고운 강모래 (두 줌)\",\n      \"desc\": \"눈에 잘 안 보이는 고운 흙먼지를 촘촘하게 걸러냅니다. 흙탕물이 섞여 있지 않은 깨끗한 모래를 골라 씁니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"손톱 크기의 작은 둥근 자갈 (한 줌)\",\n      \"desc\": \"나뭇잎이나 굵은 찌꺼기를 1차로 막아주고, 위에서 물을 콸콸 부어도 아래 모래가 파이지 않게 지켜주는 완충 돌입니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"자작나무 껍질 고깔 또는 대나무 통 1개\",\n      \"desc\": \"길이 30~40cm 정도로 아래가 좁아지는 원통이나 고깔 모양 껍질입니다. 재료들을 차곡차곡 담아 물방울을 한곳으로 모아줍니다.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"손가락 굵기의 나뭇가지 3개 (길이 50cm)\",\n      \"desc\": \"나뭇가지 3개를 묶어 땅에 세우는 튼튼한 삼발이 거치대입니다. 고깔 아래에 물받이 그릇을 놓을 수 있게 받쳐줍니다.\"\n    },\n    {\n      \"id\": \"mat-06\",\n      \"name\": \"배출구를 막을 깨끗한 물이끼 또는 헝겊 조각\",\n      \"desc\": \"고깔 맨 아래 구멍을 막아 숯과 모래가 아래로 쏟아지지 않게 지켜주는 솜마개 역할을 합니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 나뭇가지 3개로 삼발이를 세우고 고깔 달기 (아래 구멍은 이끼로 막기)\",\n      \"description\": \"손가락 굵기의 곧은 나뭇가지 세 개를 모아 윗부분을 칡덩굴이나 끈으로 단단히 묶고, 다리를 벌려 흔들리지 않는 삼발이를 땅에 세웁니다. 자작나무 껍질을 고깔 모양으로 말거나 속을 뚫은 대나무 통을 삼발이 가운데에 똑바로 묶어 고정합니다. 물이 똑똑 떨어질 맨 아래 좁은 구멍에는 물에 씻은 깨끗한 물이끼나 헝겊을 손가락으로 꾹 눌러 채웁니다. 이 마개가 없으면 위에 넣은 숯가루와 모래가 와르르 쏟아져 내립니다.\",\n      \"actionNote\": \"> 마개 꿀팁: 마개를 너무 헐겁게 막으면 숯가루가 다 빠져나와 까만 물이 됩니다. 손가락으로 밀었을 때 쑥 빠지지 않게 단단히 막으세요.\",\n      \"svgFileName\": \"pr01-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PURIFICATION STEP 1: 프레임 거치 및 하단 마개\",\n        \"나뭇가지 3개 삼발이 거치대\",\n        \"고깔 모양 자작나무 껍질 여과관\",\n        \"바닥 구멍을 꽉 막은 물이끼 마개\",\n        \"[1단계 핵심] 흔들리지 않는 삼발이 & 튼튼한 바닥 마개\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 숯을 콩알 크기로 부숴 맨 아래에 8cm 두께로 채우기\",\n      \"description\": \"모닥불에서 완전히 타서 까맣게 식은 숯을 골라 평평한 돌 위에 놓고 다른 돌로 톡톡 두드려 콩알 크기로 부숩니다. 믹서기처럼 너무 곱게 가루를 내면 물이 틈새로 지나가지 못해 꽉 막혀버립니다. 부순 숯을 고깔 안쪽 이끼 마개 위에 붓고, 나뭇가지 끝으로 살살 눌러 손가락 4마디 높이(약 8cm)로 채웁니다. 숯에 뚫린 수많은 작은 구멍들이 물속 나쁜 냄새와 찌꺼기를 쏙쏙 빨아들입니다.\",\n      \"actionNote\": \"> 크기 요령: 쌀알보다 크고 콩알만 한 알갱이만 쓰세요. 밀가루처럼 고운 숯가루는 물길을 막아버리니 골라내어 버립니다.\",\n      \"svgFileName\": \"pr01-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PURIFICATION STEP 2: 숯 흡착층 형성\",\n        \"콩알 크기로 부순 까만 숯 알갱이\",\n        \"나쁜 냄새와 독소를 빨아들이는 숯 구멍\",\n        \"손가락 네 마디 높이 (8cm) 채우기\",\n        \"[2단계 핵심] 콩알 크기 숯을 8cm 채우고 살살 다지기\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 씻은 고운 모래를 숯 위에 6cm 두께로 평평하게 덮기\",\n      \"description\": \"냇가에서 퍼온 고운 모래를 물에 두세 번 헹구어 흙탕물 찌꺼기를 깨끗하게 씻어냅니다. 씻은 모래를 숯 위에 살포시 부어 손가락 세 마디 높이(약 6cm)로 쌓습니다. 손바닥이나 납작한 돌로 표면을 톡톡 두드려 반듯하게 펴줍니다. 모래층은 아래에 있는 숯가루가 물에 둥둥 떠오르지 않게 꾹 눌러주고, 물속에 떠다니는 미세한 흙먼지를 촘촘하게 걸러냅니다.\",\n      \"actionNote\": \"> 평평하게 펴기: 모래가 한쪽으로 기울어지면 물이 얇은 쪽으로만 쏠려 정수가 제대로 안 됩니다. 반드시 모래 윗면을 평평하게 다듬으세요.\",\n      \"svgFileName\": \"pr01-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PURIFICATION STEP 3: 미세 모래층 적층\",\n        \"물에 깨끗이 헹군 고운 강모래\",\n        \"미세한 흙먼지 찌꺼기 촘촘히 차단\",\n        \"손가락 세 마디 높이 (6cm) 채우기\",\n        \"[3단계 핵심] 숯 위에 모래를 6cm 평평하게 깔기\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 작은 자갈을 4cm 얹고 흙탕물 붓기 (첫 1~2컵은 꼭 버리기!)\",\n      \"description\": \"모래 위에 손톱만 한 작은 자갈을 손가락 두 마디 높이(약 4cm)로 얹고, 맨 위에는 넓은 나뭇잎 한 장을 살포시 덮습니다. 이제 더러운 흙탕물을 위에서 천천히 붓습니다. 자갈과 나뭇잎 덕분에 물을 부어도 모래가 파이지 않고 골고루 스며듭니다. 잠시 후 맨 아래에서 물방울이 똑... 똑... 떨어집니다. 이때 맨 처음 나오는 물 1~2컵은 필터 속 숯가루가 씻겨 나오는 까만 청소 물이니 절대 마시지 말고 과감히 버리세요! 맑은 물이 똑똑 떨어지기 시작할 때 깨끗한 받침 그릇을 대어 물을 받습니다.\",\n      \"actionNote\": \"> 첫물 버리기 수칙: 첫 1~2컵은 정수기 안을 청소하는 물입니다. 아깝다고 마시지 말고 유리알처럼 맑은 물이 나올 때까지 꼭 버리세요.\",\n      \"svgFileName\": \"pr01-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PURIFICATION STEP 4: 자갈층 및 초기 세척\",\n        \"수압을 분산하는 손톱 크기 자갈층 (4cm)\",\n        \"숯가루 청소 물 (첫 1~2컵 버리기)\",\n        \"1초에 한 방울씩 떨어지는 맑은 물방울\",\n        \"[4단계 핵심] 자갈로 모래를 지키고 첫 1~2컵 버리기\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"5단계: 걸러낸 맑은 물을 불에 올려 3분 이상 펄펄 끓이기\",\n      \"description\": \"정수기를 통과해 눈으로 보기에 유리알처럼 투명해진 물을 돌 그릇이나 대나무 통에 담아 모닥불 위에 올립니다. 물 가운데에서 주먹만 한 큰 거품이 보글보글 솟구치며 펄펄 끓기 시작하면, 시계를 보며 최소 3분 이상(산속 높은 곳에서는 5분 이상) 계속 끓입니다. 정수기로 걸러도 현미경으로나 보이는 눈에 안 보이는 나쁜 벌레와 세균은 남아있습니다. 이렇게 불로 펄펄 끓여야 세균이 100% 죽어서 아이들도 안심하고 꿀꺽꿀꺽 마실 수 있는 진짜 생존 식수가 됩니다.\",\n      \"actionNote\": \"> 절대 금지: 맑아 보인다고 그냥 마시면 큰일 납니다! 흙먼지를 걸러낸 뒤 펄펄 끓여야 배탈 나지 않는 안전한 물이 됩니다.\",\n      \"svgFileName\": \"pr01-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PURIFICATION STEP 5: 100℃ 비등 멸균\",\n        \"주먹만 한 큰 거품이 솟구치는 펄펄 끓는 물\",\n        \"최소 3분 이상 가열 유지 (산속은 5분)\",\n        \"눈에 안 보이는 나쁜 세균 99.9% 완전 박멸\",\n        \"[5단계 핵심] 투명한 물도 반드시 3분 이상 펄펄 끓이기\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"치명적 실수: 맑게 걸러졌다고 끓이지 않고 그냥 꿀꺽 마시는 것\",\n    \"description\": \"숯과 모래는 눈에 보이는 흙먼지와 나쁜 냄새만 걸러줄 뿐입니다. 배를 쥐어뜯게 아프게 만드는 현미경 크기의 나쁜 세균과 기생충은 그대로 물속에 살아남아 있습니다. 물이 아무리 차갑고 맑아 보여도 끓이지 않고 마시면 몇 시간 뒤에 심한 복통과 피설사로 탈수에 빠져 목숨을 잃을 수 있습니다.\",\n    \"consequence\": \"결과: 심한 배탈과 설사병에 걸려 탈수로 야생에서 쓰러짐\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"야생에서 흙탕물 그냥 마시면 배탈 나서 사흘 안에 쓰러집니다! 자연물로 정수기 만드는 법!\",\n    \"body\": \"나뭇가지 삼발이에 고깔을 달고, 바닥을 이끼로 막으세요. 그 위에 콩알 크기 숯 8cm, 고운 모래 6cm, 작은 자갈 4cm를 차곡차곡 쌓고 흙탕물을 부으면 됩니다! 첫 2컵은 숯가루 청소 물이니 버리고 투명한 물만 받으세요. 가장 중요한 비밀! 맑다고 그냥 마시면 세균 때문에 큰일 납니다. 반드시 불에 올려 큰 거품이 나도록 3분 이상 펄펄 끓여야 진짜 안전한 물이 됩니다!\",\n    \"outro\": \"인터넷이 끊겨도 볼 수 있는 오프라인 생존 도면은 프로필 링크에서 확인하세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"3중 여과 숯·모래 원시 정수기 완성 형태\",\n    \"description\": \"나뭇가지 삼각대에 매단 원통 용기 내부에 숯, 고운 모래, 자갈, 섬유 필터가 5중으로 압축 적층되어 상단의 흙탕물이 하단 배출구에서 맑고 투명한 식수로 정수 낙하하는 완성 구조입니다.\"\n  },\n  \"createdAt\": \"2026-10-09T16:00:00.000Z\",\n  \"updatedAt\": \"2026-10-15T14:24:23+09:00\",\n  \"contentHash\": \"cf7d15c276ffaa84\"\n}","content/protocols/02-friction-fire.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"나뭇가지 마찰로 불 피우는 법 (활비비 불피우기)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[중요도: 필수 생존]\",\n  \"summary\": \"라이터나 성냥이 없을 때 주변의 마른 나뭇가지와 끈을 이용해 불을 피우는 방법입니다. 활 모양의 나무로 가운데 막대를 빠르게 회전시켜 뜨거운 까만 불씨 가루를 만들고, 마른 풀 뭉치에 옮겨 불꽃을 피워냅니다.\",\n  \"timeRequired\": \"20분\",\n  \"successRate\": \"85% (바싹 마른 나무 사용 시)\",\n  \"difficulty\": \"보통 (연습 필요)\",\n  \"outputPerHour\": \"20분당 불씨 1개 완성\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"활대와 질긴 천연 끈\",\n      \"desc\": \"길이 60~70cm 정도의 살짝 휘어진 튼튼한 나뭇가지와, 칡덩굴이나 나무껍질을 꼬아 만든 질긴 끈입니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"가운데 회전 막대 (비비는 나무)\",\n      \"desc\": \"엄지손가락 굵기(약 2cm), 길이 25cm 정도의 곧고 바싹 마른 나뭇가지입니다. 아랫부분을 연필심처럼 뾰족하게 깎아 씁니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"바닥 받침 나무와 마른 풀 뭉치\",\n      \"desc\": \"손바닥만 한 평평한 마른 나무판과, 불씨를 옮겨 붙일 새둥지 모양의 바싹 마른 풀·억새 솜털 뭉치입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"바닥 받침 나무에 불씨 가루가 모일 V자 홈 파기\",\n      \"description\": \"바닥 받침 나무에 회전 막대가 들어갈 작은 오목한 구멍을 먼저 낸 뒤, 나무 가장자리에서 그 구멍 한가운데까지 피자 조각 모양(약 45도 각도)으로 V자 홈을 파냅니다. 홈 바로 아래에는 불씨 가루를 받아낼 마른 나뭇잎을 한 장 깔아둡니다.\",\n      \"actionNote\": \"> 핵심 팁: 나무가 갈리면서 나오는 뜨거운 까만 가루가 이 V자 홈을 타고 한곳에 모여야 불씨가 됩니다. 홈 끝이 구멍 한가운데에 정확히 닿도록 파주세요.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"불씨 받침 나뭇잎\",\n        \"45° V자 홈 (막대 중심까지 파기)\",\n        \"두께 2cm 가운데 회전 막대\",\n        \"판 두께: 1.5~2cm\",\n        \"바닥 받침 나무\",\n        \"V자 홈 끝점 (구멍 한가운데와 일치)\",\n        \"핵심 준비 포인트:\",\n        \"V자 홈 끝이 막대 중심에 딱 닿아야 함\",\n        \"까만 불씨 가루가 모이는 자리\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"위에서 체중으로 누르며 활대를 앞뒤로 빠르게 당기기\",\n      \"description\": \"왼발로 바닥 받침 나무를 움직이지 않게 밟고, 손잡이 나무(또는 돌)로 회전 막대 윗부분을 수직으로 누릅니다. 활대 끈에 회전 막대를 한 바퀴 감은 뒤, 톱질하듯 활대를 앞뒤로 길게 움직여 회전시킵니다. 하얀 연기가 자욱하게 나기 시작하면 마지막 5초 동안 온 힘을 다해 빠르게 왕복합니다.\",\n      \"actionNote\": \"> 핵심 원리: 연기가 조금 난다고 바로 멈추면 안 됩니다. 하얀 연기가 뿜어져 나온 뒤에도 10~15번 더 힘껏 당겨야 가루에 열이 충분히 쌓여 스스로 타는 불씨가 됩니다.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"손잡이 누름판\",\n        \"위에서 체중 실어 누르기 (12~15kg)\",\n        \"활대 (길이 65cm 휘어진 나뭇가지)\",\n        \"활대 끝에서 끝까지 길게 당기고 밀기\",\n        \"빠르게 양방향 회전\",\n        \"바닥 받침 나무\",\n        \"하얀 연기가 피어오름\",\n        \"불씨 만드는 핵심:\",\n        \"마찰 열기: 400°C 이상\",\n        \"누르는 힘: 약하게 → 세게\",\n        \"활대 전체 길이를 끝까지 사용\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"마른 풀 뭉치에 불씨를 옮기고 살살 불어 불붙이기\",\n      \"description\": \"V자 홈 아래 나뭇잎에 모인 까만 가루 덩어리에서 혼자 연기가 모락모락 피어오르면, 새둥지처럼 만든 마른 풀 뭉치 한가운데에 조심스럽게 쏟아 넣습니다. 풀 뭉치를 살짝 감싸 쥐고 45도 위로 든 채, 불씨를 향해 길고 부드럽게 입김을 불어넣으면 불꽃이 확 피어오릅니다.\",\n      \"actionNote\": \"> 주의할 점: 풀 뭉치를 눈높이보다 살짝 위로 들면 연기가 눈에 들어가지 않고, 따뜻한 공기가 위로 올라가면서 불이 훨씬 잘 붙습니다.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"달궈진 불씨 덩어리 (450°C)\",\n        \"길고 부드럽게 입김 불기\",\n        \"불꽃이 확 피어오름\",\n        \"45도 기울여 들기\",\n        \"입김 불어 불붙이는 온도 변화\",\n        \"시간 (초)\",\n        \"온도 (°C)\",\n        \"600°C 불꽃이 타오르는 온도\",\n        \"400°C 불씨가 유지되는 온도\",\n        \"30초 기다린 뒤 옮기기 (0초)\",\n        \"불꽃 점화 (15~20초)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 막 모인 불씨 가루에 급하게 세찬 입김 불기\",\n    \"description\": \"활대질을 멈추자마자 마음이 급해 나뭇잎 위의 까만 가루에 입김을 세게 확 불어버리면, 아직 단단하게 뭉치지 못한 불씨 가루가 바람에 다 날아가 버려 열기가 순식간에 꺼집니다.\",\n    \"consequence\": \"결과: 불씨 가루에서 연기가 나면 건드리지 말고 30초 동안 스스로 단단히 뭉쳐질 때까지 기다린 뒤에 옮기세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"보우 드릴 마찰열 발화 및 불씨 착화 완성 형태\",\n    \"description\": \"화판의 45도 V홈에 마찰열로 생성된 검은 숯가루 잉걸불(400°C)이 붉게 타오르며 연기를 피워 올리고, 이를 마른 껍질 부싯깃 둥지로 안전하게 옮겨 불꽃을 피워 올린 실전 발화 완성 상태입니다.\"\n  },\n  \"createdAt\": \"2026-10-09T16:05:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"07c74b6366705dce\"\n}","content/protocols/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"불 없이 체온을 지키는 낙엽 움막 만드는 법\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[중요도: 필수 생존]\",\n  \"summary\": \"찬 바람과 비가 치는 야생에서 맨몸으로 밤을 보내면 3시간 안에 체온이 떨어져 위험해집니다. 불을 피울 수 없을 때 주변의 나뭇가지와 마른 낙엽을 두껍게 쌓아, 두꺼운 침낭처럼 내 몸의 온기를 가두어 따뜻하게 자는 방법입니다.\",\n  \"timeRequired\": \"90~120분\",\n  \"successRate\": \"92% (낙엽 두께 60cm 이상 쌓았을 때)\",\n  \"difficulty\": \"보통 (도구 없이 가능)\",\n  \"outputPerHour\": \"1인용 보온 움막 1개 완성\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"중심 기둥 나무 (긴 통나무 1개)\",\n      \"desc\": \"어른 키의 두 배 정도 길이(3.0~3.5m), 팔뚝 굵기(10~15cm)의 튼튼하고 곧은 마른 나무 1개입니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Y자 기둥 나무 2개와 양옆에 기댈 나뭇가지들\",\n      \"desc\": \"끝이 Y자로 갈라진 가슴 높이(1.5m) 나무 2개와, 양옆 벽을 만들 팔 길이(1~1.5m)의 나뭇가지 40~50개입니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"바싹 마른 낙엽과 마른 풀 (최대한 많이)\",\n      \"desc\": \"물기가 전혀 없는 마른 낙엽, 솔잎, 마른 풀을 큰 자루 수십 개 분량으로 넉넉히 모읍니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Y자 기둥 두 개를 세우고 중심 기둥 나무 올리기\",\n      \"description\": \"끝이 Y자로 갈라진 나무 두 개를 마주 보게 세워 윗부분을 맞물리거나 칡덩굴로 묶어 삼각 다리를 만듭니다. 그 위에 긴 중심 기둥 나무의 한쪽 끝을 올리고(입구 높이 80cm~1m), 반대쪽 끝은 바람이 불어오는 쪽 바닥에 닿게 내려놓습니다.\",\n      \"actionNote\": \"> 핵심 팁: 움막 안이 넓으면 내 몸의 열기로 공기를 데울 수 없어 춥습니다. 누웠을 때 어깨 양옆으로 주먹 하나(10cm) 정도만 남을 만큼 좁게 만드세요.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"움막 크기 핵심 규칙:\",\n        \"몸이 겨우 들어갈 크기 (어깨 옆 주먹 1개 여유)\",\n        \"바람 불어오는 쪽 (바닥에 고정)\",\n        \"중심 기둥 나무: 길이 3.0~3.5m\",\n        \"Y자 기둥 2개 맞물려 묶기\",\n        \"내부 공간: 몸 둘레 + 10cm (주먹 1개 여유)\",\n        \"입구 높이: 0.8~1.0m\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"양옆에 나뭇가지를 촘촘히 기대고 바닥에 낙엽 두껍게 깔기\",\n      \"description\": \"중심 기둥 나무 양옆에 나뭇가지들을 45~60도 각도로 빈틈없이 기대어 세웁니다. 그다음 움막 안쪽 바닥에 바싹 마른 낙엽을 무릎 높이(40cm 이상)만큼 수북하게 깔아줍니다. 내가 누워서 눌렸을 때도 바닥 낙엽 두께가 최소 한 뼘(20cm) 이상 유지되어야 합니다.\",\n      \"actionNote\": \"> 핵심 원리: 차가운 맨땅은 찬 공기에 비해 체온을 수십 배나 빠르게 빼앗아 갑니다. 지붕보다 바닥에 까는 낙엽 이불이 두꺼워야 얼지 않습니다.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"바닥 냉기 차단 핵심:\",\n        \"마른 낙엽을 두껍게 깔아 눌린 뒤에도 20cm 유지\",\n        \"중심 기둥 나무 (단면)\",\n        \"양옆 나뭇가지: 45°~60° 각도로 촘촘히 세우기\",\n        \"낙엽 이불: 40cm → 눌린 뒤 20cm\",\n        \"땅에서 올라오는 찬 기운 완벽 차단\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"지붕에 낙엽을 팔 길이만큼 쌓고 무거운 가지로 덮기\",\n      \"description\": \"나뭇가지 벽 위에 잔가지를 얹은 뒤, 마른 낙엽을 아래에서 위쪽으로 내 팔 전체 길이(60~90cm) 두께가 될 때까지 산더미처럼 쌓아 올립니다. 마지막으로 바람에 낙엽이 날아가지 않도록 무거운 나뭇가지들을 위에 덮어 눌러주고, 안에 들어간 뒤 입구도 낙엽 뭉치로 막아 찬 바람을 차단합니다.\",\n      \"actionNote\": \"> 주의할 점: 젖은 낙엽을 섞어 쓰면 물기가 마르면서 오히려 체온을 뺏어갑니다. 반드시 바싹 마른 낙엽만 골라 쓰세요.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"지붕 낙엽 쌓기 & 입구 막기:\",\n        \"지붕에 낙엽을 팔 길이(60~90cm)로 쌓고 입구 막기\",\n        \"마른 낙엽 벽: 60~90cm 두께\",\n        \"바람에 안 날리게 무거운 가지 덮기\",\n        \"빗물이 타고 흐르는 경사면\",\n        \"따뜻한 공기가 갇힌 내부 & 낙엽 마개\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 편하게 앉으려고 움막을 크게 짓거나 젖은 낙엽 쓰기\",\n    \"description\": \"텐트처럼 안에서 앉아 있으려고 천장을 높이고 공간을 넓게 만들면, 사람 몸에서 나오는 열기만으로는 그 넓은 공간의 찬 공기를 절대 데울 수 없습니다. 또한 젖은 낙엽을 깔면 밤새 냉기가 올라와 체온이 급격히 떨어집니다.\",\n    \"consequence\": \"결과: 반드시 몸이 겨우 들어갈 만큼 좁게 만들고, 바싹 마른 낙엽만 두껍게 쌓아야 밤새 체온을 지킬 수 있습니다.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"A-프레임 데브리 헛 (낙엽 단열 은신처) 완성 외관\",\n    \"description\": \"2.5m 굵은 용마루와 45도 갈비뼈 가지 프레임 위에 1미터 두께의 마른 낙엽층을 압축 적층하고 겉가지 격자를 덮어 강풍과 비바람을 막는 무난방 체온 보존 은신처 완성 외관입니다.\"\n  },\n  \"createdAt\": \"2026-10-09T16:08:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"042045342785ab42\"\n}","content/protocols/04-stone-axe-making.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"깬 돌과 칡덩굴로 나무 베는 돌도끼 만드는 법\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[중요도: 핵심 도구]\",\n  \"summary\": \"맨손으로는 움막 기둥이나 땔감으로 쓸 굵은 나뭇가지를 자를 수 없습니다. 강가에서 주운 단단한 돌 두 개를 45도 각도로 부딪쳐 날카로운 돌날을 떼어내고, 나무 자루 틈에 송진과 젖은 칡덩굴로 단단히 묶어 튼튼한 돌도끼를 만드는 방법입니다.\",\n  \"timeRequired\": \"60분\",\n  \"successRate\": \"90% (45도 각도로 모서리를 칠 경우)\",\n  \"difficulty\": \"보통 (초보자 가능)\",\n  \"outputPerHour\": \"돌도끼 1자루 완성\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"단단한 강돌 1개와 둥근 망치돌 1개\",\n      \"desc\": \"깨졌을 때 유리처럼 날카로운 모서리가 생기는 단단한 강돌(어른 주먹 2개 크기) 1개와, 손에 쥐고 내리칠 둥글고 묵직한 망치돌 1개입니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"팔뚝 길이의 단단한 나무 자루 (참나무·물푸레나무)\",\n      \"desc\": \"세게 내리쳐도 부러지지 않는 단단한 생나무 가지(길이 40~50cm, 손목보다 조금 가는 지름 3.5~4cm 굵기) 1개입니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"물에 적신 칡덩굴 속껍질과 소나무 송진\",\n      \"desc\": \"마르면서 스스로 오그라들어 꽉 조여지는 젖은 칡덩굴 속껍질(길이 3m 이상)과, 나무 상처에서 굳은 소나무 송진 한 주먹입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"돌과 돌을 45도 각도로 부딪쳐 날카로운 돌날 떼어내기\",\n      \"description\": \"바닥에 큰 강돌을 흔들리지 않게 받쳐 놓고, 손에 쥔 둥근 망치돌로 강돌의 가장자리 모서리를 45도 각도로 비스듬히 세게 내리칩니다. 돌 한가운데를 수직으로 치면 돌만 깨지지만, 모서리를 45도로 치면 손바닥만 하고 끝이 면도날처럼 날카로운 돌날 조각이 한 번에 떨어져 나옵니다.\",\n      \"actionNote\": \"> 핵심 팁: 돌의 평평한 한가운데를 치지 마세요. 모서리 끝에서 손가락 한 마디(1~2cm) 안쪽을 노려 한 번에 강하게 쳐야 길고 날카로운 돌날이 떨어집니다.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"① 둥근 망치돌 (내리치는 돌)\",\n        \"② 모서리 45° 비스듬히 치기\",\n        \"날카로운 돌날 (두께 1~2cm)\",\n        \"④ 쪼개져 나온 도끼날 돌조각\",\n        \"③ 바닥에 받친 큰 강돌 (너비 15~20cm)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"나무 자루 윗부분을 쪼개어 돌날 끼우고 송진 채우기\",\n      \"description\": \"단단한 나무 자루의 윗부분을 날카로운 돌로 손가락 길이(5~7cm)만큼 세로로 쪼개어 틈을 만듭니다. 자루가 밑으로 더 쪼개지지 않도록 갈라진 끝부분 아래쪽을 끈으로 먼저 묶어 둔 뒤, 틈 사이에 돌날의 두꺼운 뒷부분을 깊숙이 끼워 넣습니다. 그다음 불에 녹인 소나무 송진에 고운 숯가루를 섞어 빈틈에 가득 채워 넣습니다.\",\n      \"actionNote\": \"> 핵심 원리: 송진만 녹여서 바르면 식은 뒤에 유리처럼 쉽게 깨집니다. 불 피우고 남은 까만 숯가루를 3분의 1 정도 섞어 주면 충격에도 깨지지 않는 튼튼한 천연 접착제가 됩니다.\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"① 위에서 아래로 돌날 끼우기\",\n        \"나무 자르는 앞날\",\n        \"② 쪼갠 나무 자루 틈 (5~7cm)\",\n        \"③ 녹인 송진 + 숯가루 채우기\",\n        \"④ 더 안 갈라지게 아래쪽 먼저 묶기\",\n        \"생나무 자루 굵기: 지름 3.5~4cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"젖은 칡덩굴 줄기로 X자 모양으로 단단히 감아 말리기\",\n      \"description\": \"물에 충분히 적셔 부드러워진 칡덩굴 속껍질로 돌날과 나무 자루를 대각선 X자 모양으로 번갈아 가며 10바퀴 이상 힘껏 당겨 감습니다. 이어서 자루 아래쪽도 가로로 칭칭 감아 매듭을 묶은 뒤 그늘에서 말립니다. 젖은 칡덩굴은 마르면서 길이가 30% 가까이 줄어들기 때문에, 마른 뒤에는 쇠줄로 조인 것처럼 돌날을 꽉 잡아줍니다.\",\n      \"actionNote\": \"> 주의할 점: 다 마른 뒤 손으로 돌날을 세게 흔들어 보아 조금도 흔들리지 않아야 안전합니다. 빨리 말리겠다고 불에 가까이 대면 칡덩굴이 타서 끊어지니 꼭 바람 불고 그늘진 곳에서 말리세요.\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"① 젖은 칡 속껍질 X자로 감기\",\n        \"② 날카로운 도끼 앞날\",\n        \"③ 자루 아래쪽 가로로 칭칭 감기\",\n        \"④ 마르면서 30% 줄어들며 꽉 조임\",\n        \"완성 상태: 세게 내리쳐도 돌날이 빠지지 않는 일체형 돌도끼\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 평평한 돌 한가운데를 치거나 마른 덩굴로 묶기\",\n    \"description\": \"돌의 평평한 한가운데를 90도로 내려치면 날카로운 날이 만들어지지 않고 돌 전체가 쓸모없는 자갈로 부서집니다. 또한 물에 적시지 않은 마른 덩굴이나 거친 겉껍질로 묶으면, 나무를 찍는 순간 줄이 끊어지면서 무거운 돌날이 얼굴이나 눈으로 튀어 크게 다칠 수 있습니다.\",\n    \"consequence\": \"결과: 반드시 강돌 모서리를 45도로 쳐서 날을 만들고, 물에 불린 질긴 속껍질로 X자로 감아 그늘에서 말려야 안전하게 나무를 벨 수 있습니다.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"깬 돌과 칡덩굴 결속 원시 돌도끼 완성 형태\",\n    \"description\": \"단단한 참나무 Y자 자루 홈에 양면 타제된 날카로운 수석 날을 깊숙이 물리고, 질긴 칡덩굴과 송진 접착제로 X자 십자 결속하여 나무를 거침없이 베어 넘기는 실전 석기 돌도끼 완성 형태입니다.\"\n  },\n  \"createdAt\": \"2026-10-09T16:10:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"6ccdf224285e93f4\"\n}","content/protocols/05-natural-cordage.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"나무껍질과 칡덩굴을 꼬아 끊어지지 않는 야생 밧줄 만드는 법\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[필수 생존]\",\n  \"summary\": \"움막 기둥을 묶거나 돌도끼를 고정하고 활비비로 불을 피우려면 튼튼한 끈이 꼭 필요합니다. 줄기를 그냥 묶으면 마르면서 뚝 부러지거나 풀려버리지만, 식물 속껍질 섬유를 발라내어 두 가닥을 서로 반대 방향으로 비틀어 꼬면 어른 몸무게도 거뜬히 버티는 질긴 야생 밧줄을 만들 수 있습니다.\",\n  \"timeRequired\": \"40분\",\n  \"successRate\": \"95% (역방향 꼬기 준수 시)\",\n  \"difficulty\": \"보통 (맨손 작업 가능)\",\n  \"outputPerHour\": \"5m / 40분\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"살아있는 칡덩굴 또는 참피나무·버드나무·쐐기풀 줄기 (팔 길이 10~15줄기)\",\n      \"desc\": \"구부렸을 때 '톡' 부러지지 않고 부드럽게 휘어지며, 손톱으로 겉을 긁었을 때 연두색 물기가 도는 싱싱한 줄기를 골라야 질긴 속껍질을 얻을 수 있습니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"겉껍질을 긁어낼 날카로운 돌조각 1개\",\n      \"desc\": \"줄기 바깥의 거칠고 잘 부서지는 갈색 겉껍질만 살짝 긁어 벗겨낼 때 씁니다. 너무 날카로워 속껍질 섬유까지 끊어지지 않도록 모서리가 적당히 각진 돌을 고릅니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"섬유를 두드릴 평평한 바닥 돌과 주먹만 한 둥근 돌\",\n      \"desc\": \"물에 불린 뻣뻣한 속껍질을 바닥 돌 위에 올려놓고 둥근 돌로 살살 두드려, 머리카락처럼 가늘고 부드러운 실 결로 풀어줄 때 사용합니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"속껍질을 불릴 냇물 또는 고인 물\",\n      \"desc\": \"갓 벗긴 속껍질을 20~30분 동안 담가 두어 뻣뻣한 나무 진액을 빼고, 꼬는 동안 섬유가 꺾이지 않게 촉촉한 상태를 유지하는 데 씁니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 휘어지는 줄기 골라 거친 겉껍질 긁어내고 하얀 속껍질 벗기기\",\n      \"description\": \"먼저 줄기를 반으로 구부려 보아 부러지지 않고 탄력 있게 휘어지는지 확인합니다. 돌 모서리를 줄기에 비스듬히 대고 바깥의 거친 갈색 겉껍질만 살살 긁어내면, 그 아래에서 하얗고 질긴 속껍질 섬유층이 드러납니다. 줄기 아래쪽 끝을 손톱으로 살짝 들춰낸 뒤, 줄기 위쪽을 향해 길게 잡아당기면 딱딱한 가운데 나무 속심에서 리본 모양의 속껍질만 쭉 벗겨져 나옵니다.\",\n      \"actionNote\": \"> 핵심 팁: 바닥에 떨어져 말라비틀어진 줄기는 이미 섬유가 삭아 힘을 주면 먼지처럼 끊어집니다. 반드시 살아있는 줄기나 갓 꺾인 줄기에서 속껍질을 채취하세요.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① 돌 모서리로 거친 겉껍질만 살살 긁어내기\",\n        \"② 잘 부러지는 갈색 겉껍질 (긁어내어 버림)\",\n        \"③ 질기고 하얀 속껍질 섬유층 (밧줄 핵심 재료)\",\n        \"④ 가운데 딱딱한 나무 속심 (빼내고 버림)\",\n        \"⑤ 구부렸을 때 부러지지 않고 휘어지는 살아있는 줄기\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 냇물에 20분 불린 뒤 돌로 두드려 실처럼 부드럽게 풀기\",\n      \"description\": \"벗겨낸 속껍질 리본을 냇물에 20~30분 동안 푹 담가 불립니다. 물기를 머금어 부드러워진 속껍질을 평평한 강돌 위에 펴 놓고, 둥근 돌로 위에서 아래로 톡톡 두드립니다. 거친 나무 결이 부서지면서 머리카락이나 실처럼 가늘고 부드러운 섬유 다발로 풀립니다. 손으로 비벼 보았을 때 뻣뻣한 가시 느낌이 없고, 손가락에 감아 세게 당겨도 끊어지지 않으면 굵기가 똑같은 두 가닥으로 나눕니다.\",\n      \"actionNote\": \"> 핵심 원리: 너무 세게 내려치면 섬유가 끊어집니다. 고기를 다지듯 끊어 치지 말고, 둥근 돌로 살살 짓누르며 밀어주듯 두드려야 긴 섬유가 상하지 않습니다.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① 냇물에 20분 이상 담가 부드럽게 불린 속껍질\",\n        \"② 둥근 돌로 살살 두드려 섬유 결 쪼개기\",\n        \"③ 머리카락처럼 부드럽게 풀어진 섬유 다발\",\n        \"④ 손가락 굵기로 똑같이 나눈 두 가닥\",\n        \"⑤ 바닥에 흔들리지 않게 받친 평평한 강돌\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 바깥으로 비틀고 안쪽으로 넘기는 '역방향 꼬기' 반복하기\",\n      \"description\": \"긴 섬유 다발의 한가운데를 왼손 엄지와 검지로 꽉 쥐고 반으로 접어 위쪽 가닥과 아래쪽 가닥 두 줄을 만듭니다. 오른손으로 위쪽 가닥을 잡고 내 몸 바깥쪽(앞쪽)으로 팽팽하게 비틀어 줍니다. 그 상태 그대로 비튼 위쪽 가닥을 아래쪽 가닥 너머 내 몸 쪽(뒤쪽)으로 교차해 넘기면, 아까 아래에 있던 가닥이 새로 위쪽 가닥이 됩니다. 왼손 엄지를 한 칸 옮겨 방금 교차한 자리를 꽉 눌러 잡은 뒤, 다시 새로 올라온 위쪽 가닥을 '바깥쪽으로 비틀고 ➔ 몸 쪽으로 넘기기'를 계속 반복합니다.\",\n      \"actionNote\": \"> 핵심 원리: 두 가닥을 같은 방향으로만 감으면 손을 놓는 순간 스르륵 다 풀려버립니다. 각 가닥은 바깥으로 비틀고, 두 가닥 전체는 안쪽으로 넘겨야 풀리려는 힘이 서로 맞물려 절대 풀리지 않습니다.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① 위쪽 가닥: 몸 바깥쪽(↑)으로 단단히 비틀기\",\n        \"② 서로 되감기며 톱니처럼 맞물린 밧줄 무늬\",\n        \"③ 왼손 엄지·검지로 꼬인 자리 꽉 눌러 잡기\",\n        \"④ 비튼 위 가닥을 아래 가닥 너머 몸 쪽(↓)으로 넘기기\",\n        \"⑤ 손을 놓아도 절대 풀리지 않는 역방향 잠금 구조\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 짧은 섬유를 10cm씩 겹쳐 꼬아 원하는 길이만큼 끝없이 잇기\",\n      \"description\": \"밧줄을 꼬다 보면 한쪽 가닥이 끝에서 10cm쯤 남아 점점 얇아집니다. 이때 새 섬유 다발의 끝부분을 얇아진 기존 가닥 옆에 10cm 길이로 나란히 겹쳐 대고, 두 줄을 마치 원래 한 가닥이었던 것처럼 함께 쥐고 똑같이 바깥으로 비틀어 몸 쪽으로 넘깁니다. 3~4번만 꼬아 넘기면 새 섬유가 단단히 물려 빠지지 않습니다. 단, 위쪽 가닥과 아래쪽 가닥을 동시에 같은 자리에서 이어 붙이지 말고, 두 이음매 사이가 최소 어른 손 한 뼘(15cm) 이상 어긋나게 배치해야 합니다.\",\n      \"actionNote\": \"> 주의할 점: 두 가닥의 이음매가 같은 위치에 겹치면 그 부분만 볼록하게 두꺼워지고 힘을 받았을 때 그 자리에서 뚝 끊어집니다.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① 끝이 10cm쯤 남아 가늘어진 기존 가닥\",\n        \"② 새 섬유 다발을 10cm 나란히 겹쳐 대기\",\n        \"③ 겹친 두 줄을 한 가닥처럼 함께 비틀어 감기\",\n        \"④ 불룩해지지 않고 매끄럽게 이어진 연결부\",\n        \"⑤ 위·아래 이음매 위치를 한 뼘(15cm) 어긋나게 배치\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"5단계: 끝부분 풀림 방지 매듭 묶고 나무 기둥에 걸어 몸무게로 당겨보기\",\n      \"description\": \"필요한 길이(5m 이상)까지 다 꼬았으면, 끝에서 3cm 지점을 고리 모양으로 한 번 돌려 묶어(기본 홀치기 매듭) 끝이 풀리지 않게 마감합니다. 밧줄 겉면으로 삐져나온 잔털들을 날카로운 돌날로 살짝 긁어 정리해 주면 마찰에 쓸리지 않습니다. 마지막으로 완성된 밧줄을 팔뚝 굵기 이상의 튼튼한 나무 기둥에 감고 내 몸무게(50kg 이상)를 실어 힘껏 당겨봅니다. 이음매가 밀리지 않고 매듭이 더 단단하게 조여지면 실전 사용 준비가 끝난 것입니다.\",\n      \"actionNote\": \"> 실전 확인: 당겼을 때 '투둑' 하고 섬유 끊어지는 소리가 나거나 이음매가 미끄러지면 그 구간 위에 얇은 섬유를 한 번 더 감아 보강하세요.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① 끝부분 3cm를 접어 묶은 풀림 방지 마감 매듭\",\n        \"② 삐져나온 잔털을 돌날로 깔끔하게 정리\",\n        \"③ 나무 기둥에 걸고 몸무게(50kg+)를 실어 당겨보기\",\n        \"④ 완성된 5mm 굵기 야생 밧줄 (5m 길이)\",\n        \"⑤ 움막 기둥 묶기·돌도끼 고정·활비비 줄로 즉시 활용\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 껍질을 벗기지 않은 초록색 생줄기를 그대로 묶어 쓰기\",\n    \"description\": \"급하다고 칡덩굴이나 나뭇가지를 통째로 감아 움막 기둥이나 돌도끼를 묶으면, 당장은 단단해 보여도 반나절만 지나 수분이 마르면 부피가 줄어들면서 헐거워지고 작은 충격에도 과자처럼 바스라져 부러집니다. 반드시 겉껍질과 나무 속심을 버리고 질긴 속껍질 섬유만 발라내어 역방향으로 꼬아서 써야 마른 뒤에도 끊어지지 않습니다.\",\n    \"consequence\": \"결과: 자는 도중 움막 지붕이 무너지거나 나무를 찍던 돌도끼 날이 빠져 큰 부상을 입음\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"산속에서 끈이 하나도 없을 때, 절대 끊어지지 않는 야생 밧줄을 맨손으로 꼬는 법입니다.\",\n    \"body\": \"죽은 가지는 부러져서 못 씁니다. 휘어지는 칡덩굴의 거친 겉껍질을 돌로 긁어내고 하얀 속껍질만 길게 벗기세요. 물에 20분 불려 돌로 살살 두드리면 실처럼 부드러워집니다. 이제 반으로 접어 위 가닥은 몸 바깥쪽으로 비틀고, 아래 가닥 너머 몸 쪽으로 넘기세요. 짧아지면 새 섬유를 10cm 겹쳐 꼬아 끝없이 이을 수 있습니다.\",\n    \"outro\": \"나무에 걸고 몸무게를 실어 당겨도 안 끊어집니다. 움막 짓기와 돌도끼 고정에 바로 써보세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"2가닥 역방향 꼬임 천연 밧줄 완성 코일 다발\",\n    \"description\": \"나무 내피와 칡 줄기 섬유를 시계 방향으로 꼬고 반시계 방향으로 교차 엮어 인장 강도 90kg 이상을 견디는 촘촘하고 매끄러운 2가닥 천연 생존 밧줄 코일 완성 다발입니다.\"\n  },\n  \"createdAt\": \"2026-10-13T13:20:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"03d1706e68d38783\"\n}","content/protocols/06-clay-hearth.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"진흙과 돌을 쌓아 비바람을 막고 열기를 가두는 원시 화덕 만드는 법\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[체온·식량 필수]\",\n  \"summary\": \"야생에서 바닥에 맨 불을 피우면 바람에 불티가 날려 위험하고 열기의 80%가 허공으로 날아가 장작이 세 배 넘게 듭니다. 찰흙과 모래, 마른 풀을 섞어 이긴 진흙 반죽으로 돌을 감싸 돔 형태의 화덕을 쌓으면, 비바람이 몰아쳐도 꺼지지 않고 밥을 짓거나 밤새 은은한 온기를 품는 훌륭한 생존 열원이 됩니다.\",\n  \"timeRequired\": \"3시간\",\n  \"successRate\": \"90% (초벌 건조 준수 시)\",\n  \"difficulty\": \"보통 (흙 반죽과 돌 쌓기)\",\n  \"outputPerHour\": \"1기 완성 (영구 사용 가능)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"점토질 붉은 찰흙 2바가지 (개울가나 흙벽에서 파낸 끈끈한 흙)\",\n      \"desc\": \"손으로 쥐었을 때 차진 찰떡처럼 뭉쳐지고 손가락 사이에 끈적하게 달라붙는 흙을 고릅니다. 화덕 벽체를 하나로 굳혀주는 주원료입니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"굵은 강모래 1바가지 (돌 알갱이가 섞인 마른 흙)\",\n      \"desc\": \"찰흙만 쓰면 마를 때 부피가 줄어들며 산산조각 갈라집니다. 굵은 모래를 섞어주면 단단한 뼈대가 되어 균열을 막아줍니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"손가락 길이로 자른 마른 풀잎 또는 짚 1바가지\",\n      \"desc\": \"진흙 반죽 속에서 섬유질 철근 역할을 하여, 불의 뜨거운 열기에도 벽체가 쪼개지거나 부서지지 않게 질기게 잡아줍니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"물기 없는 단단한 깬 돌 15~20개 (주먹~머리 크기)\",\n      \"desc\": \"물속에 잠겨 있던 강돌은 열을 받으면 폭발하므로, 물가에서 10m 떨어진 마른 언덕의 햇볕에 바짝 마른 돌만 골라 씁니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 찰흙 2, 모래 1, 마른 풀 1을 물과 함께 발로 밟아 차진 반죽 만들기\",\n      \"description\": \"평평한 땅 위에 붉은 찰흙 2바가지, 굵은 모래 1바가지, 손가락 마디 길이로 자른 마른 풀 1바가지를 골고루 붓습니다. 물을 한 번에 많이 붓지 말고 조금씩 끼얹어가며 발뒤꿈치로 꾹꾹 밟아 치댑니다. 흙더미를 반으로 접어 다시 밟기를 10분 이상 반복하여, 주먹만 한 공 모양으로 둥글게 뭉쳐 손바닥 위에 올려놓아도 겉면에 실금이 가지 않고 쫀득하게 찰기가 돌 때까지 반죽합니다.\",\n      \"actionNote\": \"> 핵심 비결: 물이 너무 많으면 반죽이 죽처럼 흘러내려 벽을 쌓을 수 없고, 물이 적으면 푸석해져 부서집니다. 만두피 반죽처럼 약간 뻑뻑하면서 찰진 상태가 가장 좋습니다.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 붉은 찰흙 2바가지\",\n        \"끈끈한 점력의 기본 바탕재\",\n        \"+\",\n        \"② 굵은 모래 1바가지\",\n        \"마를 때 오그라듦 방지\",\n        \"+\",\n        \"③ 잘게 자른 마른 풀잎\",\n        \"뼈대 역할을 하는 보강 섬유\",\n        \"④ 물을 조금씩 부어가며 발로 치대기\",\n        \"한 번에 많이 붓지 말고 뒤집으며 밟기\",\n        \"⑤ 차진 반죽 덩어리 완성\",\n        \"주먹 크기로 둥글게 뭉쳐도\",\n        \"겉면에 실금이 가지 않는 상태\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 마른 땅 위에 주먹 크기 돌을 U자 모양으로 놓아 바닥 기초 다지기\",\n      \"description\": \"바람이 불어오는 반대쪽을 향해 장작 넣는 입구(어른 한 뼘 너비, 약 20cm)를 비워두고, 주먹보다 큰 단단한 마른 돌들을 말발굽(U자) 모양으로 둘러놓습니다. 바닥에는 마른 모래와 잔자갈을 2~3cm 두께로 깔아 차가운 땅바닥 습기와 냉기를 차단합니다. 돌과 돌 사이 틈새마다 1단계에서 만든 진흙 반죽을 주먹으로 꾹꾹 찔러 넣어 빈틈없이 메우고 바닥과 단단히 밀착시킵니다.\",\n      \"actionNote\": \"> 방풍 요령: 입구가 바람을 정면으로 마주 보면 강풍에 불티가 솟구쳐 위험합니다. 반드시 바람이 등 뒤에서 불어오는 방향이나 비스듬한 쪽으로 입구를 내세요.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① 앞쪽 장작 넣는 입구 (한 뼘 너비 20cm)\",\n        \"불길 조절과 공기 공급에 알맞은 입구 폭\",\n        \"② U자형 주먹만 한 마른 돌\",\n        \"기초를 지탱하는 1차 뼈대\",\n        \"③ 틈새를 메운 진흙 반죽\",\n        \"돌 사이 공기 누출 완전 차단\",\n        \"④ 바닥 마른 모래·자갈 단열층\",\n        \"차가운 땅바닥 습기와 냉기 차단\",\n        \"⑤ 바람 불어오는 반대쪽으로 입구 배치\",\n        \"강풍에 불티가 역류하거나 꺼지지 않도록 보호\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 돌과 진흙을 엇갈려 쌓으며 무릎 높이의 돔형 벽체 올리기\",\n      \"description\": \"기초 돌 위에 진흙 반죽을 손바닥 두께(약 5cm)로 두껍게 깔고, 그 위에 다음 돌을 얹는 방식으로 지그재그 엇갈려 올립니다. 위로 올라갈수록 조금씩 안쪽으로 오므려 가며 무릎 높이(약 45cm)까지 둥근 이글루 모양의 돔을 만듭니다. 벽을 다 쌓은 뒤에는 손에 물을 묻혀 안쪽 벽면을 매끄럽게 문질러 다듬습니다. 벽면이 매끄러울수록 연소실 안에서 열기가 맴돌며 높은 온도를 유지합니다.\",\n      \"actionNote\": \"> 붕괴 방지: 진흙만 높이 바르면 아래쪽이 무게를 못 이기고 무너집니다. 반드시 돌을 뼈대로 삼고 그 겉과 속을 진흙 반죽으로 두껍게 감싸듯이 발라야 합니다.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① 엇갈려 쌓은 벽체 단면\",\n        \"돌 틈에 진흙을 채워 무너짐 방지\",\n        \"② 손바닥 두께(약 5cm) 진흙벽\",\n        \"바깥으로 새는 열 손실 완벽 차단\",\n        \"③ 매끄러운 열 반사 곡면\",\n        \"손에 물을 묻혀 반질반질하게 다듬기\",\n        \"④ 열기가 모여 회전하는 둥근 연소실 내부\",\n        \"⑤ 무릎 높이(약 45cm) 외형선\",\n        \"취사 안정성과 축열 용적 최적화\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 화덕 윗부분에 냄비 받침 구멍을 내고 뒤쪽에 굴뚝 구멍 뚫기\",\n      \"description\": \"돔 천장 한가운데에 돌그릇이나 냄비를 얹을 수 있는 둥근 구멍(지름 약 15~20cm)을 남겨 마감합니다. 냄비를 얹었을 때 불길이 막혀 꺼지지 않도록 구멍 둘레에 작은 돌 3개를 삼각형으로 박아 1cm 정도의 통기 틈새를 둡니다. 그리고 화덕 뒤편 상단에는 손목 굵기 나뭇가지로 비스듬히 찔러 넣어 매운 연기가 쏙 빠져나갈 굴뚝 구멍을 뚫어줍니다. 이렇게 하면 아래 입구로 들어온 신선한 공기가 불길을 키우고 위로 연기가 빠져나가는 강한 상승 기류가 형성됩니다.\",\n      \"actionNote\": \"> 공기 순환 원리: 굴뚝이 없으면 연기가 앞쪽 장작 입구로 쏟아져 나와 눈이 맵고 불이 잘 붙지 않습니다. 뒤쪽 굴뚝을 앞 입구보다 높은 위치에 뚫어야 연기가 잘 빨려 나갑니다.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① 앞쪽 하부 공기 흡입구 (산소 유입)\",\n        \"차가운 신선한 공기가 빨려 들어가는 길목\",\n        \"② 윗부분 평평한 조리용 구멍\",\n        \"냄비나 평평한 돌판을 얹는 화구\",\n        \"③ 뒤편 상단 굴뚝 구멍\",\n        \"매운 연기를 뒤로 뽑아내는 배출구\",\n        \"④ 솟구치는 열기 순환선\",\n        \"연소실 안을 회전하며 냄비 바닥을 달굼\",\n        \"⑤ 냄비 받침 통기 틈새 돌기\",\n        \"냄비를 얹어도 불길이 막혀 꺼지지 않는 여유 공간\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"5단계: 작은 잔가지 불씨로 3시간 서서히 말려 벽돌처럼 단단하게 굽기\",\n      \"description\": \"완성된 화덕에 처음부터 큰 장작을 넣고 센 불을 피우면 흙 속의 수분이 급격히 끓어올라 벽이 쩍쩍 갈라집니다. 마른 나뭇잎과 작은 잔가지로 주먹만 한 작은 불씨를 만들어 입구 근처에서 은은하게 지핍니다. 3~4시간 동안 약한 열기를 쐬어주면 외벽에서 하얀 김(수증기)이 모락모락 빠져나가며 축축한 짙은 고동색이 밝은 황토색으로 바뀝니다. 외벽을 손으로 만졌을 때 물기가 묻어나지 않고 따뜻한 열감이 전해지면 단단한 영구 화덕이 완성된 것입니다.\",\n      \"actionNote\": \"> 건조 중 보수: 말리는 도중 외벽에 머리카락 같은 미세한 금이 생기면, 남은 묽은 진흙 반죽을 손가락에 묻혀 쓱 문질러 메워주면 감쪽같이 결합됩니다.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① 입구 작은 잔가지 불씨 (약한 열기)\",\n        \"강한 불 대신 은은한 열기로 시작\",\n        \"② 외벽 수증기 증발선\",\n        \"내부 수분이 천천히 기화\",\n        \"③ 색상 변화 관찰\",\n        \"짙은 고동색 → 밝은 황토색\",\n        \"④ 따뜻한 건조 완료 판정\",\n        \"축축함 없이 외벽 전체가 훈훈\",\n        \"⑤ 미세 실금 덧바름 보수\",\n        \"남은 진흙 반죽으로 틈새 메우기\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 물속에 젖어 있던 강돌을 화덕 불길 닿는 자리에 쌓기\",\n    \"description\": \"물가에서 방금 주워 온 강돌이나 자갈은 겉이 말라 보여도 돌 내부의 미세한 틈새에 물 분자가 갇혀 있습니다. 이 돌에 300도 이상의 뜨거운 불길이 직접 닿으면 갇힌 수분이 급격히 팽창하여 수류탄처럼 굉음을 내며 산산조각 폭발합니다. 날카로운 돌 파편이 눈과 얼굴로 날아와 실명하거나 큰 부상을 입을 수 있습니다. 반드시 물가에서 10m 떨어진 마른 언덕의 돌만 쓰고, 돌 표면을 진흙 반죽으로 5cm 이상 두껍게 덮어 불길이 돌에 직접 닿지 않도록 감싸야 합니다.\",\n    \"consequence\": \"결과: 돌 내부 수증기 폭발로 날카로운 파편이 비산하여 실명 및 중증 열상 유발\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"야생에서 바닥에 불을 피우면 열기의 80%가 날아갑니다. 비바람에도 꺼지지 않는 화덕 만드는 법입니다.\",\n    \"body\": \"찰흙 2, 모래 1, 마른 풀 1을 물과 함께 10분간 발로 밟아 차진 반죽을 만드세요. 주먹만 한 마른 돌을 U자로 놓고 앞쪽에 장작 입구를 둡니다. 돌과 진흙을 엇갈려 무릎 높이까지 돔으로 쌓고, 윗부분엔 냄비 구멍, 뒤편엔 연기가 빠질 굴뚝을 뚫으세요. 작은 불로 3시간 서서히 말려 수분을 빼면 벽돌처럼 단단해집니다. 절대 젖은 강돌을 불길에 직접 대지 마세요. 수증기 압력으로 돌이 폭발합니다.\",\n    \"outro\": \"비바람이 몰아쳐도 밥을 짓고 밤새 은은한 온기를 지킬 수 있습니다.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"점토 미장 돌 화덕 (원시 화덕 및 조리구) 완성 형태\",\n    \"description\": \"U자형 강돌 기초 위에 볏짚과 황토 반죽을 5cm 두께로 매끄럽게 미장하고, 상단 조리용 내열 상판과 후면 배기 굴뚝을 구비하여 650°C 고열을 가두는 원시 화덕 완성 형태입니다.\"\n  },\n  \"createdAt\": \"2026-10-14T10:15:00.000Z\",\n  \"contentHash\": \"92064fb90844ce2f\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\"\n}","content/protocols/08-figure-four-deadfall.json":"{\n  \"protocolId\": \"PR-08\",\n  \"category\": \"FOOD\",\n  \"title\": \"나뭇가지 3개와 바위로 짐승 잡는 법 (숫자 4 모양 돌 덫)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[단백질·식량 확보]\",\n  \"summary\": \"야생에서 짐승을 맨손으로 쫓아다니면 금방 지쳐 쓰러집니다. 손가락 굵기 나뭇가지 3개에 홈을 파서 '숫자 4' 모양으로 끼워 맞추면, 끈 하나 없이도 15kg 무거운 바위를 스스로 떠받칩니다. 안쪽 막대에 먹이를 꽂아두면, 쥐나 산짐승이 먹이를 톡 건드리는 순간 막대기가 툭 빠지면서 0.1초 만에 바위가 쾅 떨어지는 가장 확실한 생존 덫입니다.\",\n  \"timeRequired\": \"30분 (나뭇가지 깎기 20분 + 균형 맞추기 10분)\",\n  \"successRate\": \"95% (건드리면 바로 떨어지게 세팅 시)\",\n  \"difficulty\": \"보통 (각진 홈을 파내는 요령 필요)\",\n  \"outputPerHour\": \"시간당 2기 제작 설치 가능\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"손가락 굵기의 단단한 마른 나뭇가지 3개\",\n      \"desc\": \"무거운 바위를 받쳐도 부러지지 않는 단단한 참나무 가지를 준비합니다. [1번 세움대(20cm)], [2번 빗장대(25cm)], [3번 먹이대(30cm)]로 사용합니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"넓적하고 무거운 바위 1개 (10~15kg)\",\n      \"desc\": \"바닥에 닿는 면이 넓고 평평해야 짐승이 피하지 못하고 단번에 덮칩니다. 짐승 몸무게보다 훨씬 무거워야 합니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"홈을 파낼 날카로운 돌날 1개\",\n      \"desc\": \"나뭇가지를 깎아 서로 딱 물리는 홈과 걸림턱을 만들기 위한 날카로운 돌칼입니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"유인용 먹이 (산딸기, 벌레, 씨앗)\",\n      \"desc\": \"먹이대 안쪽 뾰족한 끝에 단단히 꽂아두어 짐승이 입을 대고 살짝 당기도록 유도하는 먹이입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 나뭇가지 3개 다듬기 (세움대·빗장대·먹이대에 홈 깎기)\",\n      \"description\": \"손가락 굵기의 곧은 나뭇가지 3개를 깎아 준비합니다. 첫째, 땅에 똑바로 세울 [1번 세움대(20cm)]는 윗머리를 일자 드라이버처럼 납작하게 깎고, 가운데에 네모난 홈을 팝니다. 둘째, 바위를 비스듬히 받칠 [2번 빗장대(25cm)]는 위쪽에 1번 세움대 머리를 물어줄 V자 홈을 파고, 아래 끝은 비스듬히 깎습니다. 셋째, 먹이를 꽂을 [3번 먹이대(30cm)]는 1번 세움대 홈에 걸칠 턱을 깎고, 2번 빗장대 아래 끝을 걸어줄 홈을 판 뒤, 맨 안쪽 끝을 연필처럼 뾰족하게 깎습니다.\",\n      \"actionNote\": \"> 깎을 때 꿀팁: 홈을 둥글게 파면 미끄러져서 무너집니다. 칼로 반듯하게 직각으로 파내야 세 막대가 서로를 꽉 물어줍니다.\",\n      \"svgFileName\": \"pr08-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // 3 STICKS ANATOMY & NOTCHES\",\n        \"POST (1번 세움대 - 윗머리 납작 쐐기 & 네모 홈)\",\n        \"STRUT (2번 빗장대 - 윗머리 V홈 & 아랫머리 쐐기)\",\n        \"BAIT STICK (3번 먹이대 - 걸림턱 & 홈 & 뾰족한 끝)\",\n        \"[핵심] 서로 딱 물리는 직각 홈과 걸림턱 깎기\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 1번 세움대 윗머리에 2번 빗장대 걸치기\",\n      \"description\": \"단단하고 평평한 땅바닥에 1번 세움대를 똑바로 세웁니다. 2번 빗장대의 윗홈을 1번 세움대의 납작한 윗머리에 비스듬히(약 45도 각도) 딱 걸칩니다. 손으로 위에서 살짝 눌렀을 때, 빗장대가 옆으로 미끄러지지 않고 1번 세움대 머리를 꽉 물어주는지 확인합니다.\",\n      \"actionNote\": \"> 각도 확인: 빗장대가 45도 각도로 기울어져 있어야 바위의 무거운 무게를 가장 안정적으로 받아냅니다.\",\n      \"svgFileName\": \"pr08-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // TOP NOTCH INTERLOCK\",\n        \"1번 세움대 납작 윗머리\",\n        \"2번 빗장대 V자 홈 결합\",\n        \"45도 각도로 딱 맞물림\",\n        \"[핵심] 미끄러지지 않고 딱 물리는 상단 결합\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 3번 먹이대를 끼워 '숫자 4' 모양으로 혼자 서게 만들기\",\n      \"description\": \"3번 먹이대를 땅바닥과 나란하게 가로로 들고, 먹이대의 앞쪽 턱을 1번 세움대의 가운데 홈에 겁니다. 그리고 2번 빗장대의 아래 끝을 먹이대 뒷편 홈에 살짝 걸쳐줍니다. 이제 잡고 있던 손을 천천히 놓아보세요. 세 막대가 서로를 단단히 밀어내며 끈 하나 없이 완벽한 '숫자 4' 모양으로 혼자 우뚝 섭니다!\",\n      \"actionNote\": \"> 균형 확인: 손을 놓았을 때 흔들림 없이 스스로 서 있어야 합니다. 기우뚱거리면 1번 세움대 밑바닥을 평평하게 다시 다듬으세요.\",\n      \"svgFileName\": \"pr08-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // NUMBER 4 LOCK ASSEMBLY\",\n        \"세움대-먹이대 맞물림 턱\",\n        \"빗장대-먹이대 뒷홈 걸림\",\n        \"끈 없이 혼자 서는 숫자 4\",\n        \"[핵심] 세 막대가 서로 밀어내며 스스로 자립\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 바위 기대어 얹기 & 먹이 달고 0.1초 반응 확인하기\",\n      \"description\": \"먹이대 안쪽 뾰족한 끝에 곤충이나 산딸기를 단단히 꽂아 넣습니다. 10~15kg 무거운 바위를 한 손으로 조심스럽게 들어 올려 2번 빗장대 윗부분에 45도로 살포시 기대어 놓습니다. 바위 무게가 빗장대를 지그시 누르면서 덫이 더욱 팽팽해집니다. 가느다란 나뭇가지로 먹이를 '톡' 건드렸을 때, 뼈대가 0.1초 만에 와르르 빠지면서 바위가 쾅 떨어지는지 확인한 뒤 설치를 마칩니다.\",\n      \"actionNote\": \"> 안전 제일: 바위를 얹을 때 절대 바위 밑으로 손가락을 넣지 마세요. 만에 하나 무너져도 다치지 않게 바위 옆을 잡아야 합니다.\",\n      \"svgFileName\": \"pr08-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // ROCK LOAD & 0.1S COLLAPSE\",\n        \"15kg 평평한 바위 안착\",\n        \"먹이대 끝 미끼 장착\",\n        \"톡 건드리면 0.1초 만에 바위 낙하\",\n        \"[핵심] 스치기만 해도 와르르 무너지는 민감도\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"치명적 실수: 결합 홈을 너무 깊게 파서 뻑뻑하게 만들거나, 너무 가벼운 돌을 얹는 것\",\n    \"description\": \"홈을 너무 깊게 파서 꽉 끼어버리면 짐승이 먹이를 세게 흔들어도 덫이 안 무너져 먹이만 털립니다. 반대로 돌이 너무 가벼우면 짐승이 다치기만 하고 도망쳐 버립니다.\",\n    \"consequence\": \"결과: 고기는 못 얻고 힘만 빠지며, 숲속 짐승들이 덫을 눈치채고 피해 다님\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"야생에서 짐승 잡으려고 뛰어다니면 굶어 죽습니다! 나뭇가지 3개로 만드는 0.1초 돌 덫!\",\n    \"body\": \"나뭇가지 세 개에 홈을 파서 '숫자 4' 모양으로 끼우면 끈 하나 없이 15kg 바위를 스스로 받칩니다. 안쪽 막대에 먹이를 꽂아두면, 쥐나 산짐승이 먹이를 톡 건드리는 순간 균형이 깨지면서 0.1초 만에 바위가 떨어집니다. 핵심 비밀! 홈은 걸릴 듯 말 듯 얕아야 스치자마자 바로 떨어집니다!\",\n    \"outro\": \"전기 없이 오프라인에서도 작동하는 생존 도면은 프로필 링크에서 확인하세요.\"\n  },\n  \"outcome\": {\n    \"imageFileName\": \"pr08-outcome.png\",\n    \"svgFileName\": \"pr08-outcome.svg\",\n    \"title\": \"완성된 숫자 4자 돌 덫 전체 모습\",\n    \"description\": \"손가락 굵기 막대기 3개가 서로 맞물려 15kg 무거운 바위를 비스듬히 떠받치고 있으며, 바위 안쪽의 먹이를 건드리는 즉시 0.1초 만에 뼈대가 풀려 바위가 덮치는 모습입니다.\"\n  },\n  \"createdAt\": \"2026-10-14T15:35:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"46ed0acd1b57e2da\"\n}","content/protocols/09-pit-charcoal-kiln.json":"{\n  \"protocolId\": \"PR-09\",\n  \"category\": \"FIRE\",\n  \"title\": \"흙구덩이 속에서 공기를 막아 나무를 단단한 숯으로 굽는 법 (원시 숯가마 제작법)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[무연 고열 연료 & 정수 필터 숯 확보]\",\n  \"summary\": \"모닥불에 나무를 그냥 태우면 산소와 완전히 반응해 하얀 재만 남고 아무것도 남지 않습니다. 땅에 50cm 원뿔형 구덩이를 파고 참나무를 빽빽하게 세운 뒤, 흙과 잔디로 덮어 공기 유입을 95% 차단하면 나무가 활활 타지 않고 고열에 쪄지면서 단단한 숯이 됩니다. 연기 없이 따뜻하게 밤을 지새우거나, 정수용 활성탄 필터로 쓰거나, 불씨를 며칠씩 보관할 수 있는 야생의 검은 보석입니다.\",\n  \"timeRequired\": \"5시간 (구덩이 파기 및 장작 세팅 1시간 + 탄화 3시간 + 밀폐 냉각 1시간)\",\n  \"successRate\": \"90% (공기 차단과 냉각 시간 엄수 시)\",\n  \"difficulty\": \"보통 (연기 색상 판별 요령 필요)\",\n  \"outputPerHour\": \"1회 가동 시 단단한 고급 숯 3~5kg 수확\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"손목 굵기의 마른 참나무 토막 15~20개 (길이 30~40cm)\",\n      \"desc\": \"밀도가 높고 단단한 참나무나 활엽수로 준비합니다. 무산소 상태에서 타지 않고 구워지며 단단하고 오래 타는 고급 숯이 됩니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"깊이 50cm, 지름 60cm 원뿔형 흙구덩이\",\n      \"desc\": \"아래로 갈수록 좁아지는 원뿔형으로 파내어 열기를 한곳으로 모으고 공기 순환을 통제하는 지하 가마입니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"구덩이를 덮을 굵은 나뭇가지 틀과 넓은 잎\",\n      \"desc\": \"수직으로 세운 통나무 위에 얹어 흙이 무너지지 않도록 지탱해 주는 격자 뼈대와 흙 유입 방지용 나뭇잎입니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"젖은 진흙과 잔디 뗏장 (두께 10cm)\",\n      \"desc\": \"가마 상부를 완전히 덮어 공기(산소) 유입을 95% 차단하고 가마 내부를 400도 이상 고열로 쪄내는 단열 덮개입니다.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"초벌 건조용 마른 잔가지와 불씨\",\n      \"desc\": \"구덩이 바닥 흙의 습기를 바짝 말리고 가마 하단에 불길을 번지게 할 점화재입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 50cm 원뿔형 흙구덩이 파기 및 바닥 초벌 불씨 조성\",\n      \"description\": \"비가 고이지 않는 단단하고 건조한 흙땅을 골라 윗지름 60cm, 깊이 50cm 크기로 땅을 팝니다. 아래로 내려갈수록 지름이 30cm 정도로 좁아지는 원뿔(V자) 형태로 파내야 열이 중앙으로 잘 모입니다. 바닥에 마른 잔가지와 낙엽을 넉넉히 깔고 불을 피워 구덩이 벽과 바닥의 습기를 15분 이상 바짝 말리며 빨갛게 이글거리는 숯불 밑천을 만듭니다.\",\n      \"actionNote\": \"> 파기 요령: 구덩이 바닥에 습기가 남아있으면 나무가 쪄지지 않고 썩은 냄새가 나며 불이 꺼집니다. 바닥 흙이 바짝 마를 때까지 초벌 불씨를 충분히 달구세요.\",\n      \"svgFileName\": \"pr09-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PIT EXCAVATION & PRE-DRYING\",\n        \"상부 지름 60cm 원뿔형 흙구덩이\",\n        \"깊이 50cm (바닥 지름 30cm)\",\n        \"바닥 초벌 건조 잔가지 & 숯불 밑천\",\n        \"[핵심] 흙 습기 완전 건조 및 고온 불씨 형성\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 손목 굵기 참나무를 틈새 없이 수직으로 빽빽하게 적재하기\",\n      \"description\": \"바닥의 붉은 불씨 위에 길이 30~40cm, 손목 굵기(5~8cm)의 마른 참나무 토막들을 기둥처럼 똑바로 세워 채웁니다. 나무들 사이에 빈틈이 넓으면 공기가 맴돌아 나무가 숯이 되지 못하고 하얀 재로 다 타버립니다. 통나무 사이사이의 빈틈에는 손가락 굵기의 잔가지를 쐐기처럼 찔러 넣어 틈새를 꽉 메워야 합니다.\",\n      \"actionNote\": \"> 적재 비법: 가마 안은 나무로 꽉 차서 숨 쉴 틈이 거의 없어야 합니다. 밀도가 높을수록 단단하고 묵직한 쇠 소리가 나는 최고급 숯이 됩니다.\",\n      \"svgFileName\": \"pr09-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DENSE VERTICAL TIMBER STACK\",\n        \"손목 굵기(5~8cm) 참나무 수직 적재\",\n        \"빈틈을 쐐기처럼 메운 잔가지\",\n        \"하단 초벌 불씨에서 번지는 열기\",\n        \"[핵심] 빈틈 최소화로 무산소 탄화 밀도 극대화\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 나뭇가지 틀을 얹고 젖은 흙과 잔디 뗏장으로 95% 공기 차단하기\",\n      \"description\": \"수직으로 꽂은 통나무 위에 굵은 나뭇가지들을 우물 정(井) 자 격자로 얹고, 그 위에 넓은 잎이나 풀을 촘촘히 깝니다. 그 위를 젖은 진흙과 잔디 뗏장으로 10cm 두께로 빈틈없이 덮어씌웁니다. 이때 바람이 불어오는 쪽 아래 가장자리에 손가락 굵기의 흡기 구멍 2개를 뚫고, 가마 한가운데에 주먹 크기의 연기 굴뚝 1개를 남겨 산소 공급을 5%만 허용합니다.\",\n      \"actionNote\": \"> 밀폐 점검: 굴뚝 외에 흙 틈새로 연기가 새어 나오는 곳이 있다면 즉시 진흙을 덧발라 틀어막아야 나무가 활활 타지 않습니다.\",\n      \"svgFileName\": \"pr09-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // MULTI-LAYER ANAEROBIC SEAL\",\n        \"격자 가지틀 + 넓은 잎 지지층\",\n        \"10cm 젖은 진흙 & 잔디 뗏장 덮개\",\n        \"하단 흡기 구멍 2개 (손가락 굵기)\",\n        \"중앙 배기 굴뚝 (주먹 크기)\",\n        \"[핵심] 산소 95% 차단 불완전 연소 가마 완성\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 연기 색상 변화 판별 및 완전 밀폐 냉각 후 숯 수확하기\",\n      \"description\": \"처음 1~2시간 동안은 굴뚝에서 수분이 증발하며 짙은 흰색 연기가 뿜어져 나옵니다. 2~3시간이 지나 연기가 맑고 옅은 푸른빛으로 바뀌면 나무 속 수분과 타르가 다 빠져나가고 순수한 숯이 되었다는 신호입니다! 이때 즉시 진흙 반죽으로 굴뚝과 흡기구를 100% 빈틈없이 틀어막고 불을 끕니다. 흙 표면이 차갑게 식을 때까지 최소 6시간 동안 기다린 뒤 덮개를 조심스럽게 열어 은빛 광택의 단단한 숯을 꺼냅니다.\",\n      \"actionNote\": \"> 백드래프트 주의: 아직 가마 속이 뜨거울 때 성급하게 흙을 파헤치면 신선한 공기가 들어가 불길이 폭발하며 숯이 순식간에 재가 됩니다. 반드시 완전히 식은 뒤 여세요.\",\n      \"svgFileName\": \"pr09-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SMOKE PHASE & CHARCOAL HARVEST\",\n        \"1단계: 짙은 백색 연기 (수분 증발)\",\n        \"2단계: 옅은 청색 연기 (탄화 완료)\",\n        \"모든 구멍 진흙 밀폐 후 완전 냉각\",\n        \"쇳소리 나는 고밀도 참나무 숯 수확\",\n        \"[핵심] 푸른 연기 즉시 밀폐 & 잔열 완전 냉각\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"치명적 실수: 열기가 남아있을 때 성급하게 흙 덮개를 열거나, 연기 구멍 밀폐를 깜빡하는 것\",\n    \"description\": \"가마 안이 400도 이상 달궈진 상태에서 흙 덮개를 벗겨내면, 신선한 공기 속 산소가 한꺼번에 밀려들어가며 거대한 화염이 솟구치는 백드래프트가 일어납니다. 또한 푸른 연기가 날 때 구멍을 막지 않고 방치하면 통나무 전체가 하얀 재로 산화되어 버립니다.\",\n    \"consequence\": \"결과: 몇 시간 동안 애써 구운 나무가 순식간에 재로 사라지고 화상을 입을 위험\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"모닥불에 나무 태우면 하얀 재만 남습니다! 땅속에 묻어서 쇠 소리 나는 단단한 숯 굽는 비법!\",\n    \"body\": \"흙구덩이에 참나무를 빽빽하게 세우고 흙과 뗏장으로 덮어 공기를 95% 차단하세요! 처음엔 짙은 흰 연기가 뿜어져 나오다가, 2~3시간 뒤 옅은 푸른 연기로 바뀌면 나무가 순수한 숯으로 변한 겁니다. 이때 진흙으로 모든 구멍을 틀어막고 완전히 식히면, 연기 없이 고열을 내는 최고의 생존 숯이 완성됩니다!\",\n    \"outro\": \"전기 없는 재난 상황에서도 작동하는 원시 생존 도면은 프로필 링크에서 확인하세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr09-outcome.svg\",\n    \"title\": \"완성된 원시 지하 숯가마 단면 및 다공성 숯 제원\",\n    \"description\": \"50cm 원뿔형 흙구덩이 속에서 공기를 95% 차단한 채 고온으로 구워내어, 연기 없는 고열 연료이자 식수 정화 필터로 사용 가능한 단단한 다공성 참나무 숯의 완성 단면입니다.\"\n  },\n  \"createdAt\": \"2026-10-15T05:30:00.000Z\",\n  \"contentHash\": \"06910fe5beeb5301\",\n  \"updatedAt\": \"2026-10-15T14:35:53+09:00\"\n}","content/protocols/locales/01-water-purification.de.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"Wie man schlammiges Wasser in sauberes Trinkwasser verwandelt (Naturfilter aus Kohle und Sand)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[WICHTIGES ÜBERLEBEN]\",\n  \"summary\": \"Wenn du in der Wildnis schmutziges Schlammwasser trinkst, bekommst du schwere Bauchschmerzen und Durchfall, was schnell zu gefährlicher Austrocknung führt. Wenn du drei Äste zu einem Dreibein bindest, einen Rindentrichter aufhängst und zerkleinerte Holzkohle, Sand und Kieselsteine nacheinander hineinfüllst, wird braunes Schlammwasser glasklar. Danach musst du das Wasser über einem Lagerfeuer 3 Minuten lang mit großen, kräftig sprudelnden Blasen kochen lassen, damit alle unsichtbaren fiesen Keime sterben und du es gefahrlos trinken kannst.\",\n  \"timeRequired\": \"25 Min. (15 Min. Filtern + 10 Min. Kochen)\",\n  \"successRate\": \"99.9% (Nach schichtweisem Filtern und 3+ Min. Kochen)\",\n  \"difficulty\": \"Einfach (Mit Naturmaterialien für jeden machbar)\",\n  \"outputPerHour\": \"1.5 bis 2 Liter sauberes Wasser pro Stunde\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Schwarze Holzkohle aus dem Lagerfeuer (Zwei Handvoll, erbsengroß)\",\n      \"desc\": \"Wirkt wie ein Schwamm mit winzigen Löchern, der schlechte Gerüche und Schadstoffe aufsaugt. Zerbrich die Kohle in Stücke, die so groß wie Erbsen sind (5–8 mm).\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Mit Flusswasser sauber gewaschener Sand (Zwei Handvoll)\",\n      \"desc\": \"Hält feine Schmutzkörner fest, die man mit dem Auge kaum sieht. Wasche den Sand vorher gut im Fluss, damit kein Lehm daran klebt.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Kleine runde Kieselsteine in Daumennagelgröße (Eine Handvoll)\",\n      \"desc\": \"Fangen grobe Blätter und Schmutz ab und schützen den Sand darunter davor, beim Eingießen von Wasser weggespült zu werden.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Trichter aus Birkenrinde oder hohles Bambusrohr (1 Stück)\",\n      \"desc\": \"Ein 30–40 cm langer Behälter, der nach unten schmaler wird. Hält alle Schichten zusammen und leitet die Wassertropfen nach unten.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Drei fingerdicke, gerade Äste (50 cm lang)\",\n      \"desc\": \"Werden oben zusammengebunden und als stabiles Dreibein aufgestellt. Hält den Trichter hoch genug, damit eine Schale darunter passt.\"\n    },\n    {\n      \"id\": \"mat-06\",\n      \"name\": \"Sauberes feuchtes Moos oder Stoffrest als Bodenstopfen\",\n      \"desc\": \"Wird fest in das untere Loch gedrückt, damit Kohle und Sand nicht unten herausfallen.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Dreibein aus 3 Ästen aufstellen und Trichter einhängen (Loch mit Moos stopfen)\",\n      \"description\": \"Nimm drei fingerdicke, gerade Äste, binde sie oben mit Schnur oder Pflanzenfasern fest zusammen und stelle sie als stabiles Dreibein auf den Boden. Hänge den Birkenrindentrichter oder das Bambusrohr gerade in die Mitte. Drücke nun sauberes, gewaschenes Moos oder ein Stück Stoff mit dem Finger fest in die schmale untere Öffnung. Ohne diesen Stopfen würden Kohle und Sand sofort unten herauspurzeln.\",\n      \"actionNote\": \"> Stopfen-Tipp: Ist der Stopfen zu locker, rieselt schwarzer Kohlestaub heraus. Drücke ihn fest hinein, damit er nicht wegrutscht.\",\n      \"svgFileName\": \"pr01-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PURIFICATION STEP 1: DREIBEIN & STOPFEN\",\n        \"TRIPOD FRAME (DREIBEIN)\",\n        \"CONE FUNNEL (TRICHTER)\",\n        \"MOSS PLUG (MOOSSTOPFEN)\",\n        \"[SCHRITT 1] STABILES DREIBEIN AUFSTELLEN\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Kohle auf Erbsengröße zerdrücken und 8 cm hoch einfüllen\",\n      \"description\": \"Suche kalte, tiefschwarze Holzkohle aus der Feuerstelle heraus. Lege sie auf einen flachen Stein und klopfe sie mit einem anderen Stein vorsichtig in erbsengroße Stücke. Zermahle sie nicht zu Mehl, sonst kann das Wasser nicht hindurchfließen. Schütte die Kohle auf den Moosstopfen und drücke sie mit einem Stöckchen leicht an, bis sie vier Finger breit (etwa 8 cm) hoch ist. Ihre winzigen Poren saugen Gerüche und Giftstoffe auf.\",\n      \"actionNote\": \"> Körnungs-Regel: Die Stücke müssen größer als Reiskörner sein. Feinen Staub solltest du wegpusten oder aussieben, damit nichts verstopft.\",\n      \"svgFileName\": \"pr01-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PURIFICATION STEP 2: KOHLEFILTERBETT\",\n        \"CHARCOAL CORE (AKTIVKOHLE)\",\n        \"PORE ABSORPTION (ADSORPTION)\",\n        \"THICKNESS: 8CM (DICKE)\",\n        \"[SCHRITT 2] 8CM KOHLEKOMPONENTE EINFÜLLEN\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: 6 cm sauberen Flusssand über die Kohle füllen und glattstreichen\",\n      \"description\": \"Spüle sauberen Flusssand zwei- bis dreimal im Wasser aus, um lehmigen Schmutz zu entfernen. Gieße den gewaschenen Sand vorsichtig auf die Kohleschicht, bis er drei Finger breit (etwa 6 cm) hoch liegt. Klopfe die Oberfläche mit der Handfläche oder einem flachen Stein glatt und waagerecht. Der Sand hält die Kohle am Boden fest und fängt winzige Schmutzteilchen ab.\",\n      \"actionNote\": \"> Eben halten: Wenn der Sand schief liegt, läuft das Wasser nur an der dünnen Seite ab, ohne gefiltert zu werden. Mache die Schicht ganz eben.\",\n      \"svgFileName\": \"pr01-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PURIFICATION STEP 3: SANDSCHICHT\",\n        \"RIVER SAND (FLUSSSAND)\",\n        \"PARTICLE FILTER (FILTER)\",\n        \"THICKNESS: 6CM (DICKE)\",\n        \"[SCHRITT 3] KOHLE SICHERN & SCHMUTZ FANGEN\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: 4 cm Kieselsteine auflegen und Schlammwasser gießen (Erste 1-2 Tassen wegschütten!)\",\n      \"description\": \"Lege kleine Kieselsteine zwei Finger breit (etwa 4 cm) auf den Sand und lege ein breites Laubblatt darauf. Gieße nun vorsichtig das braune Schlammwasser über das Blatt. Die Kiesel und das Blatt verhindern, dass der Wasserstrahl ein Loch in den Sand spült. Bald tropft es unten heraus: Tropf... Tropf... Ganz wichtig: Die ersten 1 bis 2 Tassen spülen den schwarzen Kohlestaub aus dem Filter. Trinke das auf keinen Fall! Schütte es weg und sammle das Wasser erst, wenn es glasklar tropft.\",\n      \"actionNote\": \"> Erstes Wasser wegschütten: Die ersten Becher reinigen das Innere des Filters. Schütte sie weg, bis das Wasser glasklar ist.\",\n      \"svgFileName\": \"pr01-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PURIFICATION STEP 4: KIESEL & SPÜLEN\",\n        \"PEBBLE LAYER (KIESEL)\",\n        \"FLUSH FIRST CUPS (SPÜLEN)\",\n        \"CLEAR DRIP (KLARTROPF)\",\n        \"[SCHRITT 4] SAND SCHÜTZEN & ERSTWASSER WEG\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Schritt 5: Das klare Wasser über dem Feuer mindestens 3 Minuten sprudelnd kochen\",\n      \"description\": \"Fülle das gefilterte, glasklare Wasser in eine Steinschale, einen Tontopf oder ein Bambusrohr und stelle es über das Lagerfeuer. Sobald große, faustgroße Blasen kräftig aufsteigen und das Wasser sprudelt, koche es mindestens 3 Minuten lang weiter (im Hochgebirge 5 Minuten). Auch wenn das Wasser sauber aussieht: Unsichtbare Keime und Parasiten leben darin weiter. Erst das heiße Kochen tötet 100% der Keime ab, sodass auch Kinder es sicher trinken können.\",\n      \"actionNote\": \"> Auf keinen Fall roh trinken: Klares Wasser ist noch KEIN keimfreies Wasser! Erst das Kochen nach dem Filtern macht es sicher.\",\n      \"svgFileName\": \"pr01-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PURIFICATION STEP 5: 100°C KOCHEN\",\n        \"BOILING 100°C (KOCHEN)\",\n        \"TIME: 3+ MIN (MINUTEN)\",\n        \"PATHOGEN FREE (KEIMFREI)\",\n        \"[SCHRITT 5] 3+ MINUTEN SPRUDELND KOCHEN\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Das klare Wasser trinken, ohne es vorher sprudelnd abzukochen\",\n    \"description\": \"Kohle und Sand fangen nur sichtbaren Schlamm und schlechten Geruch ab. Unsichtbare fiese Bakterien und Parasiten, die heftige Bauchschmerzen auslösen, schwimmen weiterhin im Wasser. Selbst wenn das Wasser eiskalt und glasklar aussieht: Wer es ungekocht trinkt, bekommt nach wenigen Stunden schweren Durchfall und bricht in der Wildnis durch Wassermangel zusammen.\",\n    \"consequence\": \"Folge: Schwere Darminfektion, extremer Durchfall und lebensgefährliche Austrocknung\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Wildes Schlammwasser zu trinken bringt dich in 3 Tagen um! So baust du einen Naturfilter ohne Plastik!\",\n    \"body\": \"Stelle ein Dreibein aus Ästen auf, hänge einen Trichter ein und stopfe unten Moos hinein. Fülle 8 cm Kohle, 6 cm sauberen Sand und 4 cm Kiesel hinein. Gieße das Schlammwasser darauf! Schütte die ersten 2 Becher weg, weil sie Kohlestaub ausspülen. Das wichtigste Geheimnis: Klares Wasser ist noch nicht sicher! Du musst es mindestens 3 Minuten lang sprudelnd kochen, um alle unsichtbaren Keime zu töten!\",\n    \"outro\": \"Genaue Offline-Überlebenspläne ohne Internet gibt es über den Link im Profil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"Fertiger Naturwasserfilter aus Kohle und Sand\",\n    \"description\": \"Ein an einem Dreibein aus Ästen aufgehängter Naturfilter mit Schichten aus Holzkohle, Sand, Kieselsteinen und Moosstopfen, der trübes Schlammwasser in glasklares Wasser verwandelt, das abgekocht werden kann.\"\n  },\n  \"createdAt\": \"2026-10-09T16:00:00.000Z\",\n  \"updatedAt\": \"2026-10-15T14:24:23+09:00\",\n  \"contentHash\": \"cf7d15c276ffaa84\"\n}","content/protocols/locales/01-water-purification.en.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"How to Turn Muddy Water into Clean Drinking Water (Natural Filter with Charcoal & Sand)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[MUST-HAVE SURVIVAL]\",\n  \"summary\": \"If you drink dirty muddy water in the wild, you will get very sick with bad stomach cramps and diarrhea, causing dangerous dehydration. By tying three sticks into a tripod, hanging a bark cone, and layering crushed charcoal, sand, and pebbles, dirty brown water turns crystal clear. Then, boil it over a campfire for 3 full minutes with big rolling bubbles to destroy invisible germs, making it completely safe to drink.\",\n  \"timeRequired\": \"25 min (15 min filtering + 10 min boiling)\",\n  \"successRate\": \"99.9% (When layered in order and boiled for 3+ minutes)\",\n  \"difficulty\": \"Easy (Anyone can build it with forest materials)\",\n  \"outputPerHour\": \"1.5 to 2.0 liters of clean water per hour\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Black oak charcoal from campfire (Two handfuls, pea-sized)\",\n      \"desc\": \"Acts like a tiny sponge with millions of holes to soak up bad smells and dirty chemicals. Crush into chunks the size of peas (5-8mm).\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Clean rinsed river sand (Two handfuls)\",\n      \"desc\": \"Catches tiny dirt specks that are hard to see. Rinse in clean water first so no muddy dust is mixed in.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Small round pebbles the size of a fingernail (One handful)\",\n      \"desc\": \"Catches large leaves and twigs first, and keeps the sand underneath from getting washed away when pouring water.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Birch bark cone or hollow bamboo stalk (1 piece)\",\n      \"desc\": \"A 30-40cm cone or hollow tube that narrows at the bottom. Holds all filtering materials and funnels drips into your cup.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Three straight finger-thick branches (50cm long)\",\n      \"desc\": \"Tied together at the top to stand up as a sturdy three-legged tripod. Holds the filter high enough to slip a cup underneath.\"\n    },\n    {\n      \"id\": \"mat-06\",\n      \"name\": \"Clean wet moss or cotton cloth scrap for bottom plug\",\n      \"desc\": \"Pushed tightly into the bottom hole so charcoal and sand do not spill out into your clean water.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Set up a 3-stick tripod and hang the cone (Plug bottom hole with moss)\",\n      \"description\": \"Gather three finger-thick straight branches, tie their tops tightly with vine or string, and spread the legs to make a sturdy tripod on the ground. Hang your birch bark cone or hollow bamboo tube straight in the middle. Pack clean, washed river moss or a cloth scrap into the narrow bottom spout using your finger. Without this plug, your charcoal and sand will dump right out.\",\n      \"actionNote\": \"> Plug Tip: If the plug is too loose, black charcoal dust leaks out. Pack it firmly so it does not pop out when pressed.\",\n      \"svgFileName\": \"pr01-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PURIFICATION STEP 1: TRIPOD FRAME\",\n        \"TRIPOD FRAME (3-POINT)\",\n        \"CONE FUNNEL (VESSEL)\",\n        \"MOSS PLUG (BASE)\",\n        \"[STEP 1] STABLE 3-POINT TRIPOD SETUP\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Crush charcoal to pea size and fill 8cm deep at the bottom\",\n      \"description\": \"Find cool, completely black charcoal from your campfire. Place it on a flat stone and tap gently with another stone to break it into pea-sized bits. Do not grind it into fine powder like flour, or water cannot drip through. Pour the charcoal into the cone over the moss plug, and gently tap it down with a stick until it is four finger widths deep (about 8cm). Its tiny sponge holes trap bad smells and dirty chemicals.\",\n      \"actionNote\": \"> Grain Rule: Use pieces bigger than rice grains and about pea-sized. Throw away dusty powder that could clog the water path.\",\n      \"svgFileName\": \"pr01-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PURIFICATION STEP 2: CHARCOAL CORE\",\n        \"CHARCOAL CORE (ACTIVE)\",\n        \"PORE ABSORPTION (TOXINS)\",\n        \"THICKNESS: 8CM\",\n        \"[STEP 2] PACK 8CM OF PEA-SIZED CHARCOAL\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Pour 6cm of clean sand over the charcoal and smooth it flat\",\n      \"description\": \"Rinse clean sand from the riverbank in water two or three times to wash away muddy silt. Gently pour the rinsed sand over the charcoal until it is three finger widths deep (about 6cm). Tap the top lightly with your palm or a flat rock to make it smooth and level. This sand layer stops charcoal chunks from floating up and catches tiny floating dirt.\",\n      \"actionNote\": \"> Leveling Tip: If the sand is slanted, water will rush down the thin side without filtering. Always make the sand bed flat.\",\n      \"svgFileName\": \"pr01-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PURIFICATION STEP 3: SAND LAYER\",\n        \"RIVER SAND (FINE)\",\n        \"PARTICLE FILTER (SILT)\",\n        \"THICKNESS: 6CM\",\n        \"[STEP 3] LOCK CHARCOAL AND TRAP SILT\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Add 4cm of pebbles and pour muddy water (Dump the first 1-2 cups!)\",\n      \"description\": \"Place small fingernail-sized pebbles on top of the sand until it is two finger widths deep (about 4cm), and place a wide green leaf gently on top. Now slowly pour dirty muddy water over the leaf. The pebbles and leaf stop the rushing water from making a hole in the sand. Soon, water will drip out the bottom: drip... drip... Important: The first 1-2 cups will be dark with charcoal dust from cleaning the filter. Do NOT drink this! Throw it away, and only collect water once it drips clear.\",\n      \"actionNote\": \"> First Flush Rule: The first 1-2 cups clean the inside of the filter. Never drink them. Wait until the water drips crystal clear.\",\n      \"svgFileName\": \"pr01-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PURIFICATION STEP 4: PEBBLE & FLUSH\",\n        \"PEBBLE LAYER (BUFFER)\",\n        \"FLUSH FIRST CUPS (DISCARD)\",\n        \"CLEAR DRIP (COLLECT)\",\n        \"[STEP 4] BUFFER WATER & DISCARD FLUSH\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Step 5: Boil the clear water over a fire for 3+ minutes with big rolling bubbles\",\n      \"description\": \"Pour your crystal-clear filtered water into a stone bowl, clay pot, or bamboo boiler and set it over the campfire. Once big, fist-sized bubbles start rolling and churning across the whole pot, keep it boiling for at least 3 full minutes (5 minutes high up in the mountains). Even though the water looks clear, tiny invisible germs that make you sick are still alive. Boiling them kills 100% of germs so kids can drink safely.\",\n      \"actionNote\": \"> Never Drink Raw: Clear water is NOT clean water! Boiling after filtering is what keeps your belly safe.\",\n      \"svgFileName\": \"pr01-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PURIFICATION STEP 5: 100°C BOIL\",\n        \"BOILING 100°C (ROLLING)\",\n        \"TIME: 3+ MIN (TIMER)\",\n        \"PATHOGEN FREE (99.9%)\",\n        \"[STEP 5] ROLLING BOIL FOR 3+ MINUTES\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Drinking clear filtered water without boiling it first\",\n    \"description\": \"Charcoal and sand only catch visible dirt and bad odors. Tiny invisible bacteria and nasty parasites are still swimming in the water. Even if the water looks icy cold and crystal clear, drinking it without boiling can give you terrible stomach cramps and bloody diarrhea within hours, leading to dangerous dehydration in the wild.\",\n    \"consequence\": \"Outcome: Severe stomach cramps, diarrhea, and dangerous wilderness dehydration\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Drinking wild muddy water will give you severe diarrhea in 3 days! Here is how to make a natural filter!\",\n    \"body\": \"Tie three sticks into a tripod, hang a bark cone, and plug the bottom with moss. Layer 8cm of pea-sized charcoal, 6cm of clean sand, and 4cm of pebbles. Pour muddy water in! Dump the first 2 cups because they clean out charcoal dust. Most important secret: clear water is NOT safe water! You must boil it for 3 full minutes with big rolling bubbles to kill invisible germs!\",\n    \"outro\": \"Find full offline survival blueprints with zero cell data via the profile link.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"Completed Natural Charcoal & Sand Water Filter\",\n    \"description\": \"A sturdy wilderness filter hanging from a three-branch tripod. Inside, charcoal, clean sand, pebbles, and a moss plug work together to turn murky muddy water into clear, boilable drinking water.\"\n  },\n  \"createdAt\": \"2026-10-09T16:00:00.000Z\",\n  \"updatedAt\": \"2026-10-15T14:24:23+09:00\",\n  \"contentHash\": \"cf7d15c276ffaa84\"\n}","content/protocols/locales/01-water-purification.es.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"Cómo convertir agua turbia en agua limpia para beber (Filtro natural con carbón y arena)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[SUPERVIVENCIA VITAL]\",\n  \"summary\": \"Si bebes agua sucia y con barro en la naturaleza, tendrás un fuerte dolor de barriga y diarrea que te deshidratará rápidamente. Si atas tres ramas para formar un trípode, cuelgas un cono de corteza y colocas en orden carbón, arena y piedritas, el agua marrón se volverá cristalina. Luego, si la hierves en una fogata durante 3 minutos con burbujas grandes que salten con fuerza, todos los microbios y bichitos invisibles morirán y podrás beberla con total seguridad.\",\n  \"timeRequired\": \"25 min (15 min filtrado + 10 min hervido)\",\n  \"successRate\": \"99.9% (Al colocar las capas en orden y hervir 3+ min)\",\n  \"difficulty\": \"Fácil (Cualquiera puede hacerlo con materiales del bosque)\",\n  \"outputPerHour\": \"1.5 a 2 litros de agua limpia por hora\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Carbón negro de leña de la fogata (Dos puñados, tamaño guisante)\",\n      \"desc\": \"Funciona como una esponja con miles de agujeritos que atrapa los malos olores y las toxinas. Rompe el carbón en trocitos del tamaño de un guisante (5-8 mm).\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Arena fina de río bien lavada (Dos puñados)\",\n      \"desc\": \"Atrapa el polvo y las partículas de barro difíciles de ver. Lávala primero en agua limpia para que no tenga polvo sucio.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Piedritas redondas del tamaño de una uña (Un puñado)\",\n      \"desc\": \"Atrapan las hojas y palitos grandes, y evitan que el agua que viertas haga un agujero en la arena de abajo.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Cono de corteza de abedul o caña de bambú hueca (1 unidad)\",\n      \"desc\": \"Un cono o tubo de 30-40 cm de largo que se estrecha abajo. Sostiene todos los materiales y canaliza las gotas hacia tu vaso.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Tres ramas rectas del grosor de un dedo (50 cm de largo)\",\n      \"desc\": \"Se atan arriba para hacer un trípode firme en el suelo. Sostiene el filtro alto para que quepa un vaso debajo.\"\n    },\n    {\n      \"id\": \"mat-06\",\n      \"name\": \"Musgo limpio y húmedo o trozo de tela para tapón inferior\",\n      \"desc\": \"Se aprieta en el agujero de abajo para que el carbón y la arena no se caigan dentro del agua limpia.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Montar el trípode con 3 ramas y colgar el cono (Tapar abajo con musgo)\",\n      \"description\": \"Junta tres ramas rectas del grosor de un dedo, ata la parte superior con lianas o cuerda y abre las patas para formar un trípode firme en el suelo. Cuelga el cono de corteza o el tubo de bambú bien vertical en el centro. Empuja musgo limpio o un trozo de tela en el orificio estrecho de abajo usando tu dedo. Sin este tapón, el carbón y la arena se caerán al recipiente.\",\n      \"actionNote\": \"> Consejo del tapón: Si queda muy suelto, saldrá polvo negro de carbón. Apriétalo bien para que no se salga al empujar.\",\n      \"svgFileName\": \"pr01-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PURIFICATION STEP 1: TRÍPODE Y TAPÓN\",\n        \"TRIPOD FRAME (TRÍPODE)\",\n        \"CONE FUNNEL (CONO)\",\n        \"MOSS PLUG (TAPÓN)\",\n        \"[PASO 1] MONTAJE DE SOPORTE DE 3 PUNTOS\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Triturar carbón al tamaño de un guisante y llenar 8 cm abajo\",\n      \"description\": \"Escoge trozos de carbón completamente negros y fríos de la fogata. Colócalos sobre una piedra plana y golpéalos suavemente con otra piedra hasta que tengan el tamaño de un guisante. No los muelas como harina o el agua no podrá pasar. Vierte el carbón sobre el tapón de musgo y compáctalo suavemente con una ramita hasta alcanzar la altura de cuatro dedos (unos 8 cm). Sus diminutos poros absorberán los malos olores y la suciedad.\",\n      \"actionNote\": \"> Regla del tamaño: Usa trozos mayores que granos de arroz. Desecha el polvo fino que pueda bloquear el paso del agua.\",\n      \"svgFileName\": \"pr01-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PURIFICATION STEP 2: LECHO DE CARBÓN\",\n        \"CHARCOAL CORE (ACTIVO)\",\n        \"PORE ABSORPTION (ABSORCIÓN)\",\n        \"THICKNESS: 8CM (GROSOR)\",\n        \"[PASO 2] EMPACAR 8CM DE CARBÓN TRITURADO\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Colocar 6 cm de arena limpia sobre el carbón y alisarla bien\",\n      \"description\": \"Lava arena limpia del río dos o tres veces con agua para quitar el barro flotante. Vierte la arena lavada con cuidado sobre el carbón hasta cubrir la altura de tres dedos (unos 6 cm). Golpea la superficie suavemente con la palma de la mano o una piedra plana para nivelarla. Esta capa de arena evita que los trozos de carbón floten y atrapa las partículas de polvo fino.\",\n      \"actionNote\": \"> Nivelación: Si la arena queda inclinada, el agua se irá por el lado fino sin filtrarse bien. Déjala siempre plana.\",\n      \"svgFileName\": \"pr01-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PURIFICATION STEP 3: CAPA DE ARENA\",\n        \"RIVER SAND (ARENA)\",\n        \"PARTICLE FILTER (FILTRO)\",\n        \"THICKNESS: 6CM (GROSOR)\",\n        \"[PASO 3] FIJAR CARBÓN Y ATRAPAR LIMO\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Poner 4 cm de piedritas y verter agua turbia (¡Tirar las primeras 1-2 tazas!)\",\n      \"description\": \"Coloca piedritas del tamaño de una uña sobre la arena hasta la altura de dos dedos (unos 4 cm) y pon una hoja ancha encima. Vierte despacio el agua sucia con barro. Las piedras y la hoja evitan que el chorro haga un agujero en la arena. En poco tiempo, comenzarán a caer gotas por abajo: gota... gota... Muy importante: Las primeras 1 o 2 tazas saldrán oscuras con polvo de carbón que limpia el filtro. ¡No las bebas! Tíralas y empieza a recoger agua cuando salga transparente.\",\n      \"actionNote\": \"> Regla del primer lavado: Las primeras tazas limpian el filtro por dentro. Tíralas siempre hasta que el agua gotee transparente.\",\n      \"svgFileName\": \"pr01-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PURIFICATION STEP 4: GRAVA Y PURGA\",\n        \"PEBBLE LAYER (GRAVA)\",\n        \"FLUSH FIRST CUPS (PURGA)\",\n        \"CLEAR DRIP (GOTEO)\",\n        \"[PASO 4] AMORTIGUAR Y PURGAR PRIMERAS TAZAS\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Paso 5: Hervir el agua limpia al fuego durante más de 3 minutos\",\n      \"description\": \"Pon el agua filtrada y transparente en un recipiente de piedra, barro o bambú y colócala sobre las brasas de la fogata. Cuando empiece a hervir con fuerza y salgan burbujas grandes como puños, mantén el hervor durante al menos 3 minutos completos (5 minutos si estás en montañas altas). Aunque el agua se vea cristalina, los microbios invisibles siguen vivos. Al hervirla con fuerza, mueren al 100% y los niños pueden beberla sin peligro.\",\n      \"actionNote\": \"> Prohibido beber sin hervir: ¡El agua transparente NO es agua segura! Solo hirviéndola después de filtrarla evitarás enfermarte.\",\n      \"svgFileName\": \"pr01-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PURIFICATION STEP 5: HERVIDO A 100°C\",\n        \"BOILING 100°C (HERVOR)\",\n        \"TIME: 3+ MIN (MINUTOS)\",\n        \"PATHOGEN FREE (99.9%)\",\n        \"[PASO 5] HERVIR CON FUERZA POR 3+ MINUTOS\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error fatal: Beber el agua transparente sin hervirla al fuego\",\n    \"description\": \"El carbón y la arena solo limpian el barro visible y el mal olor. Los microbios y parásitos microscópicos que causan vómitos y diarrea siguen vivos en el agua. Aunque el agua parezca limpia y fresca, beberla sin hervir te provocará fuertes dolores y deshidratación peligrosa en pocas horas.\",\n    \"consequence\": \"Consecuencia: Infección grave, diarrea severa y deshidratación mortal en la naturaleza\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"¡Beber agua con barro en la naturaleza te causará diarrea grave en 3 días! ¡Mira cómo hacer un filtro natural!\",\n    \"body\": \"Monta un trípode de ramas, cuelga un cono y tapa el fondo con musgo. Pon 8 cm de carbón partido, 6 cm de arena limpia y 4 cm de piedritas. ¡Vierte el agua con barro! Tira las 2 primeras tazas porque limpian el polvo de carbón. El secreto más importante: ¡agua transparente no significa agua segura! Tienes que hervirla durante 3 minutos completos con burbujas grandes para matar todos los bichitos invisibles.\",\n    \"outro\": \"Consigue los esquemas de supervivencia sin internet en el enlace de mi perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"Filtro natural de carbón y arena terminado\",\n    \"description\": \"Estructura completa de filtración colgada de un trípode de ramas con capas de carbón, arena limpia, piedritas y tapón de musgo que convierten el agua marrón en agua cristalina lista para hervir y beber.\"\n  },\n  \"createdAt\": \"2026-10-09T16:00:00.000Z\",\n  \"updatedAt\": \"2026-10-15T14:24:23+09:00\",\n  \"contentHash\": \"cf7d15c276ffaa84\"\n}","content/protocols/locales/01-water-purification.ja.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"泥水をきれいな飲み水に変える方法（炭と砂で作る自然の浄水器）\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[必須サバイバル]\",\n  \"summary\": \"野外で汚れた泥水をそのまま飲むと、ひどい腹痛や下痢になり、脱水症状で倒れてしまいます。木の枝を3本組んで三脚を作り、コーン状の筒をぶら下げて炭・砂・小石を順番に重ねると、茶色い泥水がすきとおった透明な水になります。これをたき火にかけ、大きな泡がボコボコと沸き立つ状態で3分以上しっかり沸とうさせれば、お腹を痛くする見えない悪いバイキン（細菌）まで完全にやっつけて、安心して飲むことができます。\",\n  \"timeRequired\": \"25分（ろ過 15分 + 沸とう 10分）\",\n  \"successRate\": \"99.9%（順番に重ねてろ過し、3分以上沸とうさせた場合）\",\n  \"difficulty\": \"かんたん（周りの自然のもので誰でも作れる）\",\n  \"outputPerHour\": \"1時間にきれいな水 1.5〜2リットル\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"たき火から取り出した黒い炭（えんどう豆サイズ、両手2杯）\",\n      \"desc\": \"スポンジの穴のように、水の中の嫌なにおいや汚れをグングン吸い取ります。お米より大きく、豆くらいの大きさ（5〜8mm）に砕いて使います。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"川の水でよく洗ったきれいな川砂（両手2杯）\",\n      \"desc\": \"目に見えない細かい泥やホコリを細かくキャッチします。泥が混ざっていないきれいな砂を選んで使います。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"爪くらいの小さな丸い小石（片手1杯）\",\n      \"desc\": \"落ち葉や大きなゴミを最初に止め、上から水を注いでも下の砂がえぐれないように守ってくれます。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"白樺の木の皮のコーンまたは竹の筒（1本）\",\n      \"desc\": \"長さ30〜40cmほどの、下が細くなった筒や円すい状の入れ物です。材料を順番に詰めて、しずくを1か所に集めます。\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"指の太さのまっすぐな木の枝 3本（長さ50cm）\",\n      \"desc\": \"3本を上でしばって地面に立てる丈夫な三脚です。下に水受けの器を置けるように高く支えます。\"\n    },\n    {\n      \"id\": \"mat-06\",\n      \"name\": \"一番下の穴をふさぐきれいな水ゴケまたは布のきれはし\",\n      \"desc\": \"一番下の出口にぎゅっと詰めて、炭や砂が下にこぼれ落ちないようにするストッパーです。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ1: 枝3本で三脚を立てて筒をつるす（一番下の穴はコケでふさぐ）\",\n      \"description\": \"指の太さのまっすぐな木の枝3本を集め、上側をつる草やひもでしっかり結んで、脚を広げてグラグラしない三脚を地面に立てます。白樺の皮を巻いたコーンや中をくりぬいた竹の筒を三脚の真ん中にまっすぐ固定します。水がポタポタ落ちる一番下の細い出口には、きれいに洗った水ゴケや布きれを指でグッと押し込みます。この栓がないと、上に入れた炭や砂がドッと下にこぼれてしまいます。\",\n      \"actionNote\": \"> 栓のコツ: 栓がゆるいと炭の粉が漏れて黒い水になります。指で押しても抜けないようにしっかり詰めてください。\",\n      \"svgFileName\": \"pr01-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PURIFICATION STEP 1: フレーム設置・下部栓\",\n        \"木の枝3本の三脚スタンド\",\n        \"コーン型白樺樹皮ろ過筒\",\n        \"底穴をしっかり塞ぐ水ゴケ栓\",\n        \"[ステップ1] 倒れない三脚＆丈夫な底栓の設置\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ2: 炭を豆の大きさに砕いて一番下に8cmの深さで詰める\",\n      \"description\": \"たき火から完全に燃え尽きて冷えた黒い炭を選び、平らな石の上に乗せて別の石でトントン叩いて豆サイズに砕きます。ミキサーのように細かく粉にしてしまうと、水がすき間を通れず詰まってしまいます。砕いた炭を筒の中のコケ栓の上に流し込み、木の枝の先でトントンと軽くならして指4本分の高さ（約8cm）まで詰めます。炭の無数の小さな穴が、水の中の臭いと汚れを吸い取ります。\",\n      \"actionNote\": \"> サイズの目安: お米より大きく豆くらいの粒を使ってください。小麦粉のような細かい粉は水詰まりの原因になるので取り除きます。\",\n      \"svgFileName\": \"pr01-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PURIFICATION STEP 2: 炭による吸着層\",\n        \"豆粒サイズに砕いた黒炭の粒\",\n        \"臭いと毒素を吸着する炭の微細孔\",\n        \"指4本分の高さ（8cm）まで充填\",\n        \"[ステップ2] 豆粒炭を8cm詰めて軽くならす\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ3: 洗ったきれいな砂を炭の上に6cm平らに重ねる\",\n      \"description\": \"川辺で取ったきれいな砂を水で2〜3回ゆすいで、濁った泥をきれいに洗い流します。洗った砂を炭の上にそっと注ぎ、指3本分の高さ（約6cm）まで重ねます。手のひらや平らな石で表面を軽くトントン叩いて平らにならします。砂の層は下の炭が水に浮き上がらないように押さえつけ、水の中の細かいホコリを網のようにしっかりキャッチします。\",\n      \"actionNote\": \"> 平らにするコツ: 砂が傾いていると水が薄い方ばかりに流れてろ過できません。必ず砂の上面を平らに整えてください。\",\n      \"svgFileName\": \"pr01-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PURIFICATION STEP 3: 微細砂層の積層\",\n        \"水で洗ったきれいな川砂\",\n        \"細かい泥やゴミをしっかりブロック\",\n        \"指3本分の高さ（6cm）まで充填\",\n        \"[ステップ3] 炭の上に砂を6cm平らに敷く\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"ステップ4: 小石を4cm乗せて泥水を注ぐ（最初の1〜2杯は必ず捨てる！）\",\n      \"description\": \"砂の上に爪くらいの小さな小石を指2本分の高さ（約4cm）まで乗せ、一番上には幅の広い葉っぱを1枚そっとかぶせます。これで上から濁った泥水をゆっくり注ぎます。小石と葉っぱのおかげで、水を注いでも砂がえぐれずにじわじわ染み込んでいきます。しばらくすると一番下からポタ…ポタ…と水が垂れてきます。このとき最初に出てくる1〜2杯の水は、フィルター内の炭の粉を洗い流す黒い掃除用の水です。絶対に飲まずに思い切って捨ててください！透明な水が落ち始めたら、きれいな器で水を受けます。\",\n      \"actionNote\": \"> 初水を捨てるルール: 最初の1〜2杯は浄水器の中を掃除する水です。もったいながらずに、水滴が水晶のように透きとおるまで捨ててください。\",\n      \"svgFileName\": \"pr01-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PURIFICATION STEP 4: 小石層と初期洗浄\",\n        \"水圧を分散する小石層（4cm）\",\n        \"炭粉を洗い流す初水（1〜2杯廃棄）\",\n        \"1秒に1滴ずつ落ちる澄んだ水滴\",\n        \"[ステップ4] 小石で砂を守り初水は必ず捨てる\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"ステップ5: ろ過した透明な水を火にかけて3分以上ボコボコ沸とうさせる\",\n      \"description\": \"浄水器を通って見た目には水晶のように透きとおった水を、石の器や竹の筒に入れてたき火の上にかけます。水の真ん中から大きな泡がボコボコと激しく湧き上がって沸とうし始めたら、時計を見ながら最低3分以上（標高の高い山では5分以上）ぐつぐつ沸かし続けます。浄水器でろ過しても、顕微鏡でしか見えない悪いバイキンや寄生虫は残っています。こうして熱でしっかり煮沸することで、バイキンが100%死滅し、子どもでもごくごく飲める本当の安全なサバイバル飲み水になります。\",\n      \"actionNote\": \"> そのまま飲むのは絶対禁止: 透きとおって見えてもそのまま飲んではいけません！泥を除いたあとに沸とうさせて初めて、お腹をこわさない水になります。\",\n      \"svgFileName\": \"pr01-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PURIFICATION STEP 5: 100℃煮沸殺菌\",\n        \"大きな泡がボコボコ立つ沸とう水\",\n        \"最低3分以上しっかり加熱（山は5分）\",\n        \"見えない悪い細菌を99.9%完全死滅\",\n        \"[ステップ5] 透明な水も必ず3分以上沸とうさせる\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"命に関わる失敗: 透きとおっているからと沸とうさせずにそのままゴクゴク飲むこと\",\n    \"description\": \"炭と砂は目に見える泥や嫌なにおいを取るだけです。お腹がちぎれるほど痛くなる顕微鏡サイズの細菌や寄生虫はそのまま水の中に生きています。水がどれだけ冷たくきれいに見えても、火で沸かさずに飲むと数時間後に激しい腹痛と下痢で脱水症状になり、命を落とす危険があります。\",\n    \"consequence\": \"結果: 激しい下痢とお腹の激痛で倒れ、野外で命の危機になる\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"野外で泥水をそのまま飲むと3日で倒れます！自然の素材だけで作る浄水器の作り方！\",\n    \"body\": \"枝3本で三脚を立てて筒をつるし、底をコケでふさぎます。その上に豆サイズの炭8cm、きれいな砂6cm、小石4cmを順番に重ねて泥水を注ぐだけ！最初の2杯は炭の粉を洗う水なので捨てて、透明な水だけを取ります。いちばん大事な秘密！透明でもそのまま飲むとバイキンでお腹をこわします。必ず火にかけて大きな泡が出るまで3分以上沸とうさせてください！\",\n    \"outro\": \"ネットが圏外でも見られるオフライン設計図はプロフィールのリンクから！\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"炭と砂で作る3重ろ過自然浄水器の完成形\",\n    \"description\": \"木の枝の三脚につるした筒の中に、炭・きれいな砂・小石・コケの栓が層になって詰まり、上から注いだ泥水が下の出口からキラキラ光る透明な水になってしたたり落ちる完成構造です。\"\n  },\n  \"createdAt\": \"2026-10-09T16:00:00.000Z\",\n  \"updatedAt\": \"2026-10-15T14:24:23+09:00\",\n  \"contentHash\": \"cf7d15c276ffaa84\"\n}","content/protocols/locales/01-water-purification.pt.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"Como transformar água barrenta em água limpa para beber (Filtro natural com carvão e areia)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[SOBREVIVÊNCIA VITAL]\",\n  \"summary\": \"Se você beber água suja com barro na floresta, terá fortes dores de barriga e diarreia, ficando perigosamente desidratado. Ao amarrar três galhos para formar um tripé, pendurar um cone de casca e colocar em ordem carvão, areia e pedrinhas, a água marrom fica transparente como vidro. Depois, se você ferver a água em uma fogueira por 3 minutos com bolhas grandes borbulhando forte, todos os micróbios invisíveis serão eliminados e você poderá beber sem perigo.\",\n  \"timeRequired\": \"25 min (15 min filtrando + 10 min fervendo)\",\n  \"successRate\": \"99.9% (Ao colocar as camadas em ordem e ferver por 3+ min)\",\n  \"difficulty\": \"Fácil (Qualquer pessoa consegue fazer com materiais da natureza)\",\n  \"outputPerHour\": \"1.5 a 2 litros de água limpa por hora\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Carvão preto de fogueira (Dois punhados, tamanho de ervilha)\",\n      \"desc\": \"Funciona como uma esponja cheia de furinhos que suga o mau cheiro e a sujeira. Quebre em pedacinhos do tamanho de uma ervilha (5 a 8 mm).\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Areia fina de rio bem lavada (Dois punhados)\",\n      \"desc\": \"Segura a poeira e o pó de terra difíceis de enxergar. Lave antes na água limpa para não misturar lama.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Pedrinhas redondas do tamanho de uma unha (Um punhado)\",\n      \"desc\": \"Seguram folhas e gravetos grandes e evitam que a água despejada faça um buraco na areia de baixo.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Cone de casca de árvore ou pedaço de bambu oco (1 unidade)\",\n      \"desc\": \"Um recipiente de 30 a 40 cm que afunila embaixo. Segura todas as camadas e guia os pingos para dentro do copo.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Três galhos retos da grossura de um dedo (50 cm de comprimento)\",\n      \"desc\": \"Amarrados em cima para formar um tripé firme no chão. Segura o filtro alto o suficiente para caber uma vasilha embaixo.\"\n    },\n    {\n      \"id\": \"mat-06\",\n      \"name\": \"Musgo limpo e úmido ou pedaço de pano para o tampão do fundo\",\n      \"desc\": \"Apertado no buraco de baixo para que o carvão e a areia não caiam dentro da água limpa.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Montar o tripé com 3 galhos e pendurar o cone (Tapar o fundo com musgo)\",\n      \"description\": \"Junte três galhos retos da grossura de um dedo, amarre o topo com cipó ou barbante e abra as pernas para firmar um tripé firme no chão. Prenda o cone de casca de árvore ou o tubo de bambu bem reto no meio. Empurre musgo limpo e lavado ou um pedaço de pano no bico estreito do fundo usando o dedo. Sem esse tampão, o carvão e a areia cairão direto para fora.\",\n      \"actionNote\": \"> Dica do tampão: Se ficar frouxo, sairá pó preto de carvão. Aperte bem para que ele não se solte ao empurrar com o dedo.\",\n      \"svgFileName\": \"pr01-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PURIFICATION STEP 1: TRIPÉ E PLUGUE\",\n        \"TRIPOD FRAME (TRIPÉ)\",\n        \"CONE FUNNEL (CONE)\",\n        \"MOSS PLUG (MUSGO)\",\n        \"[PASSO 1] AMARRAÇÃO DE TRIPÉ DE 3 PONTOS\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Quebrar o carvão no tamanho de ervilha e encher 8 cm no fundo\",\n      \"description\": \"Escolha pedaços de carvão bem pretos e frios da fogueira. Coloque sobre uma pedra chata e bata com outra pedra até ficarem do tamanho de ervilhas. Não moa até virar pó fino como farinha, senão a água não conseguirá passar. Despeje o carvão sobre o musgo e aperte levemente com uma varinha até atingir a altura de quatro dedos (cerca de 8 cm). Seus buraquinhos vão sugar o cheiro ruim e a sujeira.\",\n      \"actionNote\": \"> Regra do tamanho: Use pedaços maiores que grãos de arroz. Jogue fora o pó fino para não entupir o caminho da água.\",\n      \"svgFileName\": \"pr01-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PURIFICATION STEP 2: LEITO DE CARVÃO\",\n        \"CHARCOAL CORE (CARVÃO)\",\n        \"PORE ABSORPTION (ABSORÇÃO)\",\n        \"THICKNESS: 8CM (ALTURA)\",\n        \"[PASSO 2] EMPACOTAR 8CM DE CARVÃO EM GRÃOS\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Colocar 6 cm de areia limpa sobre o carvão e nivelar bem\",\n      \"description\": \"Lave a areia do rio duas ou três vezes na água para tirar a terra solta. Despeje a areia lavada sobre o carvão até cobrir a altura de três dedos (cerca de 6 cm). Bata de leve com a palma da mão ou uma pedra lisa para deixá-la bem reta. A areia impede que os pedaços de carvão boiem e segura a poeira fininha.\",\n      \"actionNote\": \"> Nivelar a areia: Se a areia ficar inclinada, a água escorrerá pelo lado mais raso sem filtrar. Deixe a superfície bem plana.\",\n      \"svgFileName\": \"pr01-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PURIFICATION STEP 3: CAMADA DE AREIA\",\n        \"RIVER SAND (AREIA)\",\n        \"PARTICLE FILTER (FILTRAGEM)\",\n        \"THICKNESS: 6CM (ALTURA)\",\n        \"[PASSO 3] FIXAR CARVÃO E RETER LIMO\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Pôr 4 cm de pedrinhas e despejar água com barro (Jogue fora os 1-2 primeiros copos!)\",\n      \"description\": \"Coloque pedrinhas do tamanho de uma unha sobre a areia até a altura de dois dedos (cerca de 4 cm) e coloque uma folha larga por cima. Despeje devagar a água barrenta sobre a folha. As pedras e a folha impedem que o fluxo de água abra um buraco na areia. Logo a água começará a pingar por baixo: plic... plic... Muito importante: Os primeiros 1 ou 2 copos saem escuros com pó de carvão limpando o filtro. Não beba isso! Jogue fora e só comece a recolher a água quando ela sair transparente.\",\n      \"actionNote\": \"> Regra da primeira água: Os primeiros copos limpam o filtro por dentro. Jogue fora até que a água pingue transparente como vidro.\",\n      \"svgFileName\": \"pr01-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PURIFICATION STEP 4: SEIXOS E PURGA\",\n        \"PEBBLE LAYER (SEIXOS)\",\n        \"FLUSH FIRST CUPS (PURGA)\",\n        \"CLEAR DRIP (PINGOS)\",\n        \"[PASSO 4] AMORTECER E DESCARTAR ÁGUA INICIAL\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Passo 5: Ferver a água limpa no fogo por mais de 3 minutos\",\n      \"description\": \"Coloque a água transparente filtrada em uma tigela de pedra, barro ou bambu e ponha sobre o fogo. Quando grandes bolhas do tamanho de um punho começarem a borbulhar com força, continue fervendo por pelo menos 3 minutos completos (5 minutos se estiver no alto de montanhas). Mesmo que a água pareça limpa, micróbios invisíveis continuam vivos. Ferver na água bem quente mata 100% deles para que as crianças possam beber com total tranquilidade.\",\n      \"actionNote\": \"> Nunca beba sem ferver: Água transparente NÃO significa água segura! Só ferver depois de filtrar protege sua barriga de doenças.\",\n      \"svgFileName\": \"pr01-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PURIFICATION STEP 5: FERVURA A 100°C\",\n        \"BOILING 100°C (FERVURA)\",\n        \"TIME: 3+ MIN (MINUTOS)\",\n        \"PATHOGEN FREE (ESTERILIZADO)\",\n        \"[PASSO 5] FERVER COM FORÇA POR 3+ MINUTOS\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro fatal: Beber a água transparente sem ferver no fogo primeiro\",\n    \"description\": \"O carvão e a areia tiram apenas o barro visível e o cheiro ruim. Os micróbios e parasitas microscópicos que causam dor forte na barriga e diarreia continuam vivos na água. Mesmo que a água pareça fresca e transparente, bebê-la sem ferver pode causar doenças graves em poucas horas, levando à desidratação perigosa na floresta.\",\n    \"consequence\": \"Resultado: Dor forte de barriga, diarreia severa e desidratação perigosa na selva\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Beber água com barro na selva pode te derrubar em 3 dias! Veja como fazer um filtro com coisas da floresta!\",\n    \"body\": \"Faça um tripé de galhos, pendure um cone e feche o fundo com musgo. Coloque 8 cm de carvão quebrado, 6 cm de areia limpa e 4 cm de pedrinhas. Despeje a água barrenta! Jogue fora os 2 primeiros copos que limpam o pó de carvão. O segredo mais importante: água transparente NÃO é água segura! Você precisa ferver no fogo por 3 minutos com bolhas grandes para matar todos os micróbios invisíveis!\",\n    \"outro\": \"Acesse os manuais de sobrevivência sem internet no link do meu perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"Filtro natural de carvão e areia concluído\",\n    \"description\": \"Um filtro de sobrevivência montado em um tripé de galhos. No interior, camadas de carvão, areia de rio, pedrinhas e tampão de musgo trabalham juntos para transformar água barrenta em água transparente pronta para ferver e beber.\"\n  },\n  \"createdAt\": \"2026-10-09T16:00:00.000Z\",\n  \"updatedAt\": \"2026-10-15T14:24:23+09:00\",\n  \"contentHash\": \"cf7d15c276ffaa84\"\n}","content/protocols/locales/01-water-purification.zh-TW.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"如何將泥水變成乾淨的飲用水（用木炭與細沙自製天然淨水器）\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[必備求生]\",\n  \"summary\": \"在野外如果不小心直接喝下髒泥水，會引起嚴重的肚子痛與腹瀉，甚至因為嚴重脫水而倒下。只要用三根樹枝架成三腳架，掛上樹皮圓錐筒，依序放入敲碎的木炭、細沙和小石子，渾濁的泥水就會慢慢變成透明清澈的乾淨水。接著將過濾水放在營火上，大火煮滾冒出像拳頭般的大泡泡，持續滾煮3分鐘以上，把看不見的壞細菌通通消滅，就可以安心咕嚕咕嚕喝下肚了。\",\n  \"timeRequired\": \"25分鐘（過濾15分鐘 + 煮沸10分鐘）\",\n  \"successRate\": \"99.9%（依序分層過濾後持續滾煮3分鐘以上）\",\n  \"difficulty\": \"簡單（運用身邊自然物，任何人都能動手完成）\",\n  \"outputPerHour\": \"每小時可過濾出 1.5 至 2 公升乾淨水\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"營火冷卻後的黑木炭（雙手捧兩把，豌豆大小）\",\n      \"desc\": \"就像有無數小孔的海綿，能把水裡的臭味和髒污緊緊吸住。敲成比米粒大、像豌豆大小（5~8毫米）的顆粒備用。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"在溪水中洗乾淨的細河沙（雙手捧兩把）\",\n      \"desc\": \"能阻擋肉眼難以看見的細小泥塵。挑選乾淨且沒有黏土泥漿的細沙使用。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"如指甲般大小的圓形小石子（單手抓一把）\",\n      \"desc\": \"在最上層阻擋落葉與粗雜質，倒入泥水時還能保護下方的細沙不被沖出大洞。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"樺樹皮圓錐筒或中空竹筒 1 支\",\n      \"desc\": \"長約30~40公分、下方漸窄的圓筒或漏斗。將所有過濾材料層層裝入，把水滴集中到下方出口。\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"約手指粗細的筆直樹枝 3 根（長約50公分）\",\n      \"desc\": \"頂端綁緊立在地面上的堅固三腳架。把過濾筒架高，讓下方有足夠空間放接水容器。\"\n    },\n    {\n      \"id\": \"mat-06\",\n      \"name\": \"塞住底部出水口的乾淨水苔或布塊\",\n      \"desc\": \"緊緊塞在最下方的出水小孔，像棉花塞一樣防止上方的木炭與細沙掉漏出來。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"步驟1：用3根樹枝架起三腳架並掛上漏斗（底部小孔用水苔塞緊）\",\n      \"description\": \"收集三根手指粗細的筆直樹枝，上方用藤蔓或細繩緊緊綁好，撐開三隻腳立在平坦地面上。將捲成圓錐形的樺樹皮或打通竹節的竹筒直直固定在三腳架正中央。在水滴即將滴下的底部窄孔中，用手指緊緊塞入洗淨的濕水苔或布塊。如果沒有塞好這個塞子，上方倒進去的木炭粉和細沙會一口氣掉光光。\",\n      \"actionNote\": \"> 瓶塞秘訣：如果塞得太鬆，黑色的木炭粉會漏出來。用手指輕推不會鬆脫即可。\",\n      \"svgFileName\": \"pr01-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PURIFICATION STEP 1: 架台與底塞\",\n        \"TRIPOD FRAME (三腳架)\",\n        \"CONE FUNNEL (過濾管)\",\n        \"MOSS PLUG (苔蘚塞)\",\n        \"[第1階段核心] 穩固三點支撐架結合\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"步驟2：將木炭敲成豌豆大小，在最底層填入8公分厚\",\n      \"description\": \"從營火堆中挑選徹底燒成黑色且冷卻的木炭，放在平平的石塊上，用另一塊石頭輕輕敲碎成豌豆般大小。千萬不要像磨麵粉一樣磨成細粉，否則水流會完全卡住無法滴下。將敲好的木炭倒在漏斗底部的苔蘚塞上方，用小樹枝輕輕壓實，堆滿約四個手指寬的高度（約8公分）。木炭上的無數微小細孔會把水裡的臭氣和髒污吸得乾乾淨淨。\",\n      \"actionNote\": \"> 尺寸訣竅：挑選比米粒大、像豌豆大的顆粒。將太細的粉塵挑出丟掉，避免堵住水路。\",\n      \"svgFileName\": \"pr01-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PURIFICATION STEP 2: 木炭吸附層\",\n        \"CHARCOAL CORE (活性炭)\",\n        \"PORE ABSORPTION (毒素吸附)\",\n        \"THICKNESS: 8CM (厚度)\",\n        \"[第2階段核心] 搗碎至豌豆大並填充8cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"步驟3：將洗乾淨的細沙平鋪在木炭上方達6公分厚度\",\n      \"description\": \"從溪邊挖來的細沙用清水沖洗兩到三次，把渾濁的泥塵漂洗乾淨。將洗乾淨的細沙輕輕倒在木炭上方，鋪滿約三個手指寬的高度（約6公分）。用手掌或扁平的小石頭輕輕拍平表面。細沙層不僅能壓住下方的木炭不讓它浮起來，還能像篩子一樣把飄浮在水裡的極微小泥屑牢牢擋住。\",\n      \"actionNote\": \"> 表面拍平：如果沙子鋪得歪歪斜斜，水會往薄的那一邊流走而過濾不完全。一定要把表面鋪平。\",\n      \"svgFileName\": \"pr01-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PURIFICATION STEP 3: 細沙層鋪設\",\n        \"RIVER SAND (細沙)\",\n        \"PARTICLE FILTER (泥屑攔截)\",\n        \"THICKNESS: 6CM (厚度)\",\n        \"[第3階段核心] 鋪設平整並攔截細泥\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"步驟4：鋪上4公分小石子並緩緩倒入泥水（前1~2杯水一定要倒掉！）\",\n      \"description\": \"在細沙上方鋪入指甲大小的圓形小石子，厚度約兩個手指寬（約4公分），最上層輕輕蓋上一片寬大的樹葉。現在開始從樹葉上方慢慢倒入髒泥水。有了小石子和樹葉的保護，倒水時細沙就不會被沖散凹陷。不久後，最下方的小孔會開始滴水：滴…滴…滴… 關鍵要點：最先滴出的1到2杯水，含有清洗濾芯帶出的黑色炭粉，絕對不能喝！請果斷倒掉，直到滴出透明清澈的水珠時，再放乾淨容器承接。\",\n      \"actionNote\": \"> 倒掉初水守則：前1~2杯水是用來清洗淨水器內部的。千萬別可惜，務必倒掉直到滴出水晶般清澈的水。\",\n      \"svgFileName\": \"pr01-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PURIFICATION STEP 4: 礫石與清洗\",\n        \"PEBBLE LAYER (石子緩衝)\",\n        \"FLUSH FIRST CUPS (倒掉初水)\",\n        \"CLEAR DRIP (清澈水滴)\",\n        \"[第4階段核心] 緩衝水流並倒掉初水\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"步驟5：將過濾出的清澈水放在火上大火持續滾煮3分鐘以上\",\n      \"description\": \"將通過淨水器後肉眼看起來像水晶般透明的水，裝入石碗、陶罐或竹筒中，放在營火上加熱。當水中央開始冒出拳頭般的大水泡並劇烈翻滾時，看著手錶持續滾煮至少3分鐘以上（高山地區需要5分鐘以上）。雖然水看起來很乾淨，但肉眼看不見的細菌和寄生蟲依然存活著。只有高溫滾煮才能徹底消滅所有壞菌，讓小朋友也能放心大口飲用。\",\n      \"actionNote\": \"> 絕對禁忌：看起來清澈的水不等於安全無菌的水！過濾後務必大火滾煮，才不會喝壞肚子。\",\n      \"svgFileName\": \"pr01-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PURIFICATION STEP 5: 100°C 沸水殺菌\",\n        \"BOILING 100°C (劇烈滾煮)\",\n        \"TIME: 3+ MIN (持續3分鐘)\",\n        \"PATHOGEN FREE (消滅壞菌)\",\n        \"[第5階段核心] 大火劇烈滾煮3分鐘以上\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命錯誤：以為水看起來乾淨透明就不煮沸直接大口喝下\",\n    \"description\": \"木炭和細沙只能過濾肉眼看得到的泥沙與臭味。會讓人肚子劇烈絞痛的微小細菌和寄生蟲，依然在水裡活躍游動。即使水看起來冰涼透明，若未經大火煮沸就直接飲用，幾小時後就會引發嚴重的腹痛和血痢，在野外迅速陷入危險的脫水狀態。\",\n    \"consequence\": \"後果：引發嚴重腸胃炎與痢疾，在野外因脫水陷入生命危險\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"在野外隨便喝泥水，三天內就會脫水倒下！教你只用身邊自然物自製淨水器！\",\n    \"body\": \"用三根樹枝立成三腳架，掛上圓錐漏斗，底部塞好水苔。依序裝入8公分碎木炭、6公分乾淨細沙、4公分小石子，倒進泥水！前2杯是清洗炭粉的水記得倒掉，只留透明水。最重要的秘密：清澈的水不代表安全的水！一定要放在火上冒大泡泡滾煮3分鐘以上，把看不見的壞菌通通消滅！\",\n    \"outro\": \"無網路也能隨時查看的離線求生手冊，請點擊個人簡介連結。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"炭砂三重過濾天然淨水器完成圖\",\n    \"description\": \"懸掛在樹枝三腳架上的天然過濾器，內部由木炭、細河沙、小石子及水苔塞層層堆疊，將上方濁黃的泥水轉化為底部滴落的透亮可飲用水。\"\n  },\n  \"createdAt\": \"2026-10-09T16:00:00.000Z\",\n  \"updatedAt\": \"2026-10-15T14:24:23+09:00\",\n  \"contentHash\": \"cf7d15c276ffaa84\"\n}","content/protocols/locales/02-friction-fire.de.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"Feuerbohren durch Reibungswärme (Bow Drill)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[GEFAHRENSTUFE: KRITISCH]\",\n  \"summary\": \"Primitive Pyrotechnik, die durch mechanische Reibung zwischen trockenem Weichholz und einer Bogenspindel über 400°C heiße Glutkohle erzeugt und durch gezielte Sauerstoffzufuhr entzündet.\",\n  \"timeRequired\": \"20 MINUTEN\",\n  \"successRate\": \"85% (Trockenholz)\",\n  \"difficulty\": \"Stufe 2 (Fortgeschrittene Technik)\",\n  \"outputPerHour\": \"1 Feuer / 20 Min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Bogenstab & Pflanzenfasersehne (BOW & STRING)\",\n      \"desc\": \"60–70 cm langer, leicht gebogener Hartholzast (Esche/Hasel) und reißfeste Naturfaserschnur.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Rotationsspindel (SPINDLE)\",\n      \"desc\": \"Gerader Zylinder (Ø 20 mm) aus trockener Zeder oder Weide. Oben abgerundet, unten 45°-Kegel.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Feuerbrett mit V-Kerbe & Zundernest (HEARTH & TINDER)\",\n      \"desc\": \"15–20 mm dickes Feuerbrett mit 45° V-Kerbe, Glutauffangblatt und trockenem Zundernest.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"45° V-Kerben-Zuschnitt & Spindelzentrierung\",\n      \"description\": \"Schnitzen Sie eine präzise 45-Grad-V-Kerbe von der Vorderkante des Feuerbretts exakt bis zum Mittelpunkt der Spindelbohrung. Legen Sie ein trockenes Blatt als Glutauffang darunter.\",\n      \"actionNote\": \"> Feldregel: Überschreitet der Kerbenwinkel 60 Grad, entweicht die Wärme und der Zündpunkt von 400°C wird nicht erreicht.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"GLUTAUFFANGBLATT [RINDENBASIS]\",\n        \"45° V-KERBE (Spitze am Achszentrum)\",\n        \"Ø 20mm SPINDELACHSE\",\n        \"DICKE: 15~20mm\",\n        \"FEUERBRETT (HEARTH BOARD)\",\n        \"KERBENSPITZE (Exakt im Bohrlochzentrum)\",\n        \"KRITISCHE AUFBAUREGEL:\",\n        \"V-Kerbenspitze muss Achszentrum berühren\",\n        \"KOHLESTAUB-SAMMELZONE (GLUTBETT)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"90° Vertikaldruck & Vollhub-Hochgeschwindigkeitsrotation\",\n      \"description\": \"Fixieren Sie das Feuerbrett mit dem linken Fuß und üben Sie über das Drucklager 12–15 kg Vertikallast aus. Bewegen Sie den Bogen waagerecht über die volle Länge (300–400 RPM), bis dichter weißer Rauch aufsteigt.\",\n      \"actionNote\": \"> Feldregel: Nicht beim ersten Rauch stoppen! Mindestens 10–15 kraftvolle Endhübe durchführen, damit der Kohlestaub vollständig verschmilzt.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"DRUCKLAGER (HANDSTÜCK)\",\n        \"F_DOWN: 12~15 kg (Vertikallast)\",\n        \"BOGENSTAB (65cm Hartholz)\",\n        \"VOLLHUB-PENDELBEWEGUNG (Volle Bogenlänge)\",\n        \"ω: 300~400 RPM\",\n        \"FEUERBRETT\",\n        \"WEISSER RAUCH (Dichter Rauch)\",\n        \"KRITISCHER SCHWELLENWERT:\",\n        \"Zündtemp.: 400°C+\",\n        \"Druck: Start 30% → Ende 100%\",\n        \"Hub: 100% Bogenlänge nutzen\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Glutkern-Einbettung & Sanfte Belüftungszündung (600°C)\",\n      \"description\": \"Lassen Sie den glimmenden Kohlestaub 30 Sekunden lang zu einem festen Glutkern (450°C) reifen. Betten Sie ihn in das Zundernest um, halten Sie es im 45°-Winkel und blasen Sie sanft bis zur Flammenzündung bei 600°C.\",\n      \"actionNote\": \"> Feldregel: Zundernest im 45°-Winkel leicht über Augenhöhe halten – der thermische Aufwind verdoppelt die Sauerstoffzufuhr.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"GLUTKERN (450°C)\",\n        \"SANFTER KONTINUIERLICHER LUFTSTROM\",\n        \"FLAMMENZÜNDUNG (Durchzündung)\",\n        \"45° HALTEWINKEL\",\n        \"TEMPERATURANSTIEG & ZÜNDMATRIX\",\n        \"ZEIT (Sek)\",\n        \"TEMP (°C)\",\n        \"600°C FLAMMEN-ZÜNDSCHWELLE\",\n        \"400°C GLIMMPUNKT (KOHLE)\",\n        \"30s Reifen & Einsetzen (0s)\",\n        \"Flammenausbruch (15~20s)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Niemals hastig in unfertigen Kohlestaub blasen\",\n    \"description\": \"Wer sofort nach dem Bohren stark auf das lose schwarze Pulver bläst, zerstreut die feinen Kohlepartikel im Wind und löscht die Kernwärme augenblicklich.\",\n    \"consequence\": \"Ein Scheitern der Feuerzündung bei Kälte beschleunigt das Absinken der Körperkerntemperatur und führt binnen 72 Stunden zum Tod durch Unterkühlung.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"Vollendete Bogenbohrer-Reibungszündung mit Glut\",\n    \"description\": \"Eine 400°C heiße Holzkohleglut aus der 45°-V-Kerbe, die sicher in das trockene Zundernest überführt und zu einer offenen Flamme entfacht wurde.\"\n  },\n  \"createdAt\": \"2026-10-09T16:05:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"07c74b6366705dce\"\n}","content/protocols/locales/02-friction-fire.en.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"Bow Drill Friction Fire Method\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[THREAT LEVEL: CRITICAL]\",\n  \"summary\": \"A primitive pyrotechnology protocol using mechanical friction between dry softwood and a bow drill to generate carbon dust embers exceeding 400°C, followed by concentrated aeration to achieve ignition.\",\n  \"timeRequired\": \"20 MINUTES\",\n  \"successRate\": \"85% (Dry Timber)\",\n  \"difficulty\": \"Tier 2 (Skilled Primitive)\",\n  \"outputPerHour\": \"1 Fire / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Bow & Vine String (BOW & STRING)\",\n      \"desc\": \"Flexible hardwood limb (ash/hazel, 60-70cm) and durable wild kudzu vine cord\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Rotational Spindle (SPINDLE)\",\n      \"desc\": \"Straight 2cm dia x 20cm dry cedar or willow shaft. Blunt top, 45-degree tapered bottom.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Hearth Board & Tinder Nest (HEARTH & TINDER)\",\n      \"desc\": \"15-20mm thick hearth board with 45° V-notch, ember collection leaf, and dry tinder nest\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"V-Notch Carving & Spindle Axis Seating\",\n      \"description\": \"Carve a precise 45-degree V-notch from the outer edge of the hearth board penetrating directly to the socket center. Place a dry ember collector leaf beneath to trap hot carbon dust.\",\n      \"actionNote\": \"> Field Rule: If the notch angle exceeds 60 degrees, thermal dissipation will prevent the dust from reaching the 400°C ignition threshold.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"EMBER CATCHER LEAF [DRY BARK/LEAF]\",\n        \"45° V-NOTCH (Apex Meets Axis Center)\",\n        \"Ø 20mm SPINDLE AXIS\",\n        \"THICKNESS: 15~20mm\",\n        \"HEARTH BOARD (SOFTWOOD)\",\n        \"NOTCH APEX (Aligned with Socket Center)\",\n        \"CRITICAL SETUP RULE:\",\n        \"Notch apex must touch spindle axis center\",\n        \"CARBON DUST ACCUMULATION ZONE (EMBER BED)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"90° Downward Load & High-Speed Reciprocating Sawing\",\n      \"description\": \"Anchor the hearth board firmly with your left foot and apply 12-15kg downward load using the bearing block. Saw the bow horizontally with full-length strokes at 300-400 RPM until dense white smoke bursts.\",\n      \"actionNote\": \"> Field Rule: Do not stop when smoke first appears. Continue 10-15 full-power acceleration strokes to ensure complete carbonization in the notch.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"BEARING BLOCK (HAND SOCKET)\",\n        \"F_DOWN: 12~15 kg (Vertical Load)\",\n        \"BOW STICK (65cm Curved Limb)\",\n        \"FULL-STROKE RECIPROCATING MOTION (Full Bow Length)\",\n        \"ω: 300~400 RPM\",\n        \"HEARTH BOARD\",\n        \"WHITE SMOKE (Dense Smoke Plume)\",\n        \"CRITICAL THRESHOLD:\",\n        \"Ignition Temp: 400°C+\",\n        \"Load: Start 30% → Final 100%\",\n        \"Stroke: Use 100% Bow Length\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Ember Transfusion & Gentle Aeration Ignition\",\n      \"description\": \"Allow the smoking carbon dust to coalesce into a cohesive coal for 30 seconds. Carefully transfer it into the center of a dry tinder nest, cup at a 45-degree elevation, and supply steady, gentle breaths to ignite flame.\",\n      \"actionNote\": \"> Field Rule: Hold the nest at a 45-degree angle slightly above eye level. Rising thermal updrafts double oxygen intake while keeping smoke away from eyes.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"EMBER CORE (450°C)\",\n        \"GENTLE CONTINUOUS BREATH (Steady Low Airflow)\",\n        \"FLAME IGNITION BURST (Flashover Stage)\",\n        \"45° ELEVATION CUPPING\",\n        \"TEMPERATURE RISE & IGNITION MATRIX\",\n        \"TIME (sec)\",\n        \"TEMP (°C)\",\n        \"600°C FLAME IGNITION THRESHOLD\",\n        \"400°C CARBON SMOLDER POINT\",\n        \"Coalesce 30s & Transfer (0s)\",\n        \"Flame Ignition (15~20s)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Never blow rashly on premature uncoalesced embers\",\n    \"description\": \"Blowing prematurely on loose carbon dust will scatter the delicate ember particles, extinguishing the core heat immediately.\",\n    \"consequence\": \"Failure to start a fire in wilderness freezing conditions leads to irreversible hypothermia and death within 72 hours.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"Completed Bow Drill Friction Fire & Ember Ignition\",\n    \"description\": \"A glowing 400°C charcoal ember generated in the 45° V-notch smoking heavily, transferred safely into a dry tinder nest and fanned into an open flame.\"\n  },\n  \"createdAt\": \"2026-10-09T16:05:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"07c74b6366705dce\"\n}","content/protocols/locales/02-friction-fire.es.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"Fuego por Fricción con Arco Táctico (Bow Drill)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[NIVEL DE AMENAZA: CRÍTICO]\",\n  \"summary\": \"Técnica pirotécnica primitiva que utiliza la fricción mecánica entre madera blanda seca y un huso giratorio para generar brasas de carbón a más de 400°C, seguida de oxigenación controlada.\",\n  \"timeRequired\": \"20 MINUTOS\",\n  \"successRate\": \"85% (Madera Seca)\",\n  \"difficulty\": \"Nivel 2 (Habilidad Técnica)\",\n  \"outputPerHour\": \"1 Fuego / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Arco y Cuerda de Fibra Natural (BOW & STRING)\",\n      \"desc\": \"Rama firme y flexible de 60-70 cm (fresno/avellano) y cuerda resistente de fibra de kudzu.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Huso Giratorio (SPINDLE)\",\n      \"desc\": \"Cilindro recto de cedro o sauce seco de Ø 20 mm. Extremo superior romo, punta inferior a 45°.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Tabla Base con Muesca V y Yesca (HEARTH & TINDER)\",\n      \"desc\": \"Tabla de 15-20 mm con muesca en V de 45°, hoja recolectora y nido de yesca seca.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Tallado de Muesca en V (45°) y Asiento del Huso\",\n      \"description\": \"Talle una muesca en V precisa de 45 grados desde el borde exterior de la tabla hasta el centro exacto del eje del huso. Coloque una hoja seca debajo para recoger el polvo de carbón caliente.\",\n      \"actionNote\": \"> Regla de Campo: Si el ángulo de la muesca supera los 60°, el calor se dispersa y nunca alcanzará el umbral de ignición de 400°C.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"HOJA RECOLECTORA [BASE DE BRASA]\",\n        \"MUESCA EN V 45° (Vértice en Centro)\",\n        \"EJE HUSO Ø 20mm\",\n        \"ESPESOR: 15~20mm\",\n        \"TABLA BASE (HEARTH BOARD)\",\n        \"VÉRTICE (Alineado al Centro del Huso)\",\n        \"REGLA CRÍTICA DE AJUSTE:\",\n        \"El vértice en V debe tocar el centro del eje\",\n        \"ZONA DE ACUMULACIÓN DE POLVO DE CARBÓN\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Carga Vertical de 90° yRotación Recíproca de Alta Velocidad\",\n      \"description\": \"Fije la tabla con el pie izquierdo y aplique 12-15 kg de carga vertical con el bloque de apoyo. Deslice el arco horizontalmente usando el 100% de su longitud a 300-400 RPM hasta que brote humo blanco denso.\",\n      \"actionNote\": \"> Regla de Campo: No se detenga al ver el primer humo. Realice 10-15 carreras adicionales a máxima potencia para consolidar la brasa.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"BLOQUE DE APOYO (SOCKET MANUAL)\",\n        \"F_DOWN: 12~15 kg (Carga Vertical)\",\n        \"ARCO TÁCTICO (Rama 65cm)\",\n        \"MOVIMIENTO RECÍPROCO DE CARRERA COMPLETA\",\n        \"ω: 300~400 RPM\",\n        \"TABLA BASE\",\n        \"HUMO BLANCO (Emisión Densa)\",\n        \"UMBRAL CRÍTICO:\",\n        \"Temp. Ignición: 400°C+\",\n        \"Presión: Inicio 30% → Final 100%\",\n        \"Carrera: 100% Longitud del Arco\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Trasplante de Brasa y Oxigenación Suave a 45°\",\n      \"description\": \"Espere 30 segundos para que el polvo humeante se cohesione en una brasa sólida (450°C). Trasládela al nido de yesca, elévelo a 45° y sople suave y continuamente hasta alcanzar 600°C y encender la llama.\",\n      \"actionNote\": \"> Regla de Campo: Sostenga la yesca a 45° por encima del nivel de los ojos para aprovechar la corriente térmica ascendente y evitar el humo.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"NÚCLEO BRASA (450°C)\",\n        \"SOPLO SUAVE Y CONTINUO (Flujo Lento)\",\n        \"IGNICIÓN DE LLAMA (Brote Térmico)\",\n        \"ELEVACIÓN A 45°\",\n        \"MATRIZ DE TEMPERATURA E IGNICIÓN\",\n        \"TIEMPO (s)\",\n        \"TEMP (°C)\",\n        \"600°C UMBRAL DE LLAMA ABIERTA\",\n        \"400°C PUNTO DE BRASA ACTIVA\",\n        \"30s Cohesión y Traslado (0s)\",\n        \"Ignición Llama (15~20s)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Nunca sople bruscamente sobre polvo de carbón recién formado\",\n    \"description\": \"Soplar con fuerza inmediatamente después de detener la fricción dispersará las partículas de carbón no cohesionadas, apagando el núcleo térmico al instante.\",\n    \"consequence\": \"El fallo de ignición en condiciones invernales acelera la pérdida de calor corporal, causando muerte por hipotermia en 72 horas.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"Ignición de Brasa por Fricción con Arco Completada\",\n    \"description\": \"Una brasa incandescente a 400°C generada en la ranura en V, transferida con éxito al nido de yesca seca y avivada hasta producir una llama viva.\"\n  },\n  \"createdAt\": \"2026-10-09T16:05:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"07c74b6366705dce\"\n}","content/protocols/locales/02-friction-fire.ja.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"ボウドリル摩擦発火法\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[危険等級: 致命的(CRITICAL)]\",\n  \"summary\": \"乾燥した軟木と弓を組み合わせた機械的摩擦熱により、400℃以上の微細炭化粉末(火種)を形成し、集中通気により炎を着火させる原始中核熱源技術。\",\n  \"timeRequired\": \"20分 (20 MINUTES)\",\n  \"successRate\": \"85% (乾燥材基準)\",\n  \"difficulty\": \"第2等級 (熟練技術)\",\n  \"outputPerHour\": \"1 Fire / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"弓と葛繊維の弦 (BOW & STRING)\",\n      \"desc\": \"長さ60~70cmの弾力ある堅木(トネリコ等)と強靭な天然葛繊維コード\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"回転軸スピンドル (SPINDLE)\",\n      \"desc\": \"直径2cm×長さ20cmの乾燥スギ/ヤナギの直棒。先端は鈍角、下端は45度円錐加工。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"V字溝火床板＆火口 (HEARTH & TINDER)\",\n      \"desc\": \"厚さ15~20mmの45°Vノッチ火床板、火種受け葉、乾燥した鳥の巣型火口\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"V字溝(ノッチ)加工およびスピンドル軸セットアップ\",\n      \"description\": \"火床板の外縁からソケット中心に向かって45度の鋭利なV字溝を切り込みます。削り出された炭化粉末が逃げずに集積できるよう、板の下に幅広の乾燥葉を敷きます。\",\n      \"actionNote\": \"> 野戦核心: ノッチの頂角が60度以上に広がると熱が逃げ、発火点(400℃)に到達しません。厳密な45度を維持してください。\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"EMBER CATCHER LEAF [火種受け葉]\",\n        \"45° V-NOTCH (溝頂点: 軸中心に接触)\",\n        \"Ø 20mm スピンドル軸\",\n        \"板厚: 15~20mm\",\n        \"HEARTH BOARD (火床板)\",\n        \"ノッチ頂点 (ソケット中心と一致)\",\n        \"重要セットアップ規則:\",\n        \"V溝の頂点はスピンドル軸中心と正確に接触\",\n        \"CARBON DUST ZONE (炭化火種集積区域)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"90度垂直加圧および高速往復摩擦回転\",\n      \"description\": \"左足で火床板を踏み込み、ハンドブロックでスピンドルを垂直に12~15kgの荷重で押さえ込みます。弓を水平に保ち全ストロークで往復させ、濃厚な白煙が出るまで300~400RPMで回転させます。\",\n      \"actionNote\": \"> 野戦核心: 煙が出てもすぐに止めないでください。発煙後、最低10~15回の全力加速ストロークを継続し、完全に炭化結合させます。\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"BEARING BLOCK (ハンドソケット)\",\n        \"F_DOWN: 12~15 kg (垂直荷重)\",\n        \"BOW STICK (長さ65cm 弓枝)\",\n        \"FULL-STROKE MOTION (弓全長での往復ストローク)\",\n        \"ω: 300~400 RPM\",\n        \"HEARTH BOARD\",\n        \"WHITE SMOKE (濃密な白煙放出)\",\n        \"臨界しきい値:\",\n        \"発火温度: 400°C+\",\n        \"加圧比率: 初期30% → 終期100%\",\n        \"ストローク: 弓全長100%使用\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"炭化火種の火口移植および緩慢通気着火\",\n      \"description\": \"火種受け葉に落ちた黒色粉末が自活煙を維持するまで30秒待機します。固まった火種を火口の中央に移し、45度の角度で持ち上げて穏やかで均一な息を吹き込み、600℃以上に急上昇させて発火させます。\",\n      \"actionNote\": \"> 野戦核心: 目線より少し高い45度上方に火口を掲げてください。煙が目を刺激するのを防ぎ、上昇気流が酸素吸入効率を倍増させます。\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"火種コア (450°C)\",\n        \"GENTLE BREATH (均一な低速送風)\",\n        \"FLAME IGNITION (自然発火・着火段階)\",\n        \"45° 上方保持\",\n        \"温度上昇＆着火マトリックス\",\n        \"時間 (秒)\",\n        \"温度 (°C)\",\n        \"600°C 火炎発火しきい値\",\n        \"400°C 炭化燻焼ポイント\",\n        \"30秒凝集後に移植 (0秒)\",\n        \"火炎着火 (15~20秒)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"未形成の火種に性急に強い息を吹き込んではならない\",\n    \"description\": \"摩擦停止直後に焦ってバラバラの黒色木粉に直接強い息を吹き込むと、微細炭化粒子が飛散し、中核熱源が瞬時に消滅します。\",\n    \"consequence\": \"寒冷荒野環境での着火失敗は深部体温低下を加速させ、72時間以内の低体温症死に直結します。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"ボウドリル摩擦発火および火種着火の完成形態\",\n    \"description\": \"火床板の45度V溝に摩擦熱で生じた黒い炭粉の熾火(400°C)が赤く燃え上がり、これを乾燥した火口の巣に移して炎を立ち上げた実戦発火の完成状態です。\"\n  },\n  \"createdAt\": \"2026-10-09T16:05:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"07c74b6366705dce\"\n}","content/protocols/locales/02-friction-fire.pt.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"Fogo por Fricção com Arco e Fuso (Bow Drill)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[NÍVEL DE AMEAÇA: CRÍTICO]\",\n  \"summary\": \"Tecnologia primitiva de ignição que utiliza o atrito mecânico entre madeira macia seca e um fuso rotativo para gerar brasa de carvão acima de 400°C, seguida de oxigenação controlada.\",\n  \"timeRequired\": \"20 MINUTOS\",\n  \"successRate\": \"85% (Madeira Seca)\",\n  \"difficulty\": \"Nível 2 (Habilidade Técnica)\",\n  \"outputPerHour\": \"1 Fogo / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Arco e Corda de Fibra Natural (BOW & STRING)\",\n      \"desc\": \"Galho resistente de 60-70 cm (freixo/aveleira) e corda firme de fibra natural de kudzu.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Fuso Rotativo (SPINDLE)\",\n      \"desc\": \"Haste cilíndrica reta de cedro ou salgueiro seco (Ø 20 mm). Topo arredondado, ponta inferior a 45°.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Prancha Base com Entalhe V e Isca (HEARTH & TINDER)\",\n      \"desc\": \"Prancha de 15-20 mm com entalhe em V de 45°, folha coletora de brasa e ninho de fibras secas.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Entalhe em V de 45° e Assentamento do Eixo do Fuso\",\n      \"description\": \"Esculpa um entalhe em V de 45 graus da borda frontal da prancha até o centro exato do soquete do fuso. Posicione uma folha seca abaixo da abertura para acumular o pó de carvão quente.\",\n      \"actionNote\": \"> Regra de Campo: Se o ângulo do entalhe passar de 60°, o calor se dissipa e o pó nunca atingirá o ponto de ignição de 400°C.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"FOLHA COLETORA [BASE DE BRASA]\",\n        \"ENTALHE EM V 45° (Vértice no Centro)\",\n        \"EIXO FUSO Ø 20mm\",\n        \"ESPESSURA: 15~20mm\",\n        \"PRANCHA BASE (HEARTH BOARD)\",\n        \"VÉRTICE (Alinhado ao Centro do Fuso)\",\n        \"REGRA CRÍTICA DE MONTAGEM:\",\n        \"O vértice em V deve tocar o centro do eixo\",\n        \"ZONA DE ACÚMULO DE PÓ DE CARVÃO (BRASA)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Carga Vertical de 90° e Rotação Recíproca de Curso Total\",\n      \"description\": \"Trave a prancha com o pé esquerdo e aplique 12-15 kg de pressão vertical no bloco de apoio. Movimente o arco horizontalmente usando 100% do comprimento a 300-400 RPM até emitir fumaça branca densa.\",\n      \"actionNote\": \"> Regra de Campo: Não pare na primeira fumaça. Execute mais 10 a 15 cursos em potência máxima para fundir a brasa no entalhe.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"BLOCO DE APOIO (SOQUETE MANUAL)\",\n        \"F_DOWN: 12~15 kg (Carga Vertical)\",\n        \"ARCO TÁTICO (Galho 65cm)\",\n        \"MOVIMENTO RECÍPROCO DE CURSO TOTAL\",\n        \"ω: 300~400 RPM\",\n        \"PRANCHA BASE\",\n        \"FUMAÇA BRANCA (Emissão Densa)\",\n        \"LIMIAR CRÍTICO:\",\n        \"Temp. Ignição: 400°C+\",\n        \"Pressão: Início 30% → Final 100%\",\n        \"Curso: 100% do Arco\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Transplante da Brasa e Sopro Suave de Ignição (600°C)\",\n      \"description\": \"Aguarde 30 segundos para o pó fumegante coalescer em uma brasa firme (450°C). Transfira para o centro do ninho de isca, eleve a 45° e sopre de forma suave e contínua até romper em chama a 600°C.\",\n      \"actionNote\": \"> Regra de Campo: Segure o ninho a 45° acima da linha dos olhos; a corrente térmica ascendente dobra a oxigenação e afasta a fumaça.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"NÚCLEO BRASA (450°C)\",\n        \"SOPRO SUAVE E CONTÍNUO (Fluxo Lento)\",\n        \"IGNIÇÃO DE CHAMA (Combustão)\",\n        \"ELEVAÇÃO A 45°\",\n        \"MATRIZ DE TEMPERATURA E IGNIÇÃO\",\n        \"TEMPO (s)\",\n        \"TEMP (°C)\",\n        \"600°C LIMIAR DE CHAMA ABERTA\",\n        \"400°C PONTO DE BRASA ATIVA\",\n        \"30s Coesão e Transplante (0s)\",\n        \"Ignição Chama (15~20s)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Nunca sopre com força sobre a brasa recém-formada\",\n    \"description\": \"Soprar precipitadamente sobre o pó de carvão solto espalhará as partículas incandescentes pelo ar, extinguindo a fonte de calor instantaneamente.\",\n    \"consequence\": \"A falha na obtenção de fogo em ambiente frio acelera a queda da temperatura corporal central, levando à morte por hipotermia em 72 horas.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"Ignição por Fricção com Arco e Brasa Concluída\",\n    \"description\": \"Uma brasa incandescente a 400°C gerada na ranhura em V, transferida com sucesso para o ninho de mecha seca e soprada até formar chamas vivas.\"\n  },\n  \"createdAt\": \"2026-10-09T16:05:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"07c74b6366705dce\"\n}","content/protocols/locales/02-friction-fire.zh-TW.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"弓鑽摩擦生火技術 (Bow Drill)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[威脅等級：致命 (CRITICAL)]\",\n  \"summary\": \"結合乾燥軟木與弓弦往復機械摩擦，產生400°C以上之高溫碳化木屑火種(Ember)，並透過精準供氧引燃明火的核心原始熱源技術。\",\n  \"timeRequired\": \"20分鐘 (20 MINUTES)\",\n  \"successRate\": \"85% (乾燥木材基準)\",\n  \"difficulty\": \"第2級 (進階求生技術)\",\n  \"outputPerHour\": \"1 Fire / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"弓桿與葛藤纖維繩 (BOW & STRING)\",\n      \"desc\": \"長60~70公分具韌性之硬木枝條，搭配強韌天然葛藤纖維繩。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"旋轉鑽軸 (SPINDLE)\",\n      \"desc\": \"直徑20mm之乾燥香杉或柳木直圓棒，頂端鈍角減阻、底端削成45度圓錐。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"V型槽鑽火底板與火絨巢 (HEARTH & TINDER)\",\n      \"desc\": \"厚15~20mm之45度V槽底板、火種收集乾葉，以及鳥巢狀乾燥植物纖維火絨。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"45° V型槽切削與鑽軸中心定位\",\n      \"description\": \"從底板外緣向凹槽中心精準切出45度V型集屑槽，使V槽頂點正好接觸鑽軸中心。底板下方緊貼乾燥寬葉片以完整收集高溫碳化木屑。\",\n      \"actionNote\": \"> 野戰核心：若V型槽角度超過60度，摩擦熱將迅速散失而無法達到400°C燃點，務必維持精準45度楔形開口。\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"EMBER CATCHER [火種收集葉片]\",\n        \"45° V型槽 (槽頂點接觸鑽軸中心)\",\n        \"Ø 20mm 鑽軸 (SPINDLE)\",\n        \"板厚: 15~20mm\",\n        \"鑽火底板 (HEARTH BOARD)\",\n        \"V槽頂點 (與凹槽中心點完全重疊)\",\n        \"關鍵設置法則:\",\n        \"V型槽頂點必須精準接觸鑽軸中心\",\n        \"碳化木屑堆積區 (火種凝聚處)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"90度垂直加壓與全行程高速往復拉弓\",\n      \"description\": \"左腳踩穩底板，手塊垂直施加12~15公斤下壓力。保持弓桿水平並使用100%弓長進行全行程推拉(300~400 RPM)，直至噴出濃密白煙。\",\n      \"actionNote\": \"> 野戰核心：冒出白煙時切勿立即停手，必須再全力加速推拉10~15次，使V槽內的碳化木屑完全凝聚成火種。\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"頂壓手塊 (BEARING BLOCK)\",\n        \"F_DOWN: 12~15 kg (垂直下壓力)\",\n        \"弓桿 (長65cm 堅韌木枝)\",\n        \"全行程往復拉動 (100%弓長推拉)\",\n        \"ω: 300~400 RPM\",\n        \"HEARTH BOARD\",\n        \"濃密白煙 (炭化達標訊號)\",\n        \"臨界指標:\",\n        \"燃點溫度: 400°C+\",\n        \"加壓比例: 初期30% → 末期100%\",\n        \"行程: 使用100%弓桿全長\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"火種移植火絨巢與45度仰角緩慢吹氣點火\",\n      \"description\": \"靜置30秒讓碳粉凝聚為450°C穩固火種後，小心移入火絨巢中央。以45度仰角托舉火絨，持續吹入均勻低速氣流，使溫度突破600°C引燃明火。\",\n      \"actionNote\": \"> 野戰核心：托舉高度應略高於視線呈45度角，避免濃煙嗆傷眼睛並利用熱對流使供氧效率倍增。\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"火種核心 (450°C)\",\n        \"平穩緩慢吹氣 (均勻低速供氧)\",\n        \"火焰爆發點燃 (自燃階段)\",\n        \"45° 仰角托舉\",\n        \"溫度攀升與點火矩陣\",\n        \"時間 (秒)\",\n        \"溫度 (°C)\",\n        \"600°C 明火點燃臨界線\",\n        \"400°C 碳粉悶燒點\",\n        \"凝聚30秒後移植 (0秒)\",\n        \"明火點燃 (15~20秒)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"切勿對尚未凝聚成形的碳粉急促吹氣\",\n    \"description\": \"停止摩擦後若急忙對鬆散的黑色木屑用力吹氣，未結合的微細碳粒會瞬間被吹散，導致核心熱源立即熄滅。\",\n    \"consequence\": \"在寒冷野外環境中生火失敗將加速核心體溫流失，於72小時內引發不可逆之失溫死亡。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"弓鑽摩擦生火與火種點燃完成形態\",\n    \"description\": \"火板45度V型槽內藉由摩擦熱生成的400°C黑炭灰餘燼劇烈冒煙，安全轉移至乾燥引火鳥巢並吹拂出明火的實戰生火完成狀態。\"\n  },\n  \"createdAt\": \"2026-10-09T16:05:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"07c74b6366705dce\"\n}","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.de.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Laubhütte (Debris Hut) A-Rahmen-Isolationsunterstand\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[GEFAHRENSTUFE: KRITISCH]\",\n  \"summary\": \"Ungeschützte Kälte- und Nässeexposition führt binnen 3 Stunden zu tödlicher Unterkühlung. Durch geometrisches Schichten von trockenem Laub und Totholz entsteht eine stehende Luftschicht (Dead Air Space), die allein durch 80–100W Körperwärme das Überleben sichert.\",\n  \"timeRequired\": \"90–120 MINUTEN\",\n  \"successRate\": \"92.4% (bei ≥60cm Isolationsschicht)\",\n  \"difficulty\": \"Stufe 2 (Schwerer Primitivbau)\",\n  \"outputPerHour\": \"1 Unterstand (≥1.5m³ Isolationsvolumen)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Firstbalken (Ridge Pole)\",\n      \"desc\": \"1 gerader, trockener Hartholzstamm (Länge 3.0–3.5m, Ø 10–15cm)\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Y-Stützgabeln & Rippenäste (Rib Sticks)\",\n      \"desc\": \"2 Y-Stützen (1.5m, Ø 5–8cm) sowie 40–50 Seitenäste (1.0–1.5m)\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Trockenes Laub & Waldstreu (Dry Debris)\",\n      \"desc\": \"2–3m³ knochentrockenes Laub, Kiefernnadeln, trockenes Gras und Rinde\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"A-Rahmen-Stütze errichten & Firstbalken verankern\",\n      \"description\": \"Verschränken Sie zwei Y-Gabelhölzer an der Spitze (oder binden Sie diese mit Ranken) und legen Sie den Firstbalken in 0.8–1.0m Höhe auf. Verankern Sie das hintere Ende direkt auf der Windseite im Boden. Der Innenraum darf nur so breit sein, dass Sie knapp hineinkriechen können.\",\n      \"actionNote\": \"> FELDREGEL: Zu großes Innenvolumen verhindert die Erwärmung durch Körperwärme. Striktes Sargmaß einhalten: maximal eine Faustbreit (≤10cm) Abstand.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [INNENVOLUMEN]:\",\n        \"Striktes Sargmaß: max. +10cm (1 Faust) Körperabstand\",\n        \"WINDWARD (Windseitiger Anker)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (Firstbalken)\",\n        \"Y-BIPOD & VINE LASHING (Y-Stützverbindung)\",\n        \"COFFIN CLEARANCE: +10cm (Max. 1 Faust Spielraum)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Rippengitter anlegen & Boden-Isoliermatratze verdichten\",\n      \"description\": \"Lehnen Sie Rippenäste im 45°–60°-Winkel dicht an beide Seiten des Firstbalkens. Schichten Sie sofort mindestens 40cm trockenes Laub auf den Boden, sodass auch unter Körpergewicht 15–20cm Isolierstärke verbleiben.\",\n      \"actionNote\": \"> PHYSIK-PRINZIP: Kalter Boden leitet Wärme dutzendfach schneller ab als Luft. Ohne 15–20cm Bodenisolierung droht rascher Kälteschock.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [BODENISOLIERUNG]:\",\n        \"Bodenkälte blockieren: ≥15~20cm komprimierte Matte\",\n        \"RIDGEPOLE SPINE (Firstbalken-Schnitt)\",\n        \"RIB LATTICE: 45°~60° (Rippengitter)\",\n        \"MATTRESS: 40cm → 20cm (Laubmatratze)\",\n        \"GROUND COLD CONDUCTION BLOCKED\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"60–90cm Außenisolierung & Sturmsicherung\",\n      \"description\": \"Decken Sie das Gitter mit Reisig ab und schichten Sie trockenes Laub von unten nach oben 60–90cm (Armlänge) dick auf. Beschweren Sie die Hülle mit schweren Totholzästen gegen Wind und verschließen Sie den Eingang mit einem Laubpfropfen.\",\n      \"actionNote\": \"> WARNUNG: Nasses Laub isoliert nicht und entzieht Wärme durch Verdunstung. Steile Außenneigung zur Regenabweisung beibehalten.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [WANDAUFBAU]:\",\n        \"60~90cm trockene Laubschicht + Eingangspfropfen\",\n        \"DEBRIS WALL: 60~90cm (Laubdämmung)\",\n        \"DEADWOOD ARMOR (Windschutz-Äste)\",\n        \"WATER SHEDDING SLOPE (Regenablauf)\",\n        \"DEAD AIR CORE & PLUG SEAL (Thermokammer)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Zu großer Innenraum & feuchtes Laub\",\n    \"description\": \"Ein hoher Innenraum zum Sitzen kann durch 80–100W menschliche Stoffwechselwärme nicht erwärmt werden. Feuchtes Laub verwandelt den Unterstand zudem in eine tödliche Kühlkammer.\",\n    \"consequence\": \"Folge: Wärmeverlust durch Leitung und Konvektion senkt die Kerntemperatur im Schlaf unter 30°C – Tod durch Unterkühlung.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Vollendete A-Rahmen Laub-Notunterkunft (Debris Hut)\",\n    \"description\": \"Ein massiver 2,5m Dachfirst und ein 45°-Rippenrahmen, umhüllt von einer 1 Meter dicken Schicht aus trockenem Laub, die Körperwärme ohne Feuer speichert.\"\n  },\n  \"createdAt\": \"2026-10-09T16:08:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"042045342785ab42\"\n}","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.en.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Debris Hut A-Frame Thermal Shelter Construction\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[THREAT LEVEL: CRITICAL]\",\n  \"summary\": \"Direct exposure to freezing wind and rain causes fatal hypothermia within 3 hours. By geometrically layering dry forest litter and deadwood to trap Dead Air Space, you build a zero-fire survival shelter that maintains core body temperature purely through human metabolic radiant heat (80–100W).\",\n  \"timeRequired\": \"90–120 MINUTES\",\n  \"successRate\": \"92.4% (with ≥60cm insulation depth)\",\n  \"difficulty\": \"Tier 2 (Heavy Primitive Construction)\",\n  \"outputPerHour\": \"1 Shelter (≥1.5m³ insulated volume)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Ridge Pole (Primary Spine)\",\n      \"desc\": \"1 straight, solid dry hardwood log (length 3.0–3.5m, diameter 10–15cm)\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Y-Frame Bipod & Rib Sticks\",\n      \"desc\": \"2 Y-forked support poles (length 1.5m, Ø 5–8cm) and 40–50 rib branches (length 1.0–1.5m)\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Dry Forest Debris (Thermal Mass)\",\n      \"desc\": \"2–3m³ of bone-dry leaves, pine needles, dry ferns, and shredded bark\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Erect A-Frame Bipod & Anchor Ridgepole\",\n      \"description\": \"Interlock two Y-forked support sticks at the apex (or lash with wild vine) to form a sturdy bipod, then seat one end of the ridgepole into the fork at 0.8–1.0m height. Anchor the tail end directly into the ground facing into the wind (windward). Size the interior strictly so your body barely crawls inside.\",\n      \"actionNote\": \"> FIELD RULE: Excess interior volume prevents metabolic heat from warming the air pocket, resulting in death by hypothermia. Enforce strict coffin clearance—leave only one fist (≤10cm) around your shoulders.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [INTERIOR SPEC]:\",\n        \"Strict Coffin Spec: max +10cm (1 fist) body clearance\",\n        \"WINDWARD (Ground Anchor)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (Hardwood Spine)\",\n        \"Y-BIPOD & VINE LASHING (Apex Joint)\",\n        \"COFFIN CLEARANCE: +10cm (1 Fist Max Gap)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Lay Rib Lattice & Pack High-Density Floor Mattress\",\n      \"description\": \"Lean rib sticks tightly along both sides of the ridgepole at a 45°–60° angle to form a dense lattice wall that prevents debris from falling through. Immediately pack at least 40cm of bone-dry leaves onto the floor so that even under full body weight it remains 15–20cm thick.\",\n      \"actionNote\": \"> PHYSICS PRINCIPLE: Cold ground conducts heat away dozens of times faster than still air. Without a compressed 15–20cm floor mattress, conductive heat loss triggers hypothermia shock rapidly.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [FLOOR INSULATION]:\",\n        \"Block ground conduction: keep ≥15~20cm compressed bed\",\n        \"RIDGEPOLE SPINE (Cross-Section)\",\n        \"RIB LATTICE: 45°~60° (Branch Grid)\",\n        \"MATTRESS: 40cm → 20cm (Leaf Bed)\",\n        \"GROUND COLD CONDUCTION BLOCKED\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Shingle 60–90cm Outer Debris & Armor Against Wind\",\n      \"description\": \"Cover the rib lattice with fine brush, then pile dry leaves from bottom to top like roof shingles to a thickness of 60–90cm (full arm's length). Lay heavy dead branches over the entire mound to prevent wind stripping, and seal the entrance tightly with a dense leaf plug.\",\n      \"actionNote\": \"> CAUTION: Wet debris has zero insulation value and steals body heat via evaporative cooling. Maintain a steep outer slope to shed rain while keeping the inner core bone-dry.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [WALL SPEC]:\",\n        \"60~90cm dry leaf mound + full entrance plug seal\",\n        \"DEBRIS WALL: 60~90cm (Dry Leaves)\",\n        \"DEADWOOD ARMOR (Wind-Weight Branches)\",\n        \"WATER SHEDDING SLOPE (Rain Drain)\",\n        \"DEAD AIR CORE & PLUG SEAL (Thermal Chamber)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Error: Building an Oversized Cabin & Mixing Wet Debris\",\n    \"description\": \"Raising the ceiling for sitting comfort creates a large air pocket that human basal metabolism (80–100W) cannot heat. Furthermore, packing damp leaves into the floor or walls turns the shelter into a conductive evaporative cooler.\",\n    \"consequence\": \"Consequence: Combined conductive and convective heat loss drops core body temperature below 30°C during sleep, causing fatal hypothermia.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Completed A-Frame Debris Hut Thermal Shelter\",\n    \"description\": \"A 2.5m heavy ridgepole and 45° rib frame blanketed by 1 meter of compressed dry leaves and thatch branches, trapping body heat down to sub-zero temperatures without fire.\"\n  },\n  \"createdAt\": \"2026-10-09T16:08:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"042045342785ab42\"\n}","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.es.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Construcción de Refugio Térmico A-Frame (Debris Hut)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[NIVEL DE AMENAZA: CRÍTICO]\",\n  \"summary\": \"La exposición al frío y la lluvia causa hipotermia mortal en 3 horas. Al apilar hojarasca seca y madera muerta para atrapar aire estancado (Dead Air Space), se construye un refugio sin fuego que conserva el calor metabólico humano (80–100W).\",\n  \"timeRequired\": \"90–120 MINUTOS\",\n  \"successRate\": \"92.4% (con ≥60cm de aislamiento)\",\n  \"difficulty\": \"Nivel 2 (Construcción Primitiva Intensiva)\",\n  \"outputPerHour\": \"1 Refugio (volumen aislado ≥1.5m³)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Viga Cumbrera (Ridge Pole)\",\n      \"desc\": \"1 tronco recto y seco de madera dura (longitud 3.0–3.5m, diámetro 10–15cm)\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Soportes en Y y Costillas (Rib Sticks)\",\n      \"desc\": \"2 horquillas en Y (1.5m, Ø 5–8cm) y 40–50 ramas laterales (1.0–1.5m)\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Hojarasca Seca Aislante (Dry Debris)\",\n      \"desc\": \"2–3m³ de hojas secas, agujas de pino, helechos secos y corteza suelta\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Erigir Bípode en A y Anclar Viga Cumbrera\",\n      \"description\": \"Entrelace dos horquillas en Y en la cúspide (o átelas con lianas) y apoye un extremo de la viga cumbrera a 0.8–1.0m de altura. Ancle el extremo opuesto en el suelo hacia el viento (barlovento). El interior debe ser tan estrecho que apenas permita entrar arrastrándose.\",\n      \"actionNote\": \"> REGLA DE CAMPO: Un volumen excesivo impide calentar el aire con calor corporal. Mantenga espacio de ataúd: solo un puño (≤10cm) alrededor del cuerpo.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [VOLUMEN INTERIOR]:\",\n        \"Espacio tipo ataúd: máx. +10cm (1 puño) de holgura\",\n        \"WINDWARD (Anclaje Barlovento)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (Viga Cumbrera)\",\n        \"Y-BIPOD & VINE LASHING (Unión en Y)\",\n        \"COFFIN CLEARANCE: +10cm (Holgura 1 Puño)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Colocar Costillas y Colchón Térmico de Suelo\",\n      \"description\": \"Apoye ramas laterales a 45°–60° a ambos lados de la viga para formar una rejilla cerrada. Cubra inmediatamente el suelo con al menos 40cm de hojas secas para que, al comprimirse con el peso corporal, conserve 15–20cm de espesor aislante.\",\n      \"actionNote\": \"> PRINCIPIO FÍSICO: La conducción térmica del suelo frío es decenas de veces mayor que la del aire. Sin aislamiento basal, el suelo drena todo el calor corporal.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [AISLAMIENTO BASAL]:\",\n        \"Bloquear conducción: mantener ≥15~20cm comprimido\",\n        \"RIDGEPOLE SPINE (Sección Cumbrera)\",\n        \"RIB LATTICE: 45°~60° (Costillas)\",\n        \"MATTRESS: 40cm → 20cm (Cama de Hojas)\",\n        \"GROUND COLD CONDUCTION BLOCKED\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Apilar 60–90cm de Hojarasca y Blindaje Cortavientos\",\n      \"description\": \"Cubra la rejilla con ramitas finas y apile hojas secas desde abajo hacia arriba hasta alcanzar 60–90cm de grosor. Coloque ramas pesadas encima para evitar que el viento vuele el aislamiento y selle la entrada con un tapón denso de hojas.\",\n      \"actionNote\": \"> PRECAUCIÓN: La hojarasca húmeda no aísla y roba calor por evaporación. Mantenga una pendiente pronunciada para evacuar la lluvia.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [ESPEC. DE MURO]:\",\n        \"Muro de hojas de 60~90cm + tapón de entrada sellado\",\n        \"DEBRIS WALL: 60~90cm (Capa Aislante)\",\n        \"DEADWOOD ARMOR (Ramas de Peso)\",\n        \"WATER SHEDDING SLOPE (Drenaje)\",\n        \"DEAD AIR CORE & PLUG SEAL (Cámara Sellada)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error Mortal: Construir un Interior Amplio y Usar Hojas Húmedas\",\n    \"description\": \"Hacer el techo alto para sentarse crea una bolsa de aire demasiado grande para los 80–100W del metabolismo humano. Además, mezclar hojas húmedas convierte el refugio en una cámara frigorífica.\",\n    \"consequence\": \"Consecuencia: La pérdida térmica por conducción y convección reduce la temperatura central bajo 30°C durante el sueño, causando muerte por hipotermia.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Refugio Térmico Debris Hut en Marco A Completado\",\n    \"description\": \"Una viga maestra de 2.5 m y costillas a 45° cubiertas por 1 metro de hojas secas compactadas y ramas, conservando el calor corporal bajo cero sin fuego.\"\n  },\n  \"createdAt\": \"2026-10-09T16:08:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"042045342785ab42\"\n}","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.ja.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"デブリハット(Debris Hut) Aフレーム断熱シェルター構築法\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[危険度: 致命的(CRITICAL)]\",\n  \"summary\": \"極寒の風雨に晒されると3時間以内に致命的な低体温症に陥る。乾燥した落ち葉と枯れ木を幾何学的に積層して静止空気層(Dead Air Space)を形成し、火気なしで人体の代謝放射熱(80〜100W)のみで内部温度を生存圏に保つ原始シェルターを構築する。\",\n  \"timeRequired\": \"90〜120分 (90-120 MINUTES)\",\n  \"successRate\": \"92.4% (断熱厚60cm以上確保時)\",\n  \"difficulty\": \"等級2 (高強度原始築造技術)\",\n  \"outputPerHour\": \"1棟完成 (有効断熱容積1.5㎥以上)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"棟木・リッジポール(Ridge Pole)\",\n      \"desc\": \"長さ3.0〜3.5m、直径10〜15cmの曲がりのない堅고な乾燥広葉樹丸太 1本\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Y字支柱および肋木枝(A-Frame & Rib Sticks)\",\n      \"desc\": \"長さ1.5m・直径5〜8cmのY字支柱2本、および長さ1.0〜1.5mの肋木用枝40〜50本\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"乾燥断熱デブリ(Dry Debris)\",\n      \"desc\": \"水分を含まない乾燥落葉、松葉、枯れ草、樹皮屑など大量(最低2〜3立方メートル)\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Aフレーム支柱の架設と棟木の固定\",\n      \"description\": \"2本のY字支柱を上端で噛み合わせるか蔓で結束して三角支柱を立て、棟木の一端を交差部に乗せる(高さ0.8〜1.0m)。反対側の端は風上側の地面に密着させる。内部空間は身体が辛うじて潜り込める狭さに制限する。\",\n      \"actionNote\": \"> 野戦鉄則: 内部容積が広すぎると体温で空気を温められず凍死する。棺(Coffin)のように身体周囲に拳1個分(10cm)の隙間だけを残せ。\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [内部容積規格]:\",\n        \"棺(Coffin)規格厳守: 身体周囲に拳1個(10cm)の余裕のみ\",\n        \"WINDWARD (風上側地面密着)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (主棟木)\",\n        \"Y-BIPOD & VINE LASHING (Y字支柱結束)\",\n        \"COFFIN CLEARANCE: +10cm (拳1個分の隙間制限)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"肋木フレーム配置と高密度断熱マットレス敷設\",\n      \"description\": \"棟木の両側に肋木枝を45〜60度の角度で密に立てかけ、落ち葉が内部に崩れ落ちない格子壁を作る。直ちに床面へ乾いた落ち葉を40cm以上敷き詰め、体重で圧縮されても15〜20cm以上の断熱厚を維持させる。\",\n      \"actionNote\": \"> 科学的原理: 土壌の熱伝導率は静止空気の数十倍に達する。床断熱がなければ全لا体温が地面へ奪われ短時間で低体温ショックに陥る。\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [床断熱原則]:\",\n        \"地面熱伝導遮断: 圧縮後も最低15~20cm厚を維持\",\n        \"RIDGEPOLE SPINE (中心棟木断面)\",\n        \"RIB LATTICE: 45°~60° (肋木格子壁)\",\n        \"MATTRESS: 40cm → 20cm (落葉寝床)\",\n        \"GROUND COLD CONDUCTION BLOCKED (地面冷気遮断)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"外壁断熱材60〜90cm積層と防風被覆\",\n      \"description\": \"骨格の上に小枝を薄く被せた後、乾いた落ち葉を下から上へ鱗状に60〜90cm(腕全体の長さ)の厚さで積み上げる。強風で飛ばないよう重い枯れ枝を外壁全体に被せて荷重をかけ、入口は落ち葉の栓で完全密閉する。\",\n      \"actionNote\": \"> 注意: 濡れた落ち葉は断熱効果がなく気化熱で体温を奪う。外壁の傾斜で雨水を流し、内部は完全な乾燥状態を保て。\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [断熱積層規格]:\",\n        \"外壁60~90cm乾燥落葉積層 + 入口プラグ完全密閉\",\n        \"DEBRIS WALL: 60~90cm (落葉断熱層)\",\n        \"DEADWOOD ARMOR (防風荷重枝)\",\n        \"WATER SHEDDING SLOPE (排水傾斜)\",\n        \"DEAD AIR CORE & PLUG SEAL (静止空気層・入口栓)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的誤認: 快適性のための大型空間確保および湿った落ち葉の使用\",\n    \"description\": \"座って休めるように天井を高くすると、人間の基礎代謝(約80〜100W)では内部空気を温めきれず体温が急速に奪われる。また湿った落ち葉を混ぜると高い熱容量と気化熱により氷の洞窟のような冷却装置へと変質する。\",\n    \"consequence\": \"誤判断時の結末: 睡眠中の伝導・対流複合熱損失により深部体温が30°C以下に急降下し、致命的な低体温症(Hypothermia)で死亡。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Aフレーム・デブリハット（落ち葉断熱シェルター）完成外観\",\n    \"description\": \"太さ2.5mの主棟木と45度の肋骨枝フレームの上に、厚さ1メートルの乾燥落ち葉層を圧縮積層し、強風と風雨を遮断する無暖房体温保持シェルターの完成外観です。\"\n  },\n  \"createdAt\": \"2026-10-09T16:08:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"042045342785ab42\"\n}","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.pt.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Construção de Abrigo Térmico A-Frame (Debris Hut)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[NÍVEL DE AMEAÇA: CRÍTICO]\",\n  \"summary\": \"A exposição ao frio e à chuva causa hipotermia fatal em até 3 horas. Ao empilhar folhagem seca e galhos mortos para criar uma camada de ar estagnado (Dead Air Space), constrói-se um abrigo sem fogo que preserva o calor metabólico humano (80–100W).\",\n  \"timeRequired\": \"90–120 MINUTOS\",\n  \"successRate\": \"92.4% (com ≥60cm de isolamento)\",\n  \"difficulty\": \"Nível 2 (Construção Primitiva Pesada)\",\n  \"outputPerHour\": \"1 Abrigo (volume isolado ≥1.5m³)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Viga Mestra (Ridge Pole)\",\n      \"desc\": \"1 tronco reto e seco de madeira dura (comprimento 3.0–3.5m, Ø 10–15cm)\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Forquilhas em Y e Costelas (Rib Sticks)\",\n      \"desc\": \"2 apoios em Y (1.5m, Ø 5–8cm) e 40–50 galhos laterais (1.0–1.5m)\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Folhagem Seca Isolante (Dry Debris)\",\n      \"desc\": \"2–3m³ de folhas secas, agulhas de pinheiro, capim seco e cascas\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Erguer Bipé em A e Ancorar Viga Mestra\",\n      \"description\": \"Encaixe duas forquilhas em Y no topo (ou amarre com cipó) e apoie uma ponta da viga mestra a 0.8–1.0m de altura. Fixe a outra extremidade no solo contra o vento (barlavento). O espaço interno deve permitir apenas entrar rastejando.\",\n      \"actionNote\": \"> REGRA DE CAMPO: Volume interno excessivo impede o aquecimento pelo corpo. Mantenha padrão caixão: apenas um punho (≤10cm) de folga.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [VOLUME INTERNO]:\",\n        \"Padrão caixão: máx. +10cm (1 punho) de folga corporal\",\n        \"WINDWARD (Fixação Barlavento)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (Viga Mestra)\",\n        \"Y-BIPOD & VINE LASHING (Amarração em Y)\",\n        \"COFFIN CLEARANCE: +10cm (Folga Máx. 1 Punho)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Posicionar Costelas e Colchão Isolante de Piso\",\n      \"description\": \"Apoie galhos laterais a 45°–60° em ambos os lados da viga formando uma grade densa. Forre imediatamente o chão com pelo menos 40cm de folhas secas para manter 15–20cm de espessura mesmo comprimido pelo peso do corpo.\",\n      \"actionNote\": \"> PRINCÍPIO FÍSICO: A condução térmica do solo frio é dezenas de vezes maior que a do ar. Sem colchão isolante, o solo drena todo o calor vital.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [ISOLAMENTO DO PISO]:\",\n        \"Bloquear condução do solo: manter ≥15~20cm comprimido\",\n        \"RIDGEPOLE SPINE (Seção da Viga)\",\n        \"RIB LATTICE: 45°~60° (Grade de Galhos)\",\n        \"MATTRESS: 40cm → 20cm (Colchão de Folhas)\",\n        \"GROUND COLD CONDUCTION BLOCKED\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Empilhar 60–90cm de Folhagem e Blindagem Contra Vento\",\n      \"description\": \"Cubra a grade com gravetos finos e acumule folhas secas de baixo para cima até 60–90cm de espessura. Coloque galhos pesados por fora para conter rajadas de vento e feche a entrada com um tampão denso de folhas.\",\n      \"actionNote\": \"> ATENÇÃO: Folhagem úmida não isola e rouba calor por evaporação. Mantenha inclinação externa para escoar a chuva.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [PAREDE TÉRMICA]:\",\n        \"60~90cm de folhas secas + tampão de entrada vedado\",\n        \"DEBRIS WALL: 60~90cm (Camada Isolante)\",\n        \"DEADWOOD ARMOR (Galhos de Contrapeso)\",\n        \"WATER SHEDDING SLOPE (Escoamento)\",\n        \"DEAD AIR CORE & PLUG SEAL (Câmara Vedada)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro Fatal: Construir Espaço Amplo e Usar Folhas Úmidas\",\n    \"description\": \"Elevar o teto para sentar cria um bolsão de ar que o metabolismo humano (80–100W) não consegue aquecer. Além disso, folhas úmidas transformam o abrigo em uma câmara de resfriamento.\",\n    \"consequence\": \"Consequência: Perda térmica por condução e convecção reduz a temperatura central abaixo de 30°C durante o sono, causando morte por hipotermia.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Abrigo Térmico Debris Hut em Estrutura A Concluído\",\n    \"description\": \"Uma viga mestra de 2,5m e costelas a 45° cobertas por 1 metro de folhas secas compactadas e galhos, retendo o calor corporal abaixo de zero sem fogo.\"\n  },\n  \"createdAt\": \"2026-10-09T16:08:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"042045342785ab42\"\n}","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.zh-TW.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"落葉屋（Debris Hut）A字型斷熱避難所構築法\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[威脅等級：致命(CRITICAL)]\",\n  \"summary\": \"在嚴寒風雨中暴露於野外會在3小時內導致致命失溫。透過幾何堆疊乾燥落葉與枯木形成靜止空氣層（Dead Air Space），無需火源即可僅憑人體代謝輻射熱（80～100W）維持核心體溫。\",\n  \"timeRequired\": \"90～120分鐘 (90-120 MINUTES)\",\n  \"successRate\": \"92.4% (確保60cm以上斷熱厚度時)\",\n  \"difficulty\": \"2級 (高強度原始構築技術)\",\n  \"outputPerHour\": \"完成1棟 (有效斷熱體積1.5㎥以上)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"主脊柱木 (Ridge Pole)\",\n      \"desc\": \"長3.0～3.5m、直徑10～15cm且筆直堅固的乾燥硬木原木1根\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Y型支撐木與肋骨枝條 (A-Frame & Rib Sticks)\",\n      \"desc\": \"長1.5m、直徑5～8cm的Y型支撐木2根，以及長1.0～1.5m的肋骨樹枝40～50根\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"乾燥斷熱殘骸 (Dry Debris)\",\n      \"desc\": \"含水量極低的乾落葉、松針、乾草與碎樹皮等大量材料（至少2～3立方公尺）\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"架設A字型主腳與錨定主脊柱木\",\n      \"description\": \"將兩根Y型支撐木在頂端交錯咬合或以藤蔓綁紮成三角支架，將主脊柱木一端架於交點（高約0.8～1.0m），另一端緊貼迎風面地面。內部空間必須嚴格限制在僅容身體爬入的窄度。\",\n      \"actionNote\": \"> 野戰鐵則：內部體積過大將無法以體溫加熱空氣而凍死。務必遵守棺木規格：身體周圍僅留一個拳頭（≤10cm）的空隙。\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [內部體積規格]:\",\n        \"嚴守棺木規格：身體周圍僅留1個拳頭(10cm)裕度\",\n        \"WINDWARD (迎風面地面錨定)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (主脊柱木)\",\n        \"Y-BIPOD & VINE LASHING (Y型支撐綁紮)\",\n        \"COFFIN CLEARANCE: +10cm (僅限1拳間隙)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"排列肋骨格柵與鋪設高密度地面斷熱床墊\",\n      \"description\": \"在主脊柱木兩側以45～60度角緊密斜靠肋骨樹枝，形成防止落葉坍塌的格柵牆。完成骨架後立即在地面鋪設至少40cm厚的乾落葉，確保躺下受壓後仍維持15～20cm以上的斷熱厚度。\",\n      \"actionNote\": \"> 科學原理：冰冷土壤的熱傳導率是靜止空氣的數十倍。若無地面斷熱層，體熱將迅速被大地吸乾並引發失溫休克。\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [地面斷熱原則]:\",\n        \"阻斷地面熱傳導：受壓後仍需維持15~20cm厚度\",\n        \"RIDGEPOLE SPINE (主脊柱木斷面)\",\n        \"RIB LATTICE: 45°~60° (肋骨格柵牆)\",\n        \"MATTRESS: 40cm → 20cm (落葉床墊)\",\n        \"GROUND COLD CONDUCTION BLOCKED (阻絕地面寒氣)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"堆疊60～90cm外部斷熱層與防風壓重披覆\",\n      \"description\": \"在骨架外覆蓋細枝後，由下往上如魚鱗般堆疊60～90cm（整條手臂長度）厚的乾落葉。最後在外牆覆蓋沉重枯枝防止強風吹散落葉，並以高密度落葉塞封死入口。\",\n      \"actionNote\": \"> 注意：潮濕落葉毫無斷熱效果且會透過蒸發奪走體溫。外牆必須維持陡峭斜度以排出雨水，確保內部乾燥。\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [斷熱堆疊規格]:\",\n        \"外牆60~90cm乾落葉堆疊 + 入口落葉塞完全密封\",\n        \"DEBRIS WALL: 60~90cm (落葉斷熱層)\",\n        \"DEADWOOD ARMOR (防風壓重外枝)\",\n        \"WATER SHEDDING SLOPE (排水斜面)\",\n        \"DEAD AIR CORE & PLUG SEAL (靜止空氣層與入口塞)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命誤判：為求舒適擴大內部空間與混用潮濕落葉\",\n    \"description\": \"為了能坐起而加高天花板會使內部空氣袋過大，人體基礎代謝（80～100W）無法將其加熱。此外，若混入潮濕落葉，水分的高熱容與蒸發熱將使避難所變成冰窖。\",\n    \"consequence\": \"誤判後果：睡眠中因傳導與對流複合熱損失，核心體溫驟降至30°C以下，導致致命失溫死亡。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"A字型落葉斷熱避難所（Debris Hut）完成外觀\",\n    \"description\": \"2.5米粗壯脊木與45度肋骨支架上覆蓋1米厚的緊實乾落葉層與防風枝條格子網，形成無暖氣下鎖住體溫的野外避難所完成外觀。\"\n  },\n  \"createdAt\": \"2026-10-09T16:08:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"042045342785ab42\"\n}","content/protocols/locales/04-stone-axe-making.de.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Steinaxt aus Flusssteinen und Ranken bauen\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[WICHTIGKEIT: KERNWERKZEUG]\",\n  \"summary\": \"Mit bloßen Händen lassen sich keine dicken Äste für Unterschlupf oder Feuerholz fällen. So schlagen Sie zwei harte Flusssteine im 45-Grad-Winkel gegeneinander, um eine scharfe Steinklinge abzuspalten, und befestigen sie mit Kiefernharz und nasser Rankenrinde fest an einem Holzstiel.\",\n  \"timeRequired\": \"60 Min.\",\n  \"successRate\": \"90% (bei 45°-Schlag auf die Kante)\",\n  \"difficulty\": \"Mittel (Anfängerfreundlich)\",\n  \"outputPerHour\": \"1 fertige Steinaxt\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 harter Flussstein & 1 runder Schlagstein\",\n      \"desc\": \"Ein dichter Flussstein (etwa zwei Fäuste groß), der mit glasartigen, scharfen Kanten bricht, sowie ein schwerer runder Stein zum Zuschlagen.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Unterarmlanger Stiel aus Hartholz (Eiche oder Esche)\",\n      \"desc\": \"Ein zäher, frischer Ast (40–50cm lang, 3,5–4cm dick), der harte Schläge aushält, ohne zu brechen.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"In Wasser eingeweichte Ranken-Innenrinde & Kiefernharz\",\n      \"desc\": \"Mindestens 3 Meter nasse Innenrinde von Ranken (zieht sich beim Trocknen stark zusammen) und eine Handvoll festes Kiefernharz.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Steine im 45-Grad-Winkel schlagen, um eine scharfe Klinge abzuspalten\",\n      \"description\": \"Legen Sie den großen Flussstein fest auf den Boden und schlagen Sie mit dem runden Schlagstein schräg im 45-Grad-Winkel kräftig auf seine Außenkante. Ein senkrechter Schlag in die Mitte zertrümmert nur den Stein, aber ein 45-Grad-Schlag auf die Kante löst mit einem Schlag eine handtellergroße, rasiermesserscharfe Steinklinge.\",\n      \"actionNote\": \"> Tipp: Schlagen Sie nicht flach in die Mitte. Zielen Sie 1–2cm innerhalb der Außenkante und schlagen Sie einmal kräftig zu.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"1. Runder Schlagstein\",\n        \"2. Kante mit 45° treffen\",\n        \"Scharfe Klinge (1-2cm)\",\n        \"4. Abgespaltene Axtklinge\",\n        \"3. Unterer Flussstein (15-20cm)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Holzstiel oben spalten, Klinge einsetzen und mit Harz füllen\",\n      \"description\": \"Spalten Sie das obere Ende des Holzstiels mit einem scharfen Stein 5–7cm tief senkrecht ein. Binden Sie direkt unter dem Spalt zuerst eine Schnur fest herum, damit das Holz nicht weiter reißt, und klemmen Sie das dicke hintere Ende der Steinklinge tief hinein. Schmelzen Sie Kiefernharz über dem Feuer, mischen Sie feines Holzkohlepulver darunter und füllen Sie alle Lücken.\",\n      \"actionNote\": \"> Prinzip: Reines Harz wird nach dem Abkühlen spröde wie Glas. Mit einem Drittel Holzkohlepulver gemischt wird es zu einem schlagfesten Naturkleber.\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"1. Klinge von oben einsetzen\",\n        \"Scharfe Schneide\",\n        \"2. Holzspalt (5-7cm)\",\n        \"3. Harz + Holzkohlepulver\",\n        \"4. Unten abbinden gegen Risse\",\n        \"Stieldicke: 3,5-4cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Mit nasser Rankenrinde X-förmig umwickeln und im Schatten trocknen\",\n      \"description\": \"Wickeln Sie die eingeweichte, biegsame Ranken-Innenrinde mehr als 10-mal straff über Kreuz (X-Form) um Steinklinge und Holzstiel. Umwickeln Sie danach den unteren Hals quer, verknoten Sie das Ende und lassen Sie die Axt im Schatten trocknen. Beim Trocknen schrumpft die nasse Ranke um fast 30% und klemmt den Stein fest wie Stahldraht.\",\n      \"actionNote\": \"> Achtung: Prüfen Sie nach dem Trocknen mit der Hand, ob die Klinge absolut wackelfrei sitzt. Nicht direkt am Feuer trocknen, sonst verbrennen die Fasern.\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"1. Nasse Ranke X-Wicklung\",\n        \"2. Freie Schneidkante\",\n        \"3. Untere Querwicklung\",\n        \"4. Schrumpft 30% beim Trocknen\",\n        \"Fertig: Feste einteilige Steinaxt\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Häufiger Fehler: Flach in die Steinmitte schlagen oder trockene Ranken nutzen\",\n    \"description\": \"Wer im 90-Grad-Winkel flach auf die Steinmitte schlägt, erhält keine scharfe Klinge, sondern zertrümmert den Stein zu nutzlosem Kies. Wer trockene, spröde Ranken oder raue Außenrinde verwendet, riskiert, dass die Bindung beim ersten Schlag reißt und die schwere Steinklinge ins Gesicht fliegt.\",\n    \"consequence\": \"Ergebnis: Immer die Kante im 45-Grad-Winkel schlagen und eingeweichte Innenrinde im Schatten trocknen lassen.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"Vollendete primitive Steinaxt mit Ast- und Harzbindung\",\n    \"description\": \"Eine beidseitig geschlagene Feuersteinklinge, tief im gespaltenen Eichenstiel verankert, mit X-Kreuz-Lianenbindung verschnürt und mit Kiefernharz versiegelt.\"\n  },\n  \"createdAt\": \"2026-10-09T16:10:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"6ccdf224285e93f4\"\n}","content/protocols/locales/04-stone-axe-making.en.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"How to Make a Stone Axe with River Stones and Vines\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[PRIORITY: CORE TOOL]\",\n  \"summary\": \"You cannot chop thick branches for shelter posts or firewood with your bare hands. Here is how to strike two hard river stones together at a 45-degree angle to split off a sharp stone blade, then lock it into a split wooden handle using pine resin and wet vine bark.\",\n  \"timeRequired\": \"60 mins\",\n  \"successRate\": \"90% (when striking the edge at 45°)\",\n  \"difficulty\": \"Medium (Beginner friendly)\",\n  \"outputPerHour\": \"1 Stone Axe Completed\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 Hard River Stone & 1 Round Hammerstone\",\n      \"desc\": \"One dense river stone (about the size of two fists) that breaks with sharp glass-like edges, plus one heavy round stone to hold and strike with.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Forearm-Length Hard Wooden Handle (Oak or Ash)\",\n      \"desc\": \"One tough green branch (40–50cm long, 3.5–4cm thick) that absorbs heavy impact without snapping.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Water-Soaked Vine Inner Bark & Pine Resin\",\n      \"desc\": \"At least 3 meters of wet inner vine bark (which shrinks and tightens as it dries) and a handful of hardened pine sap from tree bark.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Strike Stones Together at 45 Degrees to Split Off a Sharp Blade\",\n      \"description\": \"Brace the large river stone firmly on the ground, then strike its outer edge at a 45-degree angle using your round hammerstone. Hitting flat in the middle only crushes the rock, but striking the edge at 45 degrees cleanly splits off a palm-sized stone flake with a razor-sharp cutting edge.\",\n      \"actionNote\": \"> Key Tip: Do not hit the flat center of the stone. Aim 1–2cm inside the outer rim and strike firmly in one clean motion to split off a long, sharp blade.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"1. Round Hammerstone\",\n        \"2. Strike Edge at 45°\",\n        \"Sharp Blade (1-2cm)\",\n        \"4. Split Stone Axe Blade\",\n        \"3. Base River Stone (15-20cm)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Split the Top of the Wooden Handle, Wedge the Blade, and Fill with Resin\",\n      \"description\": \"Use a sharp stone flake to split the top of your wooden handle 5–7cm down the center. Tie a cord tightly right below the split first so the wood does not crack any further down, then push the thick back end of the stone blade deep into the slot. Melt pine resin over a fire, mix in fine charcoal powder, and pack it into every gap.\",\n      \"actionNote\": \"> How It Works: Pure pine resin cools brittle like glass and cracks on impact. Mixing in about one-third crushed charcoal powder turns it into a tough, shock-absorbing natural glue.\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"1. Push Blade Down In\",\n        \"Sharp Cutting Edge\",\n        \"2. Split Wood Slot (5-7cm)\",\n        \"3. Melted Resin + Charcoal\",\n        \"4. Tie Below Split First\",\n        \"Handle Width: 3.5-4cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Wrap Tightly in an X-Pattern with Wet Vine Bark and Dry in the Shade\",\n      \"description\": \"Take water-soaked, flexible inner vine bark and wrap it tightly in a diagonal X-pattern across both the stone blade and the wooden handle for more than 10 full turns. Wrap horizontally around the lower neck, tie off the knot, and let it dry in the shade. Wet vine bark shrinks by nearly 30% as it dries, clamping the stone blade like steel wire.\",\n      \"actionNote\": \"> Watch Out: Once dry, shake the stone head hard by hand—there must be zero wobble before swinging. Never dry it right next to flames or the vine fibers will scorch and snap.\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"1. Wet Vine X-Lashing\",\n        \"2. Exposed Sharp Edge\",\n        \"3. Lower Collar Wrap\",\n        \"4. Shrinks 30% When Dry\",\n        \"Finished: Solid One-Piece Stone Axe\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Critical Mistake: Striking the Flat Center of the Rock or Binding with Dry Vines\",\n    \"description\": \"Smashing the flat center of a stone at 90 degrees shatters the rock into useless gravel instead of forming a sharp edge. Also, tying the blade with dry, brittle vines or rough outer bark will cause the lashing to snap on the first swing, sending a heavy stone blade flying toward your face or eyes.\",\n    \"consequence\": \"Result: Always strike the stone edge at 45 degrees for a clean blade, and lash with water-soaked inner bark dried slowly in the shade.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"Completed Primitive Chipped Stone Axe\",\n    \"description\": \"A bifacially flaked flint blade seated deeply into a split oak haft, bound firmly with criss-cross vine lashing and sealed with pine pitch resin composite.\"\n  },\n  \"createdAt\": \"2026-10-09T16:10:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"6ccdf224285e93f4\"\n}","content/protocols/locales/04-stone-axe-making.es.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Cómo hacer un hacha de piedra con rocas de río y lianas\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[IMPORTANCIA: HERRAMIENTA CLAVE]\",\n  \"summary\": \"Con las manos vacías no puedes cortar ramas gruesas para tu refugio o para leña. Aprende a golpear dos piedras duras de río en un ángulo de 45 grados para sacar una hoja afilada y fijarla en un mango de madera con resina de pino y corteza de liana húmeda.\",\n  \"timeRequired\": \"60 min\",\n  \"successRate\": \"90% (golpeando el borde a 45°)\",\n  \"difficulty\": \"Media (Apto para principiantes)\",\n  \"outputPerHour\": \"1 hacha de piedra lista\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 piedra dura de río y 1 piedra martillo redonda\",\n      \"desc\": \"Una piedra compacta de río (del tamaño de dos puños) que al romperse deje bordes afilados como vidrio, y una piedra redonda y pesada para golpear.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Mango de madera dura del largo del antebrazo (roble o fresno)\",\n      \"desc\": \"Una rama verde y resistente (40–50cm de largo y 3.5–4cm de grosor) que soporte golpes fuertes sin partirse.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Corteza interna de liana remojada y resina de pino\",\n      \"desc\": \"Más de 3 metros de corteza interna de liana húmeda (que se encoge y aprieta al secarse) y un puñado de resina de pino seca.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Golpear dos piedras a 45 grados para sacar una hoja afilada\",\n      \"description\": \"Apoya bien la piedra grande en el suelo y golpea su borde exterior en un ángulo inclinado de 45 grados con la piedra martillo. Si golpeas el centro en vertical solo romperás la roca, pero al golpear el borde a 45 grados se desprende de una vez una lasca del tamaño de la mano con filo de navaja.\",\n      \"actionNote\": \"> Consejo clave: No golpees el centro plano de la piedra. Apunta 1–2cm hacia adentro desde el borde exterior y da un golpe seco y firme.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"1. Piedra martillo redonda\",\n        \"2. Golpear borde a 45°\",\n        \"Filo agudo (1-2cm)\",\n        \"4. Hoja de piedra separada\",\n        \"3. Piedra base (15-20cm)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Rajar la punta del mango de madera, encajar la hoja y rellenar con resina\",\n      \"description\": \"Usa una piedra afilada para abrir unahendidura vertical de 5–7cm en la punta del mango de madera. Ata primero una cuerda justo debajo de la abertura para que la madera no se siga rajando, y mete la parte trasera gruesa de la hoja de piedra. Luego derrite resina de pino al fuego, mézclala con polvo fino de carbón y rellena todos los huecos.\",\n      \"actionNote\": \"> Por qué funciona: La resina sola se vuelve frágil como el vidrio al enfriarse. Mezclar un tercio de polvo de carbón crea un pegamento natural súper resistente a los golpes.\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"1. Encajar hoja hacia abajo\",\n        \"Filo delantero\",\n        \"2. Ranura en madera (5-7cm)\",\n        \"3. Resina + polvo de carbón\",\n        \"4. Atar abajo para no rajar\",\n        \"Grosor del mango: 3.5-4cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Atar fuerte en forma de X con liana húmeda y secar a la sombra\",\n      \"description\": \"Con la corteza interna de liana bien mojada y flexible, envuelve la hoja de piedra y el mango cruzando en diagonal en forma de X más de 10 vueltas bien tensas. Después enrolla la parte inferior en horizontal, haz un nudo firme y déjalo secar a la sombra. Al secarse, la liana se encoge casi un 30% y aprieta la piedra como si fuera alambre de acero.\",\n      \"actionNote\": \"> Precaución: Cuando esté seco, mueve la piedra con fuerza con la mano; no debe moverse ni un milímetro. No la acerques al fuego para secarla rápido o la fibra se quemará y se romperá.\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"1. Amarre en X con liana\",\n        \"2. Filo cortante expuesto\",\n        \"3. Vueltas inferiores\",\n        \"4. Encoge 30% al secar\",\n        \"Listo: Hacha firme de una sola pieza\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error grave: Golpear el centro plano de la roca o atar con lianas secas\",\n    \"description\": \"Si golpeas el centro plano de la piedra a 90 grados, no saldrá ningún filo y toda la roca se romperá en grava inútil. Además, si atas con lianas secas o corteza exterior áspera, la cuerda se partirá al primer golpe y la piedra pesada puede salir disparada hacia tu cara o tus ojos.\",\n    \"consequence\": \"Resultado: Golpea siempre el borde a 45 grados y ata con fibra interna remojada en agua, secándola a la sombra.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"Hacha Primitiva de Piedra y Liana Completada\",\n    \"description\": \"Una hoja de pedernal tallada bifacialmente incrustada en un mango de roble hendido, atada firmemente en X con lianas y sellada con resina de pino.\"\n  },\n  \"createdAt\": \"2026-10-09T16:10:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"6ccdf224285e93f4\"\n}","content/protocols/locales/04-stone-axe-making.ja.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"割った石とツルで作る木切り用の石斧\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[重要度: 基本道具]\",\n  \"summary\": \"素手では小屋の柱や薪にする太い枝を切ることはできません。河原の硬い石を45度の角度でぶつけて鋭い石の刃を割り出し、木の柄の割れ目に松ヤニと濡らしたツルの皮でしっかり固定して丈夫な石斧を作る方法です。\",\n  \"timeRequired\": \"60分\",\n  \"successRate\": \"90% (角を45度で叩いた場合)\",\n  \"difficulty\": \"普通 (初心者でも可能)\",\n  \"outputPerHour\": \"石斧 1本完成\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"硬い川石 1個と丸いハンマー石 1個\",\n      \"desc\": \"割れるとガラスのように鋭い縁ができる硬い川石（こぶし2個分）1個と、手に持って叩きつける丸くて重い石1個です。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"腕の長さの硬い木の枝（ナラやトネリコの生木）\",\n      \"desc\": \"強く振り下ろしても折れにくい丈夫な生木の枝（長さ40〜50cm、太さ3.5〜4cmほど）1本です。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"水に浸したツルの内皮と松ヤニ\",\n      \"desc\": \"乾くと縮んで強く締まるツルの内皮（長さ3m以上）と、松の木の傷口で固まった松ヤニひと握りです。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"石と石を45度の角度でぶつけて鋭い石の刃を割り出す\",\n      \"description\": \"地面に大きな川石を動かないように置き、手に持った丸い石で川石の端の角を45度の角度で斜めに強く叩きます。真ん中を真上から叩くと石が砕けるだけですが、角を45度で叩くと手のひらサイズでカミソリのように鋭い石の刃が一発で剥がれ落ちます。\",\n      \"actionNote\": \"> コツ: 石の平らな真ん中を叩かないでください。角の端から指関節1つ分（1〜2cm）内側を狙って一気に強く叩くと、長くて鋭い石の刃が取れます。\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"① 丸いハンマー石（叩く石）\",\n        \"② 角を45°で斜めに叩く\",\n        \"鋭い石の刃（厚さ1〜2cm）\",\n        \"④ 剥がれた石斧の刃\",\n        \"③ 土台の川石（幅15〜20cm）\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"木の柄の上部を割って石の刃を挟み、松ヤニを詰める\",\n      \"description\": \"硬い木の柄の上側を鋭い石で指の長さ（5〜7cm）ほど縦に割って隙間を作ります。それ以上下まで割れないように割れ目のすぐ下を先に紐で縛ってから、隙間に石の刃の厚い後ろ側を奥まで差し込みます。次に火で溶かした松ヤニに細かい炭の粉を混ぜ、隙間にぎっしり詰めて固めます。\",\n      \"actionNote\": \"> 仕組み: 松ヤニだけを溶かして塗ると、冷えた後にガラスのように割れてしまいます。黒い炭の粉を3分の1ほど混ぜると、衝撃でも割れない強力な天然接着剤になります。\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"① 上から下へ石刃を差し込む\",\n        \"木を切る前の刃\",\n        \"② 割った木の隙間（5〜7cm）\",\n        \"③ 溶けた松ヤニ＋炭粉充填\",\n        \"④ 割れ止め用の下部縛り\",\n        \"生木の柄の太さ: 直径3.5〜4cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"濡れたツルの皮でX字に強く巻きつけて日陰で乾かす\",\n      \"description\": \"水に浸して柔らかくなったツルの内皮で、石の刃と木の柄を斜めのX字に交互に10周以上力いっぱい引っ張りながら巻きます。続けて柄の下側も横にぐるぐる巻いて結び、日陰で乾かします。濡れたツルは乾くと長さが約30%縮むため、乾いた後は針金で締めたように石の刃をガッチリ固定します。\",\n      \"actionNote\": \"> 注意点: 完全に乾いた後、手で石の刃を強く揺すって少しもグラつかないか確認してください。早く乾かそうとして火に近づけるとツルが焦げて切れるので、必ず風通しの良い日陰で乾かしてください。\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"① 濡れたツルをX字に巻く\",\n        \"② 鋭い石斧の先端\",\n        \"③ 柄の下側を横に強く巻く\",\n        \"④ 乾燥で30%縮んで圧着\",\n        \"完成状態: 強く叩いても抜けない一体型石斧\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絶対にしてはいけないミス: 平らな石の真ん中を叩く・乾いたツルで縛る\",\n    \"description\": \"石の平らな中央を90度で叩くと、鋭い刃ができずに石全体がただの砂利に砕けてしまいます。また、水に濡らしていない乾いたツルや硬い外皮で縛ると、木を叩いた瞬間に紐が切れ、重い石の刃が顔や目に飛んで大ケガをします。\",\n    \"consequence\": \"結果: 必ず石の角を45度で叩いて刃を作り、水に浸した丈夫な内皮でX字に巻いて日陰で乾かしてから安全に使ってください。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"割り石と葛蔓結束の原始石斧の完成形態\",\n    \"description\": \"硬い樫の木のY字柄の溝に両面打製された鋭利なフリント刃を深く噛み合わせ、強靭な葛蔓と松脂接着剤でX字十字結束した実戦石斧の完成形態です。\"\n  },\n  \"createdAt\": \"2026-10-09T16:10:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"6ccdf224285e93f4\"\n}","content/protocols/locales/04-stone-axe-making.pt.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Como fazer um machado de pedra com pedras de rio e cipó\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[IMPORTÂNCIA: FERRAMENTA ESSENCIAL]\",\n  \"summary\": \"Com as mãos vazias não é possível cortar galhos grossos para abrigo ou lenha. Veja como bater duas pedras duras de rio em um ângulo de 45 graus para tirar uma lâmina afiada e prendê-la em um cabo de madeira com resina de pinheiro e cipó úmido.\",\n  \"timeRequired\": \"60 min\",\n  \"successRate\": \"90% (batendo na borda a 45°)\",\n  \"difficulty\": \"Média (Iniciantes conseguem)\",\n  \"outputPerHour\": \"1 machado de pedra pronto\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 pedra dura de rio e 1 pedra redonda de bater\",\n      \"desc\": \"Uma pedra firme de rio (do tamanho de dois punhos) que quebre formando bordas afiadas como vidro, e uma pedra redonda e pesada para usar como martelo.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Cabo de madeira dura do tamanho do antebraço (carvalho ou freixo)\",\n      \"desc\": \"Um galho verde e resistente (40–50cm de comprimento, 3,5–4cm de espessura) que aguente pancadas fortes sem quebrar.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Fibra interna de cipó molhada e resina de pinheiro\",\n      \"desc\": \"Mais de 3 metros de casca interna de cipó deixada de molho na água (encolhe e aperta ao secar) e um punhado de resina seca de pinheiro.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Bater as pedras a 45 graus para soltar uma lâmina afiada\",\n      \"description\": \"Apoie bem a pedra grande no chão e bata na borda dela em um ângulo inclinado de 45 graus usando a pedra redonda. Bater reto no meio só esfarela a rocha, mas bater na quina a 45 graus destaca de uma só vez uma lasca do tamanho da palma da mão com fio de navalha.\",\n      \"actionNote\": \"> Dica principal: Não bata no meio plano da pedra. Mire 1–2cm para dentro da borda e dê uma pancada firme e rápida.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"1. Pedra redonda (martelo)\",\n        \"2. Bater na borda a 45°\",\n        \"Lâmina afiada (1-2cm)\",\n        \"4. Lasca de machado solta\",\n        \"3. Pedra base (15-20cm)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Rachar a ponta do cabo de madeira, encaixar a lâmina e preencher com resina\",\n      \"description\": \"Use uma pedra afiada para abrir uma fenda vertical de 5–7cm no topo do cabo de madeira. Amarre primeiro uma fibra logo abaixo da fenda para a madeira não rachar mais para baixo, e encaixe a parte traseira grossa da lâmina de pedra. Depois, derreta a resina de pinheiro no fogo, misture pó fino de carvão e preencha todos os espaços.\",\n      \"actionNote\": \"> Como funciona: A resina pura fica quebradiça como vidro depois que esfria. Misturar um terço de pó de carvão cria uma cola natural super resistente a impactos.\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"1. Encaixar lâmina por cima\",\n        \"Fio de corte frontal\",\n        \"2. Fenda no cabo (5-7cm)\",\n        \"3. Resina + pó de carvão\",\n        \"4. Amarrar embaixo antes\",\n        \"Espessura do cabo: 3,5-4cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Amarrar firme em X com cipó úmido e secar na sombra\",\n      \"description\": \"Com a fibra interna do cipó bem molhada e macia, dê mais de 10 voltas bem apertadas cruzando em X sobre a lâmina de pedra e o cabo de madeira. Em seguida, enrole a base na horizontal, dê um nó firme e deixe secar na sombra. O cipó molhado encolhe quase 30% ao secar, prendendo a pedra como se fosse arame de aço.\",\n      \"actionNote\": \"> Atenção: Depois de seco, balance a pedra com força usando a mão; ela não pode ter nenhuma folga. Não tente secar perto do fogo para não queimar e romper as fibras.\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"1. Amarração em X com cipó\",\n        \"2. Fio afiado exposto\",\n        \"3. Voltas horizontais na base\",\n        \"4. Encolhe 30% ao secar\",\n        \"Pronto: Machado firme em peça única\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro grave: Bater no meio plano da pedra ou amarrar com cipó seco\",\n    \"description\": \"Bater em ângulo reto (90 graus) no centro plano da pedra não cria lâmina e só quebra a pedra em pedregulhos inúteis. Além disso, amarrar com cipó seco ou casca grossa faz a amarração arrebentar na primeira batida, podendo lançar a pedra pesada contra o seu rosto.\",\n    \"consequence\": \"Resultado: Bata sempre na borda a 45 graus e amarre com fibra interna molhada, secando na sombra.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"Machado Primitivo de Pedra e Cipó Concluído\",\n    \"description\": \"Uma lâmina de sílex lascada bifacialmente encaixada em cabo de carvalho fendido, amarrada firmemente em X com cipós e selada com resina de pinho.\"\n  },\n  \"createdAt\": \"2026-10-09T16:10:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"6ccdf224285e93f4\"\n}","content/protocols/locales/04-stone-axe-making.zh-TW.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"用碎石與藤蔓製作砍樹石斧的方法\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[重要度：核心工具]\",\n  \"summary\": \"徒手無法砍斷用來蓋避難所或當柴燒的粗樹枝。只要將兩塊堅硬的河石以45度角互相敲擊，就能剝離出鋒利的石刃，接著嵌入木柄縫隙中，並用松脂與泡過水的濕藤皮牢牢綁緊，做出一把堅固耐用的石斧。\",\n  \"timeRequired\": \"60分鐘\",\n  \"successRate\": \"90% (以45度角敲擊邊緣時)\",\n  \"difficulty\": \"普通 (新手可完成)\",\n  \"outputPerHour\": \"完成 1 把石斧\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"堅硬河石 1 塊與圓形錘石 1 塊\",\n      \"desc\": \"敲碎後會產生如玻璃般鋒利邊緣的堅硬河石（約兩個拳頭大）1 塊，以及握在手中用來敲擊的沉重圓石 1 塊。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"前臂長度的堅硬木柄（橡木或白蠟木）\",\n      \"desc\": \"用力揮砍也不易折斷的強韌生木枝條（長 40～50cm，直徑約 3.5～4cm）1 根。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"泡水軟化的葛藤內皮與松樹樹脂\",\n      \"desc\": \"乾燥後會自動收縮勒緊的濕葛藤內皮（長 3m 以上），以及從松樹樹皮上採集的凝固松脂一把。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"以45度角敲擊石頭，剝離出鋒利的石刃\",\n      \"description\": \"將大塊河石穩穩固定在地面上，手持圓形錘石，對準大河石的邊緣角落以 45 度角斜向用力敲下去。垂直敲打正中央只會把石頭砸碎，但以 45 度角敲擊邊緣，就能一次劈下巴掌大小、邊緣如刀片般鋒利的石刃。\",\n      \"actionNote\": \"> 關鍵訣竅：千萬不要敲打石頭平坦的正中央。瞄準距離邊緣內側約一節手指（1～2cm）處，果斷用力一擊才能打出又長又利的石刃。\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"① 圓形錘石（敲擊石）\",\n        \"② 對準邊緣 45° 斜敲\",\n        \"鋒利石刃（厚 1～2cm）\",\n        \"④ 劈下的石斧刀片\",\n        \"③ 底部墊石（寬 15～20cm）\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"劈開木柄頂端，嵌入石刃並填滿松脂\",\n      \"description\": \"用鋒利的石片將硬木柄頂端垂直劈開約手指長度（5～7cm）的縫隙。為了防止木柄繼續往下裂開，先在裂縫正下方用繩子緊緊綁住，再將石刃較厚的後端深深塞進縫隙裡。接著把用火融化的松脂混入細木炭粉，填滿所有空隙並冷卻凝固。\",\n      \"actionNote\": \"> 核心原理：只塗純松脂的話，冷卻後會像玻璃一樣脆裂。混入約三分之一的細黑炭粉，就能變成耐衝擊又不碎裂的天然強力膠。\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"① 由上往下嵌入石刃\",\n        \"砍樹的前方刀刃\",\n        \"② 劈開的木柄縫隙（5～7cm）\",\n        \"③ 填入融化松脂＋木炭粉\",\n        \"④ 下方先綁緊防裂開\",\n        \"生木柄粗度：直徑 3.5～4cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"用濕藤皮以X字形緊緊纏繞並在陰涼處晾乾\",\n      \"description\": \"用充分泡水變軟的葛藤內皮，在石刃與木柄交界處以對角線 X 字形交替用力拉緊纏繞 10 圈以上，接著在木柄下方橫向繞緊打結，放在通風陰涼處晾乾。濕藤皮在乾燥過程中會縮短將近 30%，乾透後會像鐵絲一樣把石刃死死鎖住。\",\n      \"actionNote\": \"> 注意事項：完全乾透後，用手用力搖晃石刃，必須連一點點鬆動都沒有才安全。千萬別為了快乾而拿到火邊烤，藤皮烤焦後一砍就會斷裂。\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"① 濕藤皮 X 字形交叉纏繞\",\n        \"② 外露的鋒利斧刃\",\n        \"③ 木柄下方橫向繞緊固定\",\n        \"④ 乾燥收縮 30% 強力鎖緊\",\n        \"完成狀態：重擊也不脫落的一體成型石斧\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絕對不能犯的錯誤：垂直敲打石頭中央或用乾藤蔓綁縛\",\n    \"description\": \"以 90 度垂直敲擊平坦的石頭中央，只會把整塊石頭震碎成沒用的碎石。此外，若用沒泡水的乾枯藤蔓或粗糙外皮捆綁，揮斧砍樹的瞬間繩子就會斷裂，沉重的石刃會直接飛向臉部或眼睛造成嚴重傷害。\",\n    \"consequence\": \"結果：務必以 45 度角敲擊河石邊緣取刃，並用泡水軟化的強韌內皮以 X 字形纏繞後陰乾。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"敲石碎屑與葛藤結紮原始石斧完成形態\",\n    \"description\": \"堅韌橡木柄凹槽中深嵌雙面打製鋒利燧石刃，以強韌葛藤與松脂黏合劑進行X型十字結紮，具備砍伐原木威力的實戰石斧完成形態。\"\n  },\n  \"createdAt\": \"2026-10-09T16:10:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"6ccdf224285e93f4\"\n}","content/protocols/locales/05-natural-cordage.de.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Reißfestes Wildnisseil aus Baumrinde und Ranken drehen\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[ÜBERLEBENSWICHTIG]\",\n  \"summary\": \"Eine stabile Schnur ist unverzichtbar für Unterstände, Steinäxte und Feuerbohrer. Ganze grüne Ranken schrumpfen und brechen beim Trocknen; wenn man jedoch die weiße Innenrinde (Bastfaser) abzieht und zwei Stränge gegenläufig zusammendreht, entsteht ein selbstsicherndes Seil, das das Gewicht eines Erwachsenen trägt.\",\n  \"timeRequired\": \"40 Min.\",\n  \"successRate\": \"95% (Mit Gegendrehung)\",\n  \"difficulty\": \"Mittel (Mit bloßen Händen)\",\n  \"outputPerHour\": \"5m / 40 Min.\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Lebende Kudzu-Ranken, Linden-, Weiden- oder Brennnesselstängel (10~15 armlange Triebe)\",\n      \"desc\": \"Wählen Sie biegsame Triebe, die beim Knicken nicht brechen und unter dem Fingernagel grüne Feuchtigkeit zeigen.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 scharfkantiger Steinabschlag zum Abschaben\",\n      \"desc\": \"Zum vorsichtigen Abschaben der spröden braunen Außenrinde, ohne die zähen weißen Innenfasern zu beschädigen.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Flacher Unterlegstein und faustgroßer runder Klopfstein\",\n      \"desc\": \"Um die eingeweichte Innenrinde sanft weichzuklopfen, bis sie sich in feine, haarähnliche Fasern teilt.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Bach- oder Tümpelwasser zum Einweichen\",\n      \"desc\": \"Frisch abgezogene Innenrinde 20~30 Minuten wässern, um steifen Pflanzensaft zu lösen und die Fasern geschmeidig zu halten.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Biegsame Stängel wählen, Außenrinde abschaben und weiße Innenfaser abziehen\",\n      \"description\": \"Biegen Sie den Stängel zur Hälfte, um zu prüfen, ob er elastisch bleibt. Schaben Sie mit einer Steinkante vorsichtig die raue braune Außenrinde ab, bis die helle, zähe Bastschicht sichtbar wird. Heben Sie das untere Ende mit dem Fingernagel an und ziehen Sie lange Faserbänder vom harten Holzkern ab.\",\n      \"actionNote\": \"> Tipp: Abgestorbene, trockene Stängel am Boden haben morsche Fasern, die sofort reißen. Immer frische Triebe nutzen.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① Raue Außenrinde mit Steinkante abschaben\",\n        \"② Spröde braune Außenrinde (abschaben & wegwerfen)\",\n        \"③ Zähe weiße Innenfaser (Hauptmaterial fürs Seil)\",\n        \"④ Harter Holzkern in der Mitte (entfernen)\",\n        \"⑤ Biegsamer lebender Stängel bricht nicht\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: 20 Minuten im Bach wässern und mit rundem Stein weichklopfen\",\n      \"description\": \"Legen Sie die abgezogenen Rindenstreifen für 20~30 Minuten ins Wasser. Breiten Sie die aufgeweichten Streifen auf einem flachen Flussstein aus und klopfen Sie sie mit einem runden Stein sanft von oben nach unten. Sobald sich feine, weiche Faserbündel lösen, teilen Sie diese in zwei fingerdicke Stränge.\",\n      \"actionNote\": \"> Grundprinzip: Zu harte Schläge durchtrennen die Fasern. Sanft drücken und klopfen, damit die Fasern lang bleiben.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① Innenrinde 20+ Min. im Bachwasser eingeweicht\",\n        \"② Sanft mit rundem Stein klopfen zum Auffasern\",\n        \"③ Weiches, haarfein gelöstes Faserbündel\",\n        \"④ Zwei gleichmäßige, fingerdicke Faserstränge\",\n        \"⑤ Stabiler flacher Flussstein als Unterlage\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Nach außen zwirbeln und zum Körper kreuzen (Gegendrehung)\",\n      \"description\": \"Klemmen Sie die Mitte des Faserbündels zwischen linken Daumen und Zeigefinger, sodass ein oberer und ein unterer Strang entstehen. Drehen Sie den oberen Strang mit der rechten Hand fest vom Körper weg (nach außen) und legen Sie ihn dann über den unteren Strang zu Ihrem Körper hin. Linken Daumen nachsetzen, Kreuzungspunkt festhalten und wiederholen.\",\n      \"actionNote\": \"> Grundprinzip: Dreht man beide Stränge in dieselbe Richtung, rollt sich das Seil sofort wieder auf. Die Gegendrehung verriegelt beide Stränge.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① Oberer Strang: fest vom Körper wegdrehen (↑)\",\n        \"② Verzahntes Fischgrät-Seilmuster\",\n        \"③ Kreuzungspunkt mit linkem Daumen & Zeigefinger halten\",\n        \"④ Gedrehten Strang über unteren zum Körper legen (↓)\",\n        \"⑤ Selbstsichernde Gegendreh-Verriegelung\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Neue Fasern 10cm überlappen für endlose Seillänge\",\n      \"description\": \"Wenn ein Strang auf die letzten 10cm dünner wird, legen Sie ein neues Faserbündel 10cm überlappend direkt daneben. Halten Sie altes Ende und neues Bündel gemeinsam wie einen einzigen Strang und drehen Sie normal weiter. Versetzen Sie die Verbindungsstellen von oberem und unterem Strang um mindestens eine Handspanne (15cm).\",\n      \"actionNote\": \"> Achtung: Liegen beide Spleißstellen an derselben Stelle, entsteht ein dicker Knotenpunkt, der unter Zug reißt.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① Alter Strang wird bei 10cm Restlänge dünner\",\n        \"② Neues Faserbündel 10cm daneben überlappen\",\n        \"③ Beide Enden gemeinsam als einen Strang drehen\",\n        \"④ Glatte Verbindung ohne dicke Schwachstelle\",\n        \"⑤ Obere & untere Spleißstelle 15cm versetzen\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Schritt 5: Endknoten setzen und am Baumstamm mit Körpergewicht testen\",\n      \"description\": \"Nach Erreichen der gewünschten Länge (ab 5m) die letzten 3cm zu einer Schlaufe legen und mit einem festen Überhandknoten sichern. Abstehende Fasern mit einer Steinklinge glätten. Zuletzt das Seil um einen dicken Baumstamm legen und mit vollem Körpergewicht (50kg+) daran ziehen.\",\n      \"actionNote\": \"> Praxistest: Knacken Fasern oder rutscht eine Verbindung, diese Stelle sofort mit zusätzlichen Fasern umwickeln.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① Sicherungsknoten 3cm vor dem Seilende\",\n        \"② Abstehende Fasern mit Steinklinge säubern\",\n        \"③ Um Baumstamm legen & mit Körpergewicht (50kg+) ziehen\",\n        \"④ Fertiges 5mm Wildnisseil (5m Länge)\",\n        \"⑤ Bereit für Unterstand, Steinaxt & Feuerbohrer\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Ungeschälte grüne Ranken direkt zum Binden verwenden\",\n    \"description\": \"Wickelt man ganze grüne Ranken oder Zweige direkt um Unterstand oder Steinaxt, wirkt das nur anfangs fest. Sobald der Pflanzensaft trocknet, schrumpft die Ranke, lockert sich und der holzige Kern bricht bei Belastung sofort durch. Immer nur die abgezogene Innenfaser gegenläufig verdrillen.\",\n    \"consequence\": \"Folge: Das Dach des Unterstands bricht nachts ein oder der Steinaxtkopf löst sich beim Schlagen\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Wie man im Wald ohne Hilfsmittel mit bloßen Händen ein reißfestes Seil dreht.\",\n    \"body\": \"Braune Außenrinde von lebenden Ranken abschaben und weiße Innenfaser abziehen. 20 Minuten wässern und mit rundem Stein weichklopfen. Halbieren, oberen Strang vom Körper wegdrehen und zum Körper hin überkreuzen. Neue Fasern 10cm überlappen für endlose Länge.\",\n    \"outro\": \"Hält über 50kg Körpergewicht am Baumstamm. Perfekt für Unterstände, Steinäxte und Feuerbohrer.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"Vollendeter 2-Strang-Naturseilbund mit Gegenverdrallung\",\n    \"description\": \"Ein gleichmäßiger 8-mm-Seilbund aus im Uhrzeigersinn gedrehten und gegenläufig verzwirnten Bastfasern, der über 90 kgf Zuglast ohne Aufdröseln standhält.\"\n  },\n  \"createdAt\": \"2026-10-13T13:20:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"03d1706e68d38783\"\n}","content/protocols/locales/05-natural-cordage.en.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"How to Twist Unbreakable Wild Cordage from Bark and Vines\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[CRITICAL SURVIVAL]\",\n  \"summary\": \"Strong cordage is essential for lashing shelter frames, hafting stone axes, and spinning a bow drill. Whole raw vines shrink and snap brittlely once dry, but extracting inner bast fibers and reverse-wrapping two strands creates a self-locking rope strong enough to hold adult body weight.\",\n  \"timeRequired\": \"40 min\",\n  \"successRate\": \"95% (With Reverse Wrap)\",\n  \"difficulty\": \"Medium (Bare Hands)\",\n  \"outputPerHour\": \"5m / 40 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Live Kudzu Vines, Basswood, Willow, or Nettle Stems (10~15 arm-length stalks)\",\n      \"desc\": \"Choose live stalks that bend smoothly without snapping and show green moisture when scratched with a fingernail.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Sharp-Edged Stone Flake for Scraping\",\n      \"desc\": \"Used to gently scrape off the brittle brown outer bark without cutting into the tough white inner fibers beneath.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Flat Anvil Stone and Fist-Sized Round Hammer Stone\",\n      \"desc\": \"Used to gently pound soaked inner bark strips until they separate into soft, hair-like fiber strands.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Stream or Standing Water for Soaking\",\n      \"desc\": \"Soak freshly peeled inner bark for 20~30 minutes to soften stiff sap and keep fibers flexible while twisting.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Select Flexible Stalks, Scrape Outer Bark, and Peel White Inner Bark\",\n      \"description\": \"Bend the stalk in half to confirm it flexes without snapping. Hold a stone edge at an angle and lightly scrape away the rough brown outer bark until the pale, tough inner fiber layer appears. Lift the bottom edge with your fingernail and peel long ribbon strips upward away from the woody core.\",\n      \"actionNote\": \"> Key Tip: Dead, dry stalks on the ground have rotted fibers that crumble under tension. Always harvest inner bark from live or freshly cut stalks.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① Scrape off rough outer bark with stone edge\",\n        \"② Brittle brown outer bark (scrape & discard)\",\n        \"③ Tough white inner bast fiber (core rope material)\",\n        \"④ Stiff woody center core (peel off & discard)\",\n        \"⑤ Flexible live stalk that bends without snapping\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Soak in Water for 20 Minutes and Pound into Soft Hair-Like Fibers\",\n      \"description\": \"Submerge the peeled inner bark ribbons in stream water for 20~30 minutes. Lay the softened strips across a flat river stone and tap gently from top to bottom with a round stone. Once the stiff grain breaks down into soft, hair-like strands, divide them evenly into two equal bundles.\",\n      \"actionNote\": \"> Core Principle: Striking too hard with a sharp rock severs the fibers. Press and roll gently with a smooth stone to separate long intact strands.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① Inner bark soaked 20+ min in stream water\",\n        \"② Gently tap with round stone to split fibers\",\n        \"③ Softened hair-like fiber bundle\",\n        \"④ Two equal finger-thick fiber strands\",\n        \"⑤ Stable flat river stone anvil beneath\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Twist Away and Cross Toward You (Reverse-Wrap Locking Method)\",\n      \"description\": \"Pinch the middle of a fiber bundle between your left thumb and forefinger, folding it into an upper and lower strand. With your right hand, twist the upper strand tightly away from your body, then bring that twisted strand over the lower strand toward your body. Move your left thumb forward to pinch the new crossing point and repeat: twist the top strand away, then wrap it toward you.\",\n      \"actionNote\": \"> Core Principle: Twisting both strands in the same direction causes the rope to unravel immediately. Twisting away while wrapping toward you locks opposing forces together.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① Top strand: twist tightly away from body (↑)\",\n        \"② Interlocked chevron rope pattern\",\n        \"③ Pinch junction firmly with left thumb & index\",\n        \"④ Cross twisted top strand over toward body (↓)\",\n        \"⑤ Self-locking reverse-wrap structure\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Overlap New Fibers by 10cm to Splice Endless Length\",\n      \"description\": \"When either strand thins down with about 10cm remaining, lay a fresh fiber bundle alongside the old tail with a 10cm overlap. Hold both together as a single strand and continue twisting away and wrapping toward you. Always stagger splices between the upper and lower strands by at least one hand-span (15cm).\",\n      \"actionNote\": \"> Warning: Splicing both strands at the exact same spot creates a weak, bulky lump that snaps under load.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① Existing strand thinning with 10cm left\",\n        \"② Lay new fiber bundle alongside (10cm overlap)\",\n        \"③ Twist overlapped tails together as one strand\",\n        \"④ Smooth splice without bulky weak lumps\",\n        \"⑤ Stagger top & bottom splices by 15cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Step 5: Tie an End Stopper Knot and Test with Full Body Weight on a Tree\",\n      \"description\": \"Once you reach your target length (5m or more), fold the last 3cm into a loop and tie a tight overhand stopper knot. Lightly scrape off loose fuzz along the rope with a stone flake to reduce friction wear. Wrap the finished cordage around a sturdy tree trunk and pull back with your full body weight (50kg+) to verify no splices slip.\",\n      \"actionNote\": \"> Field Check: If you hear fibers snapping or see a splice slipping, wrap an extra thin fiber bundle around that section.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① Overhand stopper knot 3cm from the end\",\n        \"② Trim loose fuzz cleanly with stone flake\",\n        \"③ Wrap around tree & pull with body weight (50kg+)\",\n        \"④ Finished 5mm wild rope (5m length)\",\n        \"⑤ Ready for shelter lashing, stone axe & bow drill\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Tying Whole Unpeeled Green Vines Directly\",\n    \"description\": \"Wrapping whole raw vines or green twigs directly around a shelter frame or stone axe feels tight at first, but within hours the sap dries, the vine shrinks and loosens, and the woody core snaps like a dry cracker under impact. Always strip the outer bark and woody core, and reverse-wrap the inner bast fibers.\",\n    \"consequence\": \"Consequence: Shelter roof collapses overnight or stone axe head flies off mid-swing causing severe injury\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"When you have zero rope in the wild, here is how to twist unbreakable cordage with bare hands.\",\n    \"body\": \"Scrape the brown outer bark off live kudzu vines and peel out the white inner fibers. Soak for 20 minutes and tap with a round stone until soft. Fold in half, twist the top strand away from you, and cross it over toward you. Overlap new fibers by 10cm to splice endless length.\",\n    \"outro\": \"Tested against 50kg of body weight on a tree trunk. Ready for shelters, stone axes, and bow drills.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"Completed 2-Ply Reverse-Wrapped Natural Cordage Coil\",\n    \"description\": \"A uniform 8mm braided rope coil made by twisting bast fibers clockwise and counter-wrapping plies, sustaining over 90 kgf tensile load without slipping.\"\n  },\n  \"createdAt\": \"2026-10-13T13:20:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"03d1706e68d38783\"\n}","content/protocols/locales/05-natural-cordage.es.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Cómo trenzar cuerda salvaje irrompible con corteza y lianas\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[SUPERVIVENCIA CRÍTICA]\",\n  \"summary\": \"Una cuerda resistente es indispensable para atar refugios, fijar hachas de piedra y encender fuego con arco. Atar lianas verdes enteras falla porque encogen y se quiebran al secarse; en cambio, extraer la fibra blanca interna y trenzar dos cabos en sentido inverso crea una soga autobloqueante capaz de soportar el peso de un adulto.\",\n  \"timeRequired\": \"40 min\",\n  \"successRate\": \"95% (Con trenzado inverso)\",\n  \"difficulty\": \"Media (Con las manos)\",\n  \"outputPerHour\": \"5m / 40 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Lianas vivas de kudzu, tilo, sauce o tallos de ortiga (10~15 tallos del largo del brazo)\",\n      \"desc\": \"Elija tallos vivos que se doblen sin romperse y muestren humedad verde al rasparlos con la uña.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 lasca de piedra con borde afilado para raspar\",\n      \"desc\": \"Se usa para raspar suavemente la corteza exterior marrón sin cortar las fibras blancas internas.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Piedra plana de base y canto rodado del tamaño del puño\",\n      \"desc\": \"Para golpear suavemente la corteza interna remojada hasta separarla en hebras suaves como cabellos.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Agua de arroyo o charca para remojar\",\n      \"desc\": \"Remoje la corteza interna durante 20~30 minutos para ablandar la savia y mantener las fibras flexibles.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Elegir tallos flexibles, raspar la corteza exterior y pelar la fibra blanca interna\",\n      \"description\": \"Doble el tallo por la mitad para comprobar que se curva sin partirse. Raspe suavemente la corteza marrón exterior con el borde de una piedra hasta descubrir la capa blanca y fibrosa. Levante el extremo inferior con la uña y tire hacia arriba para desprender tiras largas separándolas del núcleo leñoso.\",\n      \"actionNote\": \"> Consejo clave: Los tallos secos caídos en el suelo tienen fibras podridas que se rompen al tensarlas. Use siempre tallos vivos.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① Raspar corteza exterior con borde de piedra\",\n        \"② Corteza marrón quebradiza (raspar y tirar)\",\n        \"③ Fibra interna blanca y firme (material clave)\",\n        \"④ Núcleo central de madera dura (desechar)\",\n        \"⑤ Tallo vivo flexible que se dobla sin partirse\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Remojar 20 minutos en el arroyo y machacar con piedra hasta suavizar\",\n      \"description\": \"Sumerja las tiras de corteza interna en agua durante 20~30 minutos. Extiéndalas sobre una piedra plana y golpéelas suavemente con una piedra redonda de arriba abajo. Cuando la fibra rígida se separe en hebras finas y suaves como hilos, divídalas en dos manojos iguales del grosor de un dedo.\",\n      \"actionNote\": \"> Principio clave: Golpear demasiado fuerte corta las fibras. Presione y machaque con suavidad para conservar hebras largas.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① Corteza interna remojada 20+ min en agua\",\n        \"② Golpear suave con piedra redonda para abrir fibras\",\n        \"③ Manojo de fibras suaves como cabellos\",\n        \"④ Dos cabos iguales del grosor de un dedo\",\n        \"⑤ Piedra plana firme apoyada en el suelo\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Retorcer hacia afuera y cruzar hacia el cuerpo (Trenzado Inverso)\",\n      \"description\": \"Sujete la mitad del manojo con el pulgar e índice izquierdos y dóblelo para formar un cabo superior y otro inferior. Con la mano derecha, retuerza con fuerza el cabo superior hacia afuera (alejándolo de usted) y luego crúcelo por encima del cabo inferior hacia su cuerpo. Avance el pulgar izquierdo para sujetar el cruce y repita siempre: retorcer hacia afuera y cruzar hacia adentro.\",\n      \"actionNote\": \"> Principio clave: Si gira ambos cabos en la misma dirección, la cuerda se deshará sola. El giro opuesto bloquea las tensiones entre sí.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① Cabo superior: retorcer firme hacia afuera (↑)\",\n        \"② Trenzado en espiga autobloqueado\",\n        \"③ Sujetar cruce con pulgar e índice izquierdos\",\n        \"④ Cruzar cabo superior hacia el cuerpo (↓)\",\n        \"⑤ Cierre inverso que no se deshace al soltar\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Superponer 10cm de fibra nueva para empalmar longitud infinita\",\n      \"description\": \"Cuando a un cabo le queden unos 10cm y se adelgace, coloque un manojo nuevo junto al extremo viejo superponiendo 10cm. Sujete ambos como si fueran un solo cabo y siga retorciendo hacia afuera y cruzando hacia usted. Separe siempre los empalmes del cabo superior e inferior al menos un palmo (15cm).\",\n      \"actionNote\": \"> Precaución: Empalmar ambos cabos en el mismo punto crea un bulto débil que se rompe al tirar.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① Cabo viejo adelgazado con 10cm restantes\",\n        \"② Colocar fibra nueva al lado (10cm superpuestos)\",\n        \"③ Retorcer ambos extremos juntos como uno solo\",\n        \"④ Empalme liso sin bultos ni puntos débiles\",\n        \"⑤ Desfasar empalmes superior e inferior por 15cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Paso 5: Hacer nudo de tope final y probar con el peso del cuerpo en un árbol\",\n      \"description\": \"Al alcanzar la longitud deseada (5m o más), doble los últimos 3cm y haga un nudo simple bien apretado para que no se deshilache. Raspe los pelos sueltos con una lasca de piedra. Por último, rodee el tronco de un árbol firme con la cuerda y tire con todo su peso (50kg+) para comprobar que ningún empalme resbale.\",\n      \"actionNote\": \"> Verificación: Si oye crujir fibras o nota que un empalme cede, refuerce ese tramo envolviendo más fibra encima.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① Nudo final de tope a 3cm del extremo\",\n        \"② Recortar fibras sueltas con lasca de piedra\",\n        \"③ Rodear árbol y tirar con peso corporal (50kg+)\",\n        \"④ Cuerda salvaje terminada de 5mm (5m largo)\",\n        \"⑤ Lista para refugios, hacha de piedra y arco\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error Fatal: Atar lianas verdes enteras sin pelar la corteza\",\n    \"description\": \"Atar ramas o lianas enteras directamente al refugio o al hacha parece firme al principio, pero al secarse la savia en pocas horas se encogen, quedan flojas y el centro leñoso se parte como una galleta seca. Siempre pele la corteza y trence solo la fibra interna.\",\n    \"consequence\": \"Consecuencia: El techo del refugio se desploma mientras duerme o la hoja del hacha sale despedida causando heridas graves\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Cómo hacer una cuerda salvaje irrompible con las manos cuando no tienes nada en el bosque.\",\n    \"body\": \"Raspa la corteza marrón de una liana viva y saca la fibra blanca interna. Remójala 20 minutos y machácala con una piedra redonda hasta suavizarla. Dóblala, retuerce el cabo superior hacia afuera y crúzalo hacia ti. Superpón 10cm de fibra nueva para alargarla sin límite.\",\n    \"outro\": \"Soporta más de 50kg colgada de un árbol. Lista para atar tu refugio o fijar un hacha de piedra.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"Rollo de Cuerda Natural de 2 Cabos con Torsión Inversa Completado\",\n    \"description\": \"Una bobina de cuerda uniforme de 8 mm trenzada en sentido inverso con fibras de corteza, capaz de resistir más de 90 kgf de carga de tracción.\"\n  },\n  \"createdAt\": \"2026-10-13T13:20:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"03d1706e68d38783\"\n}","content/protocols/locales/05-natural-cordage.ja.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"木の皮とクズのつるを撚って切れない野生ロープを作る方法\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[必須サバイバル]\",\n  \"summary\": \"シェルターの柱を結んだり、石斧を固定したり、火起こしをするには丈夫な紐が不可欠です。生のつるをそのまま結ぶと乾いた時に縮んで折れますが、内側の白い繊維を取り出して2本を逆方向にねじり合わせれば、大人の体重にも耐える強靭な野生ロープが作れます。\",\n  \"timeRequired\": \"40分\",\n  \"successRate\": \"95% (逆撚り法を守った場合)\",\n  \"difficulty\": \"普通 (素手で作業可能)\",\n  \"outputPerHour\": \"5m / 40分\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"生きているクズのつる、シナノキ・ヤナギ・イラクサの茎 (腕の長さ10〜15本)\",\n      \"desc\": \"曲げた時にポキッと折れずにしなやかに曲がり、爪で表面を削ると緑色の水分が見える新鮮な茎を選びます。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"外皮を削り落とす鋭い石の欠片 1個\",\n      \"desc\": \"茎の外側にある茶色い外皮だけを軽く削り落とすために使います。内側の繊維を切らないよう適度な角がある石を選びます。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"繊維を叩く平らな台石と拳大の丸石\",\n      \"desc\": \"水に浸した内皮を平らな石の上に置き、丸石で優しく叩いて髪の毛のように細く柔らかい繊維にほぐします。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"内皮を浸す川の水または溜まり水\",\n      \"desc\": \"剥ぎ取った内皮を20〜30分間浸して硬い樹液を抜き、撚っている間に繊維が折れないよう湿り気を保ちます。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ1: しなやかな茎を選び、茶色い外皮を削って白い内皮を剥ぎ取る\",\n      \"description\": \"まず茎を半分に曲げて折れないか確認します。石の角を斜めに当てて外側の茶色い外皮だけを優しく削り落とすと、下から白くて丈夫な内皮繊維が現れます。根元を爪で少しめくり、上に向かって長く引っ張ると、硬い木の芯からリボン状の内皮だけがきれいに剥がれます。\",\n      \"actionNote\": \"> コツ: 地面に落ちて乾いた枯れ枝は繊維が腐っており、引っ張るとすぐ切れます。必ず生きた茎から採取してください。\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① 石の角で粗い外皮だけを優しく削り落とす\",\n        \"② 折れやすい茶色い外皮 (削って捨てる)\",\n        \"③ 強靭で白い内皮繊維層 (ロープの主材料)\",\n        \"④ 中央の硬い木の芯 (剥がして捨てる)\",\n        \"⑤ 曲げても折れずにしなる生きた茎\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ2: 川の水に20分浸し、丸石で叩いて糸のように柔らかくほぐす\",\n      \"description\": \"剥ぎ取った内皮リボンを川の水に20〜30分間しっかり浸します。柔らかくなった内皮を平らな川石の上に広げ、丸石で上から下へトントンと優しく叩きます。硬い筋がほぐれて髪の毛のように細く柔らかい繊維束になったら、指の太さほどの均等な2束に分けます。\",\n      \"actionNote\": \"> 原理: 強く叩きすぎると繊維が切れます。押し潰しながら滑らせるように叩くのが長い繊維を保つ秘訣です。\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① 川の水に20分以上浸して柔らかくした内皮\",\n        \"② 丸石で優しく叩いて繊維の筋をほぐす\",\n        \"③ 髪の毛のように柔らかくほぐれた繊維束\",\n        \"④ 指の太さに均等に分けた2本の束\",\n        \"⑤ 下に敷いた安定した平らな川石\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ3: 外側にねじって手前に交差させる「逆撚り」を繰り返す\",\n      \"description\": \"長い繊維束の真ん中を左手の親指と人差し指でしっかりつまみ、半分に折って上の束と下の束の2本にします。右手で上の束を持ち、体の外側（前方）へ強くねじります。そのままねじった上の束を下の束の上を越えて自分の体側（手前）へ交差させて渡します。左手の親指をずらして交差点をしっかり押さえ、「外側へねじって➔手前へ渡す」を繰り返します。\",\n      \"actionNote\": \"> 原理: 2本を同じ方向に巻くだけだと手を離した瞬間にほどけます。外へねじりながら手前へ交差させることで戻る力が噛み合い、絶対にほどけません。\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① 上の束：体の外側(↑)へ強くねじる\",\n        \"② 互いに噛み合ったV字のロープ模様\",\n        \"③ 左手の親指と人差し指で交差点を押さえる\",\n        \"④ ねじった上の束を下の束越しに手前(↓)へ渡す\",\n        \"⑤ 手を離してもほどけない二重ロック構造\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"ステップ4: 短くなった繊維に新しい束を10cm重ねて無限に継ぎ足す\",\n      \"description\": \"編み進めて片方の束が残り10cmほどになり細くなったら、新しい繊維束の端を古い束の横に10cm重ねて添えます。2本を最初から1本だったかのように一緒に持ち、同じく外側へねじって手前へ渡します。上下の継ぎ目が同じ位置に重ならないよう、最低でも一咫（15cm）以上ずらして配置します。\",\n      \"actionNote\": \"> 注意: 上下の継ぎ目が同じ場所に重なると、そこだけ太くなって引っ張った時に切れやすくなります。\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① 残り10cmほどになり細くなった元の束\",\n        \"② 新しい繊維束を10cm並べて重ねる\",\n        \"③ 重ねた2本を1本として一緒にねじり込む\",\n        \"④ 膨らまず滑らかに繋がった継ぎ目\",\n        \"⑤ 上下の継ぎ目を15cm以上ずらして配置\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"ステップ5: 端から3cmに止め結びを作り、木の幹に掛けて体重で引っ張りテスト\",\n      \"description\": \"必要な長さ（5m以上）まで撚り終えたら、端から3cmの位置を輪にして止め結びを作り、ほどけないように仕上げます。表面にはみ出た毛羽立ちを石の刃で軽く削って整えます。最後に太い木の幹にロープを掛け、自分の体重（50kg以上）をかけて強く引っ張り、継ぎ目が滑らないか確認します。\",\n      \"actionNote\": \"> 実戦確認: 引っ張った時にプツッと音がしたり継ぎ目が滑る場合は、その部分に薄い繊維をもう一周巻き付けて補強します。\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① 端から3cmを折って結んだほどけ防止結び\",\n        \"② はみ出た毛羽立ちを石の刃できれいに整える\",\n        \"③ 木の幹に掛けて体重(50kg+)で引っ張りテスト\",\n        \"④ 完成した太さ5mmの野生ロープ (長さ5m)\",\n        \"⑤ シェルター結束・石斧固定・火起こし紐に活用\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絶対にやってはいけないミス：皮を剥いていない緑の生づるをそのまま結んで使う\",\n    \"description\": \"急いでいるからといってクズのつるや枝を丸ごと巻いてシェルターの柱や石斧を結ぶと、最初は固く見えても半日ほどで水分が抜けて縮み、緩んでしまいます。さらに乾燥した木の芯は少しの衝撃で煎餅のように折れます。必ず外皮と芯を除き、白い内皮繊維だけを逆撚りして使ってください。\",\n    \"consequence\": \"結果：就寝中にシェルターの屋根が崩落するか、木を伐採中に石斧の刃が外れて大怪我をする\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"山の中で紐が1本もない時、素手で切れない野生ロープを撚る方法です。\",\n    \"body\": \"生きたクズのつるの茶色い外皮を石で削り、白い内皮だけを長く剥ぎ取ります。水に20分浸して丸石で叩くと糸のように柔らかくなります。半分に折り、上の束を外側にねじって手前に交差させましょう。短くなったら新しい繊維を10cm重ねれば無限に伸ばせます。\",\n    \"outro\": \"木に掛けて体重で引っ張っても切れません。シェルター作りや石斧の固定にすぐ使えます。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"2本撚り逆回転編み天然ロープ完成コイル束\",\n    \"description\": \"樹皮の内皮と葛の繊維を時計回りに撚り、反時計回りに交差編みして引張強度90kg以上に耐える、均一で滑らかな2本撚り天然サバイバルロープ束です。\"\n  },\n  \"createdAt\": \"2026-10-13T13:20:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"03d1706e68d38783\"\n}","content/protocols/locales/05-natural-cordage.pt.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Como trançar corda selvagem inquebrável com casca de árvore e cipó\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[SOBREVIVÊNCIA CRÍTICA]\",\n  \"summary\": \"Uma corda forte é indispensável para amarrar abrigos, fixar machados de pedra e fazer fogo com arco. Cipós verdes inteiros encolhem e quebram ao secar; porém, extrair a fibra branca interna e torcer dois cabos em sentidos opostos cria uma corda autotravante capaz de suportar o peso de um adulto.\",\n  \"timeRequired\": \"40 min\",\n  \"successRate\": \"95% (Com torção reversa)\",\n  \"difficulty\": \"Média (Apenas com as mãos)\",\n  \"outputPerHour\": \"5m / 40 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Cipós vivos, tília, salgueiro ou caules de urtiga (10~15 hastes do comprimento do braço)\",\n      \"desc\": \"Escolha hastes vivas que dobrem sem quebrar e mostrem umidade verde ao raspar com a unha.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 lasca de pedra com borda afiada para raspar\",\n      \"desc\": \"Usada para raspar suavemente a casca externa marrom sem cortar as fibras brancas internas.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Pedra plana de base e pedra redonda do tamanho do punho\",\n      \"desc\": \"Para bater suavemente na casca interna demolhada até soltar fios macios como cabelo.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Água de riacho ou poça para demolhar\",\n      \"desc\": \"Deixe a casca interna de molho por 20~30 minutos para amolecer a seiva e manter as fibras flexíveis.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Escolher hastes flexíveis, raspar a casca externa e puxar a fibra branca interna\",\n      \"description\": \"Dobre a haste ao meio para confirmar que ela curva sem partir. Raspe levemente a casca marrom externa com a quina de uma pedra até revelar a camada branca e resistente de fibra. Levante a ponta inferior com a unha e puxe para cima para destacar fitas longas do miolo lenhoso.\",\n      \"actionNote\": \"> Dica essencial: Galhos secos caídos no chão têm fibras apodrecidas que arrebentam ao puxar. Use sempre hastes vivas.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① Raspar casca externa com quina de pedra\",\n        \"② Casca marrom quebradiça (raspar e descartar)\",\n        \"③ Fibra interna branca e forte (material da corda)\",\n        \"④ Miolo central de madeira dura (descartar)\",\n        \"⑤ Haste viva flexível que dobra sem quebrar\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Deixar 20 minutos na água e bater com pedra redonda até amaciar\",\n      \"description\": \"Mergulhe as fitas de casca interna na água do riacho por 20~30 minutos. Estenda-as sobre uma pedra plana e bata suavemente de cima para baixo com uma pedra redonda. Quando as fibras se soltarem em fios macios como cabelo, divida-as em dois feixes iguais da espessura de um dedo.\",\n      \"actionNote\": \"> Princípio básico: Bater com muita força corta as fibras. Pressione e amasse suavemente para preservar fios longos.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① Casca interna de molho 20+ min no riacho\",\n        \"② Bater suave com pedra redonda para abrir fibras\",\n        \"③ Feixe de fibras macias como fios de cabelo\",\n        \"④ Dois cabos iguais da grossura de um dedo\",\n        \"⑤ Pedra plana firme apoiada no chão\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Torcer para fora e cruzar para o corpo (Torção Reversa)\",\n      \"description\": \"Segure o meio do feixe com o polegar e o indicador esquerdos e dobre ao meio formando um cabo superior e outro inferior. Com a mão direita, torça firmemente o cabo superior para fora (longe do corpo) e depois cruze-o por cima do cabo inferior em direção ao seu corpo. Avance o polegar esquerdo para prender o cruzamento e repita sem parar.\",\n      \"actionNote\": \"> Princípio básico: Girar os dois cabos para o mesmo lado faz a corda desenrolar sozinha. A torção oposta trava os cabos entre si.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① Cabo superior: torcer firme para fora (↑)\",\n        \"② Padrão de corda travado em escama\",\n        \"③ Prender cruzamento com polegar e indicador\",\n        \"④ Cruzar cabo superior sobre o inferior para si (↓)\",\n        \"⑤ Trava reversa que não desmancha ao soltar\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Sobrepor 10cm de fibra nova para emendar comprimento infinito\",\n      \"description\": \"Quando um dos cabos estiver afinando com cerca de 10cm restantes, encoste um feixe novo ao lado da ponta antiga com 10cm de sobreposição. Segure os dois juntos como se fossem um único cabo e continue torcendo para fora e cruzando para dentro. Desencontre as emendas de cima e de baixo em pelo menos um palmo (15cm).\",\n      \"actionNote\": \"> Atenção: Fazer as duas emendas no mesmo ponto cria um caroço fraco que arrebenta sob tensão.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① Cabo antigo afinando com 10cm restantes\",\n        \"② Encostar fibra nova ao lado (10cm sobrepostos)\",\n        \"③ Torcer as duas pontas juntas como um cabo só\",\n        \"④ Emenda lisa sem caroços ou pontos fracos\",\n        \"⑤ Desencontrar emendas de cima e de baixo em 15cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Passo 5: Dar nó de trava na ponta e testar com o peso do corpo em uma árvore\",\n      \"description\": \"Ao atingir o comprimento desejado (5m ou mais), dobre os últimos 3cm e dê um nó simples bem apertado para não desfiar. Raspe os fiapos soltos com uma lasca de pedra. Por fim, passe a corda ao redor de um tronco firme e puxe com todo o peso do corpo (50kg+) para garantir que nenhuma emenda escorregue.\",\n      \"actionNote\": \"> Teste prático: Se ouvir fibras estalando ou notar deslizamento, enrole mais fibra fina sobre o trecho para reforçar.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① Nó de trava a 3cm da ponta final\",\n        \"② Aparar fiapos soltos com lasca de pedra\",\n        \"③ Passar na árvore e puxar com peso do corpo (50kg+)\",\n        \"④ Corda selvagem pronta de 5mm (5m compr.)\",\n        \"⑤ Pronta para abrigo, machado de pedra e arco\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro Fatal: Amarrar cipós verdes inteiros sem descascar\",\n    \"description\": \"Enrolar cipós ou galhos verdes inteiros diretamente no abrigo ou no machado parece firme na hora, mas em poucas horas a seiva seca, o cipó encolhe e afrouxa, e o miolo de madeira quebra como biscoito seco no primeiro impacto. Sempre descasque e trance apenas a fibra interna.\",\n    \"consequence\": \"Consequência: O teto do abrigo desaba durante o sono ou a lâmina do machado escapa causando ferimentos graves\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Como fazer uma corda selvagem inquebrável com as mãos quando você não tem nada na mata.\",\n    \"body\": \"Raspe a casca marrom de um cipó vivo e puxe a fibra branca interna. Deixe 20 minutos na água e bata com uma pedra redonda até amaciar. Dobre ao meio, torça o cabo de cima para fora e cruze para o seu lado. Sobreponha 10cm de fibra nova para emendar sem limite.\",\n    \"outro\": \"Aguenta mais de 50kg presa em uma árvore. Pronta para amarrar abrigos e fixar machados de pedra.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"Rolo de Corda Natural de 2 Pernas com Torção Reversa Concluído\",\n    \"description\": \"Uma bobina de corda uniforme de 8 mm trançada com fibras de casca interna em torção reversa, suportando mais de 90 kgf de tração sem deslizar.\"\n  },\n  \"createdAt\": \"2026-10-13T13:20:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"03d1706e68d38783\"\n}","content/protocols/locales/05-natural-cordage.zh-TW.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"用樹皮與葛藤搓出不斷裂野生繩索的方法\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[必備求生]\",\n  \"summary\": \"搭建避難所綁木柱、固定石斧或使用弓鑽生火時，堅固的繩索不可或缺。若直接拿整根青藤捆綁，乾掉後會收縮並脆裂；只有刮除粗外皮、取出白色內皮纖維，並將兩股纖維反向扭轉交疊，才能做出放手也不會散開、能承受成人體重的強韌野生繩索。\",\n  \"timeRequired\": \"40分鐘\",\n  \"successRate\": \"95% (遵守反向搓繩法時)\",\n  \"difficulty\": \"中等 (徒手即可完成)\",\n  \"outputPerHour\": \"5公尺 / 40分鐘\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"活的葛藤，或椴樹、柳樹、蕁麻莖幹 (手臂長約10~15根)\",\n      \"desc\": \"選擇對折時不會「啪」一聲斷裂、能柔韌彎曲，且用指甲刮表皮會露出翠綠水氣的新鮮藤蔓或樹枝。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"刮除外皮用的帶稜角石片 1塊\",\n      \"desc\": \"用來輕輕刮掉莖幹最外層粗糙易碎的褐色外皮。挑選邊緣適中、不會割斷內部白色纖維的石片。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"敲打纖維用的平坦墊石與拳頭大的圓石\",\n      \"desc\": \"將泡軟的內皮攤在平坦大石上，用圓石輕輕敲打，使纖維鬆開成如頭髮般細軟的絲束。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"浸泡內皮的溪水或積水\",\n      \"desc\": \"將剛剝下的內皮浸泡20~30分鐘以軟化僵硬樹液，並在搓繩過程中保持纖維濕潤不斷裂。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"第1步：挑選柔韌藤莖，刮除褐色粗外皮並撕下白色內皮\",\n      \"description\": \"先將藤莖對折，確認其有彈性且不會折斷。拿石片邊緣斜貼著莖幹，輕輕刮除表面粗糙的褐色外皮，底下就會露出雪白強韌的內皮纖維層。用指甲挑起底部邊緣，朝上方長長地拉扯，就能將絲帶般的白色內皮從堅硬的木質中心完整剝離下來。\",\n      \"actionNote\": \"> 核心訣竅：掉在地上乾枯的死枝纖維已經腐朽，一拉就會斷成碎屑，務必從活藤或剛折下的新鮮枝條取皮。\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① 用石頭稜角輕輕刮除粗糙外皮\",\n        \"② 易碎的褐色外皮 (刮除丟棄)\",\n        \"③ 強韌雪白的內皮纖維層 (做繩核心材料)\",\n        \"④ 中央堅硬的木質內芯 (剝離丟棄)\",\n        \"⑤ 彎曲時不會折斷的鮮活柔韌藤莖\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"第2步：泡溪水20分鐘後，用圓石敲打成細軟絲束\",\n      \"description\": \"將剝下的內皮絲帶放入溪水中浸泡20~30分鐘。把吸飽水分變軟的內皮攤在平坦河石上，拿圓石由上往下輕輕敲打。當僵硬的木紋被敲散、變成如頭髮或棉線般細軟的纖維束後，用手搓揉確認沒有硬刺感，再均勻分成兩股手指粗的纖維束。\",\n      \"actionNote\": \"> 核心原理：敲得太用力會砸斷纖維。不要像剁肉一樣猛砍，而是用圓石輕壓推揉，才能保留長而完整的纖維。\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① 泡溪水20分鐘以上軟化的內皮\",\n        \"② 用圓石輕輕敲打使纖維紋理鬆開\",\n        \"③ 如頭髮般細軟蓬鬆的纖維絲束\",\n        \"④ 均勻分成手指粗細的兩股纖維\",\n        \"⑤ 底部墊著穩固不搖晃的平坦河石\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"第3步：向外扭轉、向內交疊，重複「反向搓繩法」\",\n      \"description\": \"用左手拇指與食指捏住長纖維束正中央，對折成上股與下股兩條。右手抓住上股，朝遠離身體的外側（前方）用力扭緊，接著直接將這條扭緊的上股越過下股、朝自己身體方向（後方）交疊翻過來。左手拇指往前移一格捏緊剛交疊的結點，繼續重複「向外扭緊 ➔ 向內翻越」。\",\n      \"actionNote\": \"> 核心原理：若兩股都朝同方向捲，一放手就會全部鬆開。單股向外扭、兩股向內翻，回彈力才會互相咬死永不鬆脫。\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① 上股纖維：朝身體外側(↑)用力扭緊\",\n        \"② 互相回彈咬合成鋸齒狀的緊密繩紋\",\n        \"③ 左手拇指與食指捏緊剛交疊的結點\",\n        \"④ 將扭緊的上股越過下股朝身體側(↓)翻過來\",\n        \"⑤ 放手也絕對不會鬆開的反向互鎖結構\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"第4步：將新纖維重疊10公分捻入，無限延長繩索長度\",\n      \"description\": \"搓繩過程中，當其中一股剩下約10公分並逐漸變細時，取一束新纖維，將前端與變細的舊股並排重疊10公分。把新舊兩條當作同一股握在一起，照常向外扭緊並向內翻越，搓3~4圈後新纖維就會被牢牢咬住。注意上下兩股的接縫位置必須錯開至少一拃（15公分）以上。\",\n      \"actionNote\": \"> 注意事項：若上下兩股在同一個位置接線，該處會腫成一團且受力時極易從接縫處斷裂。\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① 剩下約10公分並逐漸變細的舊股\",\n        \"② 取新纖維束並排重疊10公分\",\n        \"③ 將重疊的兩條當作同一股一起扭緊\",\n        \"④ 不鼓包且平滑銜接的接縫部位\",\n        \"⑤ 上下兩股接縫位置錯開一拃(15公分)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"第5步：末端打防鬆結，掛在樹幹上用全身體重拉扯測試\",\n      \"description\": \"搓到所需長度（5公尺以上）後，在距離末端3公分處繞圈打一個緊實的單結防止散開，並用鋒利石片輕刮修整繩身竄出的毛邊。最後將完成的繩索繞在手臂粗以上的堅固樹幹上，掛上自己的全身體重（50公斤以上）用力拉扯，確認接縫不滑脫且繩結越拉越緊即可投入實戰。\",\n      \"actionNote\": \"> 實戰確認：拉扯時若聽到纖維斷裂聲或發現接縫滑動，請在該區段外再纏繞一層薄纖維加固。\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① 距離末端3公分處打緊防鬆收尾結\",\n        \"② 用石片將竄出的毛邊刮除修整乾淨\",\n        \"③ 繞在樹幹上掛上體重(50kg+)用力拉扯測試\",\n        \"④ 完成粗度5mm的強韌野生繩索 (長5m)\",\n        \"⑤ 立即用於綁避難所木柱、固定石斧與弓鑽弦\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絕對不能犯的錯誤：直接拿未剝皮的綠色生藤捆綁重物\",\n    \"description\": \"若為了省事直接拿整根青藤或綠樹枝去綁避難所木柱或石斧，當下看似緊固，但只要過半天水分蒸發，藤條就會萎縮鬆脫，中間的木芯更會在受力時像乾餅乾一樣脆裂。務必去除外皮與木芯，只取白色內皮纖維反向搓成繩索。\",\n    \"consequence\": \"後果：睡覺時避難所屋頂坍塌砸傷自己，或砍樹時石斧刀刃飛出造成嚴重外傷\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"在深山裡連一條繩子都沒有時，如何徒手搓出拉不斷的野生繩索？\",\n    \"body\": \"用石頭刮掉鮮活葛藤的褐色外皮，撕下白色內皮纖維。泡水20分鐘後用圓石敲軟成絲束。對折後將上股向外扭緊，再越過下股朝自己翻過來。變短時重疊10公分新纖維就能無限接長。\",\n    \"outro\": \"掛在樹幹上用50公斤體重拉扯也不斷裂，綁避難所、固定石斧都能馬上派上用場。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"雙股反向搓捻天然繩索完成捲束\",\n    \"description\": \"將樹皮內韌皮與葛藤纖維順時針搓捻、逆時針交叉纏繞，具備90公斤以上抗拉強度的勻稱平滑雙股天然生存繩索捲束完成形態。\"\n  },\n  \"createdAt\": \"2026-10-13T13:20:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"03d1706e68d38783\"\n}","content/protocols/locales/06-clay-hearth.de.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Wie man eine primitive Lehmofenfeuerstelle baut, um Wind abzuhalten und Hitze zu speichern\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[LEBENSWICHTIGE WÄRME & UNTERKUNFT]\",\n  \"summary\": \"Ein offenes Bodenfeuer verliert über 80% seiner Wärme an den Wind und verbraucht dreimal mehr Brennholz, während umherfliegende Funken eine schwere Brandgefahr darstellen. Durch den Bau eines Kuppelofens aus Lehm, Sand, trockenem Gras und trockenen Steinen entsteht eine wetterfeste Koch- und Wärmestelle, die Hitze speichert und die ganze Nacht über warm hält.\",\n  \"timeRequired\": \"3 Stunden\",\n  \"successRate\": \"90% (Mit langsamer Vortrocknung)\",\n  \"difficulty\": \"Mittel (Lehmkneten & Steinmauern)\",\n  \"outputPerHour\": \"1 Dauerhafter Ofen\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"2 Schalen klebriger roter Lehm (an Uferböschungen ausgegraben)\",\n      \"desc\": \"Wählen Sie dichten, bindigen Lehm, der sich wie Teig formen lässt, ohne zu zerbröckeln. Dient als thermisches Hauptbindemittel.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Schale grober Flusssand (trockener Sand mit Mineralkörnern)\",\n      \"desc\": \"Reiner Lehm schrumpft und reißt beim Trocknen. Grober Sand bildet das tragende Gerüst, das Rissbildung verhindert.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 Schale fingerlang geschnittenes trockenes Gras oder Stroh\",\n      \"desc\": \"Wirkt als Faserarmierung in der Lehmmischung und verhindert, dass die Wände unter großer Hitze zerspringen.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"15~20 staubtrockene Bruchsteine (faust- bis kopf傚groß)\",\n      \"desc\": \"Wassergesättigte Flusssteine explodieren bei Hitzeeinwirkung. Verwenden Sie nur trockene Steine von sonnigen Hängen mindestens 10 m vom Wasser entfernt.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: 2 Teile Lehm, 1 Teil Sand und 1 Teil trockenes Gras mit Wasser zu zähem Cob-Mörtel stampfen\",\n      \"description\": \"Geben Sie 2 Schalen roten Lehm, 1 Schale groben Sand und 1 Schale fingerlanges trockenes Gras auf ebenen Boden. Geben Sie schrittweise kleine Mengen Wasser hinzu, während Sie das Gemisch mit den Fersen gründlich durchtreten. Falten Sie den Haufen wiederholt um und stampfen Sie mindestens 10 Minuten, bis sich eine faustgroße Kugel ohne Oberflächenrisse formen lässt.\",\n      \"actionNote\": \"> Wasser-Faustregel: Zu viel Wasser erzeugt schlammigen Brei, der einsackt; zu wenig hinterlässt bröckeligen Staub. Streben Sie eine zähe, teigartige Konsistenz an.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 2 Teile klebriger roter Lehm\",\n        \"Bindiges mineralisches Grundmaterial\",\n        \"+\",\n        \"② 1 Teil grober Flusssand\",\n        \"Verhindert Schrumpfung und Rissbildung\",\n        \"+\",\n        \"③ Fingerlange trockene Grasfasern\",\n        \"Strukturelle Armierungsmatrix\",\n        \"④ Wasser schrittweise zugeben und mit Fersen stampfen\",\n        \"Niemals überschwemmen; falten & durchtreten\",\n        \"⑤ Fertige zähe Lehmkugel\",\n        \"Zu fester faustgroßer Kugel formbar\",\n        \"Keine Risse an der Außenfläche\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Faustgroße trockene Steine hufeisenförmig auf trockenem Boden als Fundament anordnen\",\n      \"description\": \"Richten Sie die Brennholzöffnung (eine Handspanne breit, ca. 20 cm) windabgewandt aus. Legen Sie faustgroße trockene Steine hufeisenförmig aus. Bringen Sie im Innenbereich 2~3 cm trockenen Sand und Kies ein, um Bodenfeuchtigkeit und Kälte abzusperren. Verfüllen Sie alle Zwischenräume mit zähem Lehm unter festem Faustdruck.\",\n      \"actionNote\": \"> Windrichtung beachten: Wenn die Öffnung im Gegenwind liegt, schlagen Funken ins Gesicht. Richten Sie die Feueröffnung immer windabgewandt oder schräg aus.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① Vordere Holzbeschickungsöffnung (20 cm breit)\",\n        \"Optimale Breite für Holz & Luftzufuhr\",\n        \"② Hufeisenförmige trockene Fundamentsteine\",\n        \"Tragendes Primärfundament\",\n        \"③ Dicker Lehmmörtel in Steinfugen\",\n        \"Dichtet Fugen gegen Nebenluft ab\",\n        \"④ Trockene Sand- & Kiesschicht am Boden\",\n        \"Wärmesperre gegen kalten Untergrund\",\n        \"⑤ Windabgewandte Ausrichtung der Öffnung\",\n        \"Schützt die Glut vor Windböen\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Steine und Lehm schichtweise versetzt zu einer kniehohen Kuppel aufmauern\",\n      \"description\": \"Bringen Sie eine handbreite Lehmschicht (ca. 5 cm) auf das Fundament auf, setzen Sie die nächste Steinreihe im Verband auf und neigen Sie die Wand nach innen, bis eine kniehohe Kuppel (ca. 45 cm) entsteht. Glätten Sie anschließend die Innenwand mit nassen Händen zu einer glatten Reflexionsfläche.\",\n      \"actionNote\": \"> Einsturzgefahr vermeiden: Mauern Sie niemals reine Lehmwände ohne Steinkerne hoch. Steine bilden das Skelett, während der Lehm die Wärme speichert.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① Querschnitt aus Stein & Lehmmörtel\",\n        \"Verzahnte Steine verhindern Einsturz\",\n        \"② Handtellerdicke (5 cm) wärmedämmende Lehmwand\",\n        \"Hohe Speichermasse hält Wärme über Nacht\",\n        \"③ Glatte wärmereflektierende Innenfläche\",\n        \"Mit nasser Hand für guten Zug geglättet\",\n        \"④ Kreisförmige innere Brennkammer\",\n        \"Hitze zirkuliert und steigt auf\",\n        \"⑤ Kniehohe Gesamthöhe (45 cm)\",\n        \"Optimales Verhältnis aus Volumen & Kochhöhe\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Oberen Topfausschnitt anlegen und hinteren Kaminabzug ausstechen\",\n      \"description\": \"Lassen Sie am Scheitelpunkt der Kuppel eine 15~20 cm runde Öffnung für Tontöpfe oder Steinplatten frei. Drücken Sie drei kleine Abstandssteine in den Rand, damit 1 cm Luftspalt für den Zug bleibt. Durchstoßen Sie die obere Rückwand schräg mit einem Ast, um einen Kaminabzug für den Rauch anzulegen.\",\n      \"actionNote\": \"> Zugluftprinzip: Ohne Kamin drückt der Rauch vorn heraus. Der Kaminabzug erzeugt einen Unterdruck, der Sauerstoff kräftig durch den Fußbereich ansaugt.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① Unterer vorderer Lufteinlass (Sauerstoff)\",\n        \"Frischluft strömt ins Glutbett\",\n        \"② Obere flache Kochöffnung\",\n        \"Sitz für Topf oder Bratstein\",\n        \"③ Oberer hinterer schräger Kaminabzug\",\n        \"Zieht beißenden Rauch sauber nach hinten ab\",\n        \"④ Aufsteigender thermischer Wirbelzug\",\n        \"Zirkuliert im Raum und erhitzt Topfboden\",\n        \"⑤ Topfabstandsnoppen für Dauerzug\",\n        \"Feuer erstickt nicht bei aufgesetztem Topf\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Schritt 5: Mit kleinem Zweigfeuer 3 Stunden vortrocknen und steinhart ausbrennen\",\n      \"description\": \"Entfachen Sie niemals sofort ein großes Holzfeuer in feuchtem Lehm; siedendes Porenwasser würde die Wände zersprengen. Halten Sie 3~4 Stunden lang ein winziges Zweigfeuer an der Vorderöffnung. Wenn Dampf austritt und der Lehm von feuchtem Dunkelbraun zu hellem Ocker wechselt und sich warm anfühlt, ist der Ofen einsatzbereit.\",\n      \"actionNote\": \"> Haarrisse ausbessern: Sollten beim Trocknen feine Haarrisse auftreten, streichen Sie diese einfach mit feuchtem Lehmschlicker mit dem Finger glatt.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① Sanftes Zweigglutfeuer an der Öffnung\",\n        \"Gleichmäßige Wärme lässt Feuchte entweichen\",\n        \"② Abdampfende Wasserdampfschwaden\",\n        \"Porenwasser verdampft zerstörungsfrei\",\n        \"③ Farbwechsel-Prüfpunkt\",\n        \"Feuchtes Dunkelbraun → trockenes Hellocker\",\n        \"④ Trocken- & Wärmeprüfung von Hand\",\n        \"Wand fühlt sich trocken und warm an\",\n        \"⑤ Ausbesserungsschlicker für Haarrisse\",\n        \"Risse mit frischem Lehm zuschmieren\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Verwendung nasser Flusssteine direkt im Brennraumfeuer\",\n    \"description\": \"Wassergesättigte Flusskiesel schließen selbst bei trockener Oberfläche Feuchtigkeit in mikroskopischen Poren ein. Bei Feuertemperaturen über 300°C wandelt sich dieses Wasser schlagartig in Hochdruckdampf um und detoniert wie eine Granate. Rasiermesserscharfe Splitter fliegen in Gesicht und Augen, was zu Erblindung und schweren Fleischwunden führt. Verwenden Sie nur trockene Steine 10 m abseits von Gewässern und ummanteln Sie diese mit mindestens 5 cm Lehm.\",\n    \"consequence\": \"Folge: Dampfexplosionen schleudern messerscharfe Steinsplitter, was zu Erblindung und schweren Verletzungen führt\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Ein Bodenfeuer verliert 80% seiner Wärme. So baut man einen sturmfesten Naturlehmofen.\",\n    \"body\": \"2 Teile Lehm, 1 Teil Sand und 1 Teil trockenes Gras mit Wasser zu zähem Teig stampfen. Trockene Steine hufeisenförmig windabgewandt anordnen. Steine und Lehm versetzt zu einer kniehohen Kuppel mit oberem Topfloch und Kaminabzug aufmauern. 3 Stunden mit kleiner Glut trockenbrennen. Niemals nasse Flusssteine verwenden; Dampfdruck lässt sie detonieren.\",\n    \"outro\": \"Kochen Sie warm und trotzen Sie Regen und stürmischen Winden die ganze Nacht.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"Vollendeter Stein- und Lehmofen mit Kochöffnung\",\n    \"description\": \"Ein hufeisenförmiges Steinfundament, verputzt mit 5 cm strohbasiertem feuerfestem Lehm, mit ebener Stein-Kochplatte und hinterem Abzugskamin für 650°C Hitze.\"\n  },\n  \"createdAt\": \"2026-10-14T10:15:00.000Z\",\n  \"contentHash\": \"92064fb90844ce2f\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\"\n}","content/protocols/locales/06-clay-hearth.en.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"How to Build a Primitive Clay & Stone Hearth to Block Wind and Trap Heat\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[ESSENTIAL SHELTER & WARMTH]\",\n  \"summary\": \"Building an open campfire on the ground loses over 80% of heat to the wind and burns firewood three times faster, while windborne sparks pose a severe fire hazard. By building a cob dome hearth with clay, sand, dry grass, and dry stones, you create a weatherproof cooking and heating shelter that traps heat and stays warm all night long.\",\n  \"timeRequired\": \"3 Hours\",\n  \"successRate\": \"90% (With Slow Pre-Cure)\",\n  \"difficulty\": \"Medium (Mud Mixing & Stone Stacking)\",\n  \"outputPerHour\": \"1 Permanent Hearth\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"2 Bowls of Sticky Red Clay (dug from riverbank or exposed soil banks)\",\n      \"desc\": \"Choose dense, cohesive clay that squishes like dough without crumbling. Acts as the primary thermal binder.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Bowl of Coarse Sand or Gritty Soil (dry river sand)\",\n      \"desc\": \"Pure clay shrinks and cracks apart when drying. Coarse sand acts as a structural aggregate to prevent cracking.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 Bowl of Dry Grass or Straw Cut to Finger Length\",\n      \"desc\": \"Acts as organic reinforcement fiber within the mud mixture, preventing the walls from shattering under intense fire heat.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"15~20 Bone-Dry Fractured Stones (fist to head size)\",\n      \"desc\": \"Waterlogged river stones explode violently under heat. Use only bone-dry stones gathered from sunny ridges at least 10m away from water.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Stomp 2 Parts Clay, 1 Part Sand, and 1 Part Dry Grass with Water into Tough Cob\",\n      \"description\": \"Pour 2 bowls of red clay, 1 bowl of coarse sand, and 1 bowl of finger-length dry grass onto flat ground. Add small splashes of water while thoroughly stomping with bare heels. Fold the clay mound in half and stomp repeatedly for 10 minutes until you can roll a fist-sized ball without surface cracks.\",\n      \"actionNote\": \"> Key Principle: Too much water makes sloppy mud that slumps; too little leaves crumbly dust. Aim for a stiff, dough-like consistency that holds its shape firmly.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 2 parts sticky red clay\",\n        \"Cohesive binder base material\",\n        \"+\",\n        \"② 1 part coarse river sand\",\n        \"Prevents shrinkage and cracking\",\n        \"+\",\n        \"③ Finger-length dry grass fiber\",\n        \"Reinforcing structural tensile web\",\n        \"④ Add water gradually and stomp with heels\",\n        \"Never flood all at once; fold & stomp\",\n        \"⑤ Finished stiff cob ball\",\n        \"Roll into a solid fist-sized ball\",\n        \"Zero cracks on outer surface\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Lay Fist-Sized Dry Stones in a Horseshoe U-Shape to Anchor the Foundation\",\n      \"description\": \"Orient the fire mouth opening (one hand-span wide, approx. 20 cm) away from the prevailing wind. Place fist-sized dry stones in a horseshoe U-shape. Lay 2~3 cm of dry sand and gravel inside the floor to block ground moisture and cold. Pack thick cob mud between all stone crevices with your fists to anchor them firmly.\",\n      \"actionNote\": \"> Wind Direction: Facing the mouth straight into the wind blows hot embers into your face. Always point the opening downwind or crosswind.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① Front firewood intake mouth (20 cm wide)\",\n        \"Optimal width for wood feeding & airflow\",\n        \"② Horseshoe U-shaped dry anchor stones\",\n        \"Primary foundation perimeter\",\n        \"③ Thick cob mortar in stone joints\",\n        \"Prevents drafts and air leaks\",\n        \"④ Dry sand & gravel base insulator\",\n        \"Thermal barrier against cold ground\",\n        \"⑤ Fire mouth facing away from wind\",\n        \"Protects ember bed from wind gusts\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Stagger Stones and Cob Layer by Layer into a Knee-High Dome\",\n      \"description\": \"Spread a palm-thick layer (approx. 5 cm) of cob over the foundation stones, bed down the next row of stones staggered over the joints, and corbel them slightly inward as you build up to knee height (approx. 45 cm). Once the dome is built, dip your hands in water and smooth the inner clay wall into a slick, continuous curved surface to reflect and circulate heat.\",\n      \"actionNote\": \"> Prevent Collapse: Never build pure mud walls high without stone cores. The stones provide the structural skeleton while the thick clay skin traps radiant heat.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① Staggered stone & cob cross-section\",\n        \"Interlocking stones prevent structural failure\",\n        \"② Palm-thick (5 cm) thermal cob wall\",\n        \"Heavy thermal mass traps heat overnight\",\n        \"③ Smooth water-burnished heat reflector\",\n        \"Smoothed by wet hand for smooth draft\",\n        \"④ Spherical internal combustion chamber\",\n        \"Heat circulates and concentrates upward\",\n        \"⑤ Knee-high (45 cm) total profile\",\n        \"Optimal balance of volume and cooking height\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Cut a Top Cooking Pot Ring and Punch a Rear Exhaust Flue\",\n      \"description\": \"Leave a 15~20 cm circular opening at the very top of the dome for resting a clay pot or flat cooking stone. Embed three small stone spacers around the rim to create a 1 cm gap so sitting a pot will not choke the fire. Push a wrist-thick green stick angled through the upper back wall to pierce a chimney flue hole for smoke exhaust.\",\n      \"actionNote\": \"> Air Draft Principle: Without a high rear flue, smoke billows out the front wood opening into your eyes. The flue creates a strong thermal chimney effect that draws oxygen vigorously into the base.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① Lower front air intake (oxygen supply)\",\n        \"Cold fresh air drawn into burning ember bed\",\n        \"② Flat top circular cooking port\",\n        \"Seat for stone pan or clay pot\",\n        \"③ Upper rear angled chimney flue\",\n        \"Draws acrid smoke cleanly out the back\",\n        \"④ Updraft thermal vortex airflow\",\n        \"Vigorous draft heats cooking vessel base\",\n        \"⑤ Pot spacer nubs for continuous draft\",\n        \"Air passes freely even with pot seated\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Step 5: Cure with a Low Twig Fire for 3 Hours to Bake the Clay into Brick Hardness\",\n      \"description\": \"Never light a raging log fire immediately in fresh wet cob; sudden boiling moisture will blow steam fissures through the walls. Build a tiny fist-sized twig fire near the front mouth and keep it gentle for 3~4 hours. Watch white steam vapor evaporate from the outer walls as the dark wet brown clay shifts to a warm light ochre. Once dry and warm to the touch, your permanent hearth is ready.\",\n      \"actionNote\": \"> Repairing Hairline Cracks: If minor hairline cracks appear while drying, smear a fingertip of wet clay paste over them to seal and fuse them instantly.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① Gentle twig ember fire at mouth\",\n        \"Gentle heat allows gradual moisture exit\",\n        \"② Steam vapor plumes venting outward\",\n        \"Internal water evaporates safely\",\n        \"③ Color transition milestone\",\n        \"Dark damp brown → dry pale ochre\",\n        \"④ Warm & dry touch test\",\n        \"Wall feels warm without sticky dampness\",\n        \"⑤ Touch-up paste for hairline cracks\",\n        \"Seal minor fissures with wet clay paste\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Using Wet River Stones Directly Exposed to Fire Inside the Chamber\",\n    \"description\": \"Waterlogged river stones and creek pebbles have moisture trapped inside microscopic pores even if the surface feels dry. When exposed to fires over 300°C, trapped water violently flashes into high-pressure steam and detonates like a grenade. Razor-sharp shrapnel flies outward into your face and eyes, causing blindness and catastrophic lacerations. Always gather dry stones from sunny ridges 10m away from water, and coat them under at least 5 cm of thick cob mud.\",\n    \"consequence\": \"Consequence: Steam explosion shrapnel causes permanent blindness and severe trauma\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"An open ground fire loses 80% of its heat. Here is how to build a weatherproof primitive hearth.\",\n    \"body\": \"Mix 2 parts sticky clay, 1 part sand, and 1 part dry grass with water and stomp into dough. Lay dry stones in a U-shape facing away from the wind. Stagger stones and thick mud into a knee-high dome with a pot hole on top and a chimney flue out back. Cure with a tiny fire for 3 hours to bake it rock-solid. Never use wet river stones inside; steam pressure will cause them to detonate.\",\n    \"outro\": \"Cook your meals and stay warm all night through rain and howling winds.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"Completed Stone & Tempered Clay Cooking Hearth\",\n    \"description\": \"A horseshoe stone base sealed under 5cm of straw-tempered refractory clay plaster, featuring a level stone cooktop and rear chimney flue holding intense 650°C heat.\"\n  },\n  \"createdAt\": \"2026-10-14T10:15:00.000Z\",\n  \"contentHash\": \"92064fb90844ce2f\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\"\n}","content/protocols/locales/06-clay-hearth.es.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Cómo Construir un Fogón Primitivo de Barro y Piedras para Protegerse del Viento y Retener Calor\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[CALOR Y REFUGIO ESENCIAL]\",\n  \"summary\": \"Hacer una fogata abierta directamente en el suelo pierde más del 80% del calor con el viento y consume tres veces más leña, mientras que las chispas voladoras representan un grave riesgo de incendio. Al levantar un fogón en cúpula con barro, arena, hierba seca y piedras secas, se crea un refugio térmico resistente al mal tiempo que permite cocinar y conservar calor durante toda la noche.\",\n  \"timeRequired\": \"3 Horas\",\n  \"successRate\": \"90% (Con Curado Lento)\",\n  \"difficulty\": \"Media (Amasado de Barro y Apilado)\",\n  \"outputPerHour\": \"1 Fogón Permanente\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"2 Cuencos de Arcilla Roja Pegajosa (excavada en riberas o taludes)\",\n      \"desc\": \"Elija tierra densa que se amase como masa de pan sin desmoronarse. Actúa como el aglutinante térmico principal.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Cuenco de Arena Gruesa de Río (arena seca con granos minerales)\",\n      \"desc\": \"La arcilla pura se encoge y se agrieta al secar. La arena gruesa proporciona el esqueleto estructural que evita grietas.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 Cuenco de Hierba Seca o Paja Cortada a la Medida de un Dedo\",\n      \"desc\": \"Funciona como fibra de refuerzo dentro de la mezcla, impidiendo que las paredes colapsen bajo el calor del fuego.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"15~20 Piedras Quebradas Completamente Secas (tamaño puño a cabeza)\",\n      \"desc\": \"Las piedras de río anegadas explotan con el calor. Utilice únicamente piedras secas recolectadas de lomas soleadas a más de 10 m del agua.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Pisar 2 partes de arcilla, 1 de arena y 1 de hierba seca con agua hasta formar barro maleable\",\n      \"description\": \"Vierta sobre tierra plana 2 cuencos de arcilla roja, 1 de arena gruesa y 1 de hierba seca cortada. Agregue pequeñas cantidades de agua mientras pisotea con los talones. Doble la masa por la mitad y pise durante más de 10 minutos hasta poder formar una bola del tamaño de un puño sin fisuras superficiales.\",\n      \"actionNote\": \"> Clave del Agua: Demasiada agua hace lodo aguado que se cae; muy poca deja polvo quebradizo. Busque una consistencia firme similar a masa de empanadas.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 2 partes de arcilla roja pegajosa\",\n        \"Materia prima aglutinante base\",\n        \"+\",\n        \"② 1 parte de arena gruesa de río\",\n        \"Evita contracción y agrietamiento\",\n        \"+\",\n        \"③ Fibra de hierba seca cortada\",\n        \"Malla estructural de refuerzo interno\",\n        \"④ Agregar agua poco a poco y pisar con talones\",\n        \"Nunca inundar de golpe; doblar y pisar\",\n        \"⑤ Bola de barro firme terminada\",\n        \"Moldear en bola sólida tamaño puño\",\n        \"Superficie exterior sin fisuras\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Disponer piedras secas en herradura (forma de U) sobre suelo seco para la base\",\n      \"description\": \"Oriente la boca de alimentación de leña (ancho de una mano, aprox. 20 cm) en dirección opuesta al viento. Coloque piedras secas en forma de U. Extienda en el fondo interior 2~3 cm de arena y grava seca para bloquear la humedad del suelo. Rellene todas las juntas entre piedras con barro firme usando los puños para anclarlas.\",\n      \"actionNote\": \"> Dirección del Viento: Colocar la boca de frente al viento provocará llamaradas y chispas hacia su rostro. Apunte siempre en dirección contraria o perpendicular.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① Boca frontal para leña (20 cm de ancho)\",\n        \"Ancho óptimo para leña y entrada de aire\",\n        \"② Piedras secas de anclaje en forma de U\",\n        \"Perímetro estructural de la base\",\n        \"③ Mortero de barro grueso en juntas\",\n        \"Sella fugas de aire entre piedras\",\n        \"④ Aislante de arena y grava en el fondo\",\n        \"Barrera térmica contra el suelo frío\",\n        \"⑤ Boca orientada en contra del viento\",\n        \"Protege las brasas de ráfagas violentas\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Apilar piedras y barro de forma alternada hasta formar una cúpula a la altura de la rodilla\",\n      \"description\": \"Extienda una capa de barro del grosor de una palma (aprox. 5 cm) sobre las piedras base, asiente la siguiente hilera trabando las uniones y vaya inclinándolas hacia adentro hasta alcanzar la altura de la rodilla (aprox. 45 cm). Al terminar, humedezca sus manos en agua y alise la pared interior para crear una curva reflectora continua.\",\n      \"actionNote\": \"> Evitar Colapso: Nunca levante paredes altas solo con barro sin núcleo de piedra. Las piedras brindan el esqueleto y el barro retiene la radiación térmica.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① Corte transversal de piedras y barro\",\n        \"Piedras trabadas evitan fallas estructurales\",\n        \"② Pared gruesa de barro (5 cm) aislante\",\n        \"Masa térmica retiene calor toda la noche\",\n        \"③ Superficie lisa reflectora de calor\",\n        \"Alisada con mano húmeda para buen tiro\",\n        \"④ Cámara de combustión esférica interior\",\n        \"El calor circula y se concentra arriba\",\n        \"⑤ Perfil total a la rodilla (45 cm)\",\n        \"Equilibrio ideal de volumen y cocción\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Abrir un orificio superior para ollas y perforar una chimenea trasera\",\n      \"description\": \"Deje una abertura circular de 15~20 cm en la cúspide para asentar ollas de barro o piedras planas de cocción. Incruste tres piedras pequeñas alrededor del borde para dejar 1 cm de separación que permita el paso del aire. En la parte superior trasera, introduzca una rama gruesa en diagonal para abrir el conducto de la chimenea.\",\n      \"actionNote\": \"> Principio de Tiro: Sin chimenea trasera, el humo sale por el frente cegando los ojos. El conducto genera un efecto térmico que atrae oxígeno fresco por la base.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① Entrada inferior de aire (oxígeno fresco)\",\n        \"Aire fresco succionado hacia las brasas\",\n        \"② Orificio superior plano para cocinar\",\n        \"Asiento para olla o plancha de piedra\",\n        \"③ Salida trasera inclinada de chimenea\",\n        \"Expulsa el humo denso hacia atrás\",\n        \"④ Vórtice térmico ascendente de calor\",\n        \"Gira en la cámara calentando la base\",\n        \"⑤ Salientes espaciadoras para el tiro\",\n        \"El fuego no se ahoga al colocar la olla\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Paso 5: Curar con fuego suave de ramitas durante 3 horas para endurecer el barro como ladrillo\",\n      \"description\": \"Nunca encienda un fuego fuerte inmediato en barro fresco; la ebullición repentina del agua interna reventará las paredes. Encienda una pequeña fogata de ramitas cerca de la boca y manténgala suave durante 3~4 horas. Observe cómo sale vapor blanco mientras el barro cambia de marrón oscuro húmedo a ocre pálido seco. Cuando esté caliente y seco al tacto, el fogón permanente estará listo.\",\n      \"actionNote\": \"> Reparar Fisuras: Si aparecen grietas finas durante el secado, frote pasta de barro húmeda con la yema de los dedos para sellarlas de inmediato.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① Fuego suave de ramitas en la entrada\",\n        \"Calor moderado permite salida de vapor\",\n        \"② Penachos de vapor de agua evaporándose\",\n        \"El agua interna se evapora sin reventar\",\n        \"③ Transición visual de color\",\n        \"Marrón oscuro húmedo → ocre pálido seco\",\n        \"④ Prueba de tacto seco y caliente\",\n        \"Pared tibia sin humedad pegajosa\",\n        \"⑤ Pasta de retoque para fisuras finas\",\n        \"Sellar grietas con pasta de barro fresca\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error Fatal: Usar Piedras Húmedas de Río en Contacto Directo con el Fuego en la Cámara\",\n    \"description\": \"Las piedras de río anegadas retienen agua atrapada en microporos internos aunque su superficie parezca seca. Al someterse a fuegos de más de 300°C, el agua atrapada se convierte instantáneamente en vapor a alta presión y estalla como una granada. Esquirlas afiladas salen disparadas hacia el rostro y los ojos, provocando ceguera permanente y graves traumatismos. Use siempre piedras de lomas secas a 10 m del agua y cúbralas con 5 cm de barro grueso.\",\n    \"consequence\": \"Consecuencia: La explosión por vapor arroja metralla de piedra provocando ceguera y heridas graves\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Un fuego abierto en el suelo pierde el 80% de su calor. Así se construye un fogón primitivo resistente a la lluvia.\",\n    \"body\": \"Pise 2 partes de arcilla, 1 de arena y 1 de hierba seca con agua hasta lograr una masa firme. Forme una herradura de piedras secas con la boca en contra del viento. Levante una cúpula trabando piedras y barro con un orificio superior y una chimenea trasera. Cure 3 horas con fuego suave para dejarlo duro como ladrillo. Jamás use piedras húmedas de río adentro; estallarán por presión de vapor.\",\n    \"outro\": \"Cocine alimentos y mantenga calor agradable durante toda la noche bajo tormentas.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"Fogón Primitivo de Piedra y Arcilla Revestida Completado\",\n    \"description\": \"Una base de piedra en herradura sellada con 5 cm de arcilla refractaria templada con paja, con una superficie de cocción nivelada y chimenea trasera a 650°C.\"\n  },\n  \"createdAt\": \"2026-10-14T10:15:00.000Z\",\n  \"contentHash\": \"92064fb90844ce2f\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\"\n}","content/protocols/locales/06-clay-hearth.ja.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"粘土と石を積み上げて風雨を防ぎ熱を閉じ込める原始かまどの作り方\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[体温・食料必須]\",\n  \"summary\": \"野外で地面に直接火を起こすと、熱の80%が風で散り薪が3倍以上消費される上、火の粉が舞い上がり危険です。赤粘土、砂、枯草を練り合わせた泥ペーストで石を包み込みドーム状のかまどを築くことで、風雨の中でも消えず、煮炊きを行い朝まで熱を蓄え続ける堅牢な生存熱源になります。\",\n  \"timeRequired\": \"3時間\",\n  \"successRate\": \"90% (弱火乾燥を厳守した場合)\",\n  \"difficulty\": \"普通 (泥こねと石積み作業)\",\n  \"outputPerHour\": \"1基完成 (永久使用可能)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"粘性のある赤粘土 2杯 (川岸や露出した土手から採取した粘り土)\",\n      \"desc\": \"手で握ったときに餅のようにまとまり指に吸い付く土を選びます。かまどの壁を強固に固める主原料です。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"粗い川砂 1杯 (粒状の砂利が混ざった乾いた砂)\",\n      \"desc\": \"粘土だけでは乾燥時に収縮して割れてしまいます。粗い砂を混ぜることで骨材となりひび割れを防ぎます。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"指の長さに切った枯草またはワラ 1杯\",\n      \"desc\": \"泥の中で繊維質の鉄筋の役割を果たし、炎の高熱を受けても壁体が割れたり崩れたりするのを防ぎます。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"水気のない硬い割り石 15〜20個 (拳〜頭大の乾いた石)\",\n      \"desc\": \"水に浸かっていた川石は加熱時に水蒸気爆発を起こすため、水辺から10m以上離れた日当たりの良い尾根の完全に乾いた石のみを選びます。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ 1: 粘土2、砂1、枯草1に水を少しずつ加え足で踏み込んで粘り強い泥生地を作る\",\n      \"description\": \"平らな地面に赤粘土2杯、粗砂1杯、指大に切った枯草1杯を広げます。水を一度に入れすぎず少しずつかけながら、かかとでしっかり踏み込んで練り合わせます。泥を二つ折りにしながら10分以上踏み続け、拳大の団子に丸めても表面にひびが入らない状態までしっかり練り上げます。\",\n      \"actionNote\": \"> 水加減の極意: 水が多すぎると泥が崩れて壁にならず、少なすぎるとパサついて割れます。餃子の皮のように少し硬めで粘りのある状態が最適です。\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 粘性のある赤粘土 2杯\",\n        \"粘着力を持つ基本母材\",\n        \"+\",\n        \"② 粗い川砂 1杯\",\n        \"乾燥時の収縮・ひび割れ防止\",\n        \"+\",\n        \"③ 細かく切った枯草の繊維\",\n        \"骨組みとなる補強繊維層\",\n        \"④ 水を少しずつ加え足で踏み込む\",\n        \"一気に水を注がず折り返しながら踏む\",\n        \"⑤ 粘りのある泥団子の完成\",\n        \"拳大に丸めても崩れない\",\n        \"表面に細かな亀裂がない状態\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ 2: 乾いた地面に拳大の石をU字型に並べて基礎を築く\",\n      \"description\": \"風下に向けて薪の投入口(手のひら幅、約20cm)を空け、拳より少し大きめの乾いた石を馬蹄形(U字型)に並べます。内側の床には乾いた砂や砂利を2〜3cm敷き、地面からの湿気と冷気を遮断します。石と石の隙間にステップ1で作った泥を拳で強く押し込み、隙間なく埋めて地面と密着させます。\",\n      \"actionNote\": \"> 風向きの注意: 投入口が風上を向いていると突風で火の粉が逆流し危険です。必ず風下または風を斜めに受ける向きに口を設けてください。\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① 前方の薪投入口 (幅約20cm)\",\n        \"薪の補給と給気に最適な間口\",\n        \"② U字型に並べた拳大の乾いた石\",\n        \"基礎を支える一次骨組み\",\n        \"③ 隙間を埋めた厚手の泥ペースト\",\n        \"石の隙間からの空気漏れを完全遮断\",\n        \"④ 底面の乾いた砂・砂利断熱層\",\n        \"冷たい地表の湿気と冷気を遮断\",\n        \"⑤ 風下を向けた開口部の配置\",\n        \"突風による火の粉逆流と失火を防止\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ 3: 石と泥を交互に積み上げ膝丈のドーム壁を立ち上げる\",\n      \"description\": \"基礎石の上に手のひら厚(約5cm)の泥を敷き、その上に石を互い違いに載せながら、徐々に内側へすぼめて膝の高さ(約45cm)までドーム型に築きます。壁を積み終えたら、手に水をつけて内壁を滑らかに塗り固めます。内壁が滑らかなほど、燃焼室の中で熱気が対流し高温を保てます。\",\n      \"actionNote\": \"> 崩落防止: 泥だけで高く築くと自重で潰れます。必ず石を芯材にし、その外側と内側を厚い泥でしっかり包み込むように施工してください。\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① 互い違いに積んだ壁体断面\",\n        \"石の間に泥を詰め崩壊を防止\",\n        \"② 手のひら厚(約5cm)の泥断熱壁\",\n        \"外側への熱逃げを完全に防ぐ\",\n        \"③ 滑らかな熱反射曲面\",\n        \"水の手で平滑に撫で上げた内壁\",\n        \"④ 熱が対流する円形燃焼室内部\",\n        \"⑤ 膝丈(約45cm)の外形ライン\",\n        \"調理安定性と蓄熱容積の最適化\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"ステップ 4: 天面に鍋置き用の穴を残し後方に煙突穴を開ける\",\n      \"description\": \"ドームの頂上中央に鍋や平らな石板を載せるための円形の穴(直径15〜20cm)を残します。鍋を置いた際に火が消えないよう、穴の周囲に小石3個を三角形に埋め込んで1cmの通気隙間を確保します。そして後方上部には手首太さの小枝を斜めに突き刺して煙を逃がす煙突穴を開け、強力な上昇気流を作ります。\",\n      \"actionNote\": \"> 通気の原理: 煙突がないと煙が前の投入口から噴き出して目が痛くなります。後方の煙突を前口より高い位置に設けることで煙がきれいに抜けます。\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① 前方下部の吸気口 (酸素供給)\",\n        \"冷たく新鮮な空気が引き込まれる通路\",\n        \"② 上部の平坦な調理用開口部\",\n        \"鍋や平石を安定して据える火口\",\n        \"③ 後方上部の煙突排気穴\",\n        \"煙を背後へ効率よく吸い出す排気口\",\n        \"④ 立ち昇る熱対流ライン\",\n        \"燃焼室内を旋回し鍋底を加熱\",\n        \"⑤ 鍋受け通気スペーサー突起\",\n        \"鍋を置いても炎が塞がれず消えない構造\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"ステップ 5: 小枝の弱火で3時間じっくり乾かしレンガのように焼き固める\",\n      \"description\": \"完成したかまどに最初から大木を入れて強火で燃やすと、土中の水分が一気に沸騰して壁が破裂します。枯れ葉や小枝で拳大の小さな火種を作り、投入口近くで弱火を3〜4時間維持します。外壁から白い水蒸気が立ち上り、濡れた濃い茶色から乾いた明るい黄土色へ変化したら完成です。\",\n      \"actionNote\": \"> 乾燥中の補修: 乾燥中に外壁へ髪の毛ほどの細いひび割れが出た場合は、残った緩い泥ペーストを指先で塗り込むだけで綺麗に塞がります。\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① 投入口の小枝の弱火 (穏やかな熱)\",\n        \"急熱を避け熱をゆっくり加える\",\n        \"② 外壁からの水蒸気蒸発線\",\n        \"内部水分が静かに気化して脱出\",\n        \"③ 色調変化の観察\",\n        \"濡れた濃褐色 → 乾いた明るい黄土色\",\n        \"④ 触手による乾燥完了確認\",\n        \"湿り気なく外壁全体に温かみが伝わる\",\n        \"⑤ 微細亀裂の泥ペースト補修\",\n        \"残った泥で表面の微小隙間を密閉\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絶対にやってはいけない失敗: 水に濡れた川石を火が直接触れる燃焼室に積む\",\n    \"description\": \"川辺で拾ったばかりの濡れた川石や小石は、表面が乾いて見えても内部の微細な空隙に水が閉じ込められています。300℃を超える火炎にさらされると、内部の水が急激に高圧水蒸気となり手榴弾のように爆発します。鋭利な破片が顔や目に飛散し失明や重傷を負う危険があります。必ず水辺から10m以上離れた乾いた尾根の石を選び、石の表面を5cm以上の厚い泥で覆って直火を避けてください。\",\n    \"consequence\": \"結果: 石の水蒸気爆発により鋭利な破片が飛散し失明および重度の裂傷を負う\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"野外で地面に直接火を起こすと熱の80%が逃げます。風雨でも消えない原始かまどの作り方です。\",\n    \"body\": \"粘土2、砂1、枯草1に水を加えて10分踏み込み、硬い泥生地を作ります。乾いた石をU字に並べて風下に投入口を設置。石と泥を交互に膝丈までドーム状に積み、天面に鍋穴、後ろに煙突を開けます。小枝の弱火で3時間じっくり乾かせばレンガのように固まります。濡れた川石は絶対に使わないでください。水蒸気で爆発します。\",\n    \"outro\": \"風雨の中でも煮炊きができ、朝まで暖かい熱をキープできます。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"粘土左官石かまど（原始かまど及び調理口）完成形態\",\n    \"description\": \"U字型の川石基礎の上に藁と黄土の練り土を厚さ5cmで滑らかに左官し、上部調理用耐熱天板と後部排気煙突を備えて650°Cの高熱を閉じ込める原始かまどです。\"\n  },\n  \"createdAt\": \"2026-10-14T10:15:00.000Z\",\n  \"contentHash\": \"92064fb90844ce2f\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\"\n}","content/protocols/locales/06-clay-hearth.pt.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Como Construir um Fogão Primitivo de Barro e Pedras para Bloquear o Vento e Reter Calor\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[CALOR E ABRIGO ESSENCIAIS]\",\n  \"summary\": \"Fazer uma fogueira aberta no chão perde mais de 80% do calor com o vento e consome três vezes mais lenha, enquanto fagulhas representam risco crítico de incêndio. Construindo um fogão em cúpula com barro, areia, capim seco e pedras secas, você cria um ponto de cozimento à prova de tempestades que retém calor a noite toda.\",\n  \"timeRequired\": \"3 Horas\",\n  \"successRate\": \"90% (Com Cura Lenta)\",\n  \"difficulty\": \"Média (Amassar Barro e Assentar Pedras)\",\n  \"outputPerHour\": \"1 Fogão Permanente\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"2 Tigelas de Argila Vermelha Pegajosa (escavada em margens ou barrancos)\",\n      \"desc\": \"Escolha terra densa que amasse como massa de pão sem esfarelar. Atua como o ligante térmico principal.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Tigela de Areia Grossa de Rio (areia seca com grãos minerais)\",\n      \"desc\": \"A argila pura encolhe e racha ao secar. A areia grossa fornece a estrutura que impede rachaduras.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 Tigela de Capim Seco ou Palha Cortada no Tamanho de um Dedo\",\n      \"desc\": \"Funciona como fibra de reforço dentro da mistura, impedindo que as paredes rachem sob o calor intenso.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"15~20 Pedras Quebradas Totalmente Secas (tamanho punho a cabeça)\",\n      \"desc\": \"Pedras de rio encharcadas explodem violentamente com o calor. Use apenas pedras secas coletadas em encostas ensolaradas a mais de 10 m da água.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Pisotear 2 partes de argila, 1 de areia e 1 de capim seco com água até formar massa firme\",\n      \"description\": \"Despeje no chão plano 2 tigelas de argila vermelha, 1 de areia grossa e 1 de capim seco cortado. Adicione água aos poucos enquanto pisoteia com os calcanhares. Dobre a massa ao meio e pise por mais de 10 minutos até conseguir enrolar uma bola do tamanho de um punho sem rachaduras superficiais.\",\n      \"actionNote\": \"> Ponto da Água: Água demais vira lama que escorre; pouca água vira pó quebradiço. Busque uma consistência firme parecida com massa de pão.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 2 partes de argila vermelha pegajosa\",\n        \"Matéria-prima aglomerante de base\",\n        \"+\",\n        \"② 1 parte de areia grossa de rio\",\n        \"Evita retração e rachaduras\",\n        \"+\",\n        \"③ Fibra de capim seco picado\",\n        \"Malha estrutural de reforço interno\",\n        \"④ Adicionar água aos poucos e pisar\",\n        \"Nunca inundar de vez; dobrar e pisar\",\n        \"⑤ Bola de barro firme finalizada\",\n        \"Moldar bola sólida tamanho punho\",\n        \"Superfície externa sem trincas\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Dispor pedras secas em ferradura (formato de U) sobre chão seco como base\",\n      \"description\": \"Posicione a boca para lenha (largura de um palmo, aprox. 20 cm) contra a direção do vento. Coloque pedras secas em formato de U. Espalhe 2~3 cm de areia e cascalho seco no chão interno para barrar umidade e frio. Preencha todas as frestas com barro firme usando os punhos para travá-las.\",\n      \"actionNote\": \"> Sentido do Vento: A boca virada de frente para o vento lança fagulhas no rosto. Aponte sempre na direção contrária ao vento ou na diagonal.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① Boca frontal para lenha (20 cm de largura)\",\n        \"Largura ideal para lenha e entrada de ar\",\n        \"② Pedras secas de fundação em formato U\",\n        \"Perímetro estrutural da base\",\n        \"③ Argamassa grossa de barro nas juntas\",\n        \"Veda vazamentos de ar entre pedras\",\n        \"④ Camada de areia e cascalho no fundo\",\n        \"Barreira térmica contra chão frio\",\n        \"⑤ Abertura virada contra o vento\",\n        \"Protege as brasas contra rajadas fortes\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Empilhar pedras e barro alternadamente formando uma cúpula até a altura do joelho\",\n      \"description\": \"Espalhe uma camada de barro da espessura de uma palma (aprox. 5 cm) sobre as pedras da base, assente a próxima fileira travando as juntas e vá inclinando para dentro até a altura do joelho (aprox. 45 cm). Depois de erguer, molhe as mãos na água e alise a parede interna criando uma curva contínua que reflete o calor.\",\n      \"actionNote\": \"> Evitar Quedas: Nunca levante paredes altas só de barro sem pedra. As pedras são o esqueleto e o barro espesso retém a radiação térmica.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① Corte transversal de pedras e barro\",\n        \"Pedras travadas evitam colapso estrutural\",\n        \"② Parede grossa de barro (5 cm) isolante\",\n        \"Massa térmica retém calor a noite toda\",\n        \"③ Superfície lisa refletora de calor\",\n        \"Alisada com mão úmida para bom fluxo\",\n        \"④ Câmara esférica interna de combustão\",\n        \"O calor circula e se concentra no topo\",\n        \"⑤ Perfil total até o joelho (45 cm)\",\n        \"Equilíbrio ideal de volume e altura de cocção\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Abrir bocal superior para panela e perfurar chaminé traseira\",\n      \"description\": \"Deixe uma abertura redonda de 15~20 cm no topo da cúpula para apoiar panelas ou pedras planas. Crave três pedrinhas na borda para criar uma fresta de 1 cm para o ar passar. Na parte superior traseira, fure com um galho grosso na diagonal abrindo o duto da chaminé para exaustão.\",\n      \"actionNote\": \"> Princípio da Tiragem: Sem chaminé, a fumaça sai pela frente ardendo os olhos. O duto traseiro cria um vácuo térmico que puxa oxigênio fresco pela base.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① Entrada inferior de ar (oxigênio)\",\n        \"Ar fresco puxado para a brasa\",\n        \"② Bocal plano superior de cozimento\",\n        \"Apoio para panela ou chapa de pedra\",\n        \"③ Chaminé traseira inclinada\",\n        \"Expele fumaça densa para trás\",\n        \"④ Vórtice térmico ascendente de calor\",\n        \"Circula na câmara aquecendo a panela\",\n        \"⑤ Ressaltos espaçadores para tiragem\",\n        \"O fogo não apaga com a panela apoiada\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Passo 5: Curar com fogo brando de gravetos por 3 horas para endurecer o barro como tijolo\",\n      \"description\": \"Nunca acenda fogo forte imediato em barro úmido; a água fervendo dentro dos poros explodirá as paredes. Acenda uma fogueirinha de gravetos perto da entrada e mantenha brando por 3~4 horas. Observe a fumaça branca de vapor saindo e a cor mudando de marrom escuro úmido para ocre claro seco. Quando estiver quente e seco ao toque, o fogão estará pronto.\",\n      \"actionNote\": \"> Reparar Trincas: Se surgirem pequenas rachaduras finas durante a secagem, passe pasta de barro fresca com a ponta dos dedos para vedá-las na hora.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① Fogo brando de gravetos na entrada\",\n        \"Calor suave permite saída gradual de vapor\",\n        \"② Plumas de vapor d'água evaporando\",\n        \"Água interna evapora sem estourar\",\n        \"③ Mudança visual de coloração\",\n        \"Marrom escuro úmido → ocre claro seco\",\n        \"④ Teste de toque seco e quente\",\n        \"Parede morna sem umidade pegajosa\",\n        \"⑤ Pasta de barro para vedar trincas\",\n        \"Selar frestas com pasta fresca de barro\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro Fatal: Usar Pedras Úmidas de Rio em Contato Direto com o Fogo na Câmara\",\n    \"description\": \"Pedras de rio e seixos encharcados retêm água presa em microporos mesmo com a superfície seca. Ao receber fogo acima de 300°C, a água vira vapor de alta pressão instantaneamente e detona como uma granada. Estilhaços pontiagudos voam nos olhos e rosto, causando cegueira permanente e lacerações graves. Use apenas pedras de encostas secas a 10 m da água e cubra-as com 5 cm de barro grosso.\",\n    \"consequence\": \"Consequência: A explosão por vapor lança estilhaços afiados causando cegueira e ferimentos graves\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Fogueira no chão perde 80% do calor. Veja como construir um fogão primitivo resistente a temporais.\",\n    \"body\": \"Pise 2 partes de argila, 1 de areia e 1 de capim seco com água até virar massa firme. Monte pedras secas em U viradas contra o vento. Levante a cúpula alternando pedras e barro com bocal superior e chaminé traseira. Cure por 3 horas com fogo brando até endurecer como tijolo. Nunca use pedras úmidas de rio dentro; a pressão de vapor faz elas detonarem.\",\n    \"outro\": \"Cozinhe suas refeições e mantenha calor seguro a noite toda sob tempestades.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"Fogão Primitivo de Pedra e Argila Revestida Concluído\",\n    \"description\": \"Uma base de pedra em U selada com 5 cm de argila refratária temperada com palha, com tampa nivelada para cozimento e chaminé traseira que atinge 650°C.\"\n  },\n  \"createdAt\": \"2026-10-14T10:15:00.000Z\",\n  \"contentHash\": \"92064fb90844ce2f\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\"\n}","content/protocols/locales/06-clay-hearth.zh-TW.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"如何用泥土與石塊堆砌防風避雨且鎖住溫度的原始爐灶\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[保溫與食糧必備]\",\n  \"summary\": \"在野外直接於地面生火，八成以上的熱量會隨風散失，木柴消耗量暴增三倍，且飛散的火星極易引發火災。利用紅黏土、河砂、乾草揉合的泥漿包覆乾燥石塊築成圓頂泥灶，即使狂風暴雨也不會熄滅，能烹煮食物並整夜保持溫熱，是極佳的野外生存熱源。\",\n  \"timeRequired\": \"3小時\",\n  \"successRate\": \"90% (嚴格遵循微火烘烤時)\",\n  \"difficulty\": \"普通 (踩泥揉漿與疊石作業)\",\n  \"outputPerHour\": \"完成1座 (可永久重複使用)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"具黏性的紅黏土 2碗 (河岸邊或裸露土壁挖取的黏土)\",\n      \"desc\": \"挑選捏在手中如麵糰般緊密且具黏性的泥土。這是將整個灶體緊密黏合固化的核心原料。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"粗河砂 1碗 (混有細小石粒的乾燥砂土)\",\n      \"desc\": \"純黏土乾燥時會嚴重收縮碎裂。混入粗砂能提供堅固骨架，有效防止泥壁開裂。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"剪成手指長度的乾草或稻草 1碗\",\n      \"desc\": \"在泥漿中扮演如鋼筋般的拉力纖維，使爐壁即便承受高溫大火也不會裂開坍塌。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"完全乾燥的堅硬碎石 15~20顆 (拳頭至頭顱大小)\",\n      \"desc\": \"泡過水的河石受熱極易引發高壓水蒸氣爆炸。務必使用離水邊10公尺以上陽光曬乾的山丘乾石。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"步驟 1: 將黏土2份、粗砂1份、乾草1份加水踩踏揉成韌性泥糰\",\n      \"description\": \"在平坦地面上倒出紅黏土2碗、粗砂1碗、剪短的乾草1碗。不要一次倒入過多水，分次少量潑灑，同時用腳後跟用力踩踏揉合。將泥堆對折後反覆踩踏10分鐘以上，直到能揉出拳頭大小且表面沒有裂痕的緊實泥糰為止。\",\n      \"actionNote\": \"> 水量拿捏秘訣: 水分過多會變成稀泥流淌無法築壁；水分過少則乾澀易碎。應揉至如同包子皮麵糰般略硬且黏實的狀態最佳。\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 具黏性的紅黏土 2份\",\n        \"提供黏結力的基礎基底材\",\n        \"+\",\n        \"② 粗河砂 1份\",\n        \"防止乾燥收縮與開裂\",\n        \"+\",\n        \"③ 剪碎的乾草纖維\",\n        \"強化結構拉力的內部骨幹\",\n        \"④ 少量加水並用腳後跟踩踏\",\n        \"切勿一次倒滿水；對折反覆踩\",\n        \"⑤ 完成扎實有韌性的泥糰\",\n        \"揉成拳頭大實心糰不散落\",\n        \"外表無細微龜裂痕跡\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"步驟 2: 在乾燥地面以U字型排布拳頭大石塊奠定基座\",\n      \"description\": \"朝向背風方向預留放柴火的爐口(約一手掌寬，約20公分)，將拳頭大的乾石塊排成馬蹄形(U字型)。在底部鋪上2~3公分厚的乾砂與細石子以隔絕地面濕氣與冷氣。接著用拳頭將步驟1的泥糰用力塞滿石塊間的所有縫隙，使基底緊密貼合地面。\",\n      \"actionNote\": \"> 風向安全要領: 爐口若正面迎風，強風會將火星猛烈倒灌吹向臉部。務必將爐口設在背風面或斜向避風側。\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① 前方柴火進料口 (寬約20公分)\",\n        \"兼顧添柴與進氣的最佳口徑\",\n        \"② U字型排布的拳頭大乾石塊\",\n        \"支撐基礎的主要骨幹\",\n        \"③ 填滿縫隙的厚實泥漿\",\n        \"完全阻斷石塊間漏氣縫隙\",\n        \"④ 底部乾砂與細石隔熱層\",\n        \"隔絕冰冷地面的濕氣與低溫\",\n        \"⑤ 背風方向配置爐口\",\n        \"防止強風倒灌吹散炭火\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"步驟 3: 交錯堆疊石塊與泥漿，砌出及膝高的圓頂爐壁\",\n      \"description\": \"在基座石上鋪上約一掌厚(約5公分)的泥漿，交錯疊放下一層石塊，逐漸向內收口，向上堆疊至膝蓋高度(約45公分)形成圓頂。爐壁砌好後，雙手沾水將內壁均勻抹平光滑。內壁越光滑，熱氣越能在燃燒室內部盤旋對流，保持極高溫度。\",\n      \"actionNote\": \"> 防止坍塌: 切勿不加石頭單純疊泥壁，重力會使下方坍塌。必須以石塊為核心骨架，內外包覆厚實泥漿。\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① 石塊與泥漿交錯剖面\",\n        \"交錯互鎖防止結構坍塌\",\n        \"② 一掌厚(約5公分)泥保溫壁\",\n        \"巨大蓄熱層整夜鎖住溫度\",\n        \"③ 平整光滑的熱反射曲面\",\n        \"沾水手抹平確保良好通風\",\n        \"④ 熱氣盤旋的內部球形燃燒室\",\n        \"熱流盤旋集中朝上方蓄熱\",\n        \"⑤ 及膝高(約45公分)整體高度\",\n        \"兼顧烹飪穩定度與蓄熱體積\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"步驟 4: 在爐頂保留鍋座開孔並於後方上方開鑿排煙煙囪\",\n      \"description\": \"在圓頂最上方中央保留直徑15~20公分的圓孔，供放置陶鍋或石板。在孔緣邊緣三角形嵌入3顆小石子，形成1公分的透氣縫隙，以免放上鍋具時阻斷氣流熄火。在後側略高處以粗樹枝斜斜刺入貫穿，開出排煙煙囪孔，形成強勁的自然上升氣流。\",\n      \"actionNote\": \"> 氣流對流原理: 若無後方煙囪，濃煙會全部由前方爐口湧出刺眼嗆人。後方煙囪位置高於前爐口，才能產生強大的抽風效應。\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① 前下方進氣口 (供應氧氣)\",\n        \"新鮮冷空氣被吸入炭火堆\",\n        \"② 頂部平整烹飪開口\",\n        \"承放鍋具或石板的火口\",\n        \"③ 後上方傾斜排煙煙囪孔\",\n        \"將刺鼻濃煙乾淨導向後方排出\",\n        \"④ 向上迴旋的強烈熱流線\",\n        \"在爐室盤旋加熱鍋底\",\n        \"⑤ 鍋底透氣墊石凸起\",\n        \"放上鍋具也不會阻絕火勢\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"步驟 5: 以細枝微火烘烤3小時使泥壁如磚石般堅硬\",\n      \"description\": \"切勿在剛築好的濕爐中直接燃燒大木柴；泥土內水分暴沸會直接炸裂爐壁。先以乾燥落葉與細小樹枝在爐口點燃拳頭大的微火，溫和維持3~4小時。觀察白色水蒸氣自外壁緩緩蒸發，深褐色濕泥漸轉為乾燥淺黃褐色。外壁手觸溫熱且不沾手時，堅固的永久爐灶即告完成。\",\n      \"actionNote\": \"> 修補細縫技巧: 若烘乾過程中外壁出現如髮絲般的細裂縫，取剩餘的微濕泥漿以指尖抹入塗平即可立即結合。\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① 爐口細枝微弱餘燼火 (溫和熱源)\",\n        \"均勻熱力讓內部水分緩緩排出\",\n        \"② 外壁水蒸氣蒸散線\",\n        \"孔隙水分安全氣化排出\",\n        \"③ 顏色轉變判斷指標\",\n        \"濕潤深褐色 → 乾燥淺黃褐色\",\n        \"④ 溫熱乾燥觸摸檢驗\",\n        \"外壁觸感溫熱無濕黏感\",\n        \"⑤ 髮絲裂縫泥漿修補\",\n        \"以新鮮泥漿密封微小縫隙\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命錯誤: 將濕潤的河石直接砌在接觸爐火的核心位置\",\n    \"description\": \"自溪流中剛拾取的河石與卵石，即使表面看似乾燥，內部微細孔隙依然飽含水分。接觸超過300度的高溫烈火時，內部水氣會瞬間化為超高壓蒸氣並如手榴彈般引爆破裂。鋒利的石塊碎片會高速射向臉部與眼睛，造成永久失明與嚴重撕裂傷。務必使用離水邊10公尺以上的山丘乾石，並以至少5公分厚的泥漿徹底包覆隔離。\",\n    \"consequence\": \"結果: 蒸氣爆炸引發石片飛濺，造成永久失明與重度顏面撕裂傷\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"在野外直接於地面生火會散失80%熱量。教你如何用泥石建造防風避雨的原始爐灶。\",\n    \"body\": \"黏土2份、粗砂1份、乾草1份加水用腳踩成扎實泥糰。乾石塊排成U字型，爐口朝背風面。交錯疊砌石塊與厚泥形成及膝圓頂，上方留鍋口，後方開煙囪。以細枝微火烘烤3小時即可硬如磚石。絕對不能使用濕河石，內部水蒸氣會引發爆炸。\",\n    \"outro\": \"暴風雨中也能順利煮食，整夜保留溫暖熱度。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"黏土抹面石爐（原始土灶與烹飪口）完成形態\",\n    \"description\": \"U字型河石地基上均勻抹上5公分厚的稻草黃土灰漿，具備上方平整烹飪石板與後方排煙煙囪，鎖住650°C高溫的原始土灶完成形態。\"\n  },\n  \"createdAt\": \"2026-10-14T10:15:00.000Z\",\n  \"contentHash\": \"92064fb90844ce2f\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\"\n}","content/protocols/locales/08-figure-four-deadfall.de.json":"{\n  \"protocolId\": \"PR-08\",\n  \"category\": \"FOOD\",\n  \"title\": \"Tiere fangen mit 3 Stöcken und einem Felsbrocken (Vierer-Schlagfalle)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[PROTEIN & NAHRUNG KRITISCH]\",\n  \"summary\": \"Tiere mit bloßen Händen zu jagen führt schnell zu lebensgefährlicher Erschöpfung. Wenn man drei fingerdicke Äste mit Kerben versieht und zu einer 'Ziffer 4' zusammensteckt, tragen sie ohne jedes Seil einen 15kg schweren Stein. Berührt ein Beutetier den Köder, löst sich das Gestell in 0,1 Sekunden auf und der Fels fällt herab.\",\n  \"timeRequired\": \"30 Minuten (20 Min Schnitzen + 10 Min Ausrichtung)\",\n  \"successRate\": \"95% (bei Einhaltung der Auslöser-Kerbung)\",\n  \"difficulty\": \"Mittel (präzises Schnitzen & Gleichgewicht)\",\n  \"outputPerHour\": \"2 Fallen pro Stunde (dauerhaft wiederverwendbar)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"3 fingerdicke, gerade Hartholzstäbe (25-30 cm lang)\",\n      \"desc\": \"Trockenes Eichenholz, das sich unter schwerer Steinlast nicht durchbiegt, zugeschnitten als Pfosten, Stütze und Köderstab.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 flacher, schwerer Felsbrocken (10-15 kg)\",\n      \"desc\": \"Muss das 3- bis 5-fache des Beutetiergewichts wiegen und eine ebene Unterseite besitzen, die Fluchtlücken ausschließt.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 scharfer Feuerstein-Abschlag oder Steinklinge\",\n      \"desc\": \"Primitives Schneidwerkzeug zum Schnitzen exakter 45-Grad-Keile und rechtwinkliger Haltenuten.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Natürlicher Köder (Waldbeeren, Larven, Insekten, Samen)\",\n      \"desc\": \"Fest auf die innere Spitze des Köderstabs gespießt, um das Tier zum horizontalen Ziehen zu zwingen.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Carve 3 sticks (Post, Strut, and Bait Stick notches)\",\n      \"description\": \"Prepare three finger-thick straight sticks. First, carve the top of the [1. Vertical Post (20cm)] into a flat chisel shape and cut a square notch in the middle. Second, carve a V-notch near the top of the [2. Diagonal Strut (25cm)] to catch the post tip, and bevel the bottom end. Third, carve a catch ledge on the [3. Bait Stick (30cm)] to fit the post notch, cut a rear notch to hold the strut bottom, and whittle the far inner tip into a sharp pencil point for bait.\",\n      \"actionNote\": \"> Carving Tip: If you make the notches rounded, they will slip out. Cut them crisp and square with a sharp knife edge so the sticks bite firmly into each other.\",\n      \"svgFileName\": \"pr08-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // SCHRITT 01\",\n        \"POST (Stick 1 - Chisel Tip & Square Notch)\",\n        \"STRUT (Stick 2 - Top V-Notch & Bottom Bevel)\",\n        \"BAIT STICK (Stick 3 - Catch Ledge & Pin Tip)\",\n        \"[KEY] Carve crisp square notches that bite firmly\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Rest the Diagonal Strut on top of the Vertical Post\",\n      \"description\": \"Stand the Vertical Post upright on firm, flat ground. Place the top V-notch of the Diagonal Strut onto the flat chisel tip of the post at roughly a 45-degree angle. Press down gently with your fingers to ensure the two sticks bite into each other without sliding sideways.\",\n      \"actionNote\": \"> Angle Check: Keep the strut at roughly a 45-degree angle to hold the heavy boulder weight most reliably.\",\n      \"svgFileName\": \"pr08-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // SCHRITT 02\",\n        \"Post 1 Flat Chisel Tip\",\n        \"Strut 2 V-Notch Joint\",\n        \"Locks firmly at 45°\",\n        \"[KEY] Top hinge locks firmly without sliding\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Insert the Bait Stick to make the 'Number 4' stand alone\",\n      \"description\": \"Hold the Bait Stick horizontally parallel to the ground. Hook its front catch ledge into the middle notch of the vertical post. Then hook the bottom of the diagonal strut into the rear notch of the bait stick. Slowly release your hands—the three sticks push against each other and stand completely on their own in a perfect 'Number 4' shape without any rope!\",\n      \"actionNote\": \"> Balance Check: When you let go, it must balance solidly without wobbling. If it tilts, flatten the bottom of the vertical post.\",\n      \"svgFileName\": \"pr08-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // SCHRITT 03\",\n        \"Post-Bait Stick Middle Joint\",\n        \"Strut-Bait Stick Rear Joint\",\n        \"Stands alone in Number 4 shape\",\n        \"[KEY] Sticks push against each other to stand\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Lean the heavy rock on top & test 0.1-second hair trigger\",\n      \"description\": \"Firmly impale insects or berries onto the sharp inner tip of the bait stick. Carefully lift a heavy 10-15kg flat rock with one hand and lean it gently at 45 degrees onto the upper part of the diagonal strut. The rock weight presses down, making the trap taut. Test the hair trigger by lightly tapping the bait with a twig—the sticks should collapse instantly in 0.1 seconds, dropping the boulder with a loud thud.\",\n      \"actionNote\": \"> Safety First: Never put your hands or fingers underneath the rock while setting it. Always hold the sides so you are safe if it accidentally falls.\",\n      \"svgFileName\": \"pr08-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SCHRITT 04\",\n        \"15kg Flat Rock Loaded\",\n        \"Bait set on inner tip\",\n        \"Drops rock in 0.1s when touched\",\n        \"[KEY] Hair trigger collapses instantly on touch\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Kerben zu tief schneiden oder zu leichten Stein wählen\",\n    \"description\": \"Zu tiefe Kerben klemmen fest und lösen bei Berührung nicht aus. Ein zu leichter Stein verletzt das Beutetier nur, sodass es flieht und Artgenossen im Revier dauerhaft warnt.\",\n    \"consequence\": \"Folge: Jagdmisserfolg, Hungertod und gewarntes Wild im gesamten Gebiet\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Wild hinterherzurennen lässt dich verhungern! Baue diese 0,1s-Steinfalle aus 3 Stöcken!\",\n    \"body\": \"Drei Stöcke mit Kerben zur Zahl 4 verbinden: Hält ganz ohne Seile durch reine Reibung einen 15kg-Felsen! Der Clou: Kerben flach halten. Sobald ein Nagetier den Köder berührt, bricht die Spannung und der Fels zermalmt die Beute in 0,1 Sekunden!\",\n    \"outro\": \"Offline-Überlebenspläne ohne Internetzugang über den Link im Profil abrufen.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr08-outcome.svg\",\n    \"title\": \"Completed Figure-4 Deadfall Trap Full Setup\",\n    \"description\": \"Three finger-thick sticks interlock to support a heavy 15kg rock at an angle, dropping the stone in 0.1 seconds the moment prey touches the bait beneath it.\",\n    \"imageFileName\": \"pr08-outcome.png\"\n  },\n  \"createdAt\": \"2026-10-14T15:35:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"46ed0acd1b57e2da\"\n}","content/protocols/locales/08-figure-four-deadfall.en.json":"{\n  \"protocolId\": \"PR-08\",\n  \"category\": \"FOOD\",\n  \"title\": \"How to Catch Animals with 3 Sticks and a Boulder (Figure-4 Trap)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[PROTEIN & FOOD CRITICAL]\",\n  \"summary\": \"Chasing wild animals with bare hands will quickly exhaust you to death. By carving notches into three finger-thick sticks and interlocking them into a 'number 4' shape, they can support a heavy 15kg boulder without any rope. When a rodent or small animal touches the bait, the sticks instantly slip apart in 0.1 seconds, dropping the boulder for an instant, reliable kill.\",\n  \"timeRequired\": \"30 minutes (20 min carving + 10 min trigger setup)\",\n  \"successRate\": \"95% (with proper hair-trigger notch calibration)\",\n  \"difficulty\": \"Moderate (precise notch carving & balance)\",\n  \"outputPerHour\": \"2 traps per hour (reusable indefinitely)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"3 straight dry hardwood sticks (finger-thick, 25-30cm long)\",\n      \"desc\": \"Seasoned oak or hickory sticks that will not bend or flex under the heavy deadfall load, carved into the vertical post, diagonal strut, and bait stick.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 flat heavy boulder (10-15kg)\",\n      \"desc\": \"Must weigh 3 to 5 times the target prey's body mass, with a broad flat underside that crushes down without leaving escape gaps.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 sharp flint flake or stone knife\",\n      \"desc\": \"A primitive cutting edge used to carve clean 90-degree catch ledges and 45-degree chisel wedges on the sticks.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Natural bait (wild berries, grubs, insects, or seeds)\",\n      \"desc\": \"Firmly impaled onto the pointed inner tip of the bait stick to compel the animal to tug horizontally.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Carve 3 sticks (Post, Strut, and Bait Stick notches)\",\n      \"description\": \"Prepare three finger-thick straight sticks. First, carve the top of the [1. Vertical Post (20cm)] into a flat chisel shape and cut a square notch in the middle. Second, carve a V-notch near the top of the [2. Diagonal Strut (25cm)] to catch the post tip, and bevel the bottom end. Third, carve a catch ledge on the [3. Bait Stick (30cm)] to fit the post notch, cut a rear notch to hold the strut bottom, and whittle the far inner tip into a sharp pencil point for bait.\",\n      \"actionNote\": \"> Carving Tip: If you make the notches rounded, they will slip out. Cut them crisp and square with a sharp knife edge so the sticks bite firmly into each other.\",\n      \"svgFileName\": \"pr08-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // 3 STICKS ANATOMY & NOTCHES\",\n        \"POST (Stick 1 - Chisel Tip & Square Notch)\",\n        \"STRUT (Stick 2 - Top V-Notch & Bottom Bevel)\",\n        \"BAIT STICK (Stick 3 - Catch Ledge & Pin Tip)\",\n        \"[KEY] Carve crisp square notches that bite firmly\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Rest the Diagonal Strut on top of the Vertical Post\",\n      \"description\": \"Stand the Vertical Post upright on firm, flat ground. Place the top V-notch of the Diagonal Strut onto the flat chisel tip of the post at roughly a 45-degree angle. Press down gently with your fingers to ensure the two sticks bite into each other without sliding sideways.\",\n      \"actionNote\": \"> Angle Check: Keep the strut at roughly a 45-degree angle to hold the heavy boulder weight most reliably.\",\n      \"svgFileName\": \"pr08-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // TOP NOTCH INTERLOCK\",\n        \"Post 1 Flat Chisel Tip\",\n        \"Strut 2 V-Notch Joint\",\n        \"Locks firmly at 45°\",\n        \"[KEY] Top hinge locks firmly without sliding\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Insert the Bait Stick to make the 'Number 4' stand alone\",\n      \"description\": \"Hold the Bait Stick horizontally parallel to the ground. Hook its front catch ledge into the middle notch of the vertical post. Then hook the bottom of the diagonal strut into the rear notch of the bait stick. Slowly release your hands—the three sticks push against each other and stand completely on their own in a perfect 'Number 4' shape without any rope!\",\n      \"actionNote\": \"> Balance Check: When you let go, it must balance solidly without wobbling. If it tilts, flatten the bottom of the vertical post.\",\n      \"svgFileName\": \"pr08-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // NUMBER 4 LOCK ASSEMBLY\",\n        \"Post-Bait Stick Middle Joint\",\n        \"Strut-Bait Stick Rear Joint\",\n        \"Stands alone in Number 4 shape\",\n        \"[KEY] Sticks push against each other to stand\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Lean the heavy rock on top & test 0.1-second hair trigger\",\n      \"description\": \"Firmly impale insects or berries onto the sharp inner tip of the bait stick. Carefully lift a heavy 10-15kg flat rock with one hand and lean it gently at 45 degrees onto the upper part of the diagonal strut. The rock weight presses down, making the trap taut. Test the hair trigger by lightly tapping the bait with a twig—the sticks should collapse instantly in 0.1 seconds, dropping the boulder with a loud thud.\",\n      \"actionNote\": \"> Safety First: Never put your hands or fingers underneath the rock while setting it. Always hold the sides so you are safe if it accidentally falls.\",\n      \"svgFileName\": \"pr08-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // ROCK LOAD & 0.1S COLLAPSE\",\n        \"15kg Flat Rock Loaded\",\n        \"Bait set on inner tip\",\n        \"Drops rock in 0.1s when touched\",\n        \"[KEY] Hair trigger collapses instantly on touch\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Carving notches too deep or using an undersized rock\",\n    \"description\": \"Deep notches lock too tightly and fail to release when an animal nibbles the bait, stealing your food. An undersized rock merely injures the prey, allowing it to flee and spook other animals in the area.\",\n    \"consequence\": \"Consequence: Complete trapping failure, starvation, and alert prey fleeing the zone\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Running after wild animals in the forest will starve you to death. Build this 0.1s rock trap instead!\",\n    \"body\": \"Carve three dry sticks with interlocking notches into the shape of a numeral 4. Under friction alone, it effortlessly supports a 15kg flat boulder without a single knot! The secret? Keep the notches shallow. The moment a rodent or bird nudges the bait, the tension shatters and the rock crushes down in 0.1 seconds!\",\n    \"outro\": \"Access 100% offline survival blueprints without data via the link in bio.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr08-outcome.svg\",\n    \"title\": \"Completed Figure-4 Deadfall Trap Full Setup\",\n    \"description\": \"Three finger-thick sticks interlock to support a heavy 15kg rock at an angle, dropping the stone in 0.1 seconds the moment prey touches the bait beneath it.\",\n    \"imageFileName\": \"pr08-outcome.png\"\n  },\n  \"createdAt\": \"2026-10-14T15:35:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"46ed0acd1b57e2da\"\n}","content/protocols/locales/08-figure-four-deadfall.es.json":"{\n  \"protocolId\": \"PR-08\",\n  \"category\": \"FOOD\",\n  \"title\": \"Cómo atrapar animales con 3 ramas y una roca (Trampa en Figura de 4)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[CRÍTICO: PROTEÍNA Y ALIMENTO]\",\n  \"summary\": \"Perseguir presas con las manos vacías en la naturaleza causará un agotamiento fatal. Al tallar ranuras en tres ramas del grosor de un dedo y encajarlas en forma de 'número 4', pueden sostener una roca pesada de 15kg sin usar ninguna cuerda. Cuando un animal toca el cebo, la estructura se desarma en 0.1 segundos dejando caer la roca.\",\n  \"timeRequired\": \"30 minutos (20 min tallado + 10 min calibración)\",\n  \"successRate\": \"95% (siguiendo el ajuste fino de muescas)\",\n  \"difficulty\": \"Media (tallado preciso y equilibrio de peso)\",\n  \"outputPerHour\": \"2 trampas por hora (reutilizable indefinidamente)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"3 ramas rectas de madera dura y seca (grosor de un dedo, 25-30 cm)\",\n      \"desc\": \"Madera curada de roble que no flexione bajo la carga pesada, talladas en poste vertical, puntal diagonal y varilla del cebo.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 roca plana y pesada (10-15 kg)\",\n      \"desc\": \"Debe pesar de 3 a 5 veces la masa corporal del animal objetivo, con base plana para aplastar sin dejar vías de escape.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 lasca afilada de pedernal o cuchillo de piedra\",\n      \"desc\": \"Filo primitivo para tallar cuñas biseladas a 45 grados y muescas rectas de agarre seguro.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Cebo natural (bayas silvestres, larvas, insectos o semillas)\",\n      \"desc\": \"Firmemente ensartado en el extremo afilado interior de la varilla para forzar a la presa a tirar horizontalmente.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Carve 3 sticks (Post, Strut, and Bait Stick notches)\",\n      \"description\": \"Prepare three finger-thick straight sticks. First, carve the top of the [1. Vertical Post (20cm)] into a flat chisel shape and cut a square notch in the middle. Second, carve a V-notch near the top of the [2. Diagonal Strut (25cm)] to catch the post tip, and bevel the bottom end. Third, carve a catch ledge on the [3. Bait Stick (30cm)] to fit the post notch, cut a rear notch to hold the strut bottom, and whittle the far inner tip into a sharp pencil point for bait.\",\n      \"actionNote\": \"> Carving Tip: If you make the notches rounded, they will slip out. Cut them crisp and square with a sharp knife edge so the sticks bite firmly into each other.\",\n      \"svgFileName\": \"pr08-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PASO 01\",\n        \"POST (Stick 1 - Chisel Tip & Square Notch)\",\n        \"STRUT (Stick 2 - Top V-Notch & Bottom Bevel)\",\n        \"BAIT STICK (Stick 3 - Catch Ledge & Pin Tip)\",\n        \"[KEY] Carve crisp square notches that bite firmly\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Rest the Diagonal Strut on top of the Vertical Post\",\n      \"description\": \"Stand the Vertical Post upright on firm, flat ground. Place the top V-notch of the Diagonal Strut onto the flat chisel tip of the post at roughly a 45-degree angle. Press down gently with your fingers to ensure the two sticks bite into each other without sliding sideways.\",\n      \"actionNote\": \"> Angle Check: Keep the strut at roughly a 45-degree angle to hold the heavy boulder weight most reliably.\",\n      \"svgFileName\": \"pr08-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PASO 02\",\n        \"Post 1 Flat Chisel Tip\",\n        \"Strut 2 V-Notch Joint\",\n        \"Locks firmly at 45°\",\n        \"[KEY] Top hinge locks firmly without sliding\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Insert the Bait Stick to make the 'Number 4' stand alone\",\n      \"description\": \"Hold the Bait Stick horizontally parallel to the ground. Hook its front catch ledge into the middle notch of the vertical post. Then hook the bottom of the diagonal strut into the rear notch of the bait stick. Slowly release your hands—the three sticks push against each other and stand completely on their own in a perfect 'Number 4' shape without any rope!\",\n      \"actionNote\": \"> Balance Check: When you let go, it must balance solidly without wobbling. If it tilts, flatten the bottom of the vertical post.\",\n      \"svgFileName\": \"pr08-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PASO 03\",\n        \"Post-Bait Stick Middle Joint\",\n        \"Strut-Bait Stick Rear Joint\",\n        \"Stands alone in Number 4 shape\",\n        \"[KEY] Sticks push against each other to stand\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Lean the heavy rock on top & test 0.1-second hair trigger\",\n      \"description\": \"Firmly impale insects or berries onto the sharp inner tip of the bait stick. Carefully lift a heavy 10-15kg flat rock with one hand and lean it gently at 45 degrees onto the upper part of the diagonal strut. The rock weight presses down, making the trap taut. Test the hair trigger by lightly tapping the bait with a twig—the sticks should collapse instantly in 0.1 seconds, dropping the boulder with a loud thud.\",\n      \"actionNote\": \"> Safety First: Never put your hands or fingers underneath the rock while setting it. Always hold the sides so you are safe if it accidentally falls.\",\n      \"svgFileName\": \"pr08-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PASO 04\",\n        \"15kg Flat Rock Loaded\",\n        \"Bait set on inner tip\",\n        \"Drops rock in 0.1s when touched\",\n        \"[KEY] Hair trigger collapses instantly on touch\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error fatal: Tallar muescas demasiado profundas o usar una roca ligera\",\n    \"description\": \"Las muescas excesivamente profundas se traban y no disparan cuando el animal mordisquea el cebo. Una roca liviana solo lastima a la presa, permitiéndole escapar y alertar a todos los animales del entorno.\",\n    \"consequence\": \"Consecuencia: Fracaso total, inanición y animales fugitivos en alerta\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"¡Correr tras animales en la selva te matará de hambre! ¡Haz esta trampa de roca de 0,1 segundos!\",\n    \"body\": \"Talla tres ramas con muescas precisas para formar un número 4. ¡Sostiene por pura fricción una roca de 15 kg sin una sola cuerda! El secreto: muescas poco profundas. En cuanto una presa toca el cebo, la tensión se quiebra y la roca aplasta en 0,1 segundos.\",\n    \"outro\": \"Planos de supervivencia sin conexión a internet en el enlace de la bio.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr08-outcome.svg\",\n    \"title\": \"Completed Figure-4 Deadfall Trap Full Setup\",\n    \"description\": \"Three finger-thick sticks interlock to support a heavy 15kg rock at an angle, dropping the stone in 0.1 seconds the moment prey touches the bait beneath it.\",\n    \"imageFileName\": \"pr08-outcome.png\"\n  },\n  \"createdAt\": \"2026-10-14T15:35:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"46ed0acd1b57e2da\"\n}","content/protocols/locales/08-figure-four-deadfall.ja.json":"{\n  \"protocolId\": \"PR-08\",\n  \"category\": \"FOOD\",\n  \"title\": \"木の枝3本と岩で獲物を捕る方法（数字の4型 圧殺罠）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[食糧・タンパク質確保]\",\n  \"summary\": \"野生で獲物を素手で追いかけると体力を使い果たして倒れてしまいます。指の太さの木の枝3本に溝を彫り「数字の4」の形に噛み合わせることで、紐を一切使わずに15kgの重い岩を自立して支えられます。内側の棒にエサを刺しておけば、小動物がエサをつついた瞬間に0.1秒で崩れて岩が落下する、確実なサバイバル罠です。\",\n  \"timeRequired\": \"30分（枝の加工20分 + 設置・感度調整10分）\",\n  \"successRate\": \"95%（刻み溝の感度調整厳守時）\",\n  \"difficulty\": \"普通（正確な溝削りと重量バランス）\",\n  \"outputPerHour\": \"1時間あたり2基設置可能（半永久再利用）\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"指の太さの硬い枯れ枝3本（長さ25〜30cm）\",\n      \"desc\": \"重い岩の荷重にもしならない乾燥した広葉樹（ナラ・カシ等）を選び、垂直柱・斜め支柱・水平餌棒に切り分けます。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"底が平らで重い平石1個（10〜15kg）\",\n      \"desc\": \"捕獲対象の体重の3〜5倍以上の重さがあり、小動物が隙間から逃げられないよう底面が平坦な石を使用します。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"鋭利な剥片石器または打製石刃1個\",\n      \"desc\": \"木の枝に正確な45度のクサビと直角の引っ掛け溝を削り出すための原始切削具です。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"誘引用の餌（木の実、幼虫、昆虫、種子など）\",\n      \"desc\": \"水平餌棒の先端にしっかり突き刺し、小動物が引っぱって罠を作動させるようにします。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ1: 枝3本を削る（支柱・突っ張り棒・エサ棒の溝彫り）\",\n      \"description\": \"指の太さのまっすぐな木の枝3本を用意します。1本目：地面に垂直に立てる【支柱（20cm）】の先端をマイナスドライバーのように平たく削り、中央に四角い溝を彫ります。2本目：岩を斜めに支える【突っ張り棒（25cm）】の上端に支柱を受けるV字の溝を彫り、下端を斜めに削ります。3本目：エサをつける【エサ棒（30cm）】に支柱にかける段差を削り、突っ張り棒の下端を受ける溝を彫って、先端を鉛筆のように尖らせます。\",\n      \"actionNote\": \"> 削るコツ: 溝を丸く削ると滑って崩れてしまいます。刃物で角を直角に削り出すことで、3本の枝が互いにしっかり噛み合います。\",\n      \"svgFileName\": \"pr08-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // 3 STICKS ANATOMY & NOTCHES\",\n        \"支柱（上部クサビ型＆中央四角溝）\",\n        \"突っ張り棒（上部V字溝＆下部斜め削り）\",\n        \"エサ棒（引っ掛け段差＆溝＆尖った先端）\",\n        \"[重要] 互いにしっかり噛み合う直角溝の加工\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ2: 支柱の先端に突っ張り棒を引っ掛ける\",\n      \"description\": \"平らで硬い地面に支柱をまっすぐ立てます。突っ張り棒のV字溝を、支柱先端の平たいクサビ部分に約45度の角度で噛み合わせます。上から手で軽く押したとき、横に滑らずに支柱の頭をしっかりホールドするか確認します。\",\n      \"actionNote\": \"> 角度確認: 突っ張り棒が約45度に傾いているとき、重い岩の重量を最も安定して支えられます。\",\n      \"svgFileName\": \"pr08-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // TOP NOTCH INTERLOCK\",\n        \"支柱の平たい先端\",\n        \"突っ張り棒のV字溝の結合\",\n        \"45度の角度でしっかり噛み合う\",\n        \"[重要] 滑らずにロックされる上部結合部\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ3: エサ棒を差し込み「数字の4」の形に自立させる\",\n      \"description\": \"エサ棒を地面と水平に構え、先端の段差を支柱の中央の溝に引っかけます。そして突っ張り棒の下端をエサ棒の後ろの溝に乗せます。支えていた手をゆっくり離すと、3本の枝が互いに押し合って突っ張り合い、紐なしで「数字の4」の形に自立します！\",\n      \"actionNote\": \"> バランス確認: 手を離したときにぐらつかず自立している必要があります。傾く場合は支柱の底面を平らに削り直してください。\",\n      \"svgFileName\": \"pr08-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // NUMBER 4 LOCK ASSEMBLY\",\n        \"支柱とエサ棒の中央結合段差\",\n        \"突っ張り棒とエサ棒の後部溝\",\n        \"紐なしで自立する数字の4型\",\n        \"[重要] 枝同士が押し合って自立する仕組み\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"ステップ4: 岩をもたれかけさせ、0.1秒で作動するか感度を点検する\",\n      \"description\": \"エサ棒の尖った先端に昆虫や野イチゴをしっかり刺します。片手で10〜15kgの重い平らな岩を持ち上げ、突っ張り棒の上部に45度の角度でそっともたれかけさせます。岩の重みで全体が引き締まります。細い小枝でエサを軽く「チョン」と突いたとき、0.1秒で骨組みが外れて岩がドスンと落ちるか確認して完成です。\",\n      \"actionNote\": \"> 安全第一: 岩をもたれさせるとき、絶対に岩の下に指を入れないでください。側面を支えて安全に作業します。\",\n      \"svgFileName\": \"pr08-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // ROCK LOAD & 0.1S COLLAPSE\",\n        \"15kgの平らな岩を設置\",\n        \"エサ棒の先端にエサを装着\",\n        \"触れると0.1秒で岩が落下\",\n        \"[重要] かすかな接触で即座に崩れる高感度設定\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的な失敗：溝を深く彫りすぎて固くしたり、軽すぎる石を使うこと\",\n    \"description\": \"溝が深すぎると獲物が餌を揺らしても罠が崩れず餌だけ奪われます。また石が軽すぎると獲物が負傷したまま逃走し、周囲の動物を警戒させて二度と獲れなくなります。\",\n    \"consequence\": \"結果：食糧確保失敗、体力消耗、周辺の野生動物の警戒激化\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"森で獲物を走って追うと飢え死にします！枝3本で作る0.1秒落石罠！\",\n    \"body\": \"小枝3本に角ばった溝を彫り「数字の4」に組むだけで、紐なしで15kgの岩を支えます。奥に餌を刺しておけば、ネズミや鳥が触れた瞬間にバランスが崩れ0.1秒で岩が圧殺！最大の秘訣は溝を浅く彫ること。かすっただけで即座に落ちるように調整しましょう！\",\n    \"outro\": \"オフラインでも閲覧できる原始生存図面はプロフィールのリンクから。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr08-outcome.svg\",\n    \"title\": \"完成した数字の4型圧殺罠の全景\",\n    \"description\": \"3本の枝が絶妙に噛み合って15kgの重い岩を支え、獲物がエサに触れた瞬間に0.1秒で崩れて岩が圧殺する完成形態。\",\n    \"imageFileName\": \"pr08-outcome.png\"\n  },\n  \"createdAt\": \"2026-10-14T15:35:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"46ed0acd1b57e2da\"\n}","content/protocols/locales/08-figure-four-deadfall.pt.json":"{\n  \"protocolId\": \"PR-08\",\n  \"category\": \"FOOD\",\n  \"title\": \"Como capturar animais com 3 gravetos e uma pedra (Armadilha em 4)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[CRÍTICO: PROTEÍNA E ALIMENTO]\",\n  \"summary\": \"Perseguir animais selvagens com as mãos vazias esgota rapidamente a sua energia. Entalhando encaixes em três gravetos da grossura de um dedo e montando-os em formato de 'número 4', eles sustentam uma pedra de 15kg sem nenhuma corda. Quando a presa toca a isca, a estrutura desmonta em 0,1 segundo, esmagando a presa.\",\n  \"timeRequired\": \"30 minutos (20 min entalhe + 10 min calibração)\",\n  \"successRate\": \"95% (seguindo o ajuste fino dos encaixes)\",\n  \"difficulty\": \"Média (entalhe de precisão e equilíbrio)\",\n  \"outputPerHour\": \"2 armadilhas por hora (reutilizável)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"3 gravetos retos de madeira dura seca (espessura de um dedo, 25-30 cm)\",\n      \"desc\": \"Madeira curada que não curve sob o peso da pedra, entalhada em haste vertical, escora diagonal e vareta de isca.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 pedra plana e pesada (10-15 kg)\",\n      \"desc\": \"Deve pesar de 3 a 5 vezes a massa do animal alvo, com base reta para esmagar sem deixar vãos de fuga.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 lasca de sílex afiada ou lâmina de pedra\",\n      \"desc\": \"Instrumento de corte primitivo para entalhar cunhas a 45 graus e travas retangulares precisas.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Isca natural (frutas silvestres, larvas, insetos ou sementes)\",\n      \"desc\": \"Firmemente espetada na ponta interna da vareta para obrigar a caça a puxar horizontalmente.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Carve 3 sticks (Post, Strut, and Bait Stick notches)\",\n      \"description\": \"Prepare three finger-thick straight sticks. First, carve the top of the [1. Vertical Post (20cm)] into a flat chisel shape and cut a square notch in the middle. Second, carve a V-notch near the top of the [2. Diagonal Strut (25cm)] to catch the post tip, and bevel the bottom end. Third, carve a catch ledge on the [3. Bait Stick (30cm)] to fit the post notch, cut a rear notch to hold the strut bottom, and whittle the far inner tip into a sharp pencil point for bait.\",\n      \"actionNote\": \"> Carving Tip: If you make the notches rounded, they will slip out. Cut them crisp and square with a sharp knife edge so the sticks bite firmly into each other.\",\n      \"svgFileName\": \"pr08-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PASSO 01\",\n        \"POST (Stick 1 - Chisel Tip & Square Notch)\",\n        \"STRUT (Stick 2 - Top V-Notch & Bottom Bevel)\",\n        \"BAIT STICK (Stick 3 - Catch Ledge & Pin Tip)\",\n        \"[KEY] Carve crisp square notches that bite firmly\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Rest the Diagonal Strut on top of the Vertical Post\",\n      \"description\": \"Stand the Vertical Post upright on firm, flat ground. Place the top V-notch of the Diagonal Strut onto the flat chisel tip of the post at roughly a 45-degree angle. Press down gently with your fingers to ensure the two sticks bite into each other without sliding sideways.\",\n      \"actionNote\": \"> Angle Check: Keep the strut at roughly a 45-degree angle to hold the heavy boulder weight most reliably.\",\n      \"svgFileName\": \"pr08-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PASSO 02\",\n        \"Post 1 Flat Chisel Tip\",\n        \"Strut 2 V-Notch Joint\",\n        \"Locks firmly at 45°\",\n        \"[KEY] Top hinge locks firmly without sliding\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Insert the Bait Stick to make the 'Number 4' stand alone\",\n      \"description\": \"Hold the Bait Stick horizontally parallel to the ground. Hook its front catch ledge into the middle notch of the vertical post. Then hook the bottom of the diagonal strut into the rear notch of the bait stick. Slowly release your hands—the three sticks push against each other and stand completely on their own in a perfect 'Number 4' shape without any rope!\",\n      \"actionNote\": \"> Balance Check: When you let go, it must balance solidly without wobbling. If it tilts, flatten the bottom of the vertical post.\",\n      \"svgFileName\": \"pr08-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PASSO 03\",\n        \"Post-Bait Stick Middle Joint\",\n        \"Strut-Bait Stick Rear Joint\",\n        \"Stands alone in Number 4 shape\",\n        \"[KEY] Sticks push against each other to stand\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Lean the heavy rock on top & test 0.1-second hair trigger\",\n      \"description\": \"Firmly impale insects or berries onto the sharp inner tip of the bait stick. Carefully lift a heavy 10-15kg flat rock with one hand and lean it gently at 45 degrees onto the upper part of the diagonal strut. The rock weight presses down, making the trap taut. Test the hair trigger by lightly tapping the bait with a twig—the sticks should collapse instantly in 0.1 seconds, dropping the boulder with a loud thud.\",\n      \"actionNote\": \"> Safety First: Never put your hands or fingers underneath the rock while setting it. Always hold the sides so you are safe if it accidentally falls.\",\n      \"svgFileName\": \"pr08-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PASSO 04\",\n        \"15kg Flat Rock Loaded\",\n        \"Bait set on inner tip\",\n        \"Drops rock in 0.1s when touched\",\n        \"[KEY] Hair trigger collapses instantly on touch\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro fatal: Entalhar encaixes muito fundos ou usar pedra muito leve\",\n    \"description\": \"Encaixes fundos demais travam a armadilha e não disparam quando a caça morde a isca. Uma pedra leve apenas fere o animal, que foge e alerta todas as outras presas da região.\",\n    \"consequence\": \"Consequência: Falha total na caça, fome e presas ariscas espantadas\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Correr atrás de caça na mata vai te matar de fome! Monte essa armadilha de pedra de 0,1s!\",\n    \"body\": \"Entalhe 3 gravetos em formato de número 4: sustenta por pura fricção uma pedra de 15 kg sem nenhuma corda! O segredo é manter os encaixes rasos. Assim que o animal toca a isca, a pedra desaba em 0,1 segundo!\",\n    \"outro\": \"Acesse guias de sobrevivência offline sem usar dados no link do perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr08-outcome.svg\",\n    \"title\": \"Completed Figure-4 Deadfall Trap Full Setup\",\n    \"description\": \"Three finger-thick sticks interlock to support a heavy 15kg rock at an angle, dropping the stone in 0.1 seconds the moment prey touches the bait beneath it.\",\n    \"imageFileName\": \"pr08-outcome.png\"\n  },\n  \"createdAt\": \"2026-10-14T15:35:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"46ed0acd1b57e2da\"\n}","content/protocols/locales/08-figure-four-deadfall.zh-TW.json":"{\n  \"protocolId\": \"PR-08\",\n  \"category\": \"FOOD\",\n  \"title\": \"用3根樹枝與大石頭捕捉野獸的方法（數字4字形落石陷阱）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[生存必備：蛋白質與食糧]\",\n  \"summary\": \"在野外徒手追逐獵物只會加速體力耗盡。只要在手指粗的3根樹枝上削出凹槽，拼嵌成「數字4」形狀，不需任何繩索就能穩穩支撐15公斤的重石。當小動物碰觸內側餌料的瞬間，骨架會在0.1秒內鬆脫墜落，是最實用的原始求生陷阱。\",\n  \"timeRequired\": \"30分鐘（樹枝雕刻20分鐘 + 陷阱架設與調校10分鐘）\",\n  \"successRate\": \"95%（嚴格遵守卡槽觸發靈敏度時）\",\n  \"difficulty\": \"普通（精準卡槽雕刻與重量平衡）\",\n  \"outputPerHour\": \"每小時可製作並架設2具（可永久重複使用）\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"手指粗細的筆直乾燥硬木枝3根（長25-30公分）\",\n      \"desc\": \"挑選在高重壓下不會彎曲的堅硬橡木或雜木，分別裁切為垂直立柱、對角支撐桿與水平誘餌桿。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"底部平整的沉重巨石1塊（10-15公斤）\",\n      \"desc\": \"重量必須達獵物體重的3至5倍以上，且底面寬平，確保砸落時不留任何逃生空隙。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"鋒利的燧石石片或打製石刀1把\",\n      \"desc\": \"用以在樹枝上雕刻出精準的45度斜楔與直角卡榫凹槽的原始切削工具。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"天然誘餌（野果、昆蟲幼蟲、種子等）\",\n      \"desc\": \"牢固刺穿於水平誘餌桿內側尖端，誘使動物觸動並水平拉扯觸發陷阱。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"步驟 1: 枝3本を削る（支柱・突っ張り棒・エサ棒の溝彫り）\",\n      \"description\": \"指の太さのまっすぐな木の枝3本を用意します。1本目：地面に垂直に立てる【支柱（20cm）】の先端をマイナスドライバーのように平たく削り、中央に四角い溝を彫ります。2本目：岩を斜めに支える【突っ張り棒（25cm）】の上端に支柱を受けるV字の溝を彫り、下端を斜めに削ります。3本目：エサをつける【エサ棒（30cm）】に支柱にかける段差を削り、突っ張り棒の下端を受ける溝を彫って、先端を鉛筆のように尖らせます。\",\n      \"actionNote\": \"> 削るコツ: 溝を丸く削ると滑って崩れてしまいます。刃物で角を直角に削り出すことで、3本の枝が互いにしっかり噛み合います。\",\n      \"svgFileName\": \"pr08-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // 步驟 01\",\n        \"支柱（上部クサビ型＆中央四角溝）\",\n        \"突っ張り棒（上部V字溝＆下部斜め削り）\",\n        \"エサ棒（引っ掛け段差＆溝＆尖った先端）\",\n        \"[重要] 互いにしっかり噛み合う直角溝の加工\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"步驟 2: 支柱の先端に突っ張り棒を引っ掛ける\",\n      \"description\": \"平らで硬い地面に支柱をまっすぐ立てます。突っ張り棒のV字溝を、支柱先端の平たいクサビ部分に約45度の角度で噛み合わせます。上から手で軽く押したとき、横に滑らずに支柱の頭をしっかりホールドするか確認します。\",\n      \"actionNote\": \"> 角度確認: 突っ張り棒が約45度に傾いているとき、重い岩の重量を最も安定して支えられます。\",\n      \"svgFileName\": \"pr08-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // 步驟 02\",\n        \"支柱の平たい先端\",\n        \"突っ張り棒のV字溝の結合\",\n        \"45度の角度でしっかり噛み合う\",\n        \"[重要] 滑らずにロックされる上部結合部\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"步驟 3: エサ棒を差し込み「数字の4」の形に自立させる\",\n      \"description\": \"エサ棒を地面と水平に構え、先端の段差を支柱の中央の溝に引っかけます。そして突っ張り棒の下端をエサ棒の後ろの溝に乗せます。支えていた手をゆっくり離すと、3本の枝が互いに押し合って突っ張り合い、紐なしで「数字の4」の形に自立します！\",\n      \"actionNote\": \"> バランス確認: 手を離したときにぐらつかず自立している必要があります。傾く場合は支柱の底面を平らに削り直してください。\",\n      \"svgFileName\": \"pr08-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // 步驟 03\",\n        \"支柱とエサ棒の中央結合段差\",\n        \"突っ張り棒とエサ棒の後部溝\",\n        \"紐なしで自立する数字の4型\",\n        \"[重要] 枝同士が押し合って自立する仕組み\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"步驟 4: 岩をもたれかけさせ、0.1秒で作動するか感度を点検する\",\n      \"description\": \"エサ棒の尖った先端に昆虫や野イチゴをしっかり刺します。片手で10〜15kgの重い平らな岩を持ち上げ、突っ張り棒の上部に45度の角度でそっともたれかけさせます。岩の重みで全体が引き締まります。細い小枝でエサを軽く「チョン」と突いたとき、0.1秒で骨組みが外れて岩がドスンと落ちるか確認して完成です。\",\n      \"actionNote\": \"> 安全第一: 岩をもたれさせるとき、絶対に岩の下に指を入れないでください。側面を支えて安全に作業します。\",\n      \"svgFileName\": \"pr08-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // 步驟 04\",\n        \"15kgの平らな岩を設置\",\n        \"エサ棒の先端にエサを装着\",\n        \"触れると0.1秒で岩が落下\",\n        \"[重要] かすかな接触で即座に崩れる高感度設定\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命錯誤：卡槽雕刻過深導致卡死，或使用過輕的石頭\",\n    \"description\": \"凹槽太深或過於緊繃，即使獵物大力拉扯誘餌骨架也無法崩解，白白損失食物。石頭太輕則無法一擊致命，獵物負傷逃脫並將警報擴散至整個區域。\",\n    \"consequence\": \"後果：捕獵徹底失敗、體力透支枯竭、區域獵物全部驚逃\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"在荒野狂追動物會把你活活餓死！快學這款3根樹枝做的0.1秒落石陷阱！\",\n    \"body\": \"將三根樹枝刻槽組合成數字4形狀：不用一根繩子，純靠摩擦力就能撐起15公斤巨石！關鍵秘訣在於卡槽要淺，小動物一碰誘餌，張力瞬間瓦解，巨石0.1秒直接砸落！\",\n    \"outro\": \"無須網路即可離線瀏覽的原始生存圖面，請點擊個人簡介連結。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr08-outcome.svg\",\n    \"title\": \"完成した数字の4型圧殺罠の全景\",\n    \"description\": \"3本の枝が絶妙に噛み合って15kgの重い岩を支え、獲物がエサに触れた瞬間に0.1秒で崩れて岩が圧殺する完成形態。\",\n    \"imageFileName\": \"pr08-outcome.png\"\n  },\n  \"createdAt\": \"2026-10-14T15:35:00.000Z\",\n  \"updatedAt\": \"2026-10-15T13:34:19+09:00\",\n  \"contentHash\": \"46ed0acd1b57e2da\"\n}","content/protocols/locales/09-pit-charcoal-kiln.de.json":"{\n  \"protocolId\": \"PR-09\",\n  \"category\": \"FIRE\",\n  \"title\": \"Herstellung von Hartholzkohle im anaeroben Erdgrubenmeiler\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[RAUCHFREIER BRENNSTOFF & KOHLEFILTER]\",\n  \"summary\": \"Wer Holz im offenen Lagerfeuer verbrennt, verschwendet wertvollen Brennstoff, da es mit Sauerstoff vollständig zu weißer Asche zerfällt. Durch das Ausheben einer 50cm tiefen konischen Erdgrube, dichtes vertikales Schichten von Eichenknüppeln und luftdichtes Versiegeln mit Lehm und Rasensoden wird die Sauerstoffzufuhr um 95% gedrosselt. Das Holz wird pyrolysiert statt verbrannt. Es entsteht dichte, metallisch klingende stückige Holzkohle, die rauchfrei bei 500°C brennt und Trinkwasser filtert.\",\n  \"timeRequired\": \"5 Stunden (1h Grube & Bestückung + 3h Pyrolyse + 1h geschlossene Abkühlung)\",\n  \"successRate\": \"90% (bei striktem Luftabschluss und vollständiger Abkühlung)\",\n  \"difficulty\": \"Mittel (Erkennung der Rauchphasen erforderlich)\",\n  \"outputPerHour\": \"3-5kg hochwertige Hartholzkohle pro Brand\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"15-20 armdicke trockene Eichen- oder Hartholzscheite (Länge 30-40cm)\",\n      \"desc\": \"Dichtes Hartholz, das unter Sauerstoffmangel pyrolysiert, ohne zu verflammen, und langanhaltende Glut liefert.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Konische Erdgrube (50cm Tiefe, 60cm oberer Durchmesser)\",\n      \"desc\": \"Nach unten verjüngt ausgehoben, um Strahlungswärme zu bündeln und die anaerobe Zirkulation zu steuern.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Stabiles Astgitter & breite Laubblätter\",\n      \"desc\": \"Quer über den Holzstapel gelegt, um die schwere Lehmschicht zu stützen und Erdrutsch in die Glut zu verhindern.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Feuchter Tonlehm & Rasensoden (10cm Schichtdicke)\",\n      \"desc\": \"Wärmedämmende Abdeckung, die 95% des Sauerstoffs abriegelt und das Holz bei über 400°C backt.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Trockenes Reisig & Gluttbett zur Vortrocknung\",\n      \"desc\": \"Treibt Bodenfeuchtigkeit vollständig aus und zündet die Basis der gestapelten Holzscheite an.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: 50cm Konusgrube ausheben & Vorwärmglut anlegen\",\n      \"description\": \"Wählen Sie trockenen, festen Waldboden und heben Sie eine Grube mit 60cm oberem Durchmesser und 50cm Tiefe aus, die sich nach unten auf 30cm verjüngt. Entfachen Sie am Grubenboden mindestens 15 Minuten lang ein kräftiges Reisigfeuer, um Feuchtigkeit aus den Erdwänden vollständig zu verdampfen und ein glühendes Glutbett zu schaffen.\",\n      \"actionNote\": \"> Aushub-Praxistipp: Restfeuchte in den Erdwänden führt zu Holzfäulnis und erstickt das Glutbett. Heizen Sie den Grubenboden trocken.\",\n      \"svgFileName\": \"pr09-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PIT EXCAVATION & PRE-DRYING\",\n        \"Obere Grubenöffnung 60cm Konusform\",\n        \"Tiefe 50cm (Bodendurchmesser 30cm)\",\n        \"Bodenglut & Reisig zur Vortrocknung\",\n        \"[KERN] Erdfeuchte austreiben & Glutbett bilden\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Armdicke Eichenscheite vertikal lückenlos stapeln\",\n      \"description\": \"Stellen Sie auf die rote Bodenglut trockene Eichenscheite (30-40cm lang, 5-8cm dick) senkrecht wie dichte Säulen auf. Größere Luftlücken lassen Sauerstoff zirkulieren und verbrennen das Holz zu weißer Asche. Schlagen Sie fingerdicke Zweige wie Keile in alle Zwischenräume, um maximale Packungsdichte zu erzielen.\",\n      \"actionNote\": \"> Stapel-Geheimnis: Der Meilerraum muss so dicht gefüllt sein, dass kaum Hohlräume verbleiben. Je dichter gepackt, desto härter die Holzkohle.\",\n      \"svgFileName\": \"pr09-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DENSE VERTICAL TIMBER STACK\",\n        \"Eichenscheite (5-8cm) senkrecht gestapelt\",\n        \"Dünne Keilzweige füllen Zwischenräume\",\n        \"Aufsteigende Hitze vom Bodenglutbett\",\n        \"[KERN] Hohlräume minimieren für maximale Dichte\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Astgitter auflegen & 95% Luft mit Lehm und Soden drosseln\",\n      \"description\": \"Legen Sie dicke Äste gitterförmig über die Hölzer und bedecken Sie diese mit breiten Blättern oder dichtem Gras. Tragen Sie eine 10cm dicke Schicht aus feuchtem Lehm und umgedrehten Rasensoden auf. Lassen Sie am windzugewandten Bodenrand zwei fingerdicke Zuluftlöcher und in der Mitte einen faustgroßen Kamin offen, um die Sauerstoffzufuhr auf 5% zu beschränken.\",\n      \"actionNote\": \"> Dichtheitsprüfung: Tritt Rauch aus Rissen im Lehm aus, verschmieren Sie diese sofort mit feuchtem Lehm, um offenes Aufflammen zu verhindern.\",\n      \"svgFileName\": \"pr09-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // MULTI-LAYER ANAEROBIC SEAL\",\n        \"Astgitter & Blätter-Stützschicht\",\n        \"10cm Lehm- & Rasensoden-Dämmschicht\",\n        \"2 Zuluftöffnungen (fingerdick)\",\n        \"Zentraler Rauchkamin (faustgroß)\",\n        \"[KERN] Unvollständige Verbrennung bei 95% Luftmangel\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Rauchfarbe bestimmen, hermetisch verschließen & kühlen\",\n      \"description\": \"In den ersten 1-2 Stunden entweicht dichter weißer Wasserdampf aus dem Kamin. Geht der Rauch nach 2-3 Stunden in einen feinen, transparenten Blaudunst über, sind Wasser und Teere entwichen – das Holz ist reine Kohle! Verschließen Sie Kamin und Zuluftöffnungen sofort luftdicht mit Lehmkugeln. Warten Sie mindestens 6 Stunden, bis der Hügel handkalt ist, bevor Sie ernten.\",\n      \"actionNote\": \"> Verpuffungsgefahr: Öffnet man den Meiler vorzeitig im heißen Zustand, strömt Sauerstoff ein und entfacht eine Stichflamme, die die Kohle verbrennt. Vollständig abkühlen lassen.\",\n      \"svgFileName\": \"pr09-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SMOKE PHASE & CHARCOAL HARVEST\",\n        \"Phase 1: Dichter weißer Dampf (Wasser)\",\n        \"Phase 2: Zarter Blaurauch (Pyrolyse fertig)\",\n        \"Alle Öffnungen mit Lehm dicht verschlossen\",\n        \"Metallisch klingende Hartholzkohle ernten\",\n        \"[KERN] Bei Blaurauch sofort abdichten & abkühlen\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fataler Fehler: Meiler im heißen Zustand öffnen oder Kaminversiegelung versäumen\",\n    \"description\": \"Das Freilegen der Grube bei über 400°C führt durch plötzlichen Sauerstoffeinstrom zu einer massiven Verpuffung. Bleiben die Schlitze bei Blaurauch offen, brennt die gesamte Kohle zu Asche ab.\",\n    \"consequence\": \"Konsequenz: Totalverlust der gesamten Ausbeute und schwere Brandverletzungen\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Lagerfeuer hinterlassen nur nutzlose Asche! So brennt man hochwertige Hartholzkohle unter der Erde!\",\n    \"body\": \"Schichten Sie Eichenholz senkrecht in eine 50cm Grube und dichten Sie sie mit Lehm ab, um 95% Sauerstoff zu blockieren! Nach 3 Stunden weißem Dampf kündigt feiner Blaurauch fertige Kohle an. Verschließen Sie alle Löcher mit Lehm und lassen Sie ihn erkalten. Sie erhalten dichte Kohle mit Metallklang für 500 Grad Hitze!\",\n    \"outro\": \"Offline-Überlebenspläne finden Sie über den Link im Profil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr09-outcome.svg\",\n    \"title\": \"Querschnitt des Erdgrubenmeilers & Holzkohle-Kenndaten\",\n    \"description\": \"Technische Schnittdarstellung des anaeroben 50cm Erdmeilers mit 95% Luftdrosselung zur Gewinnung poröser Eichenholzkohle für rauchfreie Hitze und Trinkwasserfilterung.\"\n  },\n  \"createdAt\": \"2026-10-15T05:30:00.000Z\",\n  \"contentHash\": \"06910fe5beeb5301\",\n  \"updatedAt\": \"2026-10-15T14:35:53+09:00\"\n}","content/protocols/locales/09-pit-charcoal-kiln.en.json":"{\n  \"protocolId\": \"PR-09\",\n  \"category\": \"FIRE\",\n  \"title\": \"How to Make Hardwood Charcoal in an Underground Pit Kiln\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[SMOKELESS FUEL & CARBON FILTER]\",\n  \"summary\": \"Burning wood in an open campfire wastes fuel by turning it completely into useless white ash. By digging a 50cm cone-shaped pit, packing hardwood tightly, and sealing it with earth and turf sod to block 95% of incoming oxygen, the timber is pyrolyzed rather than combusted. This produces dense, metallic-ringing lump charcoal that burns smokeless at 500°C, purifies contaminated water, and preserves embers for days.\",\n  \"timeRequired\": \"5 hours (1h pit digging & wood packing + 3h pyrolysis + 1h sealed cooling)\",\n  \"successRate\": \"90% (strict compliance with anaerobic seal & cooling)\",\n  \"difficulty\": \"Moderate (identifying smoke transition phases)\",\n  \"outputPerHour\": \"3-5kg premium lump charcoal per batch\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"15-20 wrist-thick dry oak or hardwood billets (30-40cm length)\",\n      \"desc\": \"Dense hardwoods such as oak, maple, or hickory that pyrolyze without combusting, yielding long-burning, high-temperature charcoal.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Cone-shaped earthen pit (50cm depth, 60cm top diameter)\",\n      \"desc\": \"Tapered downward to concentrate internal radiant heat and control anaerobic airflow circulation.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Stout branch lattice frame & broad leaves\",\n      \"desc\": \"Placed horizontally across the timber stack to support the heavy mud mound and prevent loose soil from caving in.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Moist clay mud & grass turf sod (10cm thickness)\",\n      \"desc\": \"Forms an airtight thermal blanket over the kiln, restricting oxygen by 95% and baking the wood above 400°C.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Dry kindling & starter ember bed\",\n      \"desc\": \"Completely bakes out pit wall dampness and ignites the bottom of the packed timber bundle.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Dig a 50cm Cone Pit & Establish a Starter Ember Bed\",\n      \"description\": \"Select dry, firm woodland ground and excavate a pit 60cm wide at the top and 50cm deep, tapering downward to a 30cm base. Build a brisk fire of dry twigs and leaves at the bottom for at least 15 minutes to completely bake away moisture from the pit walls and create a glowing bed of red-hot coals.\",\n      \"actionNote\": \"> Digging Insight: If residual soil moisture remains in the pit, the wood will steam, rot, and extinguish. Heat the base thoroughly until bone dry.\",\n      \"svgFileName\": \"pr09-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PIT EXCAVATION & PRE-DRYING\",\n        \"Top Opening 60cm Diameter Cone Pit\",\n        \"Depth 50cm (Base Diameter 30cm)\",\n        \"Base Pre-Drying Kindling & Ember Bed\",\n        \"[KEY] Fully bake out soil moisture for high heat\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Pack Wrist-Thick Oak Billets Vertically with Zero Gaps\",\n      \"description\": \"Directly on top of the glowing embers, stand dry oak billets (30-40cm long, 5-8cm thick) vertically like tight pillars. Any large air pockets allow free oxygen to circulate, burning your wood down to white ash. Drive slender finger-thick branches into every crevice like wooden wedges to pack the cavity to maximum density.\",\n      \"actionNote\": \"> Stacking Secret: The kiln chamber must be packed solid with almost no breathing room. Maximum density yields dense, metallic-sounding charcoal.\",\n      \"svgFileName\": \"pr09-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DENSE VERTICAL TIMBER STACK\",\n        \"Wrist-Thick (5-8cm) Oak Vertical Stack\",\n        \"Slender Wedges Filling Every Crevice\",\n        \"Heat Spreading from Bottom Embers\",\n        \"[KEY] Minimize air voids for pure anaerobic density\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Lay Branch Lattice & Seal 95% Oxygen with Mud and Turf Sod\",\n      \"description\": \"Lay thick cross branches across the top of the vertical logs in a grid pattern, then blanket them with broad green leaves or dense grass. Pack a 10cm layer of moist clay and upside-down grass sod over the dome. Poke two finger-thick air intake vents at ground level on the windward side, and leave one fist-sized chimney vent in the center, allowing only 5% oxygen intake.\",\n      \"actionNote\": \"> Seal Check: If smoke leaks through hairline cracks in the mud mound, immediately slap fresh wet clay over them to stop open flame combustion.\",\n      \"svgFileName\": \"pr09-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // MULTI-LAYER ANAEROBIC SEAL\",\n        \"Branch Lattice & Leaf Support Layer\",\n        \"10cm Moist Mud & Turf Sod Blanket\",\n        \"2 Base Intake Vents (Finger-Thick)\",\n        \"Center Exhaust Chimney (Fist-Sized)\",\n        \"[KEY] 95% oxygen starved incomplete combustion\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Monitor Smoke Transition & Hermetically Seal for Cooling\",\n      \"description\": \"For the first 1-2 hours, dense white steam billows from the chimney as moisture boils off. After 2-3 hours, when the smoke turns into a faint, translucent blue haze, moisture and tars have escaped—the wood has carbonized into pure charcoal! Instantly seal the chimney and intake vents air-tight with wet clay balls. Wait at least 6 hours until the mound is cold to the touch before opening.\",\n      \"actionNote\": \"> Backdraft Warning: Opening a hot kiln rushes fresh oxygen inside, creating a catastrophic backdraft explosion that reduces your charcoal to ash in seconds. Let it cool completely.\",\n      \"svgFileName\": \"pr09-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SMOKE PHASE & CHARCOAL HARVEST\",\n        \"Phase 1: Dense White Steam (Water Evaporation)\",\n        \"Phase 2: Faint Blue Haze (Pyrolysis Done)\",\n        \"Hermetically Seal All Vents & Cool Completely\",\n        \"Harvest Metallic-Ringing Dense Hardwood Charcoal\",\n        \"[KEY] Seal on blue smoke & cool fully to touch\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Opening the mound while hot or forgetting to seal the vents\",\n    \"description\": \"Cracking open a kiln above 400°C draws in massive volumes of fresh oxygen, creating an explosive backdraft fireball. Leaving vents unsealed when blue smoke appears allows the charcoal to catch fire and burn away into useless ash.\",\n    \"consequence\": \"Consequence: Complete loss of your fuel yield and severe burn hazards\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Burning wood in an open fire leaves only white ash! Here is how to bake metallic charcoal underground!\",\n    \"body\": \"Pack oak branches vertically into a 50cm pit and seal it under clay and sod to choke out 95% of oxygen! When thick white steam turns into faint blue smoke after 3 hours, plug every vent with mud. Once cool, you will harvest dense, metallic-sounding charcoal that burns smokeless at 500 degrees!\",\n    \"outro\": \"Tap the link in our profile for full offline survival blueprints.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr09-outcome.svg\",\n    \"title\": \"Completed Underground Pit Charcoal Kiln & Lump Charcoal Specs\",\n    \"description\": \"Cross-sectional engineering view of the 50cm underground cone kiln operating at 95% oxygen restriction, yielding dense porous hardwood charcoal ideal for smokeless high heat and emergency water filtration.\"\n  },\n  \"createdAt\": \"2026-10-15T05:30:00.000Z\",\n  \"contentHash\": \"06910fe5beeb5301\",\n  \"updatedAt\": \"2026-10-15T14:35:53+09:00\"\n}","content/protocols/locales/09-pit-charcoal-kiln.es.json":"{\n  \"protocolId\": \"PR-09\",\n  \"category\": \"FIRE\",\n  \"title\": \"Cómo hacer carbón vegetal en un horno de pozo subterráneo sin oxígeno\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[COMBUSTIBLE SIN HUMO Y FILTRO DE CARBONO]\",\n  \"summary\": \"Quemar leña en una fogata abierta la convierte por completo en ceniza blanca inútil debido al exceso de oxígeno. Al cavar un pozo cónico de 50 cm, apilar troncos de roble apretados verticalmente y sellarlo con barro y tepes de hierba para bloquear el 95% del aire, la madera se piroliza en lugar de arder. Esto genera carbón duro y denso que suena a metal, arde a 500 °C sin humo, purifica agua y conserva ascuas durante días.\",\n  \"timeRequired\": \"5 horas (1h excavación y carga + 3h pirólisis + 1h enfriamiento hermético)\",\n  \"successRate\": \"90% (cumpliendo el sellado anaeróbico y enfriamiento)\",\n  \"difficulty\": \"Media (requiere reconocer el cambio de color del humo)\",\n  \"outputPerHour\": \"3 a 5 kg de carbón vegetal duro por hornada\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"15-20 leños secos de roble del grosor de la muñeca (longitud 30-40 cm)\",\n      \"desc\": \"Maderas duras de alta densidad que se carbonizan sin consumirse en llamas, produciendo carbón duradero de alto poder calorífico.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Pozo cónico de tierra (50 cm de profundidad, 60 cm de diámetro superior)\",\n      \"desc\": \"Excavado con conicidad hacia abajo para concentrar el calor radiante y controlar el flujo de aire anaeróbico.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Enrejado de ramas gruesas y hojas anchas\",\n      \"desc\": \"Estructura colocada sobre los troncos para soportar la cubierta de lodo e impedir que la tierra caiga dentro del horno.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Barro arcilloso húmedo y tepes de césped (10 cm de espesor)\",\n      \"desc\": \"Capa aislante que sella el pozo, bloquea el 95% del oxígeno y hornea la madera a más de 400 °C.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Ramas secas y cama de brasas inicial\",\n      \"desc\": \"Seca por completo la humedad del suelo y enciende la base del lote de troncos apilados.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Excavar el pozo cónico de 50 cm y crear la cama de brasas\",\n      \"description\": \"Elija suelo firme y seco. Excave un pozo de 60 cm de diámetro superior y 50 cm de profundidad, reduciéndose a unos 30 cm en el fondo en forma de cono. Encienda un fuego generoso con ramitas secas en el fondo durante al menos 15 minutos para evaporar toda la humedad de las paredes de tierra y formar una buena base de brasas ardientes.\",\n      \"actionNote\": \"> Consejo de excavación: Si queda humedad en la tierra, la madera se pudrirá y el fuego se apagará. Caliente el fondo hasta secarlo por completo.\",\n      \"svgFileName\": \"pr09-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PIT EXCAVATION & PRE-DRYING\",\n        \"Pozo cónico de 60cm de boca superior\",\n        \"Profundidad 50cm (base de 30cm)\",\n        \"Brasas base para secar la tierra\",\n        \"[CLAVE] Secar humedad del suelo y crear brasas\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Apilar los leños de roble verticalmente sin dejar huecos\",\n      \"description\": \"Sobre las brasas incandescentes del fondo, coloque los leños secos de roble (30-40 cm de largo, 5-8 cm de grosor) en posición vertical como pilares apretados. Los huecos de aire permiten que el oxígeno circule y queme la madera hasta dejar solo cenizas. Inserte ramas delgadas a modo de cuñas en cada resquicio para compactar el interior al máximo.\",\n      \"actionNote\": \"> Secreto de carga: El interior debe quedar tan denso que casi no haya espacio libre. Cuanta más densidad, más duro y sonoro será el carbón.\",\n      \"svgFileName\": \"pr09-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DENSE VERTICAL TIMBER STACK\",\n        \"Leños de roble (5-8cm) en pila vertical\",\n        \"Ramas finas acuñadas en los huecos\",\n        \"Calor ascendente desde las brasas base\",\n        \"[CLAVE] Minimizar huecos para máxima densidad\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Colocar el enrejado de ramas y sellar el 95% del aire con barro\",\n      \"description\": \"Cruce ramas gruesas en forma de rejilla sobre los troncos verticales y cúbralas con hojas anchas o hierba densa. Aplique encima una capa de 10 cm de barro arcilloso húmedo y tepes de hierba invertidos. Deje dos pequeños respiraderos del grosor de un dedo en la base del lado del viento y una chimenea del tamaño de un puño en el centro, limitando el oxígeno al 5%.\",\n      \"actionNote\": \"> Control de sellado: Si sale humo por grietas en la cúpula de barro, tápelas de inmediato con barro fresco para evitar que prenda fuego abierto.\",\n      \"svgFileName\": \"pr09-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // MULTI-LAYER ANAEROBIC SEAL\",\n        \"Enrejado de ramas y lecho de hojas\",\n        \"Cubierta de 10cm de barro y tepes\",\n        \"2 tomas de aire base (grosor de dedo)\",\n        \"Chimenea central de tiro (puño)\",\n        \"[CLAVE] Combustión incompleta sin 95% de oxígeno\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Distinguir el color del humo, sellar y enfriar antes de cosechar\",\n      \"description\": \"Durante las primeras 1-2 horas, la chimenea emite un humo blanco denso de vapor de agua. Tras 2-3 horas, cuando el humo se vuelva tenue, transparente y azulado, el agua y el alquitrán se habrán disipado por completo: ¡la madera se ha convertido en carbón puro! Selle de inmediato la chimenea y las tomas de aire con bolas de barro. Espere al menos 6 horas hasta que el montículo esté totalmente frío al tacto antes de desenterrar.\",\n      \"actionNote\": \"> Peligro de explosión: Si abre el horno mientras está caliente, entrará aire fresco y se producirá una llamarada explosiva que convertirá el carbón en cenizas. Deje enfriar por completo.\",\n      \"svgFileName\": \"pr09-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SMOKE PHASE & CHARCOAL HARVEST\",\n        \"Fase 1: Humo blanco denso (vapor de agua)\",\n        \"Fase 2: Humo azul tenue (pirólisis lista)\",\n        \"Sellado hermético total y enfriamiento\",\n        \"Cosecha de carbón duro con sonido metálico\",\n        \"[CLAVE] Sellar con humo azul y enfriar del todo\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error fatal: Abrir el pozo mientras sigue caliente o no sellar las salidas a tiempo\",\n    \"description\": \"Abrir el horno a más de 400 °C provoca una entrada violenta de oxígeno que desata una explosión de fuego instantánea. Dejar los respiraderos abiertos tras la aparición del humo azul quemará todo el carbón hasta volverlo ceniza.\",\n    \"consequence\": \"Consecuencia: Pérdida total de la cosecha y riesgo grave de quemaduras\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"¡Quemar leña al aire libre solo deja ceniza blanca! ¡Aprende a fabricar carbón metálico bajo tierra!\",\n    \"body\": \"¡Coloca troncos de roble apretados en un pozo de 50 cm y tápalos con barro para bloquear el 95% del aire! Al principio saldrá humo blanco espeso, pero cuando se vuelva azul tenue a las 3 horas, tapa todos los agujeros con lodo. ¡Una vez frío, obtendrás carbón duro con timbre metálico que arde sin humo a 500 grados!\",\n    \"outro\": \"Planos completos de supervivencia sin conexión en el enlace de nuestro perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr09-outcome.svg\",\n    \"title\": \"Corte transversal del horno de pozo y especificaciones del carbón\",\n    \"description\": \"Vista técnica del horno subterráneo cónico operando con restricción de oxígeno al 95%, produciendo carbón vegetal poroso de roble ideal para calor sin humo y purificación de agua.\"\n  },\n  \"createdAt\": \"2026-10-15T05:30:00.000Z\",\n  \"contentHash\": \"06910fe5beeb5301\",\n  \"updatedAt\": \"2026-10-15T14:35:53+09:00\"\n}","content/protocols/locales/09-pit-charcoal-kiln.ja.json":"{\n  \"protocolId\": \"PR-09\",\n  \"category\": \"FIRE\",\n  \"title\": \"土穴で空気を遮断して木材を高硬度な炭に焼き上げる方法（原始木炭窯）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[無煙高熱燃料 & 浄水フィルター木炭確保]\",\n  \"summary\": \"焚き火で木をそのまま燃やすと酸素と完全反応して白い灰しか残りません。地面に深さ50cmの円錐形の穴を掘り、ナラなどの広葉樹を隙間なく垂直に立て並べ、泥と芝生で覆って空気の流入を95%遮断すると、木材は燃え上がらずに高温で蒸し焼きにされ、硬質な炭になります。煙を出さずに暖を取り、泥水の浄水ろ過材や火種保存に使える野外生存の黒い宝石です。\",\n  \"timeRequired\": \"5時間（穴掘り・薪配置1時間 ＋ 炭化3時間 ＋ 密閉冷却1時間）\",\n  \"successRate\": \"90%（空気遮断と冷却時間を厳守した場合）\",\n  \"difficulty\": \"普通（煙の色の変化を見極める技術が必要）\",\n  \"outputPerHour\": \"1回の稼働で高品質な硬質木炭3〜5kg収穫\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"手首ほどの太さの乾燥したナラ・カシの丸太15〜20本（長さ30〜40cm）\",\n      \"desc\": \"密度が高く硬い広葉樹を用意します。無酸素状態で燃え尽きずに炭化し、長持ちする高火力炭になります。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"深さ50cm・上部直径60cmの円錐形の土穴\",\n      \"desc\": \"下に向かって細くなる形状で熱を中心部に集中させ、空気の循環を制御する地下窯です。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"窯を覆う太い枝の格子枠と大きな広葉樹の葉\",\n      \"desc\": \"立てた丸太の上に渡し、泥が崩れ落ちないよう支える骨組みと土砂混入防止用の葉です。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"湿った粘土質の泥と芝生のターフ（厚さ10cm）\",\n      \"desc\": \"窯の上部を完全に覆って空気（酸素）の流入を95%遮断し、内部を400℃以上の高熱で蒸し焼きにする断熱蓋です。\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"下地乾燥用の小枝と熾火の種火\",\n      \"desc\": \"土穴の壁や底の湿気をしっかり飛ばし、丸太の下部に火を回すための点火材です。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"第1段階: 深さ50cmの円錐穴の掘削と底部の熾火作り\",\n      \"description\": \"水がたまらない硬く乾いた地面を選び、上部直径60cm、深さ50cmで土を掘ります。下に向かうにつれて直径30cmほどに狭まる円錐形に掘ることで熱が中央に集中します。底に乾いた小枝や落ち葉を敷いて火を起こし、15分以上しっかり穴の土を乾かして真っ赤に輝く熾火の土台を作ります。\",\n      \"actionNote\": \"> 掘削のコツ: 底に湿気が残っていると蒸し焼きにならず腐敗臭がして火が消えてしまいます。土が乾燥するまでしっかり熾火で熱してください。\",\n      \"svgFileName\": \"pr09-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PIT EXCAVATION & PRE-DRYING\",\n        \"上部直径60cm 円錐形土穴掘削\",\n        \"深さ50cm（底部直径30cm）\",\n        \"底部乾燥用小枝 ＆ 熾火の種火\",\n        \"[核心] 土の湿気を完全乾燥させ高温火種を形成\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"第2段階: 手首太さのナラ材を隙間なく垂直に敷き詰める\",\n      \"description\": \"底の赤い熾火の上に、長さ30〜40cm、手首太さ（5〜8cm）のナラの丸太を柱のようにまっすぐ立てて敷き詰めます。木材の間に広い隙間があると酸素が回って白い灰になってしまうため、隙間には指ほどの太さの小枝をくさびのように差し込んで密度を極限まで高めます。\",\n      \"actionNote\": \"> 積み方の秘訣: 窯の中は木でぎっしり詰まり、空気の抜ける隙間がほとんどない状態にしてください。密度が高いほど金属音が鳴る最高級の炭になります。\",\n      \"svgFileName\": \"pr09-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DENSE VERTICAL TIMBER STACK\",\n        \"手首太さ（5〜8cm）ナラ材の垂直積載\",\n        \"隙間をくさび状に埋めた小枝\",\n        \"底部熾火から立ち上る熱気\",\n        \"[核心] 隙間を最小化し無酸素炭化の密度を極大化\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"第3段階: 枝の枠組みを載せ泥と芝生で酸素を95%遮断する\",\n      \"description\": \"垂直に立てた丸太の上に太い枝を井桁状（格子状）に渡し、その上に大きな葉や草を敷き詰めます。その上から湿った泥と芝生を厚さ10cmで隙間なく塗り固めます。風上側の根元に指の太さの吸気口を2箇所、中央に拳大の煙突を1箇所だけ残し、酸素供給をわずか5%に制限します。\",\n      \"actionNote\": \"> 密閉の確認: 煙突以外から煙が漏れている隙間があれば、すぐに泥を追加して塞ぎ、木が勢いよく燃え上がるのを防ぎます。\",\n      \"svgFileName\": \"pr09-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // MULTI-LAYER ANAEROBIC SEAL\",\n        \"枝格子枠 ＋ 広葉樹葉の支持層\",\n        \"10cm 湿潤泥 ＆ 芝生ターフ蓋\",\n        \"下部吸気穴2箇所（指の太さ）\",\n        \"中央排気煙突（拳大）\",\n        \"[核心] 酸素95%遮断の不完全燃焼窯が完成\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"第4段階: 煙の色の変化を識別し完全密閉冷却後に木炭を収穫\",\n      \"description\": \"最初の1〜2時間は水分が蒸発して煙突から濃い白煙が噴き出します。2〜3時間経過して煙が澄んだ淡い青色に変わったら、水分とタールが抜けきり純粋な炭になった合図です！直ちに泥団子で煙突と吸気口を100%密閉して消火します。土の表面が冷えるまで最低6時間待ってから掘り出し、銀色の光沢がある硬質炭を取り出します。\",\n      \"actionNote\": \"> バックドラフト警戒: 窯の中がまだ熱い時に掘り起こすと、新鮮な空気が一気に流入して爆発的に炎上し、炭が灰に変わってしまいます。完全に冷え切ってから開けてください。\",\n      \"svgFileName\": \"pr09-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SMOKE PHASE & CHARCOAL HARVEST\",\n        \"第1段階: 濃い白煙（水分蒸発）\",\n        \"第2段階: 淡い青煙（炭化完了）\",\n        \"全通気孔を泥で完全密閉し冷却\",\n        \"澄んだ金属音のする高密度ナラ炭を収穫\",\n        \"[核心] 青煙で即座に密閉し余熱を完全冷却\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的な失敗: 熱が残っている状態で焦って蓋を開けること、または密閉忘れ\",\n    \"description\": \"窯の内部が400℃以上に達している状態で土を取り除くと、外気の酸素が一気に吸い込まれてバックドラフト（爆発的燃焼）が起こり炎上します。また青煙が出た時に穴を塞がずに放置すると木材全体が灰に酸化してしまいます。\",\n    \"consequence\": \"結果: 何時間もかけて焼いた木が一瞬で灰に消え、重度の火傷を負う危険\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"焚き火で木を燃やすと白い灰しか残りません！土に埋めて金属音の鳴る極上炭を焼く裏技！\",\n    \"body\": \"土穴にナラの木をぎっしり立て、泥と芝生で覆って酸素を95%遮断してください！最初は濃い白煙が出ますが、3時間後に透き通った青い煙に変わったら炭化完了のサイン。すべての穴を泥で塞いで完全に冷ませば、煙を出さずに500℃の熱を出す最高のサバイバル炭が完成します！\",\n    \"outro\": \"通信が途絶えたオフライン環境でも閲覧できるサバイバル図面はプロフィールのリンクから！\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr09-outcome.svg\",\n    \"title\": \"完成した原始地下木炭窯の断面及び多孔質木炭の諸元\",\n    \"description\": \"深さ50cmの円錐形土穴で酸素を95%遮断して高温蒸し焼きにし、無煙高熱燃料や飲料水ろ過フィルターとして使用可能な硬質多孔質ナラ炭の完成断面図です。\"\n  },\n  \"createdAt\": \"2026-10-15T05:30:00.000Z\",\n  \"contentHash\": \"06910fe5beeb5301\",\n  \"updatedAt\": \"2026-10-15T14:35:53+09:00\"\n}","content/protocols/locales/09-pit-charcoal-kiln.pt.json":"{\n  \"protocolId\": \"PR-09\",\n  \"category\": \"FIRE\",\n  \"title\": \"Como fazer carvão vegetal denso em trincheira de terra sem oxigênio\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[COMBUSTÍVEL SEM FUMAÇA E FILTRO DE CARBONO]\",\n  \"summary\": \"Queimar lenha em fogueira aberta consome a madeira por completo, deixando apenas cinzas brancas inúteis. Ao cavar uma vala cônica de 50 cm, empilhar toras de carvalho verticalmente e vedar tudo com barro e placas de grama para cortar 95% do oxigênio, a madeira passa por pirólise em vez de combustão. Isso produz carvão vegetal maciço de som metálico, que queima a 500 °C sem fumaça e filtra água barrenta.\",\n  \"timeRequired\": \"5 horas (1h escavação e carga + 3h pirólise + 1h resfriamento vedado)\",\n  \"successRate\": \"90% (cumprindo a vedação anaeróbica e tempo de resfriamento)\",\n  \"difficulty\": \"Médio (requer identificar a mudança na cor da fumaça)\",\n  \"outputPerHour\": \"3 a 5 kg de carvão vegetal de alta dureza por fornada\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"15-20 toretes secos de carvalho na grossura do punho (30-40 cm de comprimento)\",\n      \"desc\": \"Madeiras nobres de alta densidade que se carbonizam sem queimar em chamas abertas, gerando brasas duradouras.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Buraco cônico de terra (50 cm de profundidade, 60 cm de boca superior)\",\n      \"desc\": \"Escavado com afunilamento para o fundo para concentrar o calor e controlar a circulação de ar.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Grade de galhos grossos e folhas largas\",\n      \"desc\": \"Estrutura colocada sobre a lenha para sustentar a tampa de argila e evitar deslizamento de terra.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Barro argiloso úmido e placas de grama (10 cm de espessura)\",\n      \"desc\": \"Camada isolante que veda a vala, bloqueia 95% do oxigênio e assa a madeira a mais de 400 °C.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Gravetos secos e leito de brasas inicial\",\n      \"desc\": \"Seca completamente a umidade das paredes de terra e acende a base da carga de madeira.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Cavar buraco cônico de 50 cm e fazer leito de brasas\",\n      \"description\": \"Escolha solo seco e firme. Escave um buraco de 60 cm de diâmetro na superfície e 50 cm de profundidade, afunilando para 30 cm no fundo. Acenda uma fogueira de gravetos secos no fundo por 15 minutos para secar totalmente a umidade da terra e formar uma base de brasas incandescentes.\",\n      \"actionNote\": \"> Dica de escavação: Se restar umidade no fundo, a madeira apodrecerá e o fogo se apagará. Aqueça a base até secar completamente.\",\n      \"svgFileName\": \"pr09-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PIT EXCAVATION & PRE-DRYING\",\n        \"Abertura superior de 60cm poço cônico\",\n        \"Profundidade 50cm (base de 30cm)\",\n        \"Brasas de fundo para secagem do solo\",\n        \"[CHAVE] Secar umidade da terra e formar brasas\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Empilhar toras de carvalho verticalmente sem frestas\",\n      \"description\": \"Sobre as brasas do fundo, apoie as toras secas de carvalho (30-40 cm de comprimento, 5-8 cm de espessura) em pé, como colunas bem coladas. Frestas largas deixam o oxigênio circular e queimam tudo até virar cinza. Crave galhos finos como cunhas nos vãos para atingir densidade máxima.\",\n      \"actionNote\": \"> Segredo de empilhamento: O forno deve ficar tão compacto que quase não haja vazios. Quanto mais denso, mais resistente o carvão.\",\n      \"svgFileName\": \"pr09-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DENSE VERTICAL TIMBER STACK\",\n        \"Toras de carvalho (5-8cm) em pé\",\n        \"Galhos finos cunhados nos vãos\",\n        \"Calor subindo das brasas da base\",\n        \"[CHAVE] Minimizar vazios para densidade anaeróbica\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Assentar grade de galhos e vedar 95% do ar com barro\",\n      \"description\": \"Trance galhos grossos sobre as toras em pé e cubra-os com folhas largas ou capim denso. Aplique por cima 10 cm de barro úmido e placas de grama invertidas. Deixe duas aberturas de entrada de ar da grossura de um dedo na base do lado do vento e uma chaminé do tamanho de um punho no topo, permitindo apenas 5% de oxigênio.\",\n      \"actionNote\": \"> Checagem de vedação: Se sair fumaça por rachaduras no barro, tampe-as imediatamente com argila fresca para evitar chamas abertas.\",\n      \"svgFileName\": \"pr09-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // MULTI-LAYER ANAEROBIC SEAL\",\n        \"Grade de galhos e camada de folhas\",\n        \"Tampa de 10cm de argila e leivas\",\n        \"2 entradas de ar base (grossura de dedo)\",\n        \"Chaminé central de exaustão (punho)\",\n        \"[CHAVE] Combustão incompleta sem 95% de oxigênio\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Monitorar a cor da fumaça, lacrar e resfriar para colher\",\n      \"description\": \"Nas primeiras 1 a 2 horas, sai uma fumaça branca densa de vapor de água. Após 2 a 3 horas, quando a fumaça se tornar azul-clara e translúcida, a água e os alcatrões já evaporaram: a madeira virou carvão puro! Vede imediatamente todas as aberturas com bolas de barro. Aguarde pelo menos 6 horas até o solo estar frio ao toque antes de desenterrar.\",\n      \"actionNote\": \"> Risco de explosão: Se abrir o forno ainda quente, a entrada repentina de oxigênio causará uma explosão que reduzirá o carvão a cinzas. Deixe esfriar por completo.\",\n      \"svgFileName\": \"pr09-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SMOKE PHASE & CHARCOAL HARVEST\",\n        \"Fase 1: Fumaça branca densa (vapor)\",\n        \"Fase 2: Fumaça azul tênue (pirólise pronta)\",\n        \"Todas as aberturas lacradas e resfriadas\",\n        \"Carvão vegetal duro com ressonância metálica\",\n        \"[CHAVE] Lacrar na fumaça azul e resfriar total\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro fatal: Abrir a cova ainda quente ou esquecer de vedar as aberturas\",\n    \"description\": \"Destampar o forno acima de 400 °C puxa ar fresco de forma violenta, provocando uma labareda explosiva instantânea. Deixar as saídas abertas com a fumaça azul queimará todo o carvão até virar cinzas.\",\n    \"consequence\": \"Consequência: Perda total da produção de carvão e risco severo de queimaduras\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Fogueira ao ar livre só deixa cinza inútil! Veja como assar carvão de toque metálico debaixo da terra!\",\n    \"body\": \"Aperte toras de carvalho em pé num buraco de 50 cm e vede com barro para bloquear 95% do oxigênio! Após 3 horas, a fumaça branca vira azul claro, indicando carvão pronto. Tampe todos os furos com argila e deixe esfriar. Você colherá carvão denso que queima a 500 graus sem fumaça!\",\n    \"outro\": \"Acesse os manuais completos de sobrevivência offline no link do perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr09-outcome.svg\",\n    \"title\": \"Corte transversal da trincheira de carvão e especificações\",\n    \"description\": \"Vista técnica do forno subterrâneo cônico com 95% de restrição de oxigênio, produzindo carvão vegetal poroso de carvalho para calor sem fumaça e filtragem de emergência.\"\n  },\n  \"createdAt\": \"2026-10-15T05:30:00.000Z\",\n  \"contentHash\": \"06910fe5beeb5301\",\n  \"updatedAt\": \"2026-10-15T14:35:53+09:00\"\n}","content/protocols/locales/09-pit-charcoal-kiln.zh-TW.json":"{\n  \"protocolId\": \"PR-09\",\n  \"category\": \"FIRE\",\n  \"title\": \"在土坑中隔絕空氣將木材燒製成堅硬木炭的方法（原始炭窯製作法）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[無煙高熱燃料 & 淨水濾炭必備]\",\n  \"summary\": \"將木材直接在營火中燃燒，會與氧氣充分反應而僅留下無用的白灰。若在地面挖掘50公分深的圓錐形土坑，將橡木緊密垂直豎立排列，再以泥土和草皮封蓋阻隔95%的空氣進入，木材便不會起火燃燒，而是在高溫下被燜烤成質地堅硬的木炭。這是在野外維持體溫、淨化泥水及保存火種不可或缺的黑寶石。\",\n  \"timeRequired\": \"5小時（挖坑與木材配置1小時 ＋ 炭化3小時 ＋ 密封冷卻1小時）\",\n  \"successRate\": \"90%（嚴格遵守空氣隔絕與冷卻時間）\",\n  \"difficulty\": \"普通（需具備辨識煙霧顏色變化的要領）\",\n  \"outputPerHour\": \"單次運作可採收3至5公斤優質硬質木炭\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"手腕粗細的乾燥橡木或闊葉木段15至20根（長度30至40公分）\",\n      \"desc\": \"選用質地緻密的高硬度闊葉木，在無氧狀態下不燃燒而進行炭化，製成耐燒且持久的高溫木炭。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"深50公分、頂部直徑60公分的圓錐形土坑\",\n      \"desc\": \"向下漸漸縮小的圓錐形結構，能將熱量匯聚於中央並有效控制空氣循環。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"覆蓋炭窯的粗樹枝骨架與寬大樹葉\",\n      \"desc\": \"橫架於豎立木段之上，支撐泥土不致崩塌並防止泥沙落入炭堆的骨架與隔離層。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"濕潤黏土與草皮（厚度10公分）\",\n      \"desc\": \"完全封閉炭窯頂部，阻隔95%的空氣流入，使內部維持在400度以上高溫燜烤。\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"底部乾燥用細碎樹枝與引火炭火\",\n      \"desc\": \"徹底烤乾土坑底部與坑壁的濕氣，並引燃整批木段底部的點火材。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"第1步：挖掘50公分圓錐形土坑並培育底部基底炭火\",\n      \"description\": \"選擇排水良好、乾燥堅實的林地，挖出頂部直徑60公分、深50公分的土坑，越往下縮減至直徑約30公分呈圓錐狀，使熱量能集中於底部中央。在坑底鋪滿乾燥細枝與枯葉點火，燃燒至少15分鐘徹底烘乾土坑濕氣，形成整片紅通通的熾熱炭火床。\",\n      \"actionNote\": \"> 挖掘技巧：若坑底殘留濕氣，木段會產生酸腐臭味並熄滅。請務必用大火將坑壁土壤徹底烤乾。\",\n      \"svgFileName\": \"pr09-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PIT EXCAVATION & PRE-DRYING\",\n        \"頂部直徑60公分圓錐形土坑\",\n        \"深度50公分（底部直徑30公分）\",\n        \"底部乾燥用細枝 ＆ 炭火基底\",\n        \"[核心] 徹底烤乾土壤濕氣並形成高溫火種\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"第2步：將手腕粗的橡木段緊密垂直豎立排列無空隙\",\n      \"description\": \"在底部的紅熱炭火之上，將長30至40公分、手腕粗細（5至8公分）的乾燥橡木段如柱子般筆直豎立填滿。木段間若有較大縫隙，會因空氣流通而使木材化為白灰。請將手指粗的細枝如楔子般用力塞入所有空隙中，將填充密度提升至極致。\",\n      \"actionNote\": \"> 堆疊秘訣：炭窯內部必須塞得嚴絲合縫、幾乎毫無喘息空間。密度越高，產出的木炭越堅硬且具金屬鏗鏘聲。\",\n      \"svgFileName\": \"pr09-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DENSE VERTICAL TIMBER STACK\",\n        \"手腕粗（5至8公分）橡木垂直積載\",\n        \"以細枝如楔子般填補空隙\",\n        \"從底部炭火向上蔓延的熱氣\",\n        \"[核心] 空隙最小化達成無氧炭化密度極大化\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"第3步：搭設樹枝骨架並以濕泥及草皮隔絕95%空氣\",\n      \"description\": \"在垂直木段上方以井字形搭放粗樹枝，鋪上大片樹葉或茂密雜草，再塗抹10公分厚的濕潤黏土並蓋滿反轉草皮。在迎風面底部邊緣留下兩根手指粗細的進氣孔，中央留出一個拳頭大小的排煙煙囪，將氧氣供應限制在僅剩5%。\",\n      \"actionNote\": \"> 密封檢查：除煙囪外，若泥層裂縫有煙霧漏出，請立即補上濕泥封死，以防木材劇烈起火燃燒。\",\n      \"svgFileName\": \"pr09-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // MULTI-LAYER ANAEROBIC SEAL\",\n        \"井字樹枝架 ＋ 闊葉隔離支撐層\",\n        \"10公分濕黏土 ＆ 草皮封蓋\",\n        \"底部進氣孔2處（手指粗細）\",\n        \"中央排煙煙囪（拳頭大小）\",\n        \"[核心] 隔絕95%氧氣的不完全燃燒炭窯完成\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"第4步：辨識煙霧顏色變化、完全密封冷卻後採收木炭\",\n      \"description\": \"最初1至2小時，煙囪會排出水分蒸發的濃白水氣煙霧。待2至3小時後，煙霧轉變為澄澈、清淡的淡藍色煙霧時，代表水分與焦油已全數排出，木材已炭化完成！此時立即以濕泥團徹底封死煙囪與進氣孔滅火。等待至少6小時直至土表觸感冰涼後，方可小心挖開採收散發銀光的硬質木炭。\",\n      \"actionNote\": \"> 爆燃警示：若炭窯內部仍發燙時急於開挖，湧入的新鮮空氣會引發回燃爆燃，瞬間將木炭燒成灰燼。務必徹底放涼後再開啟。\",\n      \"svgFileName\": \"pr09-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SMOKE PHASE & CHARCOAL HARVEST\",\n        \"第1階段：濃白煙霧（水分蒸發）\",\n        \"第2階段：淡藍煙霧（炭化完成）\",\n        \"以濕泥封閉所有孔隙後徹底冷卻\",\n        \"採收具金屬聲響的高密度優質木炭\",\n        \"[核心] 見藍煙立即封孔 ＆ 完全冷卻放涼\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命錯誤：窯體尚熱時急於挖開土蓋，或未及時封閉排煙孔\",\n    \"description\": \"當內部達400度以上時掀開土蓋，外圍新鮮空氣會猛烈倒灌引發回燃大火。此外，若見藍煙時不及時封孔，整批木材將完全氧化燃燒成毫無價值的白灰。\",\n    \"consequence\": \"後果：數小時心血瞬間化為灰燼，並面臨嚴重灼傷危險\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"在營火裡燒木頭只會留下白灰！教你埋在地底燒出金屬敲擊聲的頂級硬炭！\",\n    \"body\": \"在50公分土坑內緊密豎立橡木段，覆蓋泥土草皮隔絕95%空氣！最初會冒出濃濃白煙，3小時後一旦轉為淡藍色煙霧，代表炭化大功告成。立刻用濕泥封死所有孔隙放涼。冷卻後便能採收無煙、散發500度高溫的野外頂級木炭！\",\n    \"outro\": \"無網路斷網環境也能離線使用的生存圖鑑，請點擊個人簡介連結查閱！\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr09-outcome.svg\",\n    \"title\": \"原始地下炭窯剖面及多孔木炭規格\",\n    \"description\": \"深50公分圓錐形土坑在限制95%空氣下高溫燜烤運作的技術剖面圖，產出可用於無煙高熱與飲用水過濾的緻密多孔橡木炭。\"\n  },\n  \"createdAt\": \"2026-10-15T05:30:00.000Z\",\n  \"contentHash\": \"06910fe5beeb5301\",\n  \"updatedAt\": \"2026-10-15T14:35:53+09:00\"\n}","content/svgs/02-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <pattern id=\"diag-hatch\" width=\"8\" height=\"8\" patternTransform=\"rotate(45 0 0)\" patternUnits=\"userSpaceOnUse\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#333333\" stroke-width=\"1\" />\n    </pattern>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Outer Frame Guideline -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\" />\n\n  <!-- Ember Catcher Leaf positioned under the board & notch opening -->\n  <path d=\"M 180 260 C 240 250, 440 250, 500 260 C 515 285, 430 308, 340 308 C 250 308, 165 285, 180 260 Z\" \n        fill=\"#171717\" stroke=\"#666666\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\" />\n  <text x=\"655\" y=\"298\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"end\">불씨 받침 나뭇잎</text>\n\n  <!-- Hearth Board 3D block (isometric projection) -->\n  <!-- Top Face -->\n  <polygon points=\"120,180 520,180 480,230 80,230\" fill=\"#1f1e1e\" stroke=\"#888888\" stroke-width=\"1.5\" />\n  <!-- Front Face (Thickness profile) -->\n  <polygon points=\"80,230 480,230 480,265 80,265\" fill=\"#141414\" stroke=\"#888888\" stroke-width=\"1.5\" />\n  <!-- Right Side Face -->\n  <polygon points=\"480,230 520,180 520,215 480,265\" fill=\"#181818\" stroke=\"#666666\" stroke-width=\"1.2\" />\n\n  <!-- Spindle Socket Hole on Top Surface -->\n  <ellipse cx=\"300\" cy=\"205\" rx=\"26\" ry=\"12\" fill=\"#0d0d0d\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\" />\n  <circle cx=\"300\" cy=\"205\" r=\"4\" fill=\"#E02424\" />\n\n  <!-- 45-degree V-Notch carved from outer edge inward to socket center -->\n  <!-- Wedge cut into top surface and vertical front face -->\n  <polygon points=\"300,205 260,230 340,230\" fill=\"#0d0d0d\" stroke=\"#E02424\" stroke-width=\"2\" />\n  <!-- Vertical notch slot cut down through front edge -->\n  <polygon points=\"260,230 340,230 340,265 260,265\" fill=\"#080808\" stroke=\"#E02424\" stroke-width=\"1.5\" />\n\n  <!-- 45° Angle Indicator Arc inside Notch -->\n  <path d=\"M 285,215 A 20 20 0 0 0 315,215\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"1.2\" />\n  <line x1=\"325\" y1=\"222\" x2=\"350\" y2=\"245\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"355\" y=\"248\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"start\">45° V자 홈 (막대 중심까지 파기)</text>\n\n  <!-- Spindle Axis (Ghosted Shaft entering Socket) -->\n  <path d=\"M 286,45 L 314,45 L 314,175 L 300,205 L 286,175 Z\" fill=\"#242424\" fill-opacity=\"0.85\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n  <line x1=\"293\" y1=\"55\" x2=\"293\" y2=\"170\" stroke=\"#444444\" stroke-width=\"1\" />\n  <line x1=\"307\" y1=\"55\" x2=\"307\" y2=\"170\" stroke=\"#444444\" stroke-width=\"1\" />\n\n  <!-- Spindle Dimension lines (Ø 20mm) -->\n  <line x1=\"270\" y1=\"75\" x2=\"286\" y2=\"75\" stroke=\"#888888\" stroke-width=\"1\" marker-end=\"url(#arrow-white)\" />\n  <line x1=\"330\" y1=\"75\" x2=\"314\" y2=\"75\" stroke=\"#888888\" stroke-width=\"1\" marker-end=\"url(#arrow-white)\" />\n  <text x=\"340\" y=\"79\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">두께 2cm 가운데 회전 막대</text>\n\n  <!-- Hearth Board Thickness Dimension: 15~20mm -->\n  <line x1=\"65\" y1=\"230\" x2=\"65\" y2=\"265\" stroke=\"#888888\" stroke-width=\"1\" />\n  <line x1=\"60\" y1=\"230\" x2=\"70\" y2=\"230\" stroke=\"#888888\" stroke-width=\"1\" />\n  <line x1=\"60\" y1=\"265\" x2=\"70\" y2=\"265\" stroke=\"#888888\" stroke-width=\"1\" />\n  <text x=\"20\" y=\"282\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" text-anchor=\"start\">판 두께: 1.5~2cm</text>\n\n  <!-- Hearth Board label -->\n  <text x=\"130\" y=\"215\" fill=\"#AAAAAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">바닥 받침 나무</text>\n\n  <!-- Notch Apex / Center Seating Pointer -->\n  <line x1=\"160\" y1=\"155\" x2=\"295\" y2=\"203\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" marker-end=\"url(#arrow-white)\" />\n  <text x=\"110\" y=\"150\" fill=\"#CCCCCC\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">V자 홈 끝점 (구멍 한가운데와 일치)</text>\n\n  <!-- Rule Callout Box -->\n  <rect x=\"25\" y=\"25\" width=\"255\" height=\"44\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"42\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">핵심 준비 포인트:</text>\n  <text x=\"35\" y=\"58\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">V자 홈 끝이 막대 중심에 딱 닿아야 함</text>\n\n  <!-- Carbon Dust Accumulation Zone (Under Notch Opening) -->\n  <ellipse cx=\"300\" cy=\"278\" rx=\"35\" ry=\"8\" fill=\"#E02424\" fill-opacity=\"0.2\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <line x1=\"300\" y1=\"286\" x2=\"300\" y2=\"310\" stroke=\"#E02424\" stroke-width=\"1\" />\n  <text x=\"300\" y=\"322\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"middle\">까만 불씨 가루가 모이는 자리</text>\n</svg>\n","content/svgs/02-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Grid borders -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\"/>\n\n  <!-- Hand Socket Block (Top Pressure Block) -->\n  <path d=\"M 285 25 L 375 25 L 390 55 L 270 55 Z\" fill=\"#222222\" stroke=\"#CCCCCC\" stroke-width=\"1.5\"/>\n  <text x=\"330\" y=\"42\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" text-anchor=\"middle\">손잡이 누름판</text>\n\n  <!-- Vertical Force Vector F_down -->\n  <line x1=\"330\" y1=\"12\" x2=\"330\" y2=\"25\" stroke=\"#E02424\" stroke-width=\"2.5\" marker-end=\"url(#arrow-red)\"/>\n  <text x=\"345\" y=\"18\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" font-weight=\"bold\">위에서 체중 실어 누르기 (12~15kg)</text>\n\n  <!-- Spindle Axis (Rotating cylinder) -->\n  <rect x=\"318\" y=\"55\" width=\"24\" height=\"175\" fill=\"#1e1e1e\" stroke=\"#F5F5F5\" stroke-width=\"1.5\"/>\n  \n  <!-- Bow Cord Looped Around Spindle (1 Turn Loop) -->\n  <!-- Bow Stick -->\n  <path d=\"M 60 135 C 180 110, 480 110, 600 135\" fill=\"none\" stroke=\"#888888\" stroke-width=\"6\" stroke-linecap=\"square\"/>\n  <text x=\"110\" y=\"102\" fill=\"#AAAAAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">활대 (길이 65cm 휘어진 나뭇가지)</text>\n\n  <!-- String with Tension & Single Wrap Loop around Spindle -->\n  <path d=\"M 60 135 L 318 140\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <ellipse cx=\"330\" cy=\"142\" rx=\"16\" ry=\"6\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2.5\"/>\n  <path d=\"M 342 144 L 600 135\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n\n  <!-- Horizontal Bow Stroke Sawing Arrows -->\n  <line x1=\"180\" y1=\"160\" x2=\"480\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/>\n  <line x1=\"230\" y1=\"160\" x2=\"190\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"2\" marker-end=\"url(#arrow-white)\"/>\n  <line x1=\"430\" y1=\"160\" x2=\"470\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"2\" marker-end=\"url(#arrow-white)\"/>\n  <text x=\"330\" y=\"175\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"middle\">활대 끝에서 끝까지 길게 당기고 밀기</text>\n\n  <!-- Rotation RPM Velocity Vector -->\n  <path d=\"M 360 85 A 25 15 0 1 1 360 105\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow-red)\"/>\n  <text x=\"385\" y=\"98\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" font-weight=\"bold\">빠르게 양방향 회전</text>\n\n  <!-- Hearth Board Base -->\n  <rect x=\"200\" y=\"230\" width=\"260\" height=\"40\" fill=\"#141414\" stroke=\"#888888\" stroke-width=\"1.5\"/>\n  <text x=\"210\" y=\"254\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">바닥 받침 나무</text>\n\n  <!-- Friction Contact Heat & Smoke Generation Point -->\n  <circle cx=\"330\" cy=\"230\" r=\"5\" fill=\"#E02424\"/>\n  \n  <!-- Thermal Wave / Heat Glow Ring -->\n  <circle cx=\"330\" cy=\"230\" r=\"14\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/>\n  <circle cx=\"330\" cy=\"230\" r=\"24\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"0.8\" stroke-dasharray=\"1,3\"/>\n  \n  <!-- Smoke Stream SVG Paths -->\n  <path d=\"M 326 225 Q 315 210 322 195 T 310 180\" fill=\"none\" stroke=\"#A3A3A3\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n  <path d=\"M 334 225 Q 345 208 338 190 T 350 175\" fill=\"none\" stroke=\"#A3A3A3\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n  <path d=\"M 330 220 Q 330 200 325 185\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n\n  <text x=\"295\" y=\"210\" fill=\"#CCCCCC\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"end\">하얀 연기가 피어오름</text>\n\n  <!-- Technical Specification Box on the right -->\n  <rect x=\"490\" y=\"215\" width=\"170\" height=\"70\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\"/>\n  <text x=\"500\" y=\"232\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">불씨 만드는 핵심:</text>\n  <text x=\"500\" y=\"248\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">마찰 열기: 400°C 이상</text>\n  <text x=\"500\" y=\"262\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">누르는 힘: 약하게 → 세게</text>\n  <text x=\"500\" y=\"276\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">활대 전체 길이를 끝까지 사용</text>\n</svg>\n","content/svgs/02-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n  </defs>\n\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\"/>\n\n  <!-- LEFT SIDE: TINDER NEST & AIRFLOW DYNAMICS -->\n  <!-- Tinder Nest Cup Profile (Bird's nest shape) -->\n  <path d=\"M 60 250 C 90 280, 230 280, 260 250 C 270 210, 240 180, 160 170 C 80 180, 50 210, 60 250 Z\" \n        fill=\"#181818\" stroke=\"#777777\" stroke-width=\"1.5\"/>\n  <!-- Fibers pattern inside nest -->\n  <path d=\"M 70 230 Q 160 255 250 230\" fill=\"none\" stroke=\"#444444\" stroke-width=\"1\"/>\n  <path d=\"M 80 210 Q 160 240 240 210\" fill=\"none\" stroke=\"#444444\" stroke-width=\"1\"/>\n  <path d=\"M 95 195 Q 160 225 225 195\" fill=\"none\" stroke=\"#444444\" stroke-width=\"1\"/>\n\n  <!-- Central Ember Core (Glowing Hot Carbon Coal) -->\n  <ellipse cx=\"160\" cy=\"220\" rx=\"14\" ry=\"10\" fill=\"#E02424\" stroke=\"#FFAA00\" stroke-width=\"1.5\"/>\n  <circle cx=\"160\" cy=\"220\" r=\"4\" fill=\"#FFEE55\"/>\n  <text x=\"160\" y=\"292\" fill=\"#FFAA00\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">달궈진 불씨 덩어리 (450°C)</text>\n\n  <!-- Gentle Air Stream Vectors (Breathing 45-degree angle vectors) -->\n  <path d=\"M 70 120 C 100 130, 120 160, 150 195\" fill=\"none\" stroke=\"#00D4FF\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\" marker-end=\"url(#arrow-white)\"/>\n  <path d=\"M 90 105 C 120 120, 135 155, 158 190\" fill=\"none\" stroke=\"#00D4FF\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\" marker-end=\"url(#arrow-white)\"/>\n  <text x=\"75\" y=\"95\" fill=\"#00D4FF\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">길고 부드럽게 입김 불기</text>\n\n  <!-- Smoke and Flame Transition Emitters -->\n  <path d=\"M 160 195 Q 150 150 170 110 T 165 70\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n  <path d=\"M 170 195 Q 185 145 175 105 T 190 65\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n  \n  <!-- Ignition Flame Burst Outline (Transient stage) -->\n  <path d=\"M 160 160 Q 140 120 160 90 Q 180 120 160 160 Z\" fill=\"#E02424\" fill-opacity=\"0.3\" stroke=\"#E02424\" stroke-width=\"1.5\"/>\n  <text x=\"160\" y=\"55\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">불꽃이 확 피어오름</text>\n\n  <!-- Cupping Angle 45° Spec -->\n  <line x1=\"260\" y1=\"250\" x2=\"310\" y2=\"200\" stroke=\"#888888\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/>\n  <text x=\"275\" y=\"268\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">45도 기울여 들기</text>\n\n  <!-- RIGHT SIDE: TEMPERATURE IGNITION THRESHOLD GRAPH -->\n  <rect x=\"360\" y=\"45\" width=\"295\" height=\"255\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\"/>\n  <text x=\"375\" y=\"68\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">입김 불어 불붙이는 온도 변화</text>\n\n  <!-- Graph Axes -->\n  <line x1=\"410\" y1=\"260\" x2=\"630\" y2=\"260\" stroke=\"#666666\" stroke-width=\"1\"/>\n  <line x1=\"410\" y1=\"260\" x2=\"410\" y2=\"90\" stroke=\"#666666\" stroke-width=\"1\"/>\n\n  <text x=\"630\" y=\"276\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" text-anchor=\"end\">시간 (초)</text>\n  <text x=\"375\" y=\"95\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">온도 (°C)</text>\n\n  <!-- Threshold Line 600°C Flame Point -->\n  <line x1=\"410\" y1=\"125\" x2=\"630\" y2=\"125\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/>\n  <text x=\"415\" y=\"120\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">600°C 불꽃이 타오르는 온도</text>\n\n  <!-- Threshold Line 400°C Ember Point -->\n  <line x1=\"410\" y1=\"185\" x2=\"630\" y2=\"185\" stroke=\"#FFAA00\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/>\n  <text x=\"415\" y=\"180\" fill=\"#FFAA00\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">400°C 불씨가 유지되는 온도</text>\n\n  <!-- Temperature Curve Line -->\n  <path d=\"M 410 255 Q 460 240 500 185 T 570 125 T 620 100\" fill=\"none\" stroke=\"#F5F5F5\" stroke-width=\"2.5\"/>\n  \n  <!-- Key Milestone Dots -->\n  <circle cx=\"500\" cy=\"185\" r=\"4\" fill=\"#FFAA00\"/>\n  <circle cx=\"570\" cy=\"125\" r=\"4\" fill=\"#E02424\"/>\n  \n  <text x=\"505\" y=\"202\" fill=\"#FFAA00\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\">30초 기다린 뒤 옮기기 (0초)</text>\n  <text x=\"650\" y=\"145\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"end\">불꽃 점화 (15~20초)</text>\n</svg>\n","content/svgs/03-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-03 [DEBRIS-HUT-SHELTER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 지면 기준선 -->\n  <line x1=\"40\" y1=\"280\" x2=\"360\" y2=\"280\" stroke=\"#404040\" stroke-width=\"2\"/>\n  <line x1=\"40\" y1=\"285\" x2=\"360\" y2=\"285\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"2 4\"/>\n\n  <!-- 지지 바위 / 밑동 그루터기 (Fork / Boulder) -->\n  <polygon points=\"60,280 80,180 120,180 140,280\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <text x=\"100\" y=\"240\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">STUMP FORK</text>\n\n  <!-- 3m 주 기둥 (Ridge Pole: 지지대 1m 높이에서 지면으로 경사) -->\n  <line x1=\"100\" y1=\"180\" x2=\"340\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n  <line x1=\"100\" y1=\"180\" x2=\"340\" y2=\"280\" stroke=\"#000000\" stroke-width=\"2\" stroke-linecap=\"round\"/>\n\n  <!-- 치수선: 지지 높이 1m -->\n  <line x1=\"50\" y1=\"180\" x2=\"50\" y2=\"280\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M47 185 L50 180 L53 185 M47 275 L50 280 L53 275\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"42\" y=\"235\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\" font-weight=\"bold\">1.0m</text>\n\n  <!-- 치수선: 주 기둥 길이 3m -->\n  <line x1=\"110\" y1=\"165\" x2=\"345\" y2=\"265\" stroke=\"#A3A3A3\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"235\" y=\"205\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">RIDGE POLE (3.0m)</text>\n\n  <!-- 1인 누운 신체 치수 프로파일 (점선) -->\n  <ellipse cx=\"220\" cy=\"270\" rx=\"45\" ry=\"8\" fill=\"none\" stroke=\"#525252\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/>\n  <circle cx=\"165\" cy=\"265\" r=\"7\" fill=\"none\" stroke=\"#525252\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/>\n  <text x=\"210\" y=\"255\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">BODY FIT SPACE</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: RIDGE POLE &amp; STRUCTURAL ANCHOR</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">SECURE 3m HARDWOOD AT 1m CREST TO MINIMIZE INTERNAL AIR VOLUME</text>\n</svg>\n","content/svgs/03-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-03 [DEBRIS-HUT-SHELTER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 지면 기준선 -->\n  <line x1=\"40\" y1=\"280\" x2=\"360\" y2=\"280\" stroke=\"#404040\" stroke-width=\"2\"/>\n\n  <!-- 주 기둥 (중앙) -->\n  <line x1=\"80\" y1=\"160\" x2=\"320\" y2=\"280\" stroke=\"#E5E5E5\" stroke-width=\"5\"/>\n\n  <!-- 좌우 45도 빗살 갈비뼈 잔가지 (Rib Poles) -->\n  <!-- 좌측 날개 -->\n  <line x1=\"110\" y1=\"175\" x2=\"70\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"140\" y1=\"190\" x2=\"105\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"170\" y1=\"205\" x2=\"140\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"200\" y1=\"220\" x2=\"175\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"230\" y1=\"235\" x2=\"210\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"260\" y1=\"250\" x2=\"245\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"290\" y1=\"265\" x2=\"280\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 우측 날개 (원근 입체 표현) -->\n  <line x1=\"110\" y1=\"175\" x2=\"160\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <line x1=\"140\" y1=\"190\" x2=\"195\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <line x1=\"170\" y1=\"205\" x2=\"230\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <line x1=\"200\" y1=\"220\" x2=\"265\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <line x1=\"230\" y1=\"235\" x2=\"300\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n\n  <!-- 가로 엮음 격자망 (Lattice Framework) -->\n  <path d=\"M 65 250 Q 150 200 235 250\" fill=\"none\" stroke=\"#A3A3A3\" stroke-width=\"1.5\"/>\n  <path d=\"M 75 220 Q 130 185 195 220\" fill=\"none\" stroke=\"#A3A3A3\" stroke-width=\"1.5\"/>\n\n  <!-- 45도 각도 호선 인디케이터 -->\n  <path d=\"M 120 280 A 25 25 0 0 1 135 258\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"145\" y=\"270\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">45° SLOPE</text>\n\n  <!-- 간격 표시 (10cm Spacing) -->\n  <line x1=\"70\" y1=\"290\" x2=\"105\" y2=\"290\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <text x=\"87\" y=\"303\" fill=\"#737373\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">&lt; 10cm &gt;</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: 45° RIB SKELETON &amp; LATTICE</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">DENSELY PACK RIBS EVERY 10cm TO PREVENT DEBRIS COLLAPSE</text>\n</svg>\n","content/svgs/03-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-03 [DEBRIS-HUT-SHELTER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 지면 기준선 -->\n  <line x1=\"40\" y1=\"280\" x2=\"360\" y2=\"280\" stroke=\"#404040\" stroke-width=\"2\"/>\n\n  <!-- 1m 외부 낙엽 돔 윤곽선 (Debris Mound) -->\n  <path d=\"M 50 280 Q 90 90 200 90 Q 310 90 350 280 Z\" fill=\"#141414\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <!-- 내부 골조 단면 (점선) -->\n  <path d=\"M 100 280 Q 130 180 200 180 Q 270 180 300 280\" fill=\"#050505\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/>\n\n  <!-- 바닥 40cm 마른 낙엽 단열 매트리스 (Ground Insulation) -->\n  <rect x=\"105\" y=\"245\" width=\"190\" height=\"35\" fill=\"#262626\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <line x1=\"105\" y1=\"262\" x2=\"295\" y2=\"262\" stroke=\"#525252\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  <text x=\"200\" y=\"267\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">40cm GROUND BED [LEAVES]</text>\n\n  <!-- 외벽 1m 두께 치수선 -->\n  <line x1=\"75\" y1=\"180\" x2=\"140\" y2=\"210\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M 78 186 L 75 180 L 82 178 M 133 212 L 140 210 L 137 204\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"100\" y=\"188\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"11\" font-weight=\"black\">1.0m THICK</text>\n\n  <!-- 외벽 솔잎 비늘 빗물 유도 층 (Thatch / Pine Shingles) -->\n  <path d=\"M 120 120 L 110 135 M 140 105 L 130 120 M 260 105 L 270 120 M 280 120 L 290 135\" stroke=\"#A3A3A3\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"115\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">WATER-SHEDDING PINE THATCH</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: 1m DEBRIS MOUND &amp; 40cm BED</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">NEVER SLEEP ON BARE GROUND; PILE LEAVES ARM-DEEP TO SEAL BODY HEAT</text>\n</svg>\n","content/svgs/04-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-04 [PRIMITIVE-STONE-AXE]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 작업대 받침돌 (Anvil Stone) -->\n  <polygon points=\"100,280 140,220 260,220 300,280\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"2\"/>\n  <text x=\"200\" y=\"260\" fill=\"#525252\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">ANVIL STONE</text>\n\n  <!-- 가공할 규암 원석 도끼날 (Quartzite Core) -->\n  <polygon points=\"150,220 180,130 230,130 250,220\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 둥근 망치돌 (Hammerstone) -->\n  <circle cx=\"270\" cy=\"100\" r=\"28\" fill=\"#1A1A1A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <text x=\"270\" y=\"104\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">HAMMER</text>\n\n  <!-- 70도 타격 궤적 벡터 화살표 -->\n  <path d=\"M 255 125 L 215 155\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <polygon points=\"215,155 228,148 221,140\" fill=\"#FFFFFF\"/>\n  <text x=\"260\" y=\"145\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">70° STRIKE</text>\n\n  <!-- 박편 파편 비산 궤적 (Flakes Splitting) -->\n  <polygon points=\"175,145 160,160 170,170\" fill=\"#737373\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <polygon points=\"140,180 120,195 135,205\" fill=\"#737373\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <line x1=\"180\" y1=\"150\" x2=\"130\" y2=\"190\" stroke=\"#737373\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  <text x=\"110\" y=\"175\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\">CHIPPED FLAKES</text>\n\n  <!-- 양날 각도 표시 -->\n  <path d=\"M 180 130 L 165 110 M 230 130 L 245 110\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  <text x=\"205\" y=\"115\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">BIFACIAL BEVEL</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: 70° HAMMERSTONE PERCUSSION FLAKING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">STRIKE QUARTZITE RIM AT 70° TO DETACH RAZOR SHARP BIFACIAL FLAKES</text>\n</svg>\n","content/svgs/04-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-04 [PRIMITIVE-STONE-AXE]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 참나무 Y자 손잡이 (Hardwood Y-Haft) -->\n  <!-- 메인 손잡이 몸체 -->\n  <rect x=\"185\" y=\"160\" width=\"30\" height=\"130\" fill=\"#141414\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <!-- Y자 갈래 좌측/우측 포크 -->\n  <path d=\"M 185 160 Q 170 120 145 90 L 165 80 Q 195 115 200 140 Q 205 115 235 80 L 255 90 Q 230 120 215 160 Z\" fill=\"#1A1A1A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n\n  <!-- 가공된 석기 도끼날 (결합 위치) -->\n  <polygon points=\"120,110 200,60 280,110 230,170 170,170\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <!-- 날 부분 강조선 -->\n  <path d=\"M 120 110 L 200 60 L 280 110\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n  <text x=\"200\" y=\"85\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">AXE BLADE</text>\n\n  <!-- 요철 결합 음각 가공 표시 (Notch Fit) -->\n  <line x1=\"170\" y1=\"170\" x2=\"160\" y2=\"190\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <line x1=\"230\" y1=\"170\" x2=\"240\" y2=\"190\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <text x=\"200\" y=\"200\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">FIRE-CARVED MORTISE SEAT</text>\n\n  <!-- 손잡이 규격 치수 -->\n  <line x1=\"225\" y1=\"225\" x2=\"265\" y2=\"225\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <text x=\"270\" y=\"228\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">Ø 3.5cm OAK</text>\n\n  <!-- 압입 방향 화살표 (Downward Force) -->\n  <line x1=\"200\" y1=\"35\" x2=\"200\" y2=\"55\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <polygon points=\"200,55 195,45 205,45\" fill=\"#FFFFFF\"/>\n  <text x=\"200\" y=\"30\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">PRESSURE FIT</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: Y-FORK NOTCH FIT &amp; CHARRED SEAT</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">SLIGHTLY CHAR WOOD INTERIOR TO MOLD NEGATIVE CAVITY EXACTLY TO BLADE</text>\n</svg>\n","content/svgs/04-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-04 [PRIMITIVE-STONE-AXE]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 조립된 도끼 손잡이 및 석기 날 -->\n  <rect x=\"185\" y=\"160\" width=\"30\" height=\"130\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <polygon points=\"130,110 200,60 270,110 225,170 175,170\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 8자형 교차 칡 섬유 바인딩 (Figure-8 Lashings) -->\n  <line x1=\"140\" y1=\"120\" x2=\"230\" y2=\"190\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <line x1=\"145\" y1=\"130\" x2=\"225\" y2=\"200\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <line x1=\"150\" y1=\"140\" x2=\"220\" y2=\"210\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n\n  <line x1=\"260\" y1=\"120\" x2=\"170\" y2=\"190\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <line x1=\"255\" y1=\"130\" x2=\"175\" y2=\"200\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <line x1=\"250\" y1=\"140\" x2=\"180\" y2=\"210\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n\n  <!-- 수평 감기 밴드 (Frapping Turns) -->\n  <rect x=\"175\" y=\"155\" width=\"50\" height=\"25\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/>\n\n  <!-- 송진 + 숯가루 혼합 코팅층 (Black Pine Pitch Cement) -->\n  <path d=\"M 160 145 Q 200 135 240 145 Q 235 215 200 215 Q 165 215 160 145 Z\" fill=\"#0A0A0A\" fill-opacity=\"0.7\" stroke=\"#FFFFFF\" stroke-width=\"1.5\" stroke-dasharray=\"2 3\"/>\n  <text x=\"200\" y=\"235\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"black\">PINE PITCH + CHARCOAL CEMENT</text>\n\n  <!-- 수축 장력 화살표 (Shrinkage Tension) -->\n  <path d=\"M 140 185 L 160 175 M 260 185 L 240 175\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"80\" y=\"190\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\">WET KUDZU SHRINKAGE</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: FIGURE-8 LASHINGS &amp; RESIN SEAL</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">WET FIBERS SHRINK TIGHT LIKE IRON; SEAL WITH CHARCOAL PITCH TO LOCK</text>\n</svg>\n","content/svgs/05-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-05 [EDIBLE-PLANT-TEST]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 절단된 식물 줄기 단면 (Cut Stem) -->\n  <rect x=\"180\" y=\"110\" width=\"40\" height=\"110\" fill=\"#141414\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <ellipse cx=\"200\" cy=\"110\" rx=\"20\" ry=\"8\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 유백색 독성 유즙 방출 (Milky White Sap Drop) -->\n  <path d=\"M 195 118 Q 190 145 200 155 Q 210 145 205 118 Z\" fill=\"#FFFFFF\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  <ellipse cx=\"200\" cy=\"170\" rx=\"12\" ry=\"16\" fill=\"#FFFFFF\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  \n  <!-- 치명적 독성 금지 표식 (Disallowed Cross) -->\n  <circle cx=\"200\" cy=\"170\" r=\"32\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"177\" y1=\"147\" x2=\"223\" y2=\"193\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n  <line x1=\"223\" y1=\"147\" x2=\"177\" y2=\"193\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n\n  <!-- 배제 판별 텍스트 박스 -->\n  <rect x=\"50\" y=\"235\" width=\"300\" height=\"60\" fill=\"#0A0A0A\" stroke=\"#404040\" stroke-width=\"1\"/>\n  <text x=\"65\" y=\"255\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">1. MILKY SAP (LATEX ALKALOIDS) ➔ DISCARD</text>\n  <text x=\"65\" y=\"272\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">2. BITTER ALMOND ODOR (CYANIDE) ➔ DISCARD</text>\n  <text x=\"65\" y=\"287\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"10\">3. FINE STINGING HAIRS ➔ DISCARD</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: IMMEDIATE VISUAL &amp; OLFACTORY EXCLUSION</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">IMMEDIATELY REJECT ANY SPECIMEN WITH MILKY SAP OR ALMOND SCENT</text>\n</svg>\n","content/svgs/05-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-05 [EDIBLE-PLANT-TEST]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 사람 팔 전완부 윤곽선 (Inner Forearm) -->\n  <path d=\"M 60 160 C 120 155 240 150 340 140 L 340 220 C 240 215 120 220 60 210 Z\" fill=\"#141414\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <text x=\"90\" y=\"190\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\">INNER FOREARM</text>\n\n  <!-- 식물 즙 도포 테스트 스팟 (Test Patch) -->\n  <circle cx=\"210\" cy=\"180\" r=\"18\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <circle cx=\"210\" cy=\"180\" r=\"26\" fill=\"none\" stroke=\"#737373\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <!-- 즙 도포 화살표 -->\n  <path d=\"M 210 110 L 210 155\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <polygon points=\"210,155 205,145 215,145\" fill=\"#FFFFFF\"/>\n  <text x=\"210\" y=\"100\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">RUB CRUSHED SAP</text>\n\n  <!-- 15분 경과 스톱워치 다이얼 (15 MIN Stopwatch) -->\n  <circle cx=\"290\" cy=\"180\" r=\"30\" fill=\"#0A0A0A\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <line x1=\"290\" y1=\"180\" x2=\"290\" y2=\"155\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"290\" y1=\"180\" x2=\"315\" y2=\"180\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <path d=\"M 290 155 A 25 25 0 0 1 315 180\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n  <text x=\"290\" y=\"225\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">15 MIN WAIT</text>\n\n  <!-- 이상 반응 감시 체크리스트 -->\n  <rect x=\"50\" y=\"240\" width=\"300\" height=\"55\" fill=\"#0A0A0A\" stroke=\"#404040\" stroke-width=\"1\"/>\n  <text x=\"65\" y=\"260\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">OBSERVE: ERYTHEMA / ITCHING / HIVES</text>\n  <text x=\"65\" y=\"278\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">&gt; IF BURNING SENSATION OCCURS ➔ RINSE IMMEDIATELY</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: DERMAL CONTACT &amp; 15-MINUTE MONITORING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">RUB JUICE ON SENSITIVE INNER ARM; WAIT 15 MIN FOR HISTAMINE REACTION</text>\n</svg>\n","content/svgs/05-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-05 [EDIBLE-PLANT-TEST]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 입술 및 혀 측면 프로파일 도해 (Oral Profile) -->\n  <path d=\"M 120 120 Q 170 120 190 140 Q 210 160 180 180 Q 210 190 190 220 Q 150 230 110 230\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <!-- 혀 (Tongue Extended) -->\n  <path d=\"M 175 175 C 220 170 250 185 240 200 C 220 210 185 200 175 195\" fill=\"#1F1F1F\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <text x=\"210\" y=\"195\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" font-weight=\"bold\">TONGUE TIP</text>\n\n  <!-- 식물 잎 미세 조각 안치 (Specimen Fragment) -->\n  <polygon points=\"245,185 260,180 255,195 240,195\" fill=\"#FFFFFF\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  <line x1=\"260\" y1=\"160\" x2=\"252\" y2=\"182\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <text x=\"265\" y=\"155\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" font-weight=\"bold\">LEAF PIECE (15 MIN)</text>\n\n  <!-- 침 삼킴 금지 경고 배지 (DO NOT SWALLOW) -->\n  <rect x=\"220\" y=\"80\" width=\"130\" height=\"40\" fill=\"#121212\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <text x=\"285\" y=\"98\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"black\">DO NOT SWALLOW</text>\n  <text x=\"285\" y=\"112\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">HOLD SALIVA IN MOUTH</text>\n\n  <!-- 단계별 시간 프로토콜 -->\n  <rect x=\"50\" y=\"240\" width=\"300\" height=\"55\" fill=\"#0A0A0A\" stroke=\"#404040\" stroke-width=\"1\"/>\n  <text x=\"65\" y=\"258\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">STEP A: OUTER LIP CONTACT ➔ 3 MINUTES</text>\n  <text x=\"65\" y=\"275\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">STEP B: TONGUE TIP CONTACT ➔ 15 MINUTES</text>\n  <text x=\"65\" y=\"290\" fill=\"#737373\" font-family=\"monospace\" font-size=\"8\">&gt; IF NUMBNESS OR BITTERNESS ➔ SPIT &amp; RINSE x3</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: LIP &amp; TONGUE TIP PROGRESSIVE CHECK</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">NEVER CHEW OR SWALLOW; DETECT NUMBNESS BEFORE ANY INGESTION</text>\n</svg>\n","content/svgs/06-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-06 [SOLAR-STILL-WATER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 지표면 선 -->\n  <line x1=\"40\" y1=\"180\" x2=\"360\" y2=\"180\" stroke=\"#404040\" stroke-width=\"2\"/>\n  <text x=\"50\" y=\"170\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">GROUND LEVEL</text>\n\n  <!-- 깔때기형 원형 웅덩이 단면 (Pit Excavation) -->\n  <path d=\"M 80 180 Q 140 280 200 280 Q 260 280 320 180\" fill=\"#121212\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 직경 1.0m 치수선 -->\n  <line x1=\"80\" y1=\"160\" x2=\"320\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M 85 155 L 80 160 L 85 165 M 315 155 L 320 160 L 315 165\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"152\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"bold\">DIAMETER 1.0m</text>\n\n  <!-- 깊이 50cm 치수선 -->\n  <line x1=\"340\" y1=\"180\" x2=\"340\" y2=\"280\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M 335 185 L 340 180 L 345 185 M 335 275 L 340 280 L 345 275\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"235\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">0.5m</text>\n\n  <!-- 바닥 중앙 토기 안착 홈 (Pot Hollow) -->\n  <rect x=\"180\" y=\"275\" width=\"40\" height=\"15\" fill=\"#262626\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <text x=\"200\" y=\"298\" fill=\"#737373\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">POT HOLLOW</text>\n\n  <!-- 경사벽 생 잎사귀 충진 (Transpiration Foliage) -->\n  <circle cx=\"120\" cy=\"210\" r=\"12\" fill=\"#1C1C1C\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <circle cx=\"150\" cy=\"245\" r=\"10\" fill=\"#1C1C1C\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <circle cx=\"280\" cy=\"210\" r=\"12\" fill=\"#1C1C1C\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <circle cx=\"250\" cy=\"245\" r=\"10\" fill=\"#1C1C1C\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <text x=\"135\" y=\"230\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"8\">NON-TOXIC LEAVES (2x YIELD)</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: 1m CONICAL PIT &amp; FOLIAGE PACK</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">DIG 1m x 0.5m PIT IN SUNNY GROUND; PACK WITH EDIBLE LEAVES FOR TRANSPIRATION</text>\n</svg>\n","content/svgs/06-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-06 [SOLAR-STILL-WATER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 지표면 및 웅덩이 -->\n  <line x1=\"40\" y1=\"180\" x2=\"80\" y2=\"180\" stroke=\"#404040\" stroke-width=\"2\"/>\n  <line x1=\"320\" y1=\"180\" x2=\"360\" y2=\"180\" stroke=\"#404040\" stroke-width=\"2\"/>\n  <path d=\"M 80 180 Q 140 280 200 280 Q 260 280 320 180\" fill=\"#121212\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n\n  <!-- 중앙 수거 토기 (Clay Collection Pot) -->\n  <rect x=\"180\" y=\"225\" width=\"40\" height=\"45\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <ellipse cx=\"200\" cy=\"225\" rx=\"20\" ry=\"6\" fill=\"#141414\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"252\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">COLLECTION POT</text>\n\n  <!-- 상단 수평 밀폐 시트 (Tarp / Large Leaf Membrane) -->\n  <line x1=\"60\" y1=\"180\" x2=\"340\" y2=\"180\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 양 끝단 흙/모래 밀폐 둑 (Dirt/Sand Seal Bank) -->\n  <polygon points=\"50,180 85,150 110,180\" fill=\"#262626\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <polygon points=\"290,180 315,150 350,180\" fill=\"#262626\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"80\" y=\"145\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">SOIL SEAL</text>\n  <text x=\"320\" y=\"145\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">AIR-TIGHT</text>\n\n  <!-- 밀폐 압력 및 온도 상승 인디케이터 (55°C Greenhouse) -->\n  <rect x=\"140\" y=\"90\" width=\"120\" height=\"35\" fill=\"#0A0A0A\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  <text x=\"200\" y=\"105\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">INTERNAL TEMP &gt; 55°C</text>\n  <text x=\"200\" y=\"118\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">SATURATED VAPOR PRESSURE</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: POT CENTERED &amp; PERIMETER AIRTIGHT SEAL</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">ANCHOR EDGES WITH WET SOIL; COMPLETE SEAL REQUIRED FOR 55°C VAPORIZATION</text>\n</svg>\n","content/svgs/06-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-06 [SOLAR-STILL-WATER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 웅덩이 단면 -->\n  <path d=\"M 80 160 Q 140 280 200 280 Q 260 280 320 160\" fill=\"#121212\" stroke=\"#404040\" stroke-width=\"1.5\"/>\n\n  <!-- 중앙 수거 토기 (Clay Pot) -->\n  <rect x=\"180\" y=\"230\" width=\"40\" height=\"40\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <!-- 모인 순수 증류수 수면 -->\n  <rect x=\"182\" y=\"250\" width=\"36\" height=\"18\" fill=\"#FFFFFF\" fill-opacity=\"0.8\"/>\n  <text x=\"200\" y=\"263\" fill=\"#000000\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"bold\">PURE H2O</text>\n\n  <!-- 역원뿔 형태로 처진 덮개 시트 (Inverted Cone Sheet) -->\n  <path d=\"M 70 160 L 200 210 L 330 160\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n\n  <!-- 중앙 중심 추 (Weight Stone) -->\n  <ellipse cx=\"200\" cy=\"207\" rx=\"14\" ry=\"7\" fill=\"#1A1A1A\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <text x=\"200\" y=\"195\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">STONE WEIGHT</text>\n\n  <!-- 간격 확인 (5cm Clearance) -->\n  <line x1=\"225\" y1=\"210\" x2=\"225\" y2=\"230\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"240\" y=\"222\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"8\">&gt; 5cm GAP</text>\n\n  <!-- 시트 하단 수증기 응결 및 낙하 물방울 (Condensation Droplets) -->\n  <circle cx=\"150\" cy=\"180\" r=\"3\" fill=\"#FFFFFF\"/>\n  <circle cx=\"175\" cy=\"195\" r=\"3.5\" fill=\"#FFFFFF\"/>\n  <circle cx=\"250\" cy=\"180\" r=\"3\" fill=\"#FFFFFF\"/>\n  <circle cx=\"225\" cy=\"195\" r=\"3.5\" fill=\"#FFFFFF\"/>\n  \n  <!-- 중앙 낙하 궤적 (Dripping Line) -->\n  <line x1=\"200\" y1=\"215\" x2=\"200\" y2=\"245\" stroke=\"#FFFFFF\" stroke-width=\"2\" stroke-dasharray=\"2 3\"/>\n  <polygon points=\"200,248 197,242 203,242\" fill=\"#FFFFFF\"/>\n  <text x=\"145\" y=\"228\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\">STERILE CONDENSATE</text>\n\n  <!-- 태양열 복사 화살표 (Solar Radiation Vectors) -->\n  <line x1=\"120\" y1=\"80\" x2=\"140\" y2=\"120\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <line x1=\"200\" y1=\"70\" x2=\"200\" y2=\"115\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <line x1=\"280\" y1=\"80\" x2=\"260\" y2=\"120\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"65\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">SOLAR THERMAL FLUX</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: INVERTED CONE CONDENSATION DRIP</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">STONE DRIVES CONDENSED DROPLETS TO INCLINE PEAK; DRIPS 100% STERILE WATER</text>\n</svg>\n","content/svgs/07-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-07 [PINE-RESIN-OINTMENT]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 소나무 수피 단면 (Pine Bark Trunk) -->\n  <rect x=\"60\" y=\"90\" width=\"70\" height=\"190\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <!-- 소나무 상처 및 송진 덩어리 (Resin Globules) -->\n  <polygon points=\"130,130 110,145 130,160\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"1\"/>\n  <ellipse cx=\"132\" cy=\"175\" rx=\"8\" ry=\"14\" fill=\"#FFFFFF\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"75\" y=\"145\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\">PINE TRUNK</text>\n\n  <!-- 긁어모으는 석기 스크레이퍼 -->\n  <polygon points=\"165,150 145,170 155,180\" fill=\"#E5E5E5\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <path d=\"M 160 160 L 140 175\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <polygon points=\"140,175 145,168 148,175\" fill=\"#FFFFFF\"/>\n  <text x=\"175\" y=\"165\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\">SCRAPE RAW RESIN</text>\n\n  <!-- 오목한 조리 편평석 (Concave Hearth Stone) -->\n  <path d=\"M 210 210 Q 280 250 350 210 L 330 260 Q 280 270 230 260 Z\" fill=\"#1A1A1A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <!-- 녹은 액상 송진 웅덩이 -->\n  <ellipse cx=\"280\" cy=\"225\" rx=\"45\" ry=\"12\" fill=\"#FFFFFF\" fill-opacity=\"0.9\"/>\n  <text x=\"280\" y=\"228\" fill=\"#000000\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">LIQUID RESIN (MELTED)</text>\n\n  <!-- 하부 숯불 간접열 (Charcoal Indirect Heat) -->\n  <circle cx=\"250\" cy=\"280\" r=\"8\" fill=\"#404040\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <circle cx=\"280\" cy=\"285\" r=\"9\" fill=\"#404040\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <circle cx=\"310\" cy=\"280\" r=\"8\" fill=\"#404040\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <path d=\"M 280 275 L 280 250\" stroke=\"#FFFFFF\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/>\n  <text x=\"280\" y=\"302\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">INDIRECT COAL HEAT (NO DIRECT FLAME)</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: RESIN HARVEST &amp; GENTLE INDIRECT MELTING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">SCRAPE HARD AMBER RESIN; MELT GENTLY OVER COALS AWAY FROM OPEN FIRE</text>\n</svg>\n","content/svgs/07-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-07 [PINE-RESIN-OINTMENT]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 조약돌 조제 보울 (Stone Mortar Bowl) -->\n  <ellipse cx=\"200\" cy=\"180\" rx=\"90\" ry=\"35\" fill=\"#1A1A1A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <ellipse cx=\"200\" cy=\"180\" rx=\"75\" ry=\"25\" fill=\"#0F0F0F\" stroke=\"#737373\" stroke-width=\"1\"/>\n\n  <!-- 3:1 혼합 비율 인디케이터 (3:1 Ratio) -->\n  <rect x=\"140\" y=\"80\" width=\"120\" height=\"40\" fill=\"#0A0A0A\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"98\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"black\">RATIO 3 : 1</text>\n  <text x=\"200\" y=\"112\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">RESIN (3) + STERILE CHARCOAL (1)</text>\n\n  <!-- 숯가루 살포 투입 궤적 (Charcoal Powder Dusting) -->\n  <circle cx=\"160\" cy=\"140\" r=\"2.5\" fill=\"#FFFFFF\"/>\n  <circle cx=\"170\" cy=\"148\" r=\"2\" fill=\"#FFFFFF\"/>\n  <circle cx=\"190\" cy=\"142\" r=\"3\" fill=\"#FFFFFF\"/>\n  <circle cx=\"210\" cy=\"145\" r=\"2\" fill=\"#FFFFFF\"/>\n  <circle cx=\"230\" cy=\"140\" r=\"2.5\" fill=\"#FFFFFF\"/>\n  <line x1=\"200\" y1=\"125\" x2=\"200\" y2=\"155\" stroke=\"#FFFFFF\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/>\n\n  <!-- 혼합 교반 스틱 (Wooden Stirring Paddle) -->\n  <line x1=\"260\" y1=\"110\" x2=\"210\" y2=\"185\" stroke=\"#E5E5E5\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n  <!-- 회전 교반 화살표 (Vigorous Stirring) -->\n  <path d=\"M 175 185 A 25 10 0 1 0 225 185\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <polygon points=\"225,181 231,188 223,191\" fill=\"#FFFFFF\"/>\n\n  <!-- 연고 경화 텍스처 박스 -->\n  <rect x=\"50\" y=\"240\" width=\"300\" height=\"55\" fill=\"#0A0A0A\" stroke=\"#404040\" stroke-width=\"1\"/>\n  <text x=\"65\" y=\"260\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">ANTISEPTIC: TERPENES + ACTIVATED CARBON</text>\n  <text x=\"65\" y=\"278\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">&gt; BINDS BACTERIA &amp; COATS AGAINST ANAEROBIC TETANUS</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: 3:1 STERILE CHARCOAL BLEND &amp; SALVE COMPOUNDING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">STIR CRUSHED CHARCOAL INTO WARM RESIN UNTIL IT FORMS A PLIABLE BLACK SALVE</text>\n</svg>\n","content/svgs/07-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-07 [PINE-RESIN-OINTMENT]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 팔뚝 환부 단면 (Wounded Arm Section) -->\n  <rect x=\"60\" y=\"160\" width=\"280\" height=\"60\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n\n  <!-- 상처 열상 부위 (Laceration Wound) -->\n  <line x1=\"160\" y1=\"160\" x2=\"240\" y2=\"160\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n  <line x1=\"180\" y1=\"155\" x2=\"220\" y2=\"165\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n\n  <!-- 두꺼운 송진 연고 도포층 (Thick Ointment Seal, 40°C Warm) -->\n  <path d=\"M 140 160 Q 200 140 260 160\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"4\"/>\n  <text x=\"200\" y=\"132\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">WARM SALVE SEAL (40°C)</text>\n\n  <!-- 멸균 자작나무 껍질 붕대 감기 (Birch Bark Wrap Bandage) -->\n  <path d=\"M 120 150 L 150 230 M 160 150 L 190 230 M 210 150 L 240 230 M 250 150 L 280 230\" stroke=\"#E5E5E5\" stroke-width=\"3\"/>\n  <text x=\"200\" y=\"250\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">BIRCH BARK BANDAGE COMPRESSION</text>\n\n  <!-- 100% 방수 및 혐기성 차단 배지 -->\n  <rect x=\"50\" y=\"80\" width=\"300\" height=\"35\" fill=\"#0A0A0A\" stroke=\"#FFFFFF\" stroke-width=\"1\"/>\n  <text x=\"200\" y=\"95\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">WATERPROOF + ANTIMICROBIAL BARRIER</text>\n  <text x=\"200\" y=\"107\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">CLEAN WITH BOILED WATER BEFORE APPLICATION</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: WARM APPLICATION &amp; BIRCH BARK DRESSING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">COOL TO BODY TEMP (~40°C); APPLY THICK LAYER AND BIND TO HALT SEPSIS</text>\n</svg>\n","content/svgs/pr01-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <!-- Background & Frame Gradients -->\n    <linearGradient id=\"bgGrad1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0d0d0d\"/>\n      <stop offset=\"100%\" stop-color=\"#141414\"/>\n    </linearGradient>\n    <linearGradient id=\"woodTripod\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#4a3728\"/>\n      <stop offset=\"50%\" stop-color=\"#73543d\"/>\n      <stop offset=\"100%\" stop-color=\"#3b2b1f\"/>\n    </linearGradient>\n    <linearGradient id=\"cylinderGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#2a2a2a\" stop-opacity=\"0.8\"/>\n      <stop offset=\"30%\" stop-color=\"#404040\" stop-opacity=\"0.2\"/>\n      <stop offset=\"70%\" stop-color=\"#404040\" stop-opacity=\"0.2\"/>\n      <stop offset=\"100%\" stop-color=\"#222222\" stop-opacity=\"0.8\"/>\n    </linearGradient>\n\n    <!-- Filter Layers Gradients -->\n    <linearGradient id=\"muddyWater\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#5c4028\"/>\n      <stop offset=\"100%\" stop-color=\"#422e1c\"/>\n    </linearGradient>\n    <linearGradient id=\"pebbleGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#6e6e6e\"/>\n      <stop offset=\"50%\" stop-color=\"#4f4f4f\"/>\n      <stop offset=\"100%\" stop-color=\"#383838\"/>\n    </linearGradient>\n    <linearGradient id=\"coarseSand\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#998059\"/>\n      <stop offset=\"100%\" stop-color=\"#7a6341\"/>\n    </linearGradient>\n    <linearGradient id=\"fineSand\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#c9ad7d\"/>\n      <stop offset=\"100%\" stop-color=\"#ad9162\"/>\n    </linearGradient>\n    <linearGradient id=\"charcoalGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#222222\"/>\n      <stop offset=\"50%\" stop-color=\"#141414\"/>\n      <stop offset=\"100%\" stop-color=\"#0a0a0a\"/>\n    </linearGradient>\n    <linearGradient id=\"fiberGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#8a7e6b\"/>\n      <stop offset=\"100%\" stop-color=\"#635847\"/>\n    </linearGradient>\n\n    <!-- Purified Water Gradient & Glow -->\n    <linearGradient id=\"pureWater\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\"/>\n      <stop offset=\"50%\" stop-color=\"#0284c7\"/>\n      <stop offset=\"100%\" stop-color=\"#0369a1\"/>\n    </linearGradient>\n    <radialGradient id=\"dropletGlow\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#bae6fd\" stop-opacity=\"0.9\"/>\n      <stop offset=\"60%\" stop-color=\"#38bdf8\" stop-opacity=\"0.6\"/>\n      <stop offset=\"100%\" stop-color=\"#0284c7\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <radialGradient id=\"waterSurface\" cx=\"50%\" cy=\"30%\" r=\"70%\">\n      <stop offset=\"0%\" stop-color=\"#7dd3fc\" stop-opacity=\"0.8\"/>\n      <stop offset=\"100%\" stop-color=\"#0369a1\" stop-opacity=\"0.9\"/>\n    </radialGradient>\n\n    <!-- Technical Drop Shadow -->\n    <filter id=\"subtleShadow\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"6\" flood-color=\"#000000\" flood-opacity=\"0.7\"/>\n    </filter>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad1)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshair Registration Markers -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Technical Watermark / Metadata -->\n  <text x=\"35\" y=\"60\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"74\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: 5-TIER STRATIFIED PURIFIER [100% SPEC]</text>\n  <text x=\"765\" y=\"60\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">FLOW RATE: 1.5L / HR</text>\n\n  <!-- Tripod Legs (Behind Cylinder) -->\n  <g id=\"tripod\">\n    <!-- Back Leg -->\n    <polygon points=\"398,50 402,50 435,390 425,390\" fill=\"#3b2b1f\" stroke=\"#261b13\" stroke-width=\"1\"/>\n    <!-- Left Leg -->\n    <polygon points=\"396,50 400,50 280,395 270,395\" fill=\"url(#woodTripod)\" stroke=\"#261b13\" stroke-width=\"1\"/>\n    <!-- Right Leg -->\n    <polygon points=\"400,50 404,50 530,395 520,395\" fill=\"url(#woodTripod)\" stroke=\"#261b13\" stroke-width=\"1\"/>\n    <!-- Lashing at Apex -->\n    <ellipse cx=\"400\" cy=\"56\" rx=\"14\" ry=\"7\" fill=\"#695138\" stroke=\"#3b2b1f\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"400\" cy=\"62\" rx=\"13\" ry=\"6\" fill=\"#54402c\" stroke=\"#3b2b1f\" stroke-width=\"1.5\"/>\n  </g>\n\n  <!-- Filter Funnel Housing (Glass/PET/Clay Cutaway) -->\n  <g id=\"filterHousing\" filter=\"url(#subtleShadow)\">\n    <!-- Outer Cylinder Wall -->\n    <path d=\"M 340 90 L 460 90 L 440 270 L 415 310 L 415 330 L 385 330 L 385 310 L 360 270 Z\" fill=\"url(#cylinderGrad)\" stroke=\"#4a4a4a\" stroke-width=\"2\"/>\n\n    <!-- Layer 0: Raw Muddy Water (Top Level) -->\n    <polygon points=\"342,92 458,92 454,120 346,120\" fill=\"url(#muddyWater)\"/>\n    <ellipse cx=\"400\" cy=\"92\" rx=\"58\" ry=\"6\" fill=\"#6e4f33\" stroke=\"#8c6643\" stroke-width=\"1\"/>\n    <!-- Floating particulates in muddy water -->\n    <circle cx=\"370\" cy=\"105\" r=\"1.5\" fill=\"#382617\"/>\n    <circle cx=\"420\" cy=\"102\" r=\"2\" fill=\"#2b1d11\"/>\n    <circle cx=\"395\" cy=\"112\" r=\"1.8\" fill=\"#3d2817\"/>\n\n    <!-- Layer 1: Pebbles & Coarse Gravel -->\n    <polygon points=\"346,120 454,120 450,155 350,155\" fill=\"url(#pebbleGrad)\"/>\n    <!-- Illustrated round pebbles -->\n    <ellipse cx=\"365\" cy=\"130\" rx=\"9\" ry=\"6\" fill=\"#888\" stroke=\"#444\"/>\n    <ellipse cx=\"385\" cy=\"128\" rx=\"8\" ry=\"5\" fill=\"#666\" stroke=\"#333\"/>\n    <ellipse cx=\"405\" cy=\"132\" rx=\"10\" ry=\"7\" fill=\"#777\" stroke=\"#444\"/>\n    <ellipse cx=\"428\" cy=\"129\" rx=\"9\" ry=\"6\" fill=\"#555\" stroke=\"#333\"/>\n    <ellipse cx=\"442\" cy=\"133\" rx=\"7\" ry=\"5\" fill=\"#777\" stroke=\"#444\"/>\n    <ellipse cx=\"355\" cy=\"144\" rx=\"8\" ry=\"6\" fill=\"#666\" stroke=\"#333\"/>\n    <ellipse cx=\"378\" cy=\"145\" rx=\"10\" ry=\"7\" fill=\"#777\" stroke=\"#444\"/>\n    <ellipse cx=\"400\" cy=\"144\" rx=\"9\" ry=\"6\" fill=\"#555\" stroke=\"#333\"/>\n    <ellipse cx=\"422\" cy=\"146\" rx=\"8\" ry=\"5\" fill=\"#888\" stroke=\"#444\"/>\n    <ellipse cx=\"440\" cy=\"145\" rx=\"7\" ry=\"5\" fill=\"#666\" stroke=\"#333\"/>\n\n    <!-- Layer 2: Coarse River Sand -->\n    <polygon points=\"350,155 450,155 446,190 354,190\" fill=\"url(#coarseSand)\"/>\n    <!-- Sand speckles -->\n    <line x1=\"358\" y1=\"172\" x2=\"442\" y2=\"172\" stroke=\"#665235\" stroke-dasharray=\"2 3\" stroke-width=\"1\"/>\n    <line x1=\"360\" y1=\"180\" x2=\"440\" y2=\"180\" stroke=\"#665235\" stroke-dasharray=\"3 4\" stroke-width=\"1\"/>\n\n    <!-- Layer 3: Fine Silica Sand -->\n    <polygon points=\"354,190 446,190 442,225 358,225\" fill=\"url(#fineSand)\"/>\n    <line x1=\"362\" y1=\"205\" x2=\"438\" y2=\"205\" stroke=\"#8f764d\" stroke-dasharray=\"1 2\" stroke-width=\"0.8\"/>\n    <line x1=\"364\" y1=\"215\" x2=\"436\" y2=\"215\" stroke=\"#8f764d\" stroke-dasharray=\"2 2\" stroke-width=\"0.8\"/>\n\n    <!-- Layer 4: Activated Crushed Charcoal -->\n    <polygon points=\"358,225 442,225 438,265 362,265\" fill=\"url(#charcoalGrad)\"/>\n    <!-- Charcoal granular facets -->\n    <polygon points=\"370,235 382,232 380,245 368,242\" fill=\"#333\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"392,238 406,234 404,248 390,246\" fill=\"#2a2a2a\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"418,235 430,233 428,245 415,244\" fill=\"#333\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"375,250 388,248 386,260 373,258\" fill=\"#2a2a2a\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"398,252 412,249 410,262 396,260\" fill=\"#383838\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"420,250 432,248 430,260 418,258\" fill=\"#222\" stroke=\"#111\" stroke-width=\"0.8\"/>\n\n    <!-- Layer 5: Cloth / Fiber Filter Plug -->\n    <polygon points=\"362,265 438,265 415,310 385,310\" fill=\"url(#fiberGrad)\"/>\n    <path d=\"M 370 275 Q 400 285 430 275 M 378 290 Q 400 300 422 290\" stroke=\"#473f32\" stroke-width=\"1.2\" fill=\"none\"/>\n\n    <!-- Spout Opening & Perforations -->\n    <rect x=\"385\" y=\"310\" width=\"30\" height=\"20\" fill=\"#1f1f1f\" stroke=\"#444\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Flowing Purified Water & Droplet Dynamics -->\n  <g id=\"purifiedDrop\">\n    <!-- Stream Line -->\n    <line x1=\"400\" y1=\"330\" x2=\"400\" y2=\"348\" stroke=\"#38bdf8\" stroke-width=\"2.5\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n    <!-- Clear Droplet with Radial Glow -->\n    <ellipse cx=\"400\" cy=\"358\" rx=\"6\" ry=\"10\" fill=\"url(#dropletGlow)\"/>\n    <path d=\"M 400 350 C 397 355 395 358 395 362 C 395 365 397 367 400 367 C 403 367 405 365 405 362 C 405 358 403 355 400 350 Z\" fill=\"url(#pureWater)\"/>\n    <circle cx=\"398\" cy=\"360\" r=\"1.5\" fill=\"#ffffff\" opacity=\"0.9\"/>\n  </g>\n\n  <!-- Collection Pot / Water Receptacle -->\n  <g id=\"collectionPot\" filter=\"url(#subtleShadow)\">\n    <!-- Pot Body -->\n    <path d=\"M 330 375 C 330 370 345 365 400 365 C 455 365 470 370 470 375 L 458 420 C 458 428 435 432 400 432 C 365 432 342 428 342 420 Z\" fill=\"#24211d\" stroke=\"#3d3730\" stroke-width=\"2\"/>\n    <!-- Water Level Inside Pot -->\n    <ellipse cx=\"400\" cy=\"385\" rx=\"60\" ry=\"10\" fill=\"url(#waterSurface)\"/>\n    <!-- Water Ripple Circles from Droplet Impact -->\n    <ellipse cx=\"400\" cy=\"385\" rx=\"14\" ry=\"3.5\" fill=\"none\" stroke=\"#bae6fd\" stroke-width=\"1.2\" opacity=\"0.8\"/>\n    <ellipse cx=\"400\" cy=\"385\" rx=\"28\" ry=\"6\" fill=\"none\" stroke=\"#7dd3fc\" stroke-width=\"1\" opacity=\"0.6\"/>\n    <ellipse cx=\"400\" cy=\"385\" rx=\"42\" ry=\"8\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"0.8\" opacity=\"0.4\"/>\n  </g>\n\n  <!-- Technical Callout Leader Lines & Labels (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Pebbles -->\n    <line x1=\"435\" y1=\"135\" x2=\"550\" y2=\"135\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"435\" cy=\"135\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"560\" y=\"132\" fill=\"#ffffff\" font-weight=\"bold\">STAGE 1: RIVER PEBBLES</text>\n    <text x=\"560\" y=\"145\" fill=\"#888888\">낙엽·벌레 등 대형 부유물 1차 차단</text>\n\n    <!-- Callout 2: Coarse Sand -->\n    <line x1=\"430\" y1=\"172\" x2=\"550\" y2=\"172\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"430\" cy=\"172\" r=\"2\" fill=\"#666\"/>\n    <text x=\"560\" y=\"169\" fill=\"#ffffff\" font-weight=\"bold\">STAGE 2: COARSE SAND</text>\n    <text x=\"560\" y=\"182\" fill=\"#888888\">굵은 흙 입자 및 모래 부유물 침전</text>\n\n    <!-- Callout 3: Fine Silica Sand -->\n    <line x1=\"425\" y1=\"208\" x2=\"550\" y2=\"208\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"425\" cy=\"208\" r=\"2\" fill=\"#666\"/>\n    <text x=\"560\" y=\"205\" fill=\"#ffffff\" font-weight=\"bold\">STAGE 3: FINE SILICA SAND</text>\n    <text x=\"560\" y=\"218\" fill=\"#888888\">미세 진흙 입자 및 미세 탁도 여과</text>\n\n    <!-- Callout 4: Charcoal -->\n    <line x1=\"420\" y1=\"245\" x2=\"550\" y2=\"245\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"420\" cy=\"245\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"560\" y=\"242\" fill=\"#E02424\" font-weight=\"bold\">STAGE 4: ACTIVATED CHARCOAL</text>\n    <text x=\"560\" y=\"255\" fill=\"#888888\">미세 구멍으로 독소·냄새·유기물 흡착</text>\n\n    <!-- Callout 5: Fiber Plug -->\n    <line x1=\"410\" y1=\"288\" x2=\"550\" y2=\"288\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"410\" cy=\"288\" r=\"2\" fill=\"#666\"/>\n    <text x=\"560\" y=\"285\" fill=\"#ffffff\" font-weight=\"bold\">STAGE 5: FIBER FILTER PLUG</text>\n    <text x=\"560\" y=\"298\" fill=\"#888888\">숯가루 유출 방지 및 최종 유속 조절</text>\n\n    <!-- Callout 6: Potable Water -->\n    <line x1=\"440\" y1=\"390\" x2=\"550\" y2=\"390\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"440\" cy=\"390\" r=\"2\" fill=\"#38bdf8\"/>\n    <text x=\"560\" y=\"387\" fill=\"#38bdf8\" font-weight=\"bold\">OUTPUT: CLEAR POTABLE WATER</text>\n    <text x=\"560\" y=\"400\" fill=\"#888888\">무색투명 식수 (음용 전 3분 끓임 필수)</text>\n  </g>\n\n  <!-- Technical Callout Leader Lines & Specs (Left Side) -->\n  <g id=\"calloutsLeft\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Spec Box -->\n    <rect x=\"45\" y=\"110\" width=\"180\" height=\"150\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"110\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"125\" fill=\"#E02424\" font-weight=\"bold\">CRITICAL METRICS</text>\n\n    <text x=\"55\" y=\"150\" fill=\"#aaa\">· TOTAL HEIGHT: 60-80 CM</text>\n    <text x=\"55\" y=\"170\" fill=\"#aaa\">· COMPACTION: 100% TIGHT</text>\n    <text x=\"55\" y=\"190\" fill=\"#aaa\">· CHARCOAL THICKNESS: 10 CM+</text>\n    <text x=\"55\" y=\"210\" fill=\"#aaa\">· INITIAL FLUSH: DISCARD 1L</text>\n    <text x=\"55\" y=\"230\" fill=\"#aaa\">· WATER PURITY: 99.2% CLARITY</text>\n    <text x=\"55\" y=\"250\" fill=\"#38bdf8\">· BOILING REQ: 3 MIN AT 100°C</text>\n\n    <!-- Raw Water Inflow Indicator -->\n    <path d=\"M 330 75 Q 360 82 375 92\" stroke=\"#8c6643\" stroke-width=\"2\" fill=\"none\"/>\n    <text x=\"320\" y=\"65\" fill=\"#c9ad7d\" font-weight=\"bold\">RAW MUDDY INFLOW (탁수 유입)</text>\n  </g>\n</svg>\n","content/svgs/pr01-step-01.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGradP01\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1217\"/>\n      <stop offset=\"100%\" stop-color=\"#080a0d\"/>\n    </linearGradient>\n\n    <!-- Timber Tripod Cylinder Shading -->\n    <linearGradient id=\"woodLeg\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3d2817\"/>\n      <stop offset=\"45%\" stop-color=\"#694627\"/>\n      <stop offset=\"70%\" stop-color=\"#8c5d35\"/>\n      <stop offset=\"100%\" stop-color=\"#2a1b0e\"/>\n    </linearGradient>\n\n    <!-- Birch Bark Cone Funnel -->\n    <linearGradient id=\"birchCone\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#403830\"/>\n      <stop offset=\"35%\" stop-color=\"#736658\"/>\n      <stop offset=\"65%\" stop-color=\"#9e8d7c\"/>\n      <stop offset=\"100%\" stop-color=\"#332c25\"/>\n    </linearGradient>\n\n    <!-- Moss Plug Green Gradient -->\n    <linearGradient id=\"mossGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#14532d\"/>\n      <stop offset=\"50%\" stop-color=\"#22c55e\"/>\n      <stop offset=\"100%\" stop-color=\"#052e16\"/>\n    </linearGradient>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowP01\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGradP01)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header (Label 1) -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" letter-spacing=\"0.5\">FIG. 01 // PURIFICATION STEP 1: 프레임 거치 및 하단 마개</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Tripod Legs (Back Leg first) -->\n  <line x1=\"200\" y1=\"65\" x2=\"200\" y2=\"320\" stroke=\"#000000\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n  <line x1=\"200\" y1=\"65\" x2=\"200\" y2=\"320\" stroke=\"url(#woodLeg)\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n\n  <!-- Cone Funnel Body (Birch Bark) with Drop Shadow -->\n  <polygon points=\"140,110 260,110 215,260 185,260\" fill=\"url(#birchCone)\" stroke=\"#221c17\" stroke-width=\"1.5\" filter=\"url(#shadowP01)\"/>\n  <ellipse cx=\"200\" cy=\"110\" rx=\"60\" ry=\"12\" fill=\"#52473c\" stroke=\"#221c17\" stroke-width=\"1.5\"/>\n\n  <!-- Front Tripod Left Leg -->\n  <line x1=\"200\" y1=\"65\" x2=\"120\" y2=\"320\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n  <line x1=\"200\" y1=\"65\" x2=\"120\" y2=\"320\" stroke=\"url(#woodLeg)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n\n  <!-- Front Tripod Right Leg -->\n  <line x1=\"200\" y1=\"65\" x2=\"280\" y2=\"320\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n  <line x1=\"200\" y1=\"65\" x2=\"280\" y2=\"320\" stroke=\"url(#woodLeg)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n\n  <!-- Top Lash Knot Binding Tripod -->\n  <rect x=\"188\" y=\"58\" width=\"24\" height=\"16\" rx=\"4\" fill=\"#854d0e\" stroke=\"#451a03\" stroke-width=\"1.5\"/>\n\n  <!-- Bottom Spout Opening and Moss Plug -->\n  <polygon points=\"185,260 215,260 210,282 190,282\" fill=\"#2d241c\" stroke=\"#1c1611\" stroke-width=\"1\"/>\n  <!-- Moss / Fabric Plug Core -->\n  <ellipse cx=\"200\" cy=\"275\" rx=\"11\" ry=\"7\" fill=\"url(#mossGrad)\" stroke=\"#14532d\" stroke-width=\"1\"/>\n  <!-- Texture dots for moss -->\n  <circle cx=\"197\" cy=\"274\" r=\"1.5\" fill=\"#86efac\"/>\n  <circle cx=\"203\" cy=\"276\" r=\"1.2\" fill=\"#4ade80\"/>\n\n  <!-- Support Cord wrapped around Funnel -->\n  <ellipse cx=\"200\" cy=\"140\" rx=\"48\" ry=\"9\" fill=\"none\" stroke=\"#ca8a04\" stroke-width=\"2.5\" stroke-dasharray=\"6 3\"/>\n\n  <!-- Technical Callout Lines -->\n  <!-- Callout 1: Tripod Frame (Label 2) -->\n  <line x1=\"140\" y1=\"160\" x2=\"105\" y2=\"75\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"140\" cy=\"160\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"70\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" font-weight=\"bold\">TRIPOD FRAME (삼각대)</text>\n\n  <!-- Callout 2: Cone Funnel (Label 3) -->\n  <line x1=\"240\" y1=\"170\" x2=\"105\" y2=\"165\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"240\" cy=\"170\" r=\"2.5\" fill=\"#38bdf8\"/>\n  <text x=\"24\" y=\"160\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" font-weight=\"bold\">CONE FUNNEL (여과관)</text>\n\n  <!-- Callout 3: Moss Plug (Label 4) -->\n  <line x1=\"200\" y1=\"275\" x2=\"105\" y2=\"255\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"200\" cy=\"275\" r=\"2.5\" fill=\"#22c55e\"/>\n  <text x=\"24\" y=\"250\" fill=\"#86efac\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" font-weight=\"bold\">MOSS PLUG (이끼 마개)</text>\n\n  <!-- Bottom Tactical Note Strip -->\n  <rect x=\"18\" y=\"340\" width=\"364\" height=\"34\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"340\" width=\"4\" height=\"34\" fill=\"#38bdf8\"/>\n  <!-- Label 5: Step Core Instruction -->\n  <text x=\"32\" y=\"361\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[1단계 핵심] 흔들리지 않는 3점 지지대 결속</text>\n</svg>\n","content/svgs/pr01-step-02.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGradP02\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1217\"/>\n      <stop offset=\"100%\" stop-color=\"#080a0d\"/>\n    </linearGradient>\n\n    <!-- Funnel Cutaway Shell Gradient -->\n    <linearGradient id=\"funnelCutaway\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#332c25\"/>\n      <stop offset=\"15%\" stop-color=\"#665747\"/>\n      <stop offset=\"50%\" stop-color=\"#181e26\"/>\n      <stop offset=\"85%\" stop-color=\"#665747\"/>\n      <stop offset=\"100%\" stop-color=\"#332c25\"/>\n    </linearGradient>\n\n    <!-- Charcoal Grain Texture Pattern -->\n    <pattern id=\"charcoalTexture\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\">\n      <rect width=\"12\" height=\"12\" fill=\"#111317\"/>\n      <circle cx=\"3\" cy=\"3\" r=\"2.2\" fill=\"#22272e\"/>\n      <circle cx=\"8\" cy=\"8\" r=\"2.8\" fill=\"#1b2026\"/>\n      <circle cx=\"9\" cy=\"2\" r=\"1.5\" fill=\"#2d333b\"/>\n      <circle cx=\"2\" cy=\"9\" r=\"1.8\" fill=\"#262c33\"/>\n    </pattern>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowP02\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGradP02)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header (Label 1) -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" letter-spacing=\"0.5\">FIG. 02 // PURIFICATION STEP 2: 숯 흡착층 형성</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Cutaway Cross Section Funnel Wall -->\n  <polygon points=\"120,85 240,85 195,295 165,295\" fill=\"none\" stroke=\"#4b5563\" stroke-width=\"1.5\" stroke-dasharray=\"4 2\"/>\n  <path d=\"M 120 85 L 165 295 L 195 295 L 240 85\" fill=\"none\" stroke=\"#374151\" stroke-width=\"3\"/>\n\n  <!-- Bottom Moss Plug in Cross Section -->\n  <polygon points=\"166,275 194,275 190,295 170,295\" fill=\"#14532d\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n\n  <!-- Charcoal Bed (8cm layer) with Texture and Shading -->\n  <polygon points=\"152,195 208,195 194,275 166,275\" fill=\"url(#charcoalTexture)\" stroke=\"#111827\" stroke-width=\"1.5\" filter=\"url(#shadowP02)\"/>\n  \n  <!-- Individual Charcoal Chunks (5~8mm grains) -->\n  <rect x=\"172\" y=\"202\" width=\"7\" height=\"6\" rx=\"1.5\" fill=\"#374151\" stroke=\"#1f2937\" stroke-width=\"0.8\"/>\n  <rect x=\"183\" y=\"205\" width=\"8\" height=\"7\" rx=\"1.5\" fill=\"#4b5563\" stroke=\"#1f2937\" stroke-width=\"0.8\"/>\n  <rect x=\"175\" y=\"218\" width=\"9\" height=\"7\" rx=\"2\" fill=\"#374151\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n  <rect x=\"188\" y=\"222\" width=\"7\" height=\"6\" rx=\"1.5\" fill=\"#4b5563\" stroke=\"#1f2937\" stroke-width=\"0.8\"/>\n  <rect x=\"170\" y=\"235\" width=\"8\" height=\"8\" rx=\"2\" fill=\"#1f2937\" stroke=\"#0f172a\" stroke-width=\"0.8\"/>\n  <rect x=\"182\" y=\"240\" width=\"9\" height=\"7\" rx=\"2\" fill=\"#374151\" stroke=\"#1f2937\" stroke-width=\"0.8\"/>\n  <rect x=\"174\" y=\"255\" width=\"8\" height=\"6\" rx=\"1.5\" fill=\"#4b5563\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n\n  <!-- 8cm Height Dimension Bracket -->\n  <path d=\"M 215 195 L 225 195 L 225 275 L 215 275\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n  <line x1=\"225\" y1=\"235\" x2=\"235\" y2=\"235\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n\n  <!-- Zoom Loupe: Micro-Pore Adsorption Mechanism (Right Top) -->\n  <circle cx=\"310\" cy=\"115\" r=\"32\" fill=\"#0d1117\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n  <!-- Charcoal Porous Matrix -->\n  <circle cx=\"310\" cy=\"115\" r=\"22\" fill=\"#1f2937\"/>\n  <circle cx=\"304\" cy=\"110\" r=\"3\" fill=\"#0b0f14\"/>\n  <circle cx=\"316\" cy=\"112\" r=\"2.5\" fill=\"#0b0f14\"/>\n  <circle cx=\"310\" cy=\"122\" r=\"3.2\" fill=\"#0b0f14\"/>\n  <!-- Toxin Trap Arrow Vectors into pores -->\n  <path d=\"M 292 105 L 302 109\" stroke=\"#ef4444\" stroke-width=\"1.5\" marker-end=\"url(#arrow)\"/>\n  <polygon points=\"302,109 296,106 298,112\" fill=\"#ef4444\"/>\n  <path d=\"M 326 126 L 314 123\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n  <polygon points=\"314,123 320,121 319,127\" fill=\"#ef4444\"/>\n\n  <!-- Technical Callouts -->\n  <!-- Callout 1: Charcoal Core (Label 2) -->\n  <line x1=\"160\" y1=\"235\" x2=\"115\" y2=\"75\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"160\" cy=\"235\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"70\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" font-weight=\"bold\">CHARCOAL CORE (활성 숯)</text>\n\n  <!-- Callout 2: Pore Absorption (Label 3) -->\n  <text x=\"376\" y=\"70\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">PORE ABSORPTION (미세 흡착)</text>\n\n  <!-- Callout 3: Thickness 8cm (Label 4) -->\n  <line x1=\"235\" y1=\"235\" x2=\"285\" y2=\"165\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <circle cx=\"235\" cy=\"235\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"376\" y=\"165\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">THICKNESS: 8CM (두께)</text>\n\n  <!-- Bottom Tactical Note Strip -->\n  <rect x=\"18\" y=\"340\" width=\"364\" height=\"34\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"340\" width=\"4\" height=\"34\" fill=\"#f59e0b\"/>\n  <!-- Label 5: Step Core Instruction -->\n  <text x=\"32\" y=\"361\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[2단계 핵심] 콩알 크기(5~8mm)로 부숴 8cm 충진</text>\n</svg>\n","content/svgs/pr01-step-03.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGradP03\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1217\"/>\n      <stop offset=\"100%\" stop-color=\"#080a0d\"/>\n    </linearGradient>\n\n    <!-- River Sand Granular Pattern -->\n    <pattern id=\"sandTexture\" width=\"10\" height=\"10\" patternUnits=\"userSpaceOnUse\">\n      <rect width=\"10\" height=\"10\" fill=\"#785934\"/>\n      <circle cx=\"2\" cy=\"2\" r=\"1.2\" fill=\"#d97706\"/>\n      <circle cx=\"7\" cy=\"7\" r=\"1.4\" fill=\"#fbbf24\"/>\n      <circle cx=\"8\" cy=\"2\" r=\"1\" fill=\"#b45309\"/>\n      <circle cx=\"3\" cy=\"8\" r=\"1.1\" fill=\"#fde68a\"/>\n    </pattern>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowP03\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGradP03)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header (Label 1) -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" letter-spacing=\"0.5\">FIG. 03 // PURIFICATION STEP 3: 미세 모래층 적층</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Cutaway Cross Section Funnel Wall -->\n  <polygon points=\"120,85 240,85 195,295 165,295\" fill=\"none\" stroke=\"#4b5563\" stroke-width=\"1.5\" stroke-dasharray=\"4 2\"/>\n  <path d=\"M 120 85 L 165 295 L 195 295 L 240 85\" fill=\"none\" stroke=\"#374151\" stroke-width=\"3\"/>\n\n  <!-- Bottom Moss Plug -->\n  <polygon points=\"166,275 194,275 190,295 170,295\" fill=\"#14532d\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n\n  <!-- 1. Lower Layer: Charcoal Bed (Already Placed) -->\n  <polygon points=\"152,215 208,215 194,275 166,275\" fill=\"#181c22\" stroke=\"#111827\" stroke-width=\"1\"/>\n\n  <!-- 2. Mid Layer: River Sand (6cm layer) with Texture and Shading -->\n  <polygon points=\"138,155 222,155 208,215 152,215\" fill=\"url(#sandTexture)\" stroke=\"#92400e\" stroke-width=\"1.5\" filter=\"url(#shadowP03)\"/>\n\n  <!-- Leveling Guide Arrows (수평 다듬기) -->\n  <line x1=\"145\" y1=\"150\" x2=\"215\" y2=\"150\" stroke=\"#fde68a\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <polygon points=\"215,150 209,147 209,153\" fill=\"#fde68a\"/>\n  <polygon points=\"145,150 151,147 151,153\" fill=\"#fde68a\"/>\n\n  <!-- 6cm Height Dimension Bracket -->\n  <path d=\"M 230 155 L 240 155 L 240 215 L 230 215\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n  <line x1=\"240\" y1=\"185\" x2=\"250\" y2=\"185\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n\n  <!-- Particle Trap Inset Zoom (Right Top) -->\n  <circle cx=\"310\" cy=\"115\" r=\"32\" fill=\"#0d1117\" stroke=\"#fbbf24\" stroke-width=\"1.5\"/>\n  <circle cx=\"310\" cy=\"115\" r=\"24\" fill=\"#451a03\"/>\n  <!-- Sand Grains interlocking -->\n  <circle cx=\"304\" cy=\"110\" r=\"5\" fill=\"#d97706\"/>\n  <circle cx=\"316\" cy=\"112\" r=\"4.5\" fill=\"#f59e0b\"/>\n  <circle cx=\"309\" cy=\"121\" r=\"5\" fill=\"#b45309\"/>\n  <!-- Trapped Silt Dust -->\n  <circle cx=\"310\" cy=\"114\" r=\"1.8\" fill=\"#78350f\"/>\n  <circle cx=\"306\" cy=\"118\" r=\"1.5\" fill=\"#78350f\"/>\n\n  <!-- Technical Callouts -->\n  <!-- Callout 1: River Sand (Label 2) -->\n  <line x1=\"165\" y1=\"185\" x2=\"115\" y2=\"75\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"165\" cy=\"185\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"70\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" font-weight=\"bold\">RIVER SAND (고운 모래)</text>\n\n  <!-- Callout 2: Particle Filter (Label 3) -->\n  <text x=\"376\" y=\"70\" fill=\"#fbbf24\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">PARTICLE FILTER (흙먼지 차단)</text>\n\n  <!-- Callout 3: Thickness 6cm (Label 4) -->\n  <line x1=\"250\" y1=\"185\" x2=\"295\" y2=\"165\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <circle cx=\"250\" cy=\"185\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"376\" y=\"165\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">THICKNESS: 6CM (두께)</text>\n\n  <!-- Bottom Tactical Note Strip -->\n  <rect x=\"18\" y=\"340\" width=\"364\" height=\"34\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"340\" width=\"4\" height=\"34\" fill=\"#f59e0b\"/>\n  <!-- Label 5: Step Core Instruction -->\n  <text x=\"32\" y=\"361\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[3단계 핵심] 숯을 고정하고 미세 흙먼지 차단</text>\n</svg>\n","content/svgs/pr01-step-04.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGradP04\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1217\"/>\n      <stop offset=\"100%\" stop-color=\"#080a0d\"/>\n    </linearGradient>\n\n    <!-- Water Drop Gradient -->\n    <linearGradient id=\"clearWater\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#e0f2fe\"/>\n      <stop offset=\"50%\" stop-color=\"#38bdf8\"/>\n      <stop offset=\"100%\" stop-color=\"#0284c7\"/>\n    </linearGradient>\n\n    <!-- Turbid Inflow Water -->\n    <linearGradient id=\"muddyWater\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"100%\" stop-color=\"#92400e\"/>\n    </linearGradient>\n\n    <!-- Pebble 3D Gradient -->\n    <linearGradient id=\"pebbleGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#9ca3af\"/>\n      <stop offset=\"50%\" stop-color=\"#4b5563\"/>\n      <stop offset=\"100%\" stop-color=\"#1f2937\"/>\n    </linearGradient>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowP04\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGradP04)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header (Label 1) -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" letter-spacing=\"0.5\">FIG. 04 // PURIFICATION STEP 4: 자갈층 및 초기 세척</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Funnel Outline -->\n  <polygon points=\"120,85 240,85 195,275 165,275\" fill=\"none\" stroke=\"#4b5563\" stroke-width=\"1.5\" stroke-dasharray=\"4 2\"/>\n  <path d=\"M 120 85 L 165 275 L 195 275 L 240 85\" fill=\"none\" stroke=\"#374151\" stroke-width=\"3\"/>\n\n  <!-- Inflow Muddy Water Stream -->\n  <path d=\"M 180 55 C 180 75 170 85 170 95\" stroke=\"url(#muddyWater)\" stroke-width=\"6\" stroke-linecap=\"round\" fill=\"none\"/>\n  <polygon points=\"180,50 176,58 184,58\" fill=\"#78350f\"/>\n\n  <!-- Top Pebble Bed (4cm) -->\n  <polygon points=\"125,95 235,95 222,140 138,140\" fill=\"#2d333b\" stroke=\"#1f242c\" stroke-width=\"1\" filter=\"url(#shadowP04)\"/>\n  <!-- 3D Pebbles -->\n  <ellipse cx=\"145\" cy=\"115\" rx=\"9\" ry=\"6\" fill=\"url(#pebbleGrad)\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n  <ellipse cx=\"165\" cy=\"110\" rx=\"10\" ry=\"7\" fill=\"url(#pebbleGrad)\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n  <ellipse cx=\"185\" cy=\"116\" rx=\"8\" ry=\"6\" fill=\"url(#pebbleGrad)\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n  <ellipse cx=\"205\" cy=\"112\" rx=\"11\" ry=\"7\" fill=\"url(#pebbleGrad)\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n  <ellipse cx=\"155\" cy=\"128\" rx=\"8\" ry=\"5\" fill=\"url(#pebbleGrad)\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n  <ellipse cx=\"178\" cy=\"130\" rx=\"9\" ry=\"6\" fill=\"url(#pebbleGrad)\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n  <ellipse cx=\"198\" cy=\"126\" rx=\"8\" ry=\"5\" fill=\"url(#pebbleGrad)\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n\n  <!-- Mid Sand Layer -->\n  <polygon points=\"138,140 222,140 208,195 152,195\" fill=\"#785934\" stroke=\"#92400e\" stroke-width=\"1\"/>\n  <!-- Charcoal Bed -->\n  <polygon points=\"152,195 208,195 194,255 166,255\" fill=\"#181c22\" stroke=\"#111827\" stroke-width=\"1\"/>\n  <!-- Moss Plug -->\n  <polygon points=\"166,255 194,255 190,275 170,275\" fill=\"#14532d\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n\n  <!-- Water Dripping Mechanism at Bottom Spout -->\n  <circle cx=\"180\" cy=\"285\" r=\"3.5\" fill=\"url(#clearWater)\"/>\n  <path d=\"M 180 292 C 182 297 182 301 180 304 C 178 301 178 297 180 292\" fill=\"url(#clearWater)\"/>\n\n  <!-- Dual Cup Flushing Scheme (Right Inset) -->\n  <g id=\"flushingCups\">\n    <!-- Cup 1: Dirty Black Flush Cup (DISCARD) -->\n    <rect x=\"290\" y=\"210\" width=\"30\" height=\"35\" rx=\"3\" fill=\"#181c22\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n    <rect x=\"294\" y=\"218\" width=\"22\" height=\"23\" fill=\"#0f1216\"/>\n    <!-- Red X mark -->\n    <path d=\"M 299 224 L 311 236 M 311 224 L 299 236\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n\n    <!-- Arrow from discard to clean -->\n    <path d=\"M 325 228 L 338 228\" stroke=\"#9ca3af\" stroke-width=\"1.5\"/>\n    <polygon points=\"340,228 334,225 334,231\" fill=\"#9ca3af\"/>\n\n    <!-- Cup 2: Crystal Clean Water Cup (COLLECT) -->\n    <rect x=\"345\" y=\"210\" width=\"30\" height=\"35\" rx=\"3\" fill=\"#111827\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n    <rect x=\"349\" y=\"222\" width=\"22\" height=\"19\" fill=\"#0284c7\" opacity=\"0.6\"/>\n    <!-- Green Check mark -->\n    <path d=\"M 353 230 L 358 235 L 367 225\" stroke=\"#22c55e\" stroke-width=\"2\" fill=\"none\"/>\n  </g>\n\n  <!-- Technical Callouts -->\n  <!-- Callout 1: Pebble Layer (Label 2) -->\n  <line x1=\"165\" y1=\"120\" x2=\"115\" y2=\"75\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"165\" cy=\"120\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"70\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" font-weight=\"bold\">PEBBLE LAYER (자갈층)</text>\n\n  <!-- Callout 2: Flush First Cups (Label 3) -->\n  <text x=\"376\" y=\"70\" fill=\"#f87171\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">FLUSH FIRST CUPS (첫물 버리기)</text>\n\n  <!-- Callout 3: Clear Drip (Label 4) -->\n  <line x1=\"185\" y1=\"298\" x2=\"285\" y2=\"165\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <circle cx=\"185\" cy=\"298\" r=\"2.5\" fill=\"#38bdf8\"/>\n  <text x=\"376\" y=\"165\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">CLEAR DRIP (맑은 물 방울)</text>\n\n  <!-- Bottom Tactical Note Strip -->\n  <rect x=\"18\" y=\"340\" width=\"364\" height=\"34\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"340\" width=\"4\" height=\"34\" fill=\"#38bdf8\"/>\n  <!-- Label 5: Step Core Instruction -->\n  <text x=\"32\" y=\"361\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[4단계 핵심] 자갈로 수압 분산 후 첫 1~2컵 버리기</text>\n</svg>\n","content/svgs/pr01-step-05.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGradP05\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1217\"/>\n      <stop offset=\"100%\" stop-color=\"#080a0d\"/>\n    </linearGradient>\n\n    <!-- Clay Pot Shading -->\n    <linearGradient id=\"clayPotGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#451a03\"/>\n      <stop offset=\"30%\" stop-color=\"#78350f\"/>\n      <stop offset=\"70%\" stop-color=\"#9a3412\"/>\n      <stop offset=\"100%\" stop-color=\"#2a0d01\"/>\n    </linearGradient>\n\n    <!-- Campfire Flame Gradient -->\n    <linearGradient id=\"flameGrad\" x1=\"0%\" y1=\"100%\" x2=\"0%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#dc2626\"/>\n      <stop offset=\"50%\" stop-color=\"#f97316\"/>\n      <stop offset=\"85%\" stop-color=\"#facc15\"/>\n      <stop offset=\"100%\" stop-color=\"#fef08a\"/>\n    </linearGradient>\n\n    <!-- Boiling Water Steam/Surface -->\n    <linearGradient id=\"boilingWater\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#e0f2fe\"/>\n      <stop offset=\"60%\" stop-color=\"#38bdf8\"/>\n      <stop offset=\"100%\" stop-color=\"#0284c7\"/>\n    </linearGradient>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowP05\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGradP05)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header (Label 1) -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" letter-spacing=\"0.5\">FIG. 05 // PURIFICATION STEP 5: 100℃ 비등 멸균</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Campfire Flames at Base -->\n  <g id=\"fireBase\">\n    <!-- Firewood logs -->\n    <line x1=\"130\" y1=\"305\" x2=\"230\" y2=\"285\" stroke=\"#3d2817\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n    <line x1=\"150\" y1=\"285\" x2=\"250\" y2=\"305\" stroke=\"#2a1b0e\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n    <!-- Dynamic Flame Tongues -->\n    <path d=\"M 160 300 C 150 260 170 230 180 215 C 190 235 185 265 175 300\" fill=\"url(#flameGrad)\" opacity=\"0.9\"/>\n    <path d=\"M 180 300 C 175 250 195 220 200 205 C 210 230 205 265 195 300\" fill=\"url(#flameGrad)\" opacity=\"0.95\"/>\n    <path d=\"M 200 300 C 205 260 225 240 220 225 C 215 245 210 270 215 300\" fill=\"url(#flameGrad)\" opacity=\"0.85\"/>\n  </g>\n\n  <!-- Clay Pot Cooking Vessel -->\n  <path d=\"M 135 150 C 120 185 125 250 155 265 C 175 272 225 272 245 265 C 275 250 280 185 265 150 Z\" \n        fill=\"url(#clayPotGrad)\" stroke=\"#1c0c04\" stroke-width=\"2\" filter=\"url(#shadowP05)\"/>\n  <!-- Pot Rim Ellipse -->\n  <ellipse cx=\"200\" cy=\"150\" rx=\"65\" ry=\"14\" fill=\"#5c2406\" stroke=\"#1c0c04\" stroke-width=\"1.8\"/>\n\n  <!-- Boiling Water Inside Pot -->\n  <ellipse cx=\"200\" cy=\"154\" rx=\"55\" ry=\"11\" fill=\"url(#boilingWater)\"/>\n\n  <!-- Rolling Boil Bubbles (큰 거품) -->\n  <circle cx=\"180\" cy=\"152\" r=\"6\" fill=\"#ffffff\" opacity=\"0.8\" stroke=\"#0284c7\" stroke-width=\"0.8\"/>\n  <circle cx=\"215\" cy=\"154\" r=\"7.5\" fill=\"#ffffff\" opacity=\"0.85\" stroke=\"#0284c7\" stroke-width=\"0.8\"/>\n  <circle cx=\"198\" cy=\"156\" r=\"5\" fill=\"#ffffff\" opacity=\"0.75\" stroke=\"#0284c7\" stroke-width=\"0.8\"/>\n  <circle cx=\"165\" cy=\"155\" r=\"4.5\" fill=\"#ffffff\" opacity=\"0.8\"/>\n  <circle cx=\"230\" cy=\"153\" r=\"4\" fill=\"#ffffff\" opacity=\"0.8\"/>\n\n  <!-- Steam Vapor Waves -->\n  <path d=\"M 175 140 C 170 120 180 105 175 85\" stroke=\"#93c5fd\" stroke-width=\"2\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.6\"/>\n  <path d=\"M 200 138 C 205 118 195 102 200 82\" stroke=\"#93c5fd\" stroke-width=\"2.5\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.7\"/>\n  <path d=\"M 225 140 C 230 122 220 108 225 88\" stroke=\"#93c5fd\" stroke-width=\"2\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.6\"/>\n\n  <!-- 3-Minute Timer Stopwatch Dial (Right Top Inset) -->\n  <circle cx=\"310\" cy=\"115\" r=\"32\" fill=\"#0d1117\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n  <circle cx=\"310\" cy=\"115\" r=\"26\" fill=\"#181111\"/>\n  <!-- Stopwatch Hand pointing to 3 min -->\n  <line x1=\"310\" y1=\"115\" x2=\"310\" y2=\"95\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-linecap=\"round\"/>\n  <line x1=\"310\" y1=\"115\" x2=\"328\" y2=\"122\" stroke=\"#f59e0b\" stroke-width=\"1.8\" stroke-linecap=\"round\"/>\n  <circle cx=\"310\" cy=\"115\" r=\"3\" fill=\"#ffffff\"/>\n  <!-- 3-Min Arc Badge -->\n  <path d=\"M 310 93 A 22 22 0 0 1 332 115\" stroke=\"#22c55e\" stroke-width=\"3\" fill=\"none\"/>\n\n  <!-- Technical Callouts -->\n  <!-- Callout 1: Boiling 100°C (Label 2) -->\n  <line x1=\"165\" y1=\"154\" x2=\"115\" y2=\"75\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"165\" cy=\"154\" r=\"2.5\" fill=\"#ef4444\"/>\n  <text x=\"24\" y=\"70\" fill=\"#f87171\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" font-weight=\"bold\">BOILING 100°C (펄펄 끓이기)</text>\n\n  <!-- Callout 2: Time 3+ Min (Label 3) -->\n  <text x=\"376\" y=\"70\" fill=\"#f59e0b\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">TIME: 3+ MIN (3분 이상)</text>\n\n  <!-- Callout 3: Pathogen Free (Label 4) -->\n  <line x1=\"240\" y1=\"160\" x2=\"285\" y2=\"165\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n  <circle cx=\"240\" cy=\"160\" r=\"2.5\" fill=\"#22c55e\"/>\n  <text x=\"376\" y=\"165\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">PATHOGEN FREE (세균 99.9% 사멸)</text>\n\n  <!-- Bottom Tactical Note Strip -->\n  <rect x=\"18\" y=\"340\" width=\"364\" height=\"34\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"340\" width=\"4\" height=\"34\" fill=\"#ef4444\"/>\n  <!-- Label 5: Step Core Instruction -->\n  <text x=\"32\" y=\"361\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[5단계 핵심] 큰 거품이 솟구치도록 3분 이상 가열</text>\n</svg>\n","content/svgs/pr02-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <!-- Dark Tactical Backdrop -->\n    <linearGradient id=\"bgGrad2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0c0c0c\"/>\n      <stop offset=\"100%\" stop-color=\"#151313\"/>\n    </linearGradient>\n\n    <!-- Wood Shading -->\n    <linearGradient id=\"hearthWood\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3d2d1e\"/>\n      <stop offset=\"40%\" stop-color=\"#694d34\"/>\n      <stop offset=\"70%\" stop-color=\"#4d3725\"/>\n      <stop offset=\"100%\" stop-color=\"#2b1f14\"/>\n    </linearGradient>\n    <linearGradient id=\"spindleWood\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#594432\"/>\n      <stop offset=\"50%\" stop-color=\"#806248\"/>\n      <stop offset=\"100%\" stop-color=\"#403022\"/>\n    </linearGradient>\n    <linearGradient id=\"bearingBlock\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#735c45\"/>\n      <stop offset=\"100%\" stop-color=\"#3b2d1e\"/>\n    </linearGradient>\n\n    <!-- Hot Glowing Ember & Fire Gradients -->\n    <radialGradient id=\"emberGlow\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\" stop-opacity=\"1\"/>\n      <stop offset=\"25%\" stop-color=\"#fef08a\" stop-opacity=\"0.9\"/>\n      <stop offset=\"55%\" stop-color=\"#f97316\" stop-opacity=\"0.8\"/>\n      <stop offset=\"85%\" stop-color=\"#dc2626\" stop-opacity=\"0.6\"/>\n      <stop offset=\"100%\" stop-color=\"#7f1d1d\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <linearGradient id=\"flameGrad\" x1=\"0%\" y1=\"100%\" x2=\"0%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#ef4444\"/>\n      <stop offset=\"40%\" stop-color=\"#f97316\"/>\n      <stop offset=\"75%\" stop-color=\"#fde047\"/>\n      <stop offset=\"100%\" stop-color=\"#ffffff\"/>\n    </linearGradient>\n\n    <!-- Smoke Effect Filter -->\n    <filter id=\"smokeBlur\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feGaussianBlur stdDeviation=\"3\"/>\n    </filter>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad2)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Title & Top Metrics -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: BOW DRILL FRICTION FIRE [EMBER IGNITION]</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">CORE TEMP: 400°C+</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"185\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"185\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">FRICTION MECHANICS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· NOTCH ANGLE: 45° V-CUT</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· SPINDLE RPM: 400-600</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· EMBER COLOR: DENSE CHERRY</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· TINDER PREP: DRIED BAST</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· COAL DUST: BLACK GRAPHITE</text>\n    <text x=\"55\" y=\"240\" fill=\"#f97316\">· BLOWING: GENTLE LONG BREATH</text>\n  </g>\n\n  <!-- Ground Plane Shadow -->\n  <ellipse cx=\"430\" cy=\"390\" rx=\"260\" ry=\"22\" fill=\"#050505\" opacity=\"0.9\"/>\n\n  <!-- Hearth Board (받침 판재) -->\n  <g id=\"hearthBoard\">\n    <!-- Main Plank Slab (Isometric 3D) -->\n    <polygon points=\"260,335 480,335 460,375 240,375\" fill=\"url(#hearthWood)\" stroke=\"#1a140d\" stroke-width=\"2\"/>\n    <polygon points=\"240,375 460,375 460,395 240,395\" fill=\"#241a10\" stroke=\"#1a140d\" stroke-width=\"2\"/>\n    <polygon points=\"460,375 480,335 480,355 460,395\" fill=\"#1f160e\" stroke=\"#1a140d\" stroke-width=\"2\"/>\n\n    <!-- Burn Socket & 45-degree V-Notch -->\n    <ellipse cx=\"360\" cy=\"350\" rx=\"14\" ry=\"7\" fill=\"#080808\" stroke=\"#111\" stroke-width=\"1.5\"/>\n    <polygon points=\"360,350 348,375 372,375\" fill=\"#050505\"/>\n\n    <!-- Catch Bark Tray Underneath Notch -->\n    <polygon points=\"335,372 385,372 395,388 325,388\" fill=\"#523d2b\" stroke=\"#332417\" stroke-width=\"1.5\"/>\n  </g>\n\n  <!-- Glowing Ember Coal (Hot 400°C) on Catch Tray -->\n  <g id=\"emberHot\">\n    <!-- Concentrated Red/Orange Glow Halo -->\n    <circle cx=\"360\" cy=\"378\" r=\"22\" fill=\"url(#emberGlow)\"/>\n    <!-- Black Carbon Powder Mound with Red Hot Core -->\n    <ellipse cx=\"360\" cy=\"380\" rx=\"12\" ry=\"6\" fill=\"#141414\"/>\n    <circle cx=\"359\" cy=\"379\" r=\"4.5\" fill=\"#ffedd5\"/>\n    <circle cx=\"362\" cy=\"378\" r=\"2\" fill=\"#ffffff\"/>\n    <circle cx=\"357\" cy=\"380\" r=\"1.5\" fill=\"#fde047\"/>\n\n    <!-- Rising Woodsmoke Wisps -->\n    <path d=\"M 360 372 Q 352 340 365 315 Q 375 290 358 260 Q 345 230 360 200\" stroke=\"#e2e8f0\" stroke-width=\"4\" fill=\"none\" opacity=\"0.35\" filter=\"url(#smokeBlur)\"/>\n    <path d=\"M 362 370 Q 370 335 358 310 Q 348 285 362 255\" stroke=\"#f1f5f9\" stroke-width=\"2.5\" fill=\"none\" opacity=\"0.45\" filter=\"url(#smokeBlur)\"/>\n  </g>\n\n  <!-- Spindle (회전봉) & Handhold Bearing Block -->\n  <g id=\"spindleAssembly\">\n    <!-- Vertical Spindle -->\n    <polygon points=\"354,150 366,150 364,348 356,348\" fill=\"url(#spindleWood)\" stroke=\"#261b13\" stroke-width=\"1.5\"/>\n    <!-- Bottom Carved Friction Tip (Charred) -->\n    <polygon points=\"356,345 364,345 362,352 358,352\" fill=\"#171717\"/>\n\n    <!-- Top Handhold Bearing Block -->\n    <path d=\"M 340 148 C 340 135 350 130 360 130 C 370 130 380 135 380 148 L 375 156 L 345 156 Z\" fill=\"url(#bearingBlock)\" stroke=\"#261b13\" stroke-width=\"1.8\"/>\n    <!-- Lubricant / Leaf Cushion Layer in Handhold Socket -->\n    <line x1=\"346\" y1=\"154\" x2=\"374\" y2=\"154\" stroke=\"#4ade80\" stroke-width=\"2\"/>\n  </g>\n\n  <!-- Bow & Taut Cord Wrapped Around Spindle -->\n  <g id=\"bowAndCord\">\n    <!-- Curved Wooden Bow Branch -->\n    <path d=\"M 230 290 Q 290 190 470 230\" fill=\"none\" stroke=\"#785336\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n    <path d=\"M 230 290 Q 290 190 470 230\" fill=\"none\" stroke=\"#47301e\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n\n    <!-- Taut Rawhide / Fiber Bowstring Wrapped Once Around Spindle -->\n    <line x1=\"230\" y1=\"288\" x2=\"355\" y2=\"250\" stroke=\"#d4b483\" stroke-width=\"2.5\"/>\n    <!-- Wrap Turn around spindle shaft -->\n    <ellipse cx=\"360\" cy=\"250\" rx=\"7\" ry=\"3.5\" fill=\"#8c6c45\" stroke=\"#d4b483\" stroke-width=\"2\"/>\n    <line x1=\"365\" y1=\"250\" x2=\"470\" y2=\"228\" stroke=\"#d4b483\" stroke-width=\"2.5\"/>\n  </g>\n\n  <!-- Tinder Nest with Sprouting Flame (부싯깃 둥지 & 피어난 불꽃) -->\n  <g id=\"tinderNestAndFlame\">\n    <!-- Bird's Nest Bundle of Fibers -->\n    <ellipse cx=\"560\" cy=\"365\" rx=\"55\" ry=\"24\" fill=\"#36291a\" stroke=\"#241b12\" stroke-width=\"2\"/>\n    <path d=\"M 515 360 Q 560 380 605 360 M 520 370 Q 560 385 600 370 M 530 355 Q 560 370 590 355\" stroke=\"#78593a\" stroke-width=\"1.5\" fill=\"none\"/>\n\n    <!-- Blazing Fire Flame Center -->\n    <path d=\"M 560 355 C 540 340 535 305 555 270 C 560 288 568 295 565 275 C 575 285 585 310 580 340 C 585 330 588 318 584 305 C 595 320 592 345 575 355 Z\" fill=\"url(#flameGrad)\" filter=\"url(#smokeBlur)\"/>\n    <path d=\"M 560 355 C 545 342 542 312 555 280 C 559 295 566 300 564 285 C 572 295 580 315 576 342 C 580 334 582 324 579 315 C 588 326 585 346 572 355 Z\" fill=\"url(#flameGrad)\"/>\n    <!-- White Hot Core -->\n    <ellipse cx=\"563\" cy=\"345\" rx=\"8\" ry=\"14\" fill=\"#ffffff\" opacity=\"0.95\"/>\n    <ellipse cx=\"563\" cy=\"345\" rx=\"14\" ry=\"20\" fill=\"#fef08a\" opacity=\"0.7\"/>\n\n    <!-- Rising Flame Sparks & Smoke -->\n    <circle cx=\"550\" cy=\"245\" r=\"1.5\" fill=\"#f97316\"/>\n    <circle cx=\"568\" cy=\"230\" r=\"1.2\" fill=\"#fde047\"/>\n    <circle cx=\"562\" cy=\"210\" r=\"1\" fill=\"#f97316\"/>\n    <path d=\"M 560 260 Q 550 220 565 180 Q 575 150 560 120\" stroke=\"#cbd5e1\" stroke-width=\"3\" fill=\"none\" opacity=\"0.25\" filter=\"url(#smokeBlur)\"/>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Handhold -->\n    <line x1=\"380\" y1=\"140\" x2=\"565\" y2=\"140\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"380\" cy=\"140\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"137\" fill=\"#ffffff\" font-weight=\"bold\">TOP BEARING BLOCK</text>\n    <text x=\"570\" y=\"150\" fill=\"#888888\">윤활유/풀잎 삽입으로 상단 마찰 최소화</text>\n\n    <!-- Callout 2: Bow & String -->\n    <line x1=\"435\" y1=\"230\" x2=\"565\" y2=\"230\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"435\" cy=\"230\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"227\" fill=\"#ffffff\" font-weight=\"bold\">BOW RIGGING (활비비 구동)</text>\n    <text x=\"570\" y=\"240\" fill=\"#888888\">1회 감김 텐션으로 고속 회전력 전달</text>\n\n    <!-- Callout 3: Ember Coal -->\n    <line x1=\"375\" y1=\"380\" x2=\"565\" y2=\"380\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"375\" cy=\"380\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"377\" fill=\"#E02424\" font-weight=\"bold\">STAGE 1: 400°C GLOWING EMBER</text>\n    <text x=\"570\" y=\"390\" fill=\"#888888\">V홈 숯가루가 잉걸불로 자가 연소</text>\n\n    <!-- Callout 4: Flame Nest -->\n    <line x1=\"560\" y1=\"310\" x2=\"565\" y2=\"310\" stroke=\"#f97316\" stroke-width=\"1\"/>\n    <circle cx=\"560\" cy=\"310\" r=\"2\" fill=\"#f97316\"/>\n    <text x=\"570\" y=\"307\" fill=\"#f97316\" font-weight=\"bold\">STAGE 2: SUSTAINED OPEN FLAME</text>\n    <text x=\"570\" y=\"320\" fill=\"#888888\">부싯깃 둥지 감싸 쥐고 완만한 호흡 착화</text>\n  </g>\n</svg>\n","content/svgs/pr03-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <linearGradient id=\"bgGrad3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0a0f0d\"/>\n      <stop offset=\"100%\" stop-color=\"#141916\"/>\n    </linearGradient>\n\n    <!-- Wood Trunk Gradients -->\n    <linearGradient id=\"ridgepoleWood\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3f2e1d\"/>\n      <stop offset=\"50%\" stop-color=\"#694f34\"/>\n      <stop offset=\"100%\" stop-color=\"#2a1e12\"/>\n    </linearGradient>\n\n    <!-- Dense Leaf Blanket Texture Gradients -->\n    <linearGradient id=\"leafLayer\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#713f12\"/>\n      <stop offset=\"35%\" stop-color=\"#854d0e\"/>\n      <stop offset=\"70%\" stop-color=\"#a16207\"/>\n      <stop offset=\"100%\" stop-color=\"#4d3800\"/>\n    </linearGradient>\n    <radialGradient id=\"shelterInterior\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#050505\"/>\n      <stop offset=\"80%\" stop-color=\"#111111\"/>\n      <stop offset=\"100%\" stop-color=\"#1a1a1a\"/>\n    </radialGradient>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad3)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Metadata -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: A-FRAME DEBRIS HUT [THERMAL SHELTER]</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">DEAD-AIR INSULATION: 1.0M</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">SHELTER METRICS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· RIDGEPOLE: 2.5-3.0 M</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· ROOF PITCH: 45° SLANT</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· LEAF THICKNESS: 100 CM</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· GROUND BEDDING: 50 CM</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· ENTRANCE: LOW BRAWL FIT</text>\n    <text x=\"55\" y=\"240\" fill=\"#4ade80\">· TEMP RETENTION: +15°C</text>\n  </g>\n\n  <!-- Forest Ground Base -->\n  <polygon points=\"120,410 680,410 740,360 200,360\" fill=\"#141a13\" opacity=\"0.8\"/>\n  <ellipse cx=\"450\" cy=\"390\" rx=\"240\" ry=\"22\" fill=\"#080c09\"/>\n\n  <!-- Debris Hut Main Volume (3D Sloping Dome) -->\n  <g id=\"debrisHutStructure\">\n    <!-- Back End Ground Anchor (Tail) -->\n    <ellipse cx=\"640\" cy=\"350\" rx=\"40\" ry=\"18\" fill=\"#1a140d\"/>\n\n    <!-- Thick 1-Meter Debris Leaf Mound Volume (Roof Shading) -->\n    <path d=\"M 330 155 C 390 145 520 220 650 345 L 610 380 C 490 385 360 385 240 375 C 230 330 260 200 330 155 Z\" fill=\"url(#leafLayer)\" stroke=\"#3f2305\" stroke-width=\"2\"/>\n\n    <!-- Highlighting Leaf Scales / Foliage Tufts -->\n    <g stroke=\"#a16207\" stroke-width=\"1.2\" fill=\"#854d0e\" opacity=\"0.85\">\n      <ellipse cx=\"370\" cy=\"210\" rx=\"18\" ry=\"10\"/>\n      <ellipse cx=\"410\" cy=\"230\" rx=\"22\" ry=\"12\"/>\n      <ellipse cx=\"460\" cy=\"250\" rx=\"20\" ry=\"11\"/>\n      <ellipse cx=\"510\" cy=\"280\" rx=\"24\" ry=\"13\"/>\n      <ellipse cx=\"560\" cy=\"310\" rx=\"22\" ry=\"12\"/>\n      <ellipse cx=\"350\" cy=\"260\" rx=\"20\" ry=\"11\"/>\n      <ellipse cx=\"390\" cy=\"280\" rx=\"22\" ry=\"12\"/>\n      <ellipse cx=\"440\" cy=\"300\" rx=\"24\" ry=\"14\"/>\n      <ellipse cx=\"490\" cy=\"330\" rx=\"25\" ry=\"13\"/>\n      <ellipse cx=\"310\" cy=\"300\" rx=\"18\" ry=\"10\"/>\n      <ellipse cx=\"350\" cy=\"325\" rx=\"22\" ry=\"12\"/>\n      <ellipse cx=\"400\" cy=\"340\" rx=\"24\" ry=\"13\"/>\n    </g>\n\n    <!-- Exterior Weighting Thatch Branches (바람막이 겉가지 격자) -->\n    <g stroke=\"#452e18\" stroke-width=\"3\" stroke-linecap=\"round\">\n      <line x1=\"335\" y1=\"170\" x2=\"270\" y2=\"365\"/>\n      <line x1=\"380\" y1=\"180\" x2=\"330\" y2=\"370\"/>\n      <line x1=\"435\" y1=\"210\" x2=\"395\" y2=\"375\"/>\n      <line x1=\"490\" y1=\"240\" x2=\"465\" y2=\"380\"/>\n      <line x1=\"550\" y1=\"280\" x2=\"530\" y2=\"380\"/>\n      <!-- Cross horizontal sticks -->\n      <line x1=\"290\" y1=\"280\" x2=\"540\" y2=\"305\"/>\n      <line x1=\"260\" y1=\"330\" x2=\"570\" y2=\"350\"/>\n    </g>\n\n    <!-- Front A-Frame Crutch Entrance Structure -->\n    <!-- Left A-Frame Post -->\n    <polygon points=\"230,370 240,370 338,150 330,150\" fill=\"url(#ridgepoleWood)\" stroke=\"#1a120b\" stroke-width=\"1.5\"/>\n    <!-- Right A-Frame Post -->\n    <polygon points=\"350,370 340,370 330,150 338,150\" fill=\"url(#ridgepoleWood)\" stroke=\"#1a120b\" stroke-width=\"1.5\"/>\n    <!-- Apex Notch Crotch -->\n    <ellipse cx=\"334\" cy=\"150\" rx=\"10\" ry=\"6\" fill=\"#523922\" stroke=\"#261b11\" stroke-width=\"1.5\"/>\n\n    <!-- Ridgepole Extending Through Apex to Back Tail -->\n    <polygon points=\"328,145 342,145 650,345 640,348\" fill=\"url(#ridgepoleWood)\" stroke=\"#261b11\" stroke-width=\"1.5\"/>\n\n    <!-- Small Snug Entrance Opening -->\n    <path d=\"M 260 370 C 260 280 320 280 320 370 Z\" fill=\"url(#shelterInterior)\" stroke=\"#291b10\" stroke-width=\"2\"/>\n\n    <!-- Entrance Door Plug (낙엽 차단 마개) Placed Beside Entry -->\n    <g id=\"doorPlug\">\n      <ellipse cx=\"230\" cy=\"380\" rx=\"26\" ry=\"16\" fill=\"#5c3a14\" stroke=\"#33200b\" stroke-width=\"1.5\"/>\n      <path d=\"M 215 375 Q 230 385 245 375\" stroke=\"#854d0e\" stroke-width=\"1.2\" fill=\"none\"/>\n    </g>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Ridgepole -->\n    <line x1=\"335\" y1=\"150\" x2=\"565\" y2=\"150\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"335\" cy=\"150\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"147\" fill=\"#ffffff\" font-weight=\"bold\">HEAVY RIDGEPOLE (용마루)</text>\n    <text x=\"570\" y=\"160\" fill=\"#888888\">성인 체중을 견디는 굵은 주 기둥 안착</text>\n\n    <!-- Callout 2: Debris Layer -->\n    <line x1=\"440\" y1=\"240\" x2=\"565\" y2=\"240\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"440\" cy=\"240\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"237\" fill=\"#E02424\" font-weight=\"bold\">1-METER DEBRIS INSULATION</text>\n    <text x=\"570\" y=\"250\" fill=\"#888888\">마른 낙엽 1미터로 영하권 체온 손실 방지</text>\n\n    <!-- Callout 3: Thatch Lattice -->\n    <line x1=\"510\" y1=\"310\" x2=\"565\" y2=\"310\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"510\" cy=\"310\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"307\" fill=\"#ffffff\" font-weight=\"bold\">THATCH TRELLIS (겉가지 격자)</text>\n    <text x=\"570\" y=\"320\" fill=\"#888888\">돌풍에 낙엽이 날리지 않게 상단 누름 고정</text>\n\n    <!-- Callout 4: Snug Entrance & Plug -->\n    <line x1=\"285\" y1=\"350\" x2=\"565\" y2=\"350\" stroke=\"#4ade80\" stroke-width=\"1\"/>\n    <circle cx=\"285\" cy=\"350\" r=\"2\" fill=\"#4ade80\"/>\n    <text x=\"570\" y=\"347\" fill=\"#4ade80\" font-weight=\"bold\">LOW ENTRANCE &amp; DOOR PLUG</text>\n    <text x=\"570\" y=\"360\" fill=\"#888888\">기어 들어갈 크기 + 취침 시 마개 차단</text>\n  </g>\n</svg>\n","content/svgs/pr03-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Outer Frame Guideline -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\" />\n\n  <!-- Rule Callout Box -->\n  <rect x=\"25\" y=\"24\" width=\"330\" height=\"44\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"41\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">움막 크기 핵심 규칙:</text>\n  <text x=\"35\" y=\"58\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">몸이 겨우 들어갈 크기 (어깨 옆 주먹 1개 여유)</text>\n\n  <!-- Ground Baseline -->\n  <line x1=\"40\" y1=\"265\" x2=\"640\" y2=\"265\" stroke=\"#666666\" stroke-width=\"2\" />\n  <line x1=\"60\" y1=\"273\" x2=\"620\" y2=\"273\" stroke=\"#333333\" stroke-width=\"1\" stroke-dasharray=\"6,4\" />\n\n  <!-- Windward Force Vector (Left Side) -->\n  <line x1=\"45\" y1=\"195\" x2=\"115\" y2=\"195\" stroke=\"#E02424\" stroke-width=\"1.8\" marker-end=\"url(#arrow-red)\" />\n  <line x1=\"45\" y1=\"215\" x2=\"105\" y2=\"215\" stroke=\"#E02424\" stroke-width=\"1.2\" stroke-dasharray=\"3,2\" marker-end=\"url(#arrow-red)\" />\n  <text x=\"45\" y=\"182\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">바람 불어오는 쪽 (바닥에 고정)</text>\n\n  <!-- Main Ridgepole (3.0~3.5m Hardwood Spine) from (110, 265) to (490, 115) -->\n  <polygon points=\"105,265 492,110 498,124 125,265\" fill=\"#262626\" stroke=\"#F5F5F5\" stroke-width=\"2\" />\n  <!-- Ground Stake / Anchor at Windward Tail -->\n  <polygon points=\"102,248 112,248 112,282 102,282\" fill=\"#E02424\" stroke=\"#F5F5F5\" stroke-width=\"1.2\" />\n\n  <!-- Ridgepole Label & Leader Line -->\n  <line x1=\"280\" y1=\"190\" x2=\"250\" y2=\"132\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"165\" y=\"124\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">중심 기둥 나무: 길이 3.0~3.5m</text>\n\n  <!-- Y-Frame Bipod Support Sticks at Entrance (Apex at 490, 118) -->\n  <line x1=\"445\" y1=\"265\" x2=\"508\" y2=\"92\" stroke=\"#CCCCCC\" stroke-width=\"5\" />\n  <line x1=\"535\" y1=\"265\" x2=\"472\" y2=\"92\" stroke=\"#999999\" stroke-width=\"5\" />\n  <!-- Vine Lashing Node at Apex -->\n  <circle cx=\"490\" cy=\"116\" r=\"11\" fill=\"#141414\" stroke=\"#E02424\" stroke-width=\"2\" />\n  <line x1=\"481\" y1=\"112\" x2=\"499\" y2=\"120\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n  <line x1=\"481\" y1=\"120\" x2=\"499\" y2=\"112\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n\n  <!-- Lashing Node Label -->\n  <line x1=\"490\" y1=\"102\" x2=\"490\" y2=\"68\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"490\" y=\"60\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"middle\">Y자 기둥 2개 맞물려 묶기</text>\n\n  <!-- Interior Prone Body Clearance Envelope (Coffin Spec) -->\n  <path d=\"M 165,258 L 455,258 L 455,212 L 385,205 L 165,242 Z\" fill=\"#1c1b1b\" stroke=\"#888888\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\" />\n  <!-- Clearance Gap Arrows (+10cm Fist Tolerance) -->\n  <line x1=\"365\" y1=\"172\" x2=\"365\" y2=\"205\" stroke=\"#E02424\" stroke-width=\"1.5\" marker-end=\"url(#arrow-red)\" />\n  <text x=\"340\" y=\"298\" fill=\"#CCCCCC\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"middle\">내부 공간: 몸 둘레 + 10cm (주먹 1개 여유)</text>\n\n  <!-- Vertical Elevation Dimension (0.8 ~ 1.0m) on Right -->\n  <line x1=\"575\" y1=\"116\" x2=\"575\" y2=\"265\" stroke=\"#F5F5F5\" stroke-width=\"1.2\" />\n  <line x1=\"565\" y1=\"116\" x2=\"585\" y2=\"116\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n  <line x1=\"565\" y1=\"265\" x2=\"585\" y2=\"265\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n  <text x=\"655\" y=\"194\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">입구 높이: 0.8~1.0m</text>\n</svg>\n","content/svgs/pr03-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Outer Frame Guideline -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\" />\n\n  <!-- Rule Callout Box -->\n  <rect x=\"25\" y=\"24\" width=\"335\" height=\"44\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"41\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">바닥 냉기 차단 핵심:</text>\n  <text x=\"35\" y=\"58\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">마른 낙엽을 두껍게 깔아 눌린 뒤에도 20cm 유지</text>\n\n  <!-- Ground Baseline -->\n  <line x1=\"60\" y1=\"265\" x2=\"620\" y2=\"265\" stroke=\"#666666\" stroke-width=\"2\" />\n\n  <!-- Cross-Section A-Frame Rib Lattice (Center X = 340, Apex Y = 88) -->\n  <!-- Left & Right Rib Poles at 52° Pitch -->\n  <line x1=\"340\" y1=\"88\" x2=\"185\" y2=\"265\" stroke=\"#F5F5F5\" stroke-width=\"4\" />\n  <line x1=\"340\" y1=\"88\" x2=\"495\" y2=\"265\" stroke=\"#F5F5F5\" stroke-width=\"4\" />\n  <!-- Secondary Lattice Branches -->\n  <line x1=\"295\" y1=\"138\" x2=\"412\" y2=\"170\" stroke=\"#777777\" stroke-width=\"1.5\" stroke-dasharray=\"5,3\" />\n  <line x1=\"255\" y1=\"184\" x2=\"445\" y2=\"208\" stroke=\"#777777\" stroke-width=\"1.5\" stroke-dasharray=\"5,3\" />\n\n  <!-- Ridgepole Cross-Section Circle at Apex -->\n  <circle cx=\"340\" cy=\"88\" r=\"14\" fill=\"#262626\" stroke=\"#E02424\" stroke-width=\"2.5\" />\n  <circle cx=\"340\" cy=\"88\" r=\"4\" fill=\"#F5F5F5\" />\n  <line x1=\"354\" y1=\"84\" x2=\"430\" y2=\"56\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"436\" y=\"59\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">중심 기둥 나무 (단면)</text>\n\n  <!-- Rib Pitch Angle Indicator (45° ~ 60°) -->\n  <path d=\"M 222,265 A 36 36 0 0 0 209,238\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"1.8\" />\n  <line x1=\"252\" y1=\"188\" x2=\"175\" y2=\"145\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"35\" y=\"140\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">양옆 나뭇가지: 45°~60° 각도로 촘촘히 세우기</text>\n\n  <!-- Interior Floor Mattress: Initial 40cm Mound (Dashed) & Compressed 15~20cm Core (Solid) -->\n  <path d=\"M 215,265 Q 340,175 465,265 Z\" fill=\"#1c1b1b\" stroke=\"#888888\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\" />\n  <rect x=\"215\" y=\"222\" width=\"250\" height=\"43\" fill=\"#252323\" stroke=\"#E02424\" stroke-width=\"2\" />\n  <!-- Texture lines inside mattress -->\n  <line x1=\"230\" y1=\"236\" x2=\"450\" y2=\"236\" stroke=\"#666666\" stroke-width=\"1\" stroke-dasharray=\"8,4\" />\n  <line x1=\"225\" y1=\"250\" x2=\"455\" y2=\"250\" stroke=\"#666666\" stroke-width=\"1\" stroke-dasharray=\"6,5\" />\n\n  <!-- Mattress Dimension Callout on Right -->\n  <line x1=\"470\" y1=\"235\" x2=\"520\" y2=\"205\" stroke=\"#E02424\" stroke-width=\"1.2\" marker-end=\"url(#arrow-red)\" />\n  <text x=\"655\" y=\"200\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">낙엽 이불: 40cm → 눌린 뒤 20cm</text>\n\n  <!-- Ground Cold Conduction Blocked Vectors (Bottom) -->\n  <line x1=\"270\" y1=\"292\" x2=\"270\" y2=\"270\" stroke=\"#E02424\" stroke-width=\"1.5\" marker-end=\"url(#arrow-red)\" />\n  <line x1=\"340\" y1=\"292\" x2=\"340\" y2=\"270\" stroke=\"#E02424\" stroke-width=\"1.5\" marker-end=\"url(#arrow-red)\" />\n  <line x1=\"410\" y1=\"292\" x2=\"410\" y2=\"270\" stroke=\"#E02424\" stroke-width=\"1.5\" marker-end=\"url(#arrow-red)\" />\n  <text x=\"340\" y=\"314\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">땅에서 올라오는 찬 기운 완벽 차단</text>\n</svg>","content/svgs/pr03-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Outer Frame Guideline -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\" />\n\n  <!-- Rule Callout Box -->\n  <rect x=\"25\" y=\"24\" width=\"335\" height=\"44\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"41\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">지붕 낙엽 쌓기 &amp; 입구 막기:</text>\n  <text x=\"35\" y=\"58\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">지붕에 낙엽을 팔 길이(60~90cm)로 쌓고 입구 막기</text>\n\n  <!-- Ground Baseline -->\n  <line x1=\"45\" y1=\"268\" x2=\"635\" y2=\"268\" stroke=\"#666666\" stroke-width=\"2\" />\n\n  <!-- Outer Heavy Deadwood Wind-Armor Layer (Outer Mound) -->\n  <path d=\"M 95,268 Q 340,22 585,268 Z\" fill=\"#191818\" stroke=\"#F5F5F5\" stroke-width=\"2.2\" />\n  <!-- Shingled Debris Layer (60~90cm Thickness Zone) -->\n  <path d=\"M 135,268 Q 340,68 545,268 Z\" fill=\"#222020\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"6,3\" />\n\n  <!-- Inner Rib Core & Dead-Air Thermal Chamber -->\n  <polygon points=\"340,142 230,268 450,268\" fill=\"#121212\" stroke=\"#E02424\" stroke-width=\"2\" />\n  <!-- Entrance Debris Plug / Seal Indicator inside Chamber -->\n  <circle cx=\"340\" cy=\"222\" r=\"24\" fill=\"#291414\" stroke=\"#E02424\" stroke-width=\"1.8\" stroke-dasharray=\"3,2\" />\n  <path d=\"M 326,222 L 354,222 M 340,208 L 340,236\" stroke=\"#E02424\" stroke-width=\"1.5\" />\n\n  <!-- 60~90cm Thickness Dimension Callout (Left Slope) -->\n  <line x1=\"185\" y1=\"162\" x2=\"255\" y2=\"212\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow-red)\" />\n  <line x1=\"185\" y1=\"162\" x2=\"135\" y2=\"128\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"30\" y=\"120\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">마른 낙엽 벽: 60~90cm 두께</text>\n\n  <!-- Heavy Deadwood Armor Callout (Right Slope) -->\n  <line x1=\"455\" y1=\"118\" x2=\"505\" y2=\"75\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"655\" y=\"70\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"end\">바람에 안 날리게 무거운 가지 덮기</text>\n\n  <!-- Rain / Wind Shedding Vector on Right Slope -->\n  <line x1=\"505\" y1=\"145\" x2=\"575\" y2=\"215\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" marker-end=\"url(#arrow-white)\" />\n  <text x=\"655\" y=\"142\" fill=\"#AAAAAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" text-anchor=\"end\">빗물이 타고 흐르는 경사면</text>\n\n  <!-- Dead Air Space & Entrance Plug Label (Bottom Center) -->\n  <line x1=\"340\" y1=\"246\" x2=\"340\" y2=\"292\" stroke=\"#E02424\" stroke-width=\"1.2\" />\n  <text x=\"340\" y=\"312\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">따뜻한 공기가 갇힌 내부 &amp; 낙엽 마개</text>\n</svg>","content/svgs/pr04-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <linearGradient id=\"bgGrad4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0c0d0e\"/>\n      <stop offset=\"100%\" stop-color=\"#14171a\"/>\n    </linearGradient>\n\n    <!-- Haft Wood Texture -->\n    <linearGradient id=\"haftWood\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3d2c1d\"/>\n      <stop offset=\"35%\" stop-color=\"#694e36\"/>\n      <stop offset=\"70%\" stop-color=\"#523c28\"/>\n      <stop offset=\"100%\" stop-color=\"#2b1e12\"/>\n    </linearGradient>\n\n    <!-- Stone Axe Head (Chert / Basalt Flint) -->\n    <linearGradient id=\"flintStone\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#474747\"/>\n      <stop offset=\"40%\" stop-color=\"#2e2e2e\"/>\n      <stop offset=\"80%\" stop-color=\"#1a1a1a\"/>\n      <stop offset=\"100%\" stop-color=\"#0f0f0f\"/>\n    </linearGradient>\n\n    <!-- Pine Pitch Resin Glue -->\n    <linearGradient id=\"pitchResin\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#1c1106\"/>\n      <stop offset=\"50%\" stop-color=\"#42290d\"/>\n      <stop offset=\"100%\" stop-color=\"#0f0802\"/>\n    </linearGradient>\n\n    <!-- Raw Vine Lashing -->\n    <linearGradient id=\"vineLashing\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#a8895b\"/>\n      <stop offset=\"50%\" stop-color=\"#7a623e\"/>\n      <stop offset=\"100%\" stop-color=\"#4f3e26\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad4)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Title & Top Metrics -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: PRIMITIVE STONE AXE [BIFACIAL CHERT]</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">TENSILE RATING: 80 KGF</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">AXE SPECIFICATIONS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· STONE: RIVER BASALT/FLINT</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· BEVEL: 35° BIFACE EDGE</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· HAFT: DRIED OAK / HICKORY</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· BINDING: X-CROSS VINE</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· RESIN: PINE PITCH + ASH</text>\n    <text x=\"55\" y=\"240\" fill=\"#38bdf8\">· CHOPPING EFF: 10 CM / 5 MIN</text>\n  </g>\n\n  <!-- Shadow Under Stone Axe -->\n  <ellipse cx=\"440\" cy=\"380\" rx=\"200\" ry=\"16\" fill=\"#050505\" opacity=\"0.9\"/>\n\n  <!-- Complete Stone Axe Assembly -->\n  <g id=\"axeAssembly\" transform=\"rotate(-15 420 250)\">\n    <!-- Wooden Haft Handle (Diagonal Solid Club) -->\n    <path d=\"M 280 230 C 310 232 440 242 560 250 C 585 252 600 256 600 268 C 600 280 580 282 560 280 C 440 270 310 255 280 250 Z\" fill=\"url(#haftWood)\" stroke=\"#1a120b\" stroke-width=\"2\"/>\n\n    <!-- Forked Cleft / Socket at Head End -->\n    <path d=\"M 285 220 C 265 215 250 200 250 185 L 295 190 C 295 210 285 220 285 220 Z\" fill=\"#241a10\" stroke=\"#120c07\" stroke-width=\"1.5\"/>\n\n    <!-- Chipped Basalt/Flint Stone Axe Blade Head -->\n    <polygon points=\"210,135 295,155 315,225 240,240 185,190\" fill=\"url(#flintStone)\" stroke=\"#111111\" stroke-width=\"2\"/>\n    <!-- Chipping Facets & Flaking Edges (Realistic Bifacial Flakes) -->\n    <polygon points=\"210,135 250,155 235,175 195,160\" fill=\"#3d3d3d\" stroke=\"#222\" stroke-width=\"1\"/>\n    <polygon points=\"250,155 295,155 280,185 235,175\" fill=\"#4d4d4d\" stroke=\"#222\" stroke-width=\"1\"/>\n    <polygon points=\"195,160 235,175 225,210 185,190\" fill=\"#262626\" stroke=\"#111\" stroke-width=\"1\"/>\n    <polygon points=\"235,175 280,185 270,220 225,210\" fill=\"#363636\" stroke=\"#222\" stroke-width=\"1\"/>\n    <polygon points=\"280,185 315,225 270,220\" fill=\"#1f1f1f\" stroke=\"#111\" stroke-width=\"1\"/>\n    <!-- Razor-Sharp Front Cutting Edge Highlight -->\n    <path d=\"M 210 135 L 185 190 L 240 240\" fill=\"none\" stroke=\"#e0e0e0\" stroke-width=\"1.8\" stroke-linecap=\"round\"/>\n\n    <!-- Black Pine Pitch Resin Adhesive Layer Sealing Socket -->\n    <ellipse cx=\"285\" cy=\"225\" rx=\"30\" ry=\"20\" fill=\"url(#pitchResin)\" opacity=\"0.95\"/>\n\n    <!-- Tight Criss-Cross Vine / Rawhide Lashings (X-Lashing Pattern) -->\n    <g stroke=\"url(#vineLashing)\" stroke-width=\"3.5\" stroke-linecap=\"round\">\n      <!-- Diagonal Forward Turns -->\n      <line x1=\"260\" y1=\"210\" x2=\"310\" y2=\"255\"/>\n      <line x1=\"265\" y1=\"205\" x2=\"315\" y2=\"250\"/>\n      <line x1=\"270\" y1=\"200\" x2=\"320\" y2=\"245\"/>\n      <!-- Diagonal Backward Turns (Crossing to form X) -->\n      <line x1=\"310\" y1=\"210\" x2=\"260\" y2=\"255\"/>\n      <line x1=\"315\" y1=\"205\" x2=\"265\" y2=\"250\"/>\n      <line x1=\"320\" y1=\"200\" x2=\"270\" y2=\"245\"/>\n      <!-- Tight Frapping Turns Around Socket Base -->\n      <line x1=\"280\" y1=\"250\" x2=\"280\" y2=\"265\" stroke-width=\"4\"/>\n      <line x1=\"288\" y1=\"248\" x2=\"288\" y2=\"263\" stroke-width=\"4\"/>\n    </g>\n\n    <!-- Handle Grip Carvings / Notches -->\n    <line x1=\"520\" y1=\"248\" x2=\"520\" y2=\"276\" stroke=\"#241a10\" stroke-width=\"1.5\"/>\n    <line x1=\"535\" y1=\"250\" x2=\"535\" y2=\"278\" stroke=\"#241a10\" stroke-width=\"1.5\"/>\n    <line x1=\"550\" y1=\"252\" x2=\"550\" y2=\"280\" stroke=\"#241a10\" stroke-width=\"1.5\"/>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Stone Blade -->\n    <line x1=\"260\" y1=\"140\" x2=\"565\" y2=\"140\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"260\" cy=\"140\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"137\" fill=\"#E02424\" font-weight=\"bold\">CHIPPED BIFACE STONE BLADE</text>\n    <text x=\"570\" y=\"150\" fill=\"#888888\">양면 박편 타제로 세운 35도 예리한 절삭날</text>\n\n    <!-- Callout 2: Resin Seal -->\n    <line x1=\"350\" y1=\"210\" x2=\"565\" y2=\"210\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"350\" cy=\"210\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"207\" fill=\"#ffffff\" font-weight=\"bold\">PINE PITCH COMPOSITE SEAL</text>\n    <text x=\"570\" y=\"220\" fill=\"#888888\">송진과 숯가루 혼합재로 유격 100% 밀봉</text>\n\n    <!-- Callout 3: Cross Lashing -->\n    <line x1=\"330\" y1=\"280\" x2=\"565\" y2=\"280\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"330\" cy=\"280\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"277\" fill=\"#ffffff\" font-weight=\"bold\">X-CROSS VINE LASHING</text>\n    <text x=\"570\" y=\"290\" fill=\"#888888\">충격을 흡수 분산하는 십자 결속 및 프래핑</text>\n\n    <!-- Callout 4: Oak Haft -->\n    <line x1=\"490\" y1=\"340\" x2=\"565\" y2=\"340\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"490\" cy=\"340\" r=\"2\" fill=\"#38bdf8\"/>\n    <text x=\"570\" y=\"337\" fill=\"#38bdf8\" font-weight=\"bold\">HARDENED OAK HAFT</text>\n    <text x=\"570\" y=\"350\" fill=\"#888888\">불에 그슬려 경화한 묵직한 참나무 손잡이</text>\n  </g>\n</svg>\n","content/svgs/pr04-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#E02424\" />\n    </marker>\n    <marker id=\"arrow-white\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#F5F5F5\" />\n    </marker>\n  </defs>\n\n  <!-- Background technical coordinate lines -->\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"#131313\" />\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4 4\" />\n  <line x1=\"340\" y1=\"20\" x2=\"340\" y2=\"320\" stroke=\"#222222\" stroke-width=\"1\" />\n\n  <!-- Core River Stone (Base Cobble) -->\n  <path d=\"M 220 275 C 180 265 145 225 155 180 C 165 140 210 130 260 135 C 310 140 345 165 350 210 C 355 250 310 280 220 275 Z\" \n        fill=\"#1c1b1b\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n  \n  <!-- Flake detachment line & fracture cone -->\n  <path d=\"M 310 150 Q 325 180 340 215\" stroke=\"#E02424\" stroke-width=\"2.2\" stroke-dasharray=\"3 3\" />\n  <path d=\"M 340 215 C 360 210 395 185 400 160 C 390 145 350 140 310 150 Z\" \n        fill=\"#262626\" stroke=\"#E02424\" stroke-width=\"2\" />\n\n  <!-- Detached Sharp Axe Blade (Separating Flake) -->\n  <path d=\"M 430 190 Q 480 145 520 180 Q 490 225 430 190 Z\" \n        fill=\"#1a1a1a\" stroke=\"#F5F5F5\" stroke-width=\"2\" />\n  <path d=\"M 430 190 Q 475 160 520 180\" stroke=\"#E02424\" stroke-width=\"2\" />\n\n  <!-- Hammerstone (Striking Stone) -->\n  <ellipse cx=\"280\" cy=\"70\" rx=\"42\" ry=\"30\" fill=\"#222222\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" transform=\"rotate(-25 280 70)\" />\n  \n  <!-- 45 Degree Kinetic Strike Vector -->\n  <line x1=\"260\" y1=\"85\" x2=\"310\" y2=\"148\" stroke=\"#E02424\" stroke-width=\"3\" marker-end=\"url(#arrow)\" />\n  \n  <!-- 45 Degree Angle Arc & Guide Lines -->\n  <line x1=\"310\" y1=\"150\" x2=\"380\" y2=\"150\" stroke=\"#737373\" stroke-width=\"1\" stroke-dasharray=\"3 3\" />\n  <line x1=\"310\" y1=\"150\" x2=\"260\" y2=\"90\" stroke=\"#737373\" stroke-width=\"1\" stroke-dasharray=\"3 3\" />\n  <path d=\"M 350 150 A 40 40 0 0 0 338 122\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"1.8\" />\n\n  <!-- Technical dimension line -->\n  <line x1=\"155\" y1=\"295\" x2=\"350\" y2=\"295\" stroke=\"#525252\" stroke-width=\"1\" />\n  <line x1=\"155\" y1=\"290\" x2=\"155\" y2=\"300\" stroke=\"#525252\" stroke-width=\"1\" />\n  <line x1=\"350\" y1=\"290\" x2=\"350\" y2=\"300\" stroke=\"#525252\" stroke-width=\"1\" />\n\n  <!-- 5 Clear Korean labels placed in non-overlapping safe zones -->\n  <rect x=\"25\" y=\"28\" width=\"205\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"44\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">① 둥근 망치돌 (내리치는 돌)</text>\n\n  <rect x=\"25\" y=\"84\" width=\"215\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"100\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\">② 모서리 45° 비스듬히 치기</text>\n\n  <rect x=\"420\" y=\"112\" width=\"225\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"430\" y=\"128\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\" font-weight=\"bold\">날카로운 돌날 (두께 1~2cm)</text>\n\n  <rect x=\"420\" y=\"245\" width=\"230\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"430\" y=\"261\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">④ 쪼개져 나온 도끼날 돌조각</text>\n\n  <text x=\"250\" y=\"316\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#9E9E9E\" text-anchor=\"middle\">③ 바닥에 받친 큰 강돌 (너비 15~20cm)</text>\n</svg>\n","content/svgs/pr04-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"#131313\" />\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4 4\" />\n\n  <!-- Wooden Handle (Shaft) -->\n  <path d=\"M 315 170 L 315 275 L 355 275 L 355 170 Z\" fill=\"#201f1f\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n  \n  <!-- Split Cleft Head (Two tines separated) -->\n  <path d=\"M 315 170 C 315 140 280 110 270 70 L 305 70 C 315 105 330 135 335 170 Z\" fill=\"#292828\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n  <path d=\"M 355 170 C 355 140 390 110 400 70 L 365 70 C 355 105 340 135 335 170 Z\" fill=\"#292828\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n\n  <!-- Split stop safety collar notch -->\n  <line x1=\"300\" y1=\"172\" x2=\"370\" y2=\"172\" stroke=\"#E02424\" stroke-width=\"2.2\" stroke-dasharray=\"3 2\" />\n\n  <!-- Melted Pine Resin + Charcoal Glue Bedding (Inside cleft) -->\n  <path d=\"M 305 130 C 315 150 335 168 335 168 C 335 168 355 150 365 130 C 355 110 315 110 305 130 Z\" \n        fill=\"#78350f\" stroke=\"#d97706\" stroke-width=\"1.5\" />\n  <circle cx=\"325\" cy=\"140\" r=\"2.5\" fill=\"#171717\" />\n  <circle cx=\"335\" cy=\"132\" r=\"2\" fill=\"#171717\" />\n  <circle cx=\"345\" cy=\"142\" r=\"2.5\" fill=\"#171717\" />\n  <circle cx=\"335\" cy=\"150\" r=\"1.8\" fill=\"#171717\" />\n\n  <!-- Wedged Stone Blade in Slot -->\n  <path d=\"M 230 100 L 440 100 L 415 135 L 255 135 Z\" fill=\"#333333\" stroke=\"#F5F5F5\" stroke-width=\"2\" />\n  <path d=\"M 230 100 Q 210 115 255 135\" stroke=\"#E02424\" stroke-width=\"2.5\" />\n\n  <!-- Insertion down vector -->\n  <line x1=\"335\" y1=\"30\" x2=\"335\" y2=\"85\" stroke=\"#E02424\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\" />\n\n  <!-- Dimension callout for handle diameter -->\n  <line x1=\"280\" y1=\"288\" x2=\"390\" y2=\"288\" stroke=\"#525252\" stroke-width=\"1\" />\n  <line x1=\"280\" y1=\"283\" x2=\"280\" y2=\"293\" stroke=\"#525252\" stroke-width=\"1\" />\n  <line x1=\"390\" y1=\"283\" x2=\"390\" y2=\"293\" stroke=\"#525252\" stroke-width=\"1\" />\n\n  <!-- 5 Clear Korean labels in safe zones -->\n  <rect x=\"420\" y=\"30\" width=\"225\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"430\" y=\"46\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">① 위에서 아래로 돌날 끼우기</text>\n\n  <rect x=\"25\" y=\"102\" width=\"175\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"118\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\" font-weight=\"bold\">나무 자르는 앞날</text>\n\n  <rect x=\"445\" y=\"96\" width=\"215\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"455\" y=\"112\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\">② 쪼갠 나무 자루 틈 (5~7cm)</text>\n\n  <rect x=\"430\" y=\"152\" width=\"230\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"440\" y=\"168\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">③ 녹인 송진 + 숯가루 채우기</text>\n\n  <rect x=\"25\" y=\"220\" width=\"255\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"236\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">④ 더 안 갈라지게 아래쪽 먼저 묶기</text>\n\n  <text x=\"335\" y=\"314\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#9E9E9E\" text-anchor=\"middle\">생나무 자루 굵기: 지름 3.5~4cm</text>\n</svg>\n","content/svgs/pr04-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"#131313\" />\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4 4\" />\n\n  <!-- Wooden Shaft Handle -->\n  <rect x=\"315\" y=\"45\" width=\"45\" height=\"225\" fill=\"#201f1f\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n  \n  <!-- Stone Blade Head Fixed Horizontally -->\n  <path d=\"M 200 90 L 470 90 L 440 145 L 230 145 Z\" fill=\"#2e2d2d\" stroke=\"#F5F5F5\" stroke-width=\"2\" />\n  <path d=\"M 200 90 Q 180 115 230 145\" stroke=\"#E02424\" stroke-width=\"3\" />\n\n  <!-- Cross-Lashing Vine Bands (X-Pattern) -->\n  <line x1=\"280\" y1=\"80\" x2=\"390\" y2=\"160\" stroke=\"#84cc16\" stroke-width=\"4.5\" stroke-linecap=\"round\" />\n  <line x1=\"285\" y1=\"75\" x2=\"395\" y2=\"155\" stroke=\"#4d7c0f\" stroke-width=\"3\" stroke-linecap=\"round\" />\n  <line x1=\"390\" y1=\"80\" x2=\"280\" y2=\"160\" stroke=\"#84cc16\" stroke-width=\"4.5\" stroke-linecap=\"round\" />\n  <line x1=\"395\" y1=\"75\" x2=\"285\" y2=\"155\" stroke=\"#4d7c0f\" stroke-width=\"3\" stroke-linecap=\"round\" />\n\n  <!-- Horizontal securing turns around shaft collar -->\n  <rect x=\"305\" y=\"165\" width=\"65\" height=\"40\" fill=\"#3f6212\" stroke=\"#84cc16\" stroke-width=\"1.5\" />\n  <line x1=\"305\" y1=\"175\" x2=\"370\" y2=\"175\" stroke=\"#ecfccb\" stroke-width=\"1\" />\n  <line x1=\"305\" y1=\"185\" x2=\"370\" y2=\"185\" stroke=\"#ecfccb\" stroke-width=\"1\" />\n  <line x1=\"305\" y1=\"195\" x2=\"370\" y2=\"195\" stroke=\"#ecfccb\" stroke-width=\"1\" />\n\n  <!-- Inward tension arrows (Shrinkage vectors) -->\n  <line x1=\"250\" y1=\"120\" x2=\"290\" y2=\"120\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow)\" />\n  <line x1=\"420\" y1=\"120\" x2=\"380\" y2=\"120\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow)\" />\n  <line x1=\"337\" y1=\"225\" x2=\"337\" y2=\"208\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow)\" />\n\n  <!-- 5 Clear Korean labels in safe zones -->\n  <rect x=\"415\" y=\"30\" width=\"235\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"425\" y=\"46\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#84cc16\">① 젖은 칡 속껍질 X자로 감기</text>\n\n  <rect x=\"25\" y=\"95\" width=\"160\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"111\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\">② 날카로운 도끼 앞날</text>\n\n  <rect x=\"415\" y=\"172\" width=\"235\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"425\" y=\"188\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">③ 자루 아래쪽 가로로 칭칭 감기</text>\n\n  <rect x=\"415\" y=\"232\" width=\"235\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"425\" y=\"248\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\">④ 마르면서 30% 줄어들며 꽉 조임</text>\n\n  <text x=\"340\" y=\"308\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\" text-anchor=\"middle\" font-weight=\"bold\">완성 상태: 세게 내리쳐도 돌날이 빠지지 않는 일체형 돌도끼</text>\n</svg>\n","content/svgs/pr05-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <linearGradient id=\"bgGrad5\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0c0d0c\"/>\n      <stop offset=\"100%\" stop-color=\"#141814\"/>\n    </linearGradient>\n\n    <!-- Natural Cordage Fiber Gradients -->\n    <linearGradient id=\"cordLight\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#80623f\"/>\n      <stop offset=\"50%\" stop-color=\"#bda078\"/>\n      <stop offset=\"100%\" stop-color=\"#694d2f\"/>\n    </linearGradient>\n    <linearGradient id=\"cordDark\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#543e26\"/>\n      <stop offset=\"50%\" stop-color=\"#8a6c47\"/>\n      <stop offset=\"100%\" stop-color=\"#402d1a\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad5)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Title & Top Metrics -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: 2-PLY REVERSE-WRAPPED NATURAL CORDAGE</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">TENSILE LOAD: 90+ KGF</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">CORDAGE METRICS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· STRUCTURE: 2-PLY REVERSE</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· STRAND TWIST: CLOCKWISE</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· PLY INTERLOCK: COUNTER-CW</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· SPLICING: 1/3 STAGGERED</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· DIAMETER: 8.0 MM UNIFORM</text>\n    <text x=\"55\" y=\"240\" fill=\"#4ade80\">· TENSILE BREAK: 92.4 KGF</text>\n  </g>\n\n  <!-- Ground Plane Shadow -->\n  <ellipse cx=\"430\" cy=\"385\" rx=\"180\" ry=\"18\" fill=\"#060606\" opacity=\"0.9\"/>\n\n  <!-- Coiled Rope Bundle (원형 코일 다발) -->\n  <g id=\"ropeCoil\">\n    <!-- Back Loop Turns -->\n    <ellipse cx=\"400\" cy=\"270\" rx=\"90\" ry=\"60\" fill=\"none\" stroke=\"url(#cordDark)\" stroke-width=\"10\"/>\n    <ellipse cx=\"402\" cy=\"265\" rx=\"85\" ry=\"55\" fill=\"none\" stroke=\"url(#cordLight)\" stroke-width=\"9\"/>\n    <ellipse cx=\"398\" cy=\"260\" rx=\"80\" ry=\"50\" fill=\"none\" stroke=\"url(#cordDark)\" stroke-width=\"9\"/>\n\n    <!-- Front Loop Turns -->\n    <ellipse cx=\"400\" cy=\"275\" rx=\"95\" ry=\"65\" fill=\"none\" stroke=\"url(#cordLight)\" stroke-width=\"10\"/>\n    <ellipse cx=\"405\" cy=\"280\" rx=\"90\" ry=\"60\" fill=\"none\" stroke=\"url(#cordDark)\" stroke-width=\"9\"/>\n    <ellipse cx=\"395\" cy=\"285\" rx=\"85\" ry=\"55\" fill=\"none\" stroke=\"url(#cordLight)\" stroke-width=\"10\"/>\n\n    <!-- Center Binding Collar (다발 고정 묶음) -->\n    <rect x=\"382\" y=\"210\" width=\"36\" height=\"135\" rx=\"6\" fill=\"#4d3722\" stroke=\"#2b1d10\" stroke-width=\"2\"/>\n    <!-- Individual Wrap Wrappings Around Center -->\n    <g stroke=\"url(#cordLight)\" stroke-width=\"5\" stroke-linecap=\"round\">\n      <line x1=\"384\" y1=\"225\" x2=\"416\" y2=\"225\"/>\n      <line x1=\"384\" y1=\"240\" x2=\"416\" y2=\"240\"/>\n      <line x1=\"384\" y1=\"255\" x2=\"416\" y2=\"255\"/>\n      <line x1=\"384\" y1=\"270\" x2=\"416\" y2=\"270\"/>\n      <line x1=\"384\" y1=\"285\" x2=\"416\" y2=\"285\"/>\n      <line x1=\"384\" y1=\"300\" x2=\"416\" y2=\"300\"/>\n      <line x1=\"384\" y1=\"315\" x2=\"416\" y2=\"315\"/>\n      <line x1=\"384\" y1=\"330\" x2=\"416\" y2=\"330\"/>\n    </g>\n\n    <!-- Trailing Working End with Figure-8 Stopper Knot -->\n    <path d=\"M 400 340 Q 370 380 320 375 Q 290 370 270 380\" fill=\"none\" stroke=\"url(#cordLight)\" stroke-width=\"9\" stroke-linecap=\"round\"/>\n    <!-- Figure-8 Knot Ball -->\n    <circle cx=\"270\" cy=\"380\" r=\"10\" fill=\"#735435\" stroke=\"#3b2b1a\" stroke-width=\"2\"/>\n    <path d=\"M 264 374 Q 270 386 276 374\" stroke=\"#d4b483\" stroke-width=\"2.5\" fill=\"none\"/>\n  </g>\n\n  <!-- Zoom Loupe Window for Micro Reverse-Wrap Detail -->\n  <g id=\"microDetailWindow\" transform=\"translate(180, 110)\">\n    <!-- Lens Circle -->\n    <circle cx=\"150\" cy=\"50\" r=\"48\" fill=\"#141414\" stroke=\"#444\" stroke-width=\"2\"/>\n    <!-- Interior 2-Ply Braid Micro Strands -->\n    <g stroke-width=\"4.5\" stroke-linecap=\"round\">\n      <!-- Strand A (Dark Bast) -->\n      <path d=\"M 115 35 Q 130 30 145 45 Q 160 60 175 45 Q 190 30 195 40\" fill=\"none\" stroke=\"#694d2f\"/>\n      <!-- Strand B (Light Kudzu) -->\n      <path d=\"M 115 55 Q 130 65 145 45 Q 160 25 175 45 Q 190 65 195 55\" fill=\"none\" stroke=\"#c4a57b\"/>\n      <!-- Surface Twisting Hatch Lines -->\n      <line x1=\"124\" y1=\"38\" x2=\"128\" y2=\"44\" stroke=\"#3d2b18\" stroke-width=\"1.2\"/>\n      <line x1=\"154\" y1=\"48\" x2=\"158\" y2=\"54\" stroke=\"#3d2b18\" stroke-width=\"1.2\"/>\n      <line x1=\"138\" y1=\"48\" x2=\"142\" y2=\"54\" stroke=\"#edd6b6\" stroke-width=\"1.2\"/>\n      <line x1=\"168\" y1=\"38\" x2=\"172\" y2=\"44\" stroke=\"#edd6b6\" stroke-width=\"1.2\"/>\n    </g>\n    <!-- Loupe Label -->\n    <text x=\"150\" y=\"88\" fill=\"#888\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">5X MAGNIFICATION</text>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Reverse Wrap Mechanics -->\n    <line x1=\"375\" y1=\"150\" x2=\"565\" y2=\"150\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"375\" cy=\"150\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"147\" fill=\"#E02424\" font-weight=\"bold\">2-PLY REVERSE INTERLOCK</text>\n    <text x=\"570\" y=\"160\" fill=\"#888888\">자체 마찰력으로 당길수록 더 단단히 조임</text>\n\n    <!-- Callout 2: Center Collar -->\n    <line x1=\"418\" y1=\"250\" x2=\"565\" y2=\"250\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"418\" cy=\"250\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"247\" fill=\"#ffffff\" font-weight=\"bold\">EXPEDITION COIL PACK</text>\n    <text x=\"570\" y=\"260\" fill=\"#888888\">엉킴 없이 즉각 풀리는 야전 휴대 권취</text>\n\n    <!-- Callout 3: Tensile Strength -->\n    <line x1=\"480\" y1=\"310\" x2=\"565\" y2=\"310\" stroke=\"#4ade80\" stroke-width=\"1\"/>\n    <circle cx=\"480\" cy=\"310\" r=\"2\" fill=\"#4ade80\"/>\n    <text x=\"570\" y=\"307\" fill=\"#4ade80\" font-weight=\"bold\">TENSILE BREAK: 90+ KGF</text>\n    <text x=\"570\" y=\"320\" fill=\"#888888\">성인 체중 및 쉘터 가이라인 완벽 지지</text>\n\n    <!-- Callout 4: Figure-8 Stopper -->\n    <line x1=\"280\" y1=\"380\" x2=\"565\" y2=\"380\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"280\" cy=\"380\" r=\"2\" fill=\"#38bdf8\"/>\n    <text x=\"570\" y=\"377\" fill=\"#38bdf8\" font-weight=\"bold\">FIGURE-8 STOPPER KNOT</text>\n    <text x=\"570\" y=\"390\" fill=\"#888888\">말단 올 풀림을 영구 방지하는 8자 마감</text>\n  </g>\n</svg>\n","content/svgs/pr05-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Grid & Guide lines -->\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Outer circle (Stem cross section) -->\n  <circle cx=\"190\" cy=\"175\" r=\"95\" fill=\"#1C1814\" stroke=\"#8B5A2B\" stroke-width=\"5\" />\n  <circle cx=\"190\" cy=\"175\" r=\"82\" fill=\"#242820\" stroke=\"#E5E5E5\" stroke-dasharray=\"3 3\" stroke-width=\"2.5\" />\n  <circle cx=\"190\" cy=\"175\" r=\"45\" fill=\"#151515\" stroke=\"#444444\" stroke-width=\"2\" />\n  <circle cx=\"190\" cy=\"175\" r=\"6\" fill=\"#666666\" />\n\n  <!-- Stone scraper tool peeling bark -->\n  <path d=\"M175,78 L240,48 L228,92 Z\" fill=\"#3A3A3A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <path d=\"M195,85 Q235,90 265,70\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"2\" stroke-dasharray=\"4 2\"/>\n\n  <!-- Bent living vine diagram -->\n  <path d=\"M350,245 Q430,135 545,195\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"6\"/>\n  <circle cx=\"350\" cy=\"245\" r=\"4\" fill=\"#10B981\"/>\n  <circle cx=\"545\" cy=\"195\" r=\"4\" fill=\"#10B981\"/>\n\n  <!-- Peel strand visualization -->\n  <path d=\"M265,125 C305,105 350,135 395,115\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"5\"/>\n  <path d=\"M275,145 C315,125 360,155 405,135\" fill=\"none\" stroke=\"#8B5A2B\" stroke-width=\"4\"/>\n\n  <!-- Callout lines -->\n  <line x1=\"240\" y1=\"58\" x2=\"295\" y2=\"48\" stroke=\"#E5E5E5\" stroke-width=\"1.2\"/>\n  <line x1=\"265\" y1=\"120\" x2=\"295\" y2=\"95\" stroke=\"#8B5A2B\" stroke-width=\"1.2\"/>\n  <line x1=\"270\" y1=\"165\" x2=\"295\" y2=\"145\" stroke=\"#E5E5E5\" stroke-width=\"1.2\"/>\n  <line x1=\"190\" y1=\"175\" x2=\"295\" y2=\"205\" stroke=\"#888888\" stroke-width=\"1.2\"/>\n\n  <!-- 5 Clean, Non-Overlapping Labels -->\n  <text x=\"300\" y=\"52\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">① 돌 모서리로 거친 겉껍질만 살살 긁어내기</text>\n  <text x=\"300\" y=\"98\" fill=\"#C49A6C\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">② 잘 부러지는 갈색 겉껍질 (긁어내어 버림)</text>\n  <text x=\"300\" y=\"148\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">③ 질기고 하얀 속껍질 섬유층 (밧줄 핵심 재료)</text>\n  <text x=\"300\" y=\"208\" fill=\"#9E9E9E\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">④ 가운데 딱딱한 나무 속심 (빼내고 버림)</text>\n  <text x=\"260\" y=\"295\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 구부렸을 때 부러지지 않고 휘어지는 살아있는 줄기</text>\n</svg>","content/svgs/pr05-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Water stream / pool zone on left -->\n  <rect x=\"70\" y=\"80\" width=\"130\" height=\"90\" fill=\"#102528\" stroke=\"#007788\" stroke-width=\"1.5\"/>\n  <path d=\"M75,115 Q135,95 195,115\" fill=\"none\" stroke=\"#00B4D8\" stroke-width=\"2\"/>\n  <path d=\"M75,135 Q135,155 195,135\" fill=\"none\" stroke=\"#00B4D8\" stroke-width=\"2\"/>\n  <path d=\"M90,100 Q120,150 170,110\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"3\"/>\n\n  <!-- Flat anvil stone in center -->\n  <polygon points=\"240,225 450,225 470,265 220,265\" fill=\"#282828\" stroke=\"#666666\" stroke-width=\"2\"/>\n\n  <!-- Round hand hammer stone -->\n  <ellipse cx=\"335\" cy=\"145\" rx=\"36\" ry=\"26\" fill=\"#3D3D3D\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <line x1=\"335\" y1=\"175\" x2=\"335\" y2=\"210\" stroke=\"#E02424\" stroke-width=\"2.5\" stroke-dasharray=\"3 3\"/>\n  <polygon points=\"330,205 335,218 340,205\" fill=\"#E02424\"/>\n\n  <!-- Crushed soft fiber on the stone -->\n  <path d=\"M270,220 C310,210 350,230 400,220\" stroke=\"#E5E5E5\" stroke-width=\"6\"/>\n  <path d=\"M280,217 C320,223 360,215 395,221\" stroke=\"#9E9E9E\" stroke-width=\"2\"/>\n\n  <!-- Two split bundles on right -->\n  <path d=\"M490,145 Q525,180 575,170\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"4\"/>\n  <path d=\"M490,215 Q525,195 575,225\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"4\"/>\n  <circle cx=\"490\" cy=\"180\" r=\"14\" fill=\"none\" stroke=\"#D97706\" stroke-width=\"2\" stroke-dasharray=\"2 2\"/>\n\n  <!-- 5 Clean, Non-Overlapping Labels -->\n  <text x=\"70\" y=\"55\" fill=\"#00B4D8\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">① 냇물에 20분 이상 담가 부드럽게 불린 속껍질</text>\n  <text x=\"250\" y=\"98\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">② 둥근 돌로 살살 두드려 섬유 결 쪼개기</text>\n  <text x=\"380\" y=\"135\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">③ 머리카락처럼 부드럽게 풀어진 섬유 다발</text>\n  <text x=\"380\" y=\"255\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">④ 손가락 굵기로 똑같이 나눈 두 가닥</text>\n  <text x=\"190\" y=\"298\" fill=\"#9E9E9E\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 바닥에 흔들리지 않게 받친 평평한 강돌</text>\n</svg>","content/svgs/pr05-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Left finished twisted rope -->\n  <g transform=\"translate(95, 165)\">\n    <path d=\"M0,0 C20,-15 40,15 60,0 C80,-15 100,15 120,0 C140,-15 160,15 180,0\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"10\"/>\n    <path d=\"M0,0 C20,15 40,-15 60,0 C80,15 100,-15 120,0 C140,15 160,-15 180,0\" fill=\"none\" stroke=\"#888888\" stroke-width=\"7\"/>\n  </g>\n\n  <!-- Left hand pinch point -->\n  <circle cx=\"275\" cy=\"165\" r=\"18\" fill=\"#1E1E1E\" stroke=\"#E02424\" stroke-width=\"2.5\"/>\n  <circle cx=\"275\" cy=\"165\" r=\"4\" fill=\"#E02424\"/>\n\n  <!-- Top strand twisting outward (away from body) -->\n  <path d=\"M290,157 Q365,115 445,110\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"7\"/>\n  <path d=\"M365,120 C370,95 390,90 400,105\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"3\"/>\n  <polygon points=\"400,97 407,107 395,110\" fill=\"#10B981\"/>\n\n  <!-- Bottom strand crossing over towards body -->\n  <path d=\"M290,173 Q355,215 445,220\" fill=\"none\" stroke=\"#888888\" stroke-width=\"7\"/>\n  <path d=\"M375,135 C405,155 395,185 385,200\" fill=\"none\" stroke=\"#D97706\" stroke-width=\"3\" stroke-dasharray=\"4 2\"/>\n  <polygon points=\"380,193 383,207 393,198\" fill=\"#D97706\"/>\n\n  <!-- Double lock icon/diagram on right -->\n  <rect x=\"490\" y=\"115\" width=\"110\" height=\"95\" fill=\"#151515\" stroke=\"#333333\" stroke-width=\"1.5\"/>\n  <path d=\"M520,162 L570,162 M545,137 L545,187\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <circle cx=\"545\" cy=\"162\" r=\"18\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"2\"/>\n\n  <!-- 5 Clean, Non-Overlapping Labels -->\n  <text x=\"250\" y=\"62\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">① 위쪽 가닥: 몸 바깥쪽(↑)으로 단단히 비틀기</text>\n  <text x=\"70\" y=\"115\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">② 서로 되감기며 톱니처럼 맞물린 밧줄 무늬</text>\n  <text x=\"70\" y=\"218\" fill=\"#E02424\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">③ 왼손 엄지·검지로 꼬인 자리 꽉 눌러 잡기</text>\n  <text x=\"250\" y=\"258\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">④ 비튼 위 가닥을 아래 가닥 너머 몸 쪽(↓)으로 넘기기</text>\n  <text x=\"280\" y=\"298\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 손을 놓아도 절대 풀리지 않는 역방향 잠금 구조</text>\n</svg>","content/svgs/pr05-step-04.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Top strand: Thinned old strand + New thick strand overlap -->\n  <g transform=\"translate(80, 120)\">\n    <path d=\"M0,20 L160,20\" stroke=\"#888888\" stroke-width=\"5\"/>\n    <path d=\"M160,20 L260,20\" stroke=\"#888888\" stroke-width=\"2.5\" stroke-dasharray=\"2 2\"/>\n    <path d=\"M160,10 L260,10\" stroke=\"#10B981\" stroke-width=\"3\"/>\n    <path d=\"M260,10 L430,10\" stroke=\"#10B981\" stroke-width=\"6\"/>\n    <line x1=\"160\" y1=\"-5\" x2=\"260\" y2=\"-5\" stroke=\"#E02424\" stroke-width=\"1.5\"/>\n    <line x1=\"160\" y1=\"-10\" x2=\"160\" y2=\"0\" stroke=\"#E02424\" stroke-width=\"1.5\"/>\n    <line x1=\"260\" y1=\"-10\" x2=\"260\" y2=\"0\" stroke=\"#E02424\" stroke-width=\"1.5\"/>\n  </g>\n\n  <!-- Bottom strand: Staggered junction 15cm further right -->\n  <g transform=\"translate(80, 200)\">\n    <path d=\"M0,20 L300,20\" stroke=\"#888888\" stroke-width=\"5\"/>\n    <path d=\"M300,20 L400,20\" stroke=\"#888888\" stroke-width=\"2.5\" stroke-dasharray=\"2 2\"/>\n    <path d=\"M300,10 L400,10\" stroke=\"#D97706\" stroke-width=\"3\"/>\n    <path d=\"M400,10 L470,10\" stroke=\"#D97706\" stroke-width=\"6\"/>\n    <line x1=\"210\" y1=\"45\" x2=\"350\" y2=\"45\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/>\n    <polygon points=\"210,41 202,45 210,49\" fill=\"#E5E5E5\"/>\n    <polygon points=\"350,41 358,45 350,49\" fill=\"#E5E5E5\"/>\n  </g>\n\n  <!-- Smooth twisted rope preview on far right -->\n  <path d=\"M520,165 C545,150 570,180 595,165\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"8\"/>\n\n  <!-- 5 Clean, Non-Overlapping Top-Level Labels -->\n  <text x=\"75\" y=\"58\" fill=\"#9E9E9E\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">① 끝이 10cm쯤 남아 가늘어진 기존 가닥</text>\n  <text x=\"235\" y=\"96\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">② 새 섬유 다발을 10cm 나란히 겹쳐 대기</text>\n  <text x=\"75\" y=\"178\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">③ 겹친 두 줄을 한 가닥처럼 함께 비틀어 감기</text>\n  <text x=\"360\" y=\"232\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">④ 불룩해지지 않고 매끄럽게 이어진 연결부</text>\n  <text x=\"150\" y=\"295\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 위·아래 이음매 위치를 한 뼘(15cm) 어긋나게 배치</text>\n</svg>","content/svgs/pr05-step-05.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Tree trunk on left -->\n  <rect x=\"95\" y=\"75\" width=\"55\" height=\"205\" fill=\"#221C18\" stroke=\"#665544\" stroke-width=\"3\"/>\n  <path d=\"M95,115 L150,115 M95,175 L150,175 M95,235 L150,235\" stroke=\"#443322\" stroke-width=\"1\"/>\n\n  <!-- Rope wrapped around tree trunk -->\n  <ellipse cx=\"122\" cy=\"155\" rx=\"33\" ry=\"12\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"6\"/>\n  <line x1=\"155\" y1=\"155\" x2=\"425\" y2=\"155\" stroke=\"#E5E5E5\" stroke-width=\"6\"/>\n\n  <!-- End eye knot -->\n  <g transform=\"translate(425, 155)\">\n    <circle cx=\"20\" cy=\"0\" r=\"16\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"5\"/>\n    <rect x=\"0\" y=\"-8\" width=\"12\" height=\"16\" fill=\"#E02424\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Stone scraper trimming loose fuzz -->\n  <polygon points=\"310,115 350,100 340,130\" fill=\"#444444\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M290,152 L295,140 M305,152 L310,143 M320,152 L325,141\" stroke=\"#9E9E9E\" stroke-width=\"1.5\"/>\n\n  <!-- Body weight tension indicator arrow -->\n  <g transform=\"translate(310, 168)\">\n    <line x1=\"0\" y1=\"10\" x2=\"65\" y2=\"10\" stroke=\"#E02424\" stroke-width=\"3\"/>\n    <polygon points=\"65,5 77,10 65,15\" fill=\"#E02424\"/>\n  </g>\n\n  <!-- Practical usage box on right -->\n  <rect x=\"495\" y=\"105\" width=\"110\" height=\"110\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\"/>\n  <line x1=\"510\" y1=\"135\" x2=\"590\" y2=\"135\" stroke=\"#10B981\" stroke-width=\"2\"/>\n  <line x1=\"510\" y1=\"160\" x2=\"590\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <line x1=\"510\" y1=\"185\" x2=\"590\" y2=\"185\" stroke=\"#D97706\" stroke-width=\"2\"/>\n\n  <!-- 5 Clean, Non-Overlapping Top-Level Labels -->\n  <text x=\"270\" y=\"62\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">① 끝부분 3cm를 접어 묶은 풀림 방지 마감 매듭</text>\n  <text x=\"175\" y=\"102\" fill=\"#9E9E9E\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">② 삐져나온 잔털을 돌날로 깔끔하게 정리</text>\n  <text x=\"175\" y=\"212\" fill=\"#E02424\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">③ 나무 기둥에 걸고 몸무게(50kg+)를 실어 당겨보기</text>\n  <text x=\"175\" y=\"255\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">④ 완성된 5mm 굵기 야생 밧줄 (5m 길이)</text>\n  <text x=\"210\" y=\"298\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 움막 기둥 묶기·돌도끼 고정·활비비 줄로 즉시 활용</text>\n</svg>","content/svgs/pr06-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <linearGradient id=\"bgGrad6\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0e0c0b\"/>\n      <stop offset=\"100%\" stop-color=\"#17120f\"/>\n    </linearGradient>\n\n    <!-- Clay & Terracotta Plaster Gradients -->\n    <linearGradient id=\"clayPlaster\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#a8653b\"/>\n      <stop offset=\"40%\" stop-color=\"#8c4e26\"/>\n      <stop offset=\"80%\" stop-color=\"#693717\"/>\n      <stop offset=\"100%\" stop-color=\"#45230c\"/>\n    </linearGradient>\n    <linearGradient id=\"stoneBlock\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#4a4a4a\"/>\n      <stop offset=\"50%\" stop-color=\"#737373\"/>\n      <stop offset=\"100%\" stop-color=\"#3d3d3d\"/>\n    </linearGradient>\n\n    <!-- Glowing Firebox Interior -->\n    <radialGradient id=\"hearthFireGlow\" cx=\"50%\" cy=\"60%\" r=\"55%\">\n      <stop offset=\"0%\" stop-color=\"#ffffff\"/>\n      <stop offset=\"20%\" stop-color=\"#fef08a\"/>\n      <stop offset=\"50%\" stop-color=\"#f97316\"/>\n      <stop offset=\"80%\" stop-color=\"#dc2626\"/>\n      <stop offset=\"100%\" stop-color=\"#140804\"/>\n    </radialGradient>\n\n    <filter id=\"heatBlur\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\">\n      <feGaussianBlur stdDeviation=\"2\"/>\n    </filter>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad6)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Metadata -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: STONE &amp; TEMPERED CLAY HEARTH [650°C SPEC]</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">MAX TEMP: 650°C</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">HEARTH METRICS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· BASE: U-SHAPE RIVER STONE</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· CLAY WALL: 50 MM THICK</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· DRAFT: REAR EXHAUST FLUE</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· COOKTOP: LEVEL STONE RIM</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· FUEL EFF: 3X WOOD SAVING</text>\n    <text x=\"55\" y=\"240\" fill=\"#f97316\">· CORE TEMP: 650°C INTENSE</text>\n  </g>\n\n  <!-- Ground Plane Shadow -->\n  <ellipse cx=\"430\" cy=\"390\" rx=\"220\" ry=\"20\" fill=\"#050302\" opacity=\"0.9\"/>\n\n  <!-- Clay & Stone Hearth Structure (3D Perspective) -->\n  <g id=\"hearth3D\">\n    <!-- Foundation River Stones Layer (Base Tier) -->\n    <g id=\"baseStones\">\n      <ellipse cx=\"290\" cy=\"365\" rx=\"32\" ry=\"18\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"340\" cy=\"375\" rx=\"35\" ry=\"19\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"400\" cy=\"380\" rx=\"38\" ry=\"20\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"460\" cy=\"375\" rx=\"35\" ry=\"19\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"510\" cy=\"365\" rx=\"32\" ry=\"18\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n    </g>\n\n    <!-- Main Terracotta Clay Domed Wall Body -->\n    <path d=\"M 270 360 C 270 230 330 180 400 180 C 470 180 530 230 530 360 Z\" fill=\"url(#clayPlaster)\" stroke=\"#381907\" stroke-width=\"2\"/>\n\n    <!-- Clay Drying Cracks & Straw Binder Texture -->\n    <g stroke=\"#52240b\" stroke-width=\"1.2\" fill=\"none\" opacity=\"0.7\">\n      <path d=\"M 320 250 Q 335 265 330 285\"/>\n      <path d=\"M 470 240 Q 460 260 475 275\"/>\n      <path d=\"M 360 210 Q 380 220 375 235\"/>\n      <path d=\"M 430 215 Q 420 230 435 245\"/>\n    </g>\n\n    <!-- Top Level Cooking Platform Rim (돌판/냄비 얹는 조리구) -->\n    <ellipse cx=\"400\" cy=\"180\" rx=\"55\" ry=\"18\" fill=\"#4d4d4d\" stroke=\"#262626\" stroke-width=\"2\"/>\n    <ellipse cx=\"400\" cy=\"180\" rx=\"42\" ry=\"13\" fill=\"#171717\" stroke=\"#333\" stroke-width=\"1.5\"/>\n\n    <!-- Rear Vertical Chimney Flue (후면 배기 굴뚝) -->\n    <g id=\"chimneyFlue\">\n      <path d=\"M 465 190 L 485 130 L 515 130 L 505 210 Z\" fill=\"url(#clayPlaster)\" stroke=\"#381907\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"500\" cy=\"130\" rx=\"15\" ry=\"6\" fill=\"#140804\" stroke=\"#381907\" stroke-width=\"1.2\"/>\n      <!-- Hot Chimney Exhaust Heat Shimmer -->\n      <path d=\"M 500 125 Q 492 95 505 75 Q 515 55 500 35\" stroke=\"#f97316\" stroke-width=\"2\" fill=\"none\" opacity=\"0.4\" filter=\"url(#heatBlur)\"/>\n      <path d=\"M 504 125 Q 512 90 498 70\" stroke=\"#fef08a\" stroke-width=\"1.5\" fill=\"none\" opacity=\"0.5\" filter=\"url(#heatBlur)\"/>\n    </g>\n\n    <!-- Front Firebox Mouth (연소실 아치 개구부) -->\n    <path d=\"M 335 365 C 335 250 465 250 465 365 Z\" fill=\"#0d0401\" stroke=\"#260f04\" stroke-width=\"2\"/>\n    <!-- Intense Glowing Radiant Embers in Firebox -->\n    <ellipse cx=\"400\" cy=\"340\" rx=\"60\" ry=\"24\" fill=\"url(#hearthFireGlow)\"/>\n\n    <!-- Firewood Logs & Core Flames Inside -->\n    <!-- Charred Log 1 -->\n    <polygon points=\"350,355 425,325 435,335 360,365\" fill=\"#1c1109\" stroke=\"#080402\" stroke-width=\"1\"/>\n    <!-- Charred Log 2 -->\n    <polygon points=\"445,355 375,325 365,335 435,365\" fill=\"#1c1109\" stroke=\"#080402\" stroke-width=\"1\"/>\n    <!-- Active Flame Tongues -->\n    <path d=\"M 400 345 C 385 330 380 300 400 270 C 405 285 412 290 410 275 C 418 285 425 305 420 330 C 425 320 428 310 424 298 C 432 312 430 335 415 345 Z\" fill=\"#f97316\" filter=\"url(#heatBlur)\"/>\n    <ellipse cx=\"402\" cy=\"335\" rx=\"14\" ry=\"18\" fill=\"#fef08a\"/>\n    <ellipse cx=\"402\" cy=\"335\" rx=\"8\" ry=\"10\" fill=\"#ffffff\"/>\n\n    <!-- Inflow Air Draft Direction Arrows (하단 산소 흡입) -->\n    <g stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"none\">\n      <path d=\"M 300 375 Q 330 365 350 355\"/>\n      <path d=\"M 500 375 Q 470 365 450 355\"/>\n    </g>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Chimney Flue -->\n    <line x1=\"505\" y1=\"130\" x2=\"565\" y2=\"130\" stroke=\"#f97316\" stroke-width=\"1\"/>\n    <circle cx=\"505\" cy=\"130\" r=\"2\" fill=\"#f97316\"/>\n    <text x=\"570\" y=\"127\" fill=\"#f97316\" font-weight=\"bold\">REAR EXHAUST CHIMNEY</text>\n    <text x=\"570\" y=\"140\" fill=\"#888888\">후면 굴뚝 상승 기류로 불완전연소 방지</text>\n\n    <!-- Callout 2: Top Cooktop Rim -->\n    <line x1=\"455\" y1=\"180\" x2=\"565\" y2=\"180\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"455\" cy=\"180\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"177\" fill=\"#ffffff\" font-weight=\"bold\">LEVEL COOKING RIM</text>\n    <text x=\"570\" y=\"190\" fill=\"#888888\">냄비·판석을 안정되게 얹는 직화 가열구</text>\n\n    <!-- Callout 3: 5cm Clay Wall -->\n    <line x1=\"510\" y1=\"260\" x2=\"565\" y2=\"260\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"510\" cy=\"260\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"257\" fill=\"#E02424\" font-weight=\"bold\">5CM CLAY INSULATION</text>\n    <text x=\"570\" y=\"270\" fill=\"#888888\">볏짚 황토 미장으로 열기를 가두어 650°C 유지</text>\n\n    <!-- Callout 4: Arch Inflow Draft -->\n    <line x1=\"465\" y1=\"340\" x2=\"565\" y2=\"340\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"465\" cy=\"340\" r=\"2\" fill=\"#38bdf8\"/>\n    <text x=\"570\" y=\"337\" fill=\"#38bdf8\" font-weight=\"bold\">INFLOW DRAFT ARCH</text>\n    <text x=\"570\" y=\"350\" fill=\"#888888\">바람을 막고 하단 산소를 흡입하는 아치 입구</text>\n  </g>\n</svg>\n","content/svgs/pr06-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <defs>\n            <marker id=\"arrow-step1\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#06B6D4\" />\n            </marker>\n          </defs>\n\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 01 // CLAY TEMPERING &amp; FIBER MATRIX BLUEPRINT\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Material 1: 붉은 찰흙 2바가지 -->\n          <g transform=\"translate(100, 70)\">\n            <ellipse cx=\"45\" cy=\"45\" rx=\"38\" ry=\"24\" fill=\"#1C1815\" stroke=\"#D97706\" stroke-width=\"1.5\" />\n            <path d=\"M 20 45 Q 45 15 70 45\" stroke=\"#D97706\" stroke-width=\"1\" fill=\"none\" stroke-dasharray=\"2,2\" />\n            <circle cx=\"45\" cy=\"35\" r=\"4\" fill=\"#D97706\" />\n          </g>\n          <text x=\"80\" y=\"155\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 붉은 찰흙 2바가지\n          </text>\n          <text x=\"80\" y=\"175\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            끈끈한 점력의 기본 바탕재\n          </text>\n\n          <!-- Plus Sign 1 -->\n          <text x=\"210\" y=\"115\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"18\" font-weight=\"bold\">+</text>\n\n          <!-- Material 2: 굵은 모래 1바가지 -->\n          <g transform=\"translate(235, 75)\">\n            <ellipse cx=\"40\" cy=\"40\" rx=\"34\" ry=\"20\" fill=\"#151717\" stroke=\"#06B6D4\" stroke-width=\"1.5\" />\n            <!-- Sand speckles -->\n            <circle cx=\"28\" cy=\"38\" r=\"1.5\" fill=\"#06B6D4\" />\n            <circle cx=\"42\" cy=\"32\" r=\"1.5\" fill=\"#06B6D4\" />\n            <circle cx=\"50\" cy=\"42\" r=\"1.5\" fill=\"#06B6D4\" />\n            <circle cx=\"35\" cy=\"45\" r=\"1.5\" fill=\"#06B6D4\" />\n          </g>\n          <text x=\"235\" y=\"155\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② 굵은 모래 1바가지\n          </text>\n          <text x=\"235\" y=\"175\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            마를 때 오그라듦 방지\n          </text>\n\n          <!-- Plus Sign 2 -->\n          <text x=\"350\" y=\"115\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"18\" font-weight=\"bold\">+</text>\n\n          <!-- Material 3: 잘게 자른 마른 풀잎 -->\n          <g transform=\"translate(375, 75)\">\n            <ellipse cx=\"40\" cy=\"40\" rx=\"34\" ry=\"20\" fill=\"#141914\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n            <!-- Grass fiber lines -->\n            <line x1=\"25\" y1=\"36\" x2=\"40\" y2=\"44\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n            <line x1=\"38\" y1=\"32\" x2=\"52\" y2=\"40\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n            <line x1=\"30\" y1=\"46\" x2=\"48\" y2=\"42\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n          </g>\n          <text x=\"375\" y=\"155\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 잘게 자른 마른 풀잎\n          </text>\n          <text x=\"375\" y=\"175\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            뼈대 역할을 하는 보강 섬유\n          </text>\n\n          <!-- Arrow downward to kneading and ball -->\n          <path d=\"M 290 190 L 290 220\" stroke=\"#06B6D4\" stroke-width=\"1.5\" marker-end=\"url(#arrow-step1)\" />\n\n          <!-- Process 4: 물을 조금씩 부어가며 발로 치대기 -->\n          <rect x=\"80\" y=\"235\" width=\"220\" height=\"65\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n          <text x=\"95\" y=\"260\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 물을 조금씩 부어가며 발로 치대기\n          </text>\n          <text x=\"95\" y=\"282\" fill=\"#AAAAAA\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            한 번에 많이 붓지 말고 뒤집으며 밟기\n          </text>\n\n          <!-- Process 5: 차진 반죽 덩어리 판정 -->\n          <g transform=\"translate(350, 225)\">\n            <!-- Clay ball -->\n            <circle cx=\"65\" cy=\"40\" r=\"32\" fill=\"#1C1815\" stroke=\"#E5E5E5\" stroke-width=\"2\" />\n            <!-- Inner smooth contour -->\n            <path d=\"M 45 40 Q 65 20 85 40\" stroke=\"#888888\" stroke-width=\"1\" fill=\"none\" />\n            <circle cx=\"65\" cy=\"40\" r=\"4\" fill=\"#10B981\" />\n          </g>\n          <text x=\"470\" y=\"255\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 차진 반죽 덩어리 완성\n          </text>\n          <text x=\"470\" y=\"278\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            주먹 크기로 둥글게 뭉쳐도\n          </text>\n          <text x=\"470\" y=\"295\" fill=\"#AAAAAA\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            겉면에 실금이 가지 않는 상태\n          </text>\n        </svg>","content/svgs/pr06-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <defs>\n            <marker id=\"arrow-wind\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#06B6D4\" />\n            </marker>\n          </defs>\n\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 02 // FOUNDATION LAYOUT &amp; AIR ENTRY SCHEMATIC\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Center U-Shape Stone Structure (Top-Down View) -->\n          <g transform=\"translate(180, 75)\">\n            <!-- Base Ground Insulation Bed (모래/자갈층) -->\n            <rect x=\"0\" y=\"0\" width=\"220\" height=\"190\" fill=\"#121212\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"3,3\" />\n\n            <!-- U-shaped Mud Bed -->\n            <path d=\"M 40 170 L 40 50 Q 110 10 180 50 L 180 170\" fill=\"none\" stroke=\"#654321\" stroke-width=\"36\" stroke-linecap=\"round\" stroke-linejoin=\"round\" />\n\n            <!-- Stones in U-Shape -->\n            <!-- Left arm stones -->\n            <circle cx=\"40\" cy=\"160\" r=\"14\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"40\" cy=\"120\" r=\"15\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"45\" cy=\"80\" r=\"14\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <!-- Curve stones -->\n            <circle cx=\"70\" cy=\"45\" r=\"15\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"110\" cy=\"30\" r=\"16\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"150\" cy=\"45\" r=\"15\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <!-- Right arm stones -->\n            <circle cx=\"175\" cy=\"80\" r=\"14\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"180\" cy=\"120\" r=\"15\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"180\" cy=\"160\" r=\"14\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n\n            <!-- Front Opening (장작 입구 폭 20cm) -->\n            <line x1=\"56\" y1=\"165\" x2=\"164\" y2=\"165\" stroke=\"#F59E0B\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\" />\n            <line x1=\"56\" y1=\"160\" x2=\"56\" y2=\"170\" stroke=\"#F59E0B\" stroke-width=\"1.5\" />\n            <line x1=\"164\" y1=\"160\" x2=\"164\" y2=\"170\" stroke=\"#F59E0B\" stroke-width=\"1.5\" />\n          </g>\n\n          <!-- Label 1: 앞쪽 장작 넣는 입구 (한 뼘 너비 20cm) -->\n          <text x=\"80\" y=\"290\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 앞쪽 장작 넣는 입구 (한 뼘 너비 20cm)\n          </text>\n          <text x=\"80\" y=\"308\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            불길 조절과 공기 공급에 알맞은 입구 폭\n          </text>\n\n          <!-- Label 2: U자형으로 둘러앉힌 마른 돌 -->\n          <line x1=\"180\" y1=\"130\" x2=\"120\" y2=\"100\" stroke=\"#E5E5E5\" stroke-width=\"1\" />\n          <text x=\"75\" y=\"85\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② U자형 주먹만 한 마른 돌\n          </text>\n          <text x=\"75\" y=\"103\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            기초를 지탱하는 1차 뼈대\n          </text>\n\n          <!-- Label 3: 돌 틈새를 메운 진흙 반죽 -->\n          <line x1=\"395\" y1=\"145\" x2=\"450\" y2=\"120\" stroke=\"#D97706\" stroke-width=\"1\" />\n          <text x=\"455\" y=\"115\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 틈새를 메운 진흙 반죽\n          </text>\n          <text x=\"455\" y=\"133\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            돌 사이 공기 누출 완전 차단\n          </text>\n\n          <!-- Label 4: 바닥 모래·자갈 단열층 -->\n          <line x1=\"290\" y1=\"180\" x2=\"450\" y2=\"190\" stroke=\"#06B6D4\" stroke-width=\"1\" />\n          <text x=\"455\" y=\"185\" fill=\"#06B6D4\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 바닥 마른 모래·자갈 단열층\n          </text>\n          <text x=\"455\" y=\"203\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            차가운 땅바닥 습기와 냉기 차단\n          </text>\n\n          <!-- Label 5: 바람 불어오는 반대 방향 -->\n          <g transform=\"translate(420, 245)\">\n            <path d=\"M 0 15 L 45 15\" stroke=\"#06B6D4\" stroke-width=\"1.5\" marker-end=\"url(#arrow-wind)\" />\n            <path d=\"M 5 28 L 50 28\" stroke=\"#06B6D4\" stroke-width=\"1.5\" marker-end=\"url(#arrow-wind)\" />\n          </g>\n          <text x=\"390\" y=\"290\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 바람 불어오는 반대쪽으로 입구 배치\n          </text>\n          <text x=\"390\" y=\"308\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            강풍에 불티가 역류하거나 꺼지지 않도록 보호\n          </text>\n        </svg>","content/svgs/pr06-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <defs>\n            <marker id=\"arrow-swirl\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#E02424\" />\n            </marker>\n          </defs>\n\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 03 // DOME CHAMBER CROSS-SECTION &amp; THERMAL CURVATURE\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Cutaway Dome Silhouette -->\n          <g transform=\"translate(190, 70)\">\n            <!-- Outer Mud Layer -->\n            <path d=\"M 30 190 C 30 70 80 20 150 20 C 220 20 270 70 270 190\" fill=\"none\" stroke=\"#8B5A2B\" stroke-width=\"40\" stroke-linecap=\"round\" />\n\n            <!-- Embedded Staggered Stones (Cross section) -->\n            <!-- Left wall stones -->\n            <ellipse cx=\"40\" cy=\"170\" rx=\"14\" ry=\"10\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"44\" cy=\"130\" rx=\"13\" ry=\"9\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"58\" cy=\"90\" rx=\"12\" ry=\"9\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"85\" cy=\"55\" rx=\"12\" ry=\"8\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <!-- Top apex stones -->\n            <ellipse cx=\"125\" cy=\"32\" rx=\"12\" ry=\"8\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"175\" cy=\"32\" rx=\"12\" ry=\"8\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <!-- Right wall stones -->\n            <ellipse cx=\"215\" cy=\"55\" rx=\"12\" ry=\"8\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"242\" cy=\"90\" rx=\"12\" ry=\"9\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"256\" cy=\"130\" rx=\"13\" ry=\"9\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"260\" cy=\"170\" rx=\"14\" ry=\"10\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n\n            <!-- Smooth Interior Heat Reflector Surface -->\n            <path d=\"M 50 190 C 50 90 90 40 150 40 C 210 40 250 90 250 190\" fill=\"#141414\" stroke=\"#F59E0B\" stroke-width=\"2\" />\n\n            <!-- Rotating Heat Swirl Inside Chamber -->\n            <path d=\"M 120 160 Q 150 100 180 140 Q 150 170 135 120\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"2\" stroke-dasharray=\"3,3\" marker-end=\"url(#arrow-swirl)\" />\n\n            <!-- Dimension: Height 45cm (무릎 높이) -->\n            <line x1=\"295\" y1=\"20\" x2=\"295\" y2=\"190\" stroke=\"#06B6D4\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n            <line x1=\"290\" y1=\"20\" x2=\"300\" y2=\"20\" stroke=\"#06B6D4\" stroke-width=\"1\" />\n            <line x1=\"290\" y1=\"190\" x2=\"300\" y2=\"190\" stroke=\"#06B6D4\" stroke-width=\"1\" />\n            <text x=\"305\" y=\"110\" fill=\"#06B6D4\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">45cm</text>\n          </g>\n\n          <!-- Label 1: 돌과 진흙을 엇갈려 쌓은 벽체 단면 -->\n          <line x1=\"210\" y1=\"180\" x2=\"130\" y2=\"150\" stroke=\"#E5E5E5\" stroke-width=\"1\" />\n          <text x=\"75\" y=\"125\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 엇갈려 쌓은 벽체 단면\n          </text>\n          <text x=\"75\" y=\"143\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            돌 틈에 진흙을 채워 무너짐 방지\n          </text>\n\n          <!-- Label 2: 손바닥 두께(약 5cm) 단열벽 -->\n          <line x1=\"430\" y1=\"180\" x2=\"480\" y2=\"150\" stroke=\"#D97706\" stroke-width=\"1\" />\n          <text x=\"470\" y=\"130\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② 손바닥 두께(약 5cm) 진흙벽\n          </text>\n          <text x=\"470\" y=\"148\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            바깥으로 새는 열 손실 완벽 차단\n          </text>\n\n          <!-- Label 3: 안쪽 벽면 매끄러운 열 반사 곡면 -->\n          <line x1=\"270\" y1=\"130\" x2=\"150\" y2=\"225\" stroke=\"#F59E0B\" stroke-width=\"1\" />\n          <text x=\"75\" y=\"235\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 매끄러운 열 반사 곡면\n          </text>\n          <text x=\"75\" y=\"253\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            손에 물을 묻혀 반질반질하게 다듬기\n          </text>\n\n          <!-- Label 4: 열기가 모여 회전하는 연소실 내부 -->\n          <text x=\"210\" y=\"295\" fill=\"#E02424\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 열기가 모여 회전하는 둥근 연소실 내부\n          </text>\n\n          <!-- Label 5: 무릎 높이(약 45cm) 전체 외형선 -->\n          <text x=\"460\" y=\"235\" fill=\"#06B6D4\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 무릎 높이(약 45cm) 외형선\n          </text>\n          <text x=\"460\" y=\"253\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            취사 안정성과 축열 용적 최적화\n          </text>\n        </svg>","content/svgs/pr06-step-04.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <defs>\n            <marker id=\"arrow-draft-blue\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#06B6D4\" />\n            </marker>\n            <marker id=\"arrow-draft-red\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#E02424\" />\n            </marker>\n            <marker id=\"arrow-smoke\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#888888\" />\n            </marker>\n          </defs>\n\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 04 // AIR DRAFT PERSPECTIVE &amp; EXHAUST BLUEPRINT\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Perspective Cutaway Chamber -->\n          <g transform=\"translate(160, 65)\">\n            <!-- Outer structure wireframe / body -->\n            <path d=\"M 30 180 L 30 120 Q 50 40 160 30 L 260 50 Q 320 80 330 180 Z\" fill=\"#151515\" stroke=\"#333333\" stroke-width=\"1\" />\n\n            <!-- Flat Top Cooking Rim (냄비 얹는 자리) -->\n            <ellipse cx=\"160\" cy=\"40\" rx=\"36\" ry=\"12\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"2\" />\n            <path d=\"M 124 40 Q 160 52 196 40\" stroke=\"#888888\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n\n            <!-- Clay Spacer Knobs (틈새 돌기) -->\n            <circle cx=\"128\" cy=\"38\" r=\"3\" fill=\"#F59E0B\" />\n            <circle cx=\"160\" cy=\"51\" r=\"3\" fill=\"#F59E0B\" />\n            <circle cx=\"192\" cy=\"38\" r=\"3\" fill=\"#F59E0B\" />\n\n            <!-- Rear Chimney Flue (뒤편 굴뚝 구멍) -->\n            <ellipse cx=\"275\" cy=\"55\" rx=\"18\" ry=\"8\" fill=\"#111111\" stroke=\"#888888\" stroke-width=\"1.5\" />\n            <path d=\"M 275 55 Q 290 20 285 5\" stroke=\"#888888\" stroke-width=\"2\" stroke-dasharray=\"3,3\" marker-end=\"url(#arrow-smoke)\" />\n\n            <!-- Front Air/Wood Opening (앞쪽 하부 흡입구) -->\n            <path d=\"M 30 180 Q 70 120 110 180\" fill=\"#0C0C0C\" stroke=\"#06B6D4\" stroke-width=\"2\" />\n\n            <!-- Internal Fire Draft Flow -->\n            <!-- Blue Oxygen entry -->\n            <path d=\"M 10 165 L 60 160\" stroke=\"#06B6D4\" stroke-width=\"2.5\" marker-end=\"url(#arrow-draft-blue)\" />\n            <!-- Red Flame Rising to pot -->\n            <path d=\"M 80 155 Q 120 110 155 60\" stroke=\"#E02424\" stroke-width=\"2.5\" marker-end=\"url(#arrow-draft-red)\" />\n            <!-- Red Heat to rear chimney -->\n            <path d=\"M 140 100 Q 210 90 265 65\" stroke=\"#E02424\" stroke-width=\"2\" stroke-dasharray=\"3,3\" marker-end=\"url(#arrow-draft-red)\" />\n          </g>\n\n          <!-- Label 1: 앞쪽 하부 공기 흡입구 -->\n          <text x=\"75\" y=\"260\" fill=\"#06B6D4\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 앞쪽 하부 공기 흡입구 (산소 유입)\n          </text>\n          <text x=\"75\" y=\"278\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            차가운 신선한 공기가 빨려 들어가는 길목\n          </text>\n\n          <!-- Label 2: 윗부분 평평한 조리용 구멍 -->\n          <line x1=\"320\" y1=\"100\" x2=\"220\" y2=\"70\" stroke=\"#E5E5E5\" stroke-width=\"1\" />\n          <text x=\"75\" y=\"90\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② 윗부분 평평한 조리용 구멍\n          </text>\n          <text x=\"75\" y=\"108\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            냄비나 평평한 돌판을 얹는 화구\n          </text>\n\n          <!-- Label 3: 뒤편 상단 굴뚝 구멍 -->\n          <text x=\"445\" y=\"85\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 뒤편 상단 굴뚝 구멍\n          </text>\n          <text x=\"445\" y=\"103\" fill=\"#666666\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            매운 연기를 뒤로 뽑아내는 배출구\n          </text>\n\n          <!-- Label 4: 붉은 화살표 열기 순환 -->\n          <text x=\"400\" y=\"185\" fill=\"#E02424\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 솟구치는 열기 순환선\n          </text>\n          <text x=\"400\" y=\"203\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            연소실 안을 회전하며 냄비 바닥을 달굼\n          </text>\n\n          <!-- Label 5: 냄비를 얹어도 공기가 통하는 틈새 -->\n          <text x=\"390\" y=\"260\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 냄비 받침 통기 틈새 돌기\n          </text>\n          <text x=\"390\" y=\"278\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            냄비를 얹어도 불길이 막혀 꺼지지 않는 여유 공간\n          </text>\n        </svg>","content/svgs/pr06-step-05.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 05 // CONTROLLED DEHYDRATION &amp; CERAMIC HARDENING\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Main Curing Stove Illustration -->\n          <g transform=\"translate(180, 70)\">\n            <!-- Left Side (Dark Wet Clay) transitioning to Right Side (Bright Baked Ocher) -->\n            <path d=\"M 40 180 C 40 80 80 40 140 40 L 180 40 C 240 40 280 80 280 180 Z\" fill=\"#2A1E14\" stroke=\"#D97706\" stroke-width=\"1.5\" />\n            \n            <!-- Baked Ocher Highlight on right half -->\n            <path d=\"M 160 40 C 220 40 260 80 260 180 L 160 180 Z\" fill=\"#422812\" opacity=\"0.6\" />\n\n            <!-- Rising Steam Lines (외벽 수증기) -->\n            <path d=\"M 80 50 Q 70 30 85 10\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\" fill=\"none\" />\n            <path d=\"M 120 45 Q 110 25 125 5\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\" fill=\"none\" />\n            <path d=\"M 200 45 Q 190 25 205 5\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\" fill=\"none\" />\n            <path d=\"M 240 50 Q 230 30 245 10\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\" fill=\"none\" />\n\n            <!-- Weak Ember Fire at Entry (작은 불씨) -->\n            <ellipse cx=\"60\" cy=\"175\" rx=\"20\" ry=\"8\" fill=\"#111111\" stroke=\"#333333\" stroke-width=\"1\" />\n            <circle cx=\"55\" cy=\"173\" r=\"3\" fill=\"#E02424\" />\n            <circle cx=\"65\" cy=\"175\" r=\"4\" fill=\"#F59E0B\" />\n            <circle cx=\"60\" cy=\"170\" r=\"2.5\" fill=\"#E5E5E5\" />\n\n            <!-- Small Surface Hairline Cracks being patched -->\n            <line x1=\"190\" y1=\"90\" x2=\"210\" y2=\"105\" stroke=\"#E5E5E5\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n            <!-- Patch indicator circle -->\n            <circle cx=\"200\" cy=\"98\" r=\"8\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n          </g>\n\n          <!-- Label 1: 입구에 지핀 작은 잔가지 불씨 -->\n          <text x=\"75\" y=\"270\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 입구 작은 잔가지 불씨 (약한 열기)\n          </text>\n          <text x=\"75\" y=\"288\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            강한 불 대신 은은한 열기로 시작\n          </text>\n\n          <!-- Label 2: 외벽에서 김(수증기)이 빠져나가는 모습 -->\n          <text x=\"75\" y=\"90\" fill=\"#AAAAAA\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② 외벽 수증기 증발선\n          </text>\n          <text x=\"75\" y=\"108\" fill=\"#666666\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            내부 수분이 천천히 기화\n          </text>\n\n          <!-- Label 3: 진흙 색상 변화 -->\n          <text x=\"440\" y=\"90\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 색상 변화 관찰\n          </text>\n          <text x=\"440\" y=\"108\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            짙은 고동색 → 밝은 황토색\n          </text>\n\n          <!-- Label 4: 손을 댔을 때 따뜻한 열감 -->\n          <text x=\"440\" y=\"170\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 따뜻한 건조 완료 판정\n          </text>\n          <text x=\"440\" y=\"188\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            축축함 없이 외벽 전체가 훈훈\n          </text>\n\n          <!-- Label 5: 갈라진 미세 틈을 덧바를 진흙 반죽 여분 -->\n          <text x=\"390\" y=\"270\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 미세 실금 덧바름 보수\n          </text>\n          <text x=\"390\" y=\"288\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            남은 진흙 반죽으로 틈새 메우기\n          </text>\n        </svg>","content/svgs/pr07-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <!-- Background Technical Gradient -->\n    <linearGradient id=\"bgGradOutcome\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#080a0e\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1218\"/>\n      <stop offset=\"100%\" stop-color=\"#090b0f\"/>\n    </linearGradient>\n\n    <!-- Timber Anchor Post Gradients -->\n    <linearGradient id=\"anchorPostCylinder\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#2d1e12\"/>\n      <stop offset=\"25%\" stop-color=\"#4a3320\"/>\n      <stop offset=\"50%\" stop-color=\"#735235\"/>\n      <stop offset=\"75%\" stop-color=\"#553a24\"/>\n      <stop offset=\"100%\" stop-color=\"#1e140c\"/>\n    </linearGradient>\n    <linearGradient id=\"anchorTopCap\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#5a4029\"/>\n      <stop offset=\"50%\" stop-color=\"#7a583a\"/>\n      <stop offset=\"100%\" stop-color=\"#3b291a\"/>\n    </linearGradient>\n\n    <!-- Wood Bark Texture Pattern -->\n    <pattern id=\"barkLines\" width=\"20\" height=\"40\" patternUnits=\"userSpaceOnUse\">\n      <line x1=\"5\" y1=\"0\" x2=\"4\" y2=\"40\" stroke=\"#1f140b\" stroke-width=\"1.2\" opacity=\"0.6\"/>\n      <line x1=\"12\" y1=\"0\" x2=\"13\" y2=\"40\" stroke=\"#1f140b\" stroke-width=\"1.5\" opacity=\"0.5\"/>\n      <line x1=\"18\" y1=\"0\" x2=\"17\" y2=\"40\" stroke=\"#8c6442\" stroke-width=\"0.8\" opacity=\"0.3\"/>\n    </pattern>\n\n    <!-- Manila Standing Rope 3D Tubular Gradient -->\n    <linearGradient id=\"ropeManilaOutcome\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#652b05\"/>\n      <stop offset=\"20%\" stop-color=\"#a14908\"/>\n      <stop offset=\"48%\" stop-color=\"#fef3c7\"/>\n      <stop offset=\"75%\" stop-color=\"#b45309\"/>\n      <stop offset=\"100%\" stop-color=\"#3d1502\"/>\n    </linearGradient>\n\n    <!-- Tactical Green Working Rope 3D Gradient -->\n    <linearGradient id=\"ropeGreenOutcome\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#0f3d20\"/>\n      <stop offset=\"22%\" stop-color=\"#15803d\"/>\n      <stop offset=\"48%\" stop-color=\"#bbf7d0\"/>\n      <stop offset=\"75%\" stop-color=\"#16a34a\"/>\n      <stop offset=\"100%\" stop-color=\"#052e16\"/>\n    </linearGradient>\n\n    <!-- Deep Drop Shadow for Over/Under Crossing -->\n    <filter id=\"shadowDeepOutcome\" x=\"-30%\" y=\"-30%\" width=\"160%\" height=\"160%\">\n      <feDropShadow dx=\"0\" dy=\"6\" stdDeviation=\"6\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n\n    <!-- Manila Braid Texture Pattern -->\n    <pattern id=\"braidManilaOutcome\" width=\"14\" height=\"14\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"14\" stroke=\"#451a03\" stroke-width=\"2.5\" opacity=\"0.65\"/>\n      <line x1=\"7\" y1=\"0\" x2=\"7\" y2=\"14\" stroke=\"#fef3c7\" stroke-width=\"1.8\" opacity=\"0.45\"/>\n    </pattern>\n\n    <!-- Paracord Texture Pattern for Working Tail -->\n    <pattern id=\"braidGreenOutcome\" width=\"8\" height=\"8\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(-45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#052e16\" stroke-width=\"2\" opacity=\"0.7\"/>\n      <line x1=\"4\" y1=\"0\" x2=\"4\" y2=\"8\" stroke=\"#bbf7d0\" stroke-width=\"1.2\" opacity=\"0.5\"/>\n    </pattern>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGradOutcome)\"/>\n  <rect x=\"14\" y=\"14\" width=\"772\" height=\"422\" fill=\"none\" stroke=\"#22262e\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 22 32 L 34 32 M 28 26 L 28 38\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 778 32 L 766 32 M 772 26 L 772 38\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 22 418 L 34 418 M 28 412 L 28 424\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 778 418 L 766 418 M 772 412 L 772 424\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header Strip -->\n  <text x=\"32\" y=\"38\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // MASTER SPECIFICATION</text>\n  <text x=\"32\" y=\"56\" fill=\"#ef4444\" font-family=\"'JetBrains Mono', monospace\" font-size=\"12\" font-weight=\"bold\">BOWLINE MASTER BLUEPRINT // 매듭의 왕 완전 제원도</text>\n  <text x=\"768\" y=\"38\" fill=\"#22c55e\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">RELEASE: 1.0 SEC // JAM-PROOF</text>\n  <line x1=\"32\" y1=\"66\" x2=\"768\" y2=\"66\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Left Technical Spec Card -->\n  <g id=\"specCardLeft\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">\n    <rect x=\"32\" y=\"80\" width=\"190\" height=\"175\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n    <rect x=\"32\" y=\"80\" width=\"190\" height=\"24\" fill=\"#181d24\"/>\n    <text x=\"44\" y=\"96\" fill=\"#ef4444\" font-weight=\"bold\">BOWLINE SPECIFICATIONS</text>\n    <text x=\"44\" y=\"122\" fill=\"#d1d5db\">· KNOT TYPE: FIXED LOOP</text>\n    <text x=\"44\" y=\"142\" fill=\"#d1d5db\">· SLIPPAGE: ZERO (0%)</text>\n    <text x=\"44\" y=\"162\" fill=\"#d1d5db\">· EFFICIENCY: 75% RATING</text>\n    <text x=\"44\" y=\"182\" fill=\"#d1d5db\">· JAMMING: 100% JAM-PROOF</text>\n    <text x=\"44\" y=\"202\" fill=\"#d1d5db\">· RELEASE: BREAK THE BACK</text>\n    <text x=\"44\" y=\"222\" fill=\"#4ade80\">· LOAD CAPACITY: 500+ KG</text>\n    <text x=\"44\" y=\"242\" fill=\"#38bdf8\">· TAIL POSITION: INSIDE LOOP</text>\n  </g>\n\n  <!-- Left Material Guide Strip -->\n  <g id=\"matGuideLeft\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">\n    <rect x=\"32\" y=\"265\" width=\"190\" height=\"135\" fill=\"#0d1014\" stroke=\"#1e242c\" stroke-width=\"1\"/>\n    <rect x=\"32\" y=\"265\" width=\"4\" height=\"135\" fill=\"#f59e0b\"/>\n    <text x=\"44\" y=\"284\" fill=\"#f59e0b\" font-weight=\"bold\">[TWO-COLOR CONTRAST]</text>\n    <rect x=\"44\" y=\"295\" width=\"12\" height=\"12\" fill=\"url(#ropeManilaOutcome)\"/>\n    <text x=\"62\" y=\"305\" fill=\"#fde68a\">원줄: 마닐라 탄 로프</text>\n    <text x=\"62\" y=\"318\" fill=\"#9ca3af\">(하중 지탱 주 라인)</text>\n    <rect x=\"44\" y=\"335\" width=\"12\" height=\"12\" fill=\"url(#ropeGreenOutcome)\"/>\n    <text x=\"62\" y=\"345\" fill=\"#86efac\">작동 끝단: 전술 그린 줄</text>\n    <text x=\"62\" y=\"358\" fill=\"#9ca3af\">(토끼 궤적 전용 식별)</text>\n    <text x=\"44\" y=\"385\" fill=\"#38bdf8\">안전: 꼬리는 고리 안쪽 위치</text>\n  </g>\n\n  <!-- Ground Plane Cast Shadow -->\n  <ellipse cx=\"440\" cy=\"410\" rx=\"220\" ry=\"16\" fill=\"#030405\" opacity=\"0.95\"/>\n\n  <!-- ============================================================== -->\n  <!-- 3D RIGGING SCENE: TIMBER POST + 3D BRAIDED BOWLINE KNOT -->\n  <!-- ============================================================== -->\n  <!-- 1. Anchor Post: Rope passing BEHIND Post (Drawn First) -->\n  <path d=\"M 410 325 C 455 350 515 350 550 325\" stroke=\"#000000\" stroke-width=\"22\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 410 325 C 455 350 515 350 550 325\" stroke=\"url(#ropeManilaOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 410 325 C 455 350 515 350 550 325\" stroke=\"url(#braidManilaOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n\n  <!-- 2. Timber Anchor Post Solid Cylinder -->\n  <g id=\"timberPostGroup\">\n    <!-- Cast Shadow on Timber Post from incoming top line -->\n    <polygon points=\"480,210 525,210 520,415 475,415\" fill=\"url(#anchorPostCylinder)\" stroke=\"#1a120b\" stroke-width=\"1.5\"/>\n    <polygon points=\"480,210 525,210 520,415 475,415\" fill=\"url(#barkLines)\" opacity=\"0.65\"/>\n    <!-- Top Cap Ellipse with Tree Growth Rings -->\n    <ellipse cx=\"502\" cy=\"210\" rx=\"22.5\" ry=\"9\" fill=\"url(#anchorTopCap)\" stroke=\"#261b11\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"502\" cy=\"210\" rx=\"15\" ry=\"6\" fill=\"none\" stroke=\"#3b291a\" stroke-width=\"1\"/>\n    <ellipse cx=\"502\" cy=\"210\" rx=\"7\" ry=\"3\" fill=\"none\" stroke=\"#261b11\" stroke-width=\"0.8\"/>\n    <!-- Timber Post Label -->\n    <text x=\"502\" y=\"195\" fill=\"#d1d5db\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">TIMBER POST</text>\n  </g>\n\n  <!-- 3. Anchor Post: Rope passing IN FRONT OF Post (Drawn After Post) -->\n  <path d=\"M 550 325 C 525 285 460 280 415 295\" stroke=\"#000000\" stroke-width=\"22\" stroke-linecap=\"round\" fill=\"none\" filter=\"url(#shadowDeepOutcome)\"/>\n  <path d=\"M 550 325 C 525 285 460 280 415 295\" stroke=\"url(#ropeManilaOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 550 325 C 525 285 460 280 415 295\" stroke=\"url(#braidManilaOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n\n  <!-- 4. Main Standing Line (하중 받는 수직 원줄) -->\n  <path d=\"M 315 75 L 315 190\" stroke=\"#000000\" stroke-width=\"24\" stroke-linecap=\"round\"/>\n  <path d=\"M 315 75 L 315 190\" stroke=\"url(#ropeManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\"/>\n  <path d=\"M 315 75 L 315 190\" stroke=\"url(#braidManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n\n  <!-- 5. Nipper Loop Ring (토끼굴 3D 고리) -->\n  <path d=\"M 315 190 C 275 200 265 240 305 252 C 335 258 355 232 340 205 C 335 195 315 190 315 190\" \n        stroke=\"#000000\" stroke-width=\"24\" stroke-linecap=\"round\" fill=\"none\" filter=\"url(#shadowDeepOutcome)\"/>\n  <path d=\"M 315 190 C 275 200 265 240 305 252 C 335 258 355 232 340 205 C 335 195 315 190 315 190\" \n        stroke=\"url(#ropeManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 315 190 C 275 200 265 240 305 252 C 335 258 355 232 340 205 C 335 195 315 190 315 190\" \n        stroke=\"url(#braidManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n\n  <!-- 6. Collar Loop (뒤통수 칼라 링) Wrapped around Standing Line -->\n  <path d=\"M 310 248 C 295 230 290 190 315 180 C 345 170 365 205 340 245\" \n        stroke=\"#000000\" stroke-width=\"24\" stroke-linecap=\"round\" fill=\"none\" filter=\"url(#shadowDeepOutcome)\"/>\n  <path d=\"M 310 248 C 295 230 290 190 315 180 C 345 170 365 205 340 245\" \n        stroke=\"url(#ropeGreenOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 310 248 C 295 230 290 190 315 180 C 345 170 365 205 340 245\" \n        stroke=\"url(#braidGreenOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- 7. Working End Tail (고리 안쪽에 안전하게 잠긴 토끼 꼬리) -->\n  <path d=\"M 335 240 L 365 295\" stroke=\"#000000\" stroke-width=\"22\" stroke-linecap=\"round\" filter=\"url(#shadowDeepOutcome)\"/>\n  <path d=\"M 335 240 L 365 295\" stroke=\"url(#ropeGreenOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n  <path d=\"M 335 240 L 365 295\" stroke=\"url(#braidGreenOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\" opacity=\"0.75\"/>\n\n  <!-- 8. Eye Loop Leads connecting knot to anchor post -->\n  <path d=\"M 305 252 C 295 285 350 310 410 325\" stroke=\"#000000\" stroke-width=\"24\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 305 252 C 295 285 350 310 410 325\" stroke=\"url(#ropeManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 305 252 C 295 285 350 310 410 325\" stroke=\"url(#braidManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n\n  <path d=\"M 415 295 C 380 285 350 270 335 240\" stroke=\"#000000\" stroke-width=\"24\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 415 295 C 380 285 350 270 335 240\" stroke=\"url(#ropeManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 415 295 C 380 285 350 270 335 240\" stroke=\"url(#braidManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n\n  <!-- Dynamic Opposing Tension Force Arrows -->\n  <g stroke=\"#ef4444\" stroke-width=\"2.5\" fill=\"none\">\n    <!-- Tension upward on standing line -->\n    <line x1=\"315\" y1=\"135\" x2=\"315\" y2=\"95\"/>\n    <polygon points=\"315,86 308,100 322,100\" fill=\"#ef4444\"/>\n    <!-- Tension pulling toward timber anchor post -->\n    <line x1=\"410\" y1=\"300\" x2=\"445\" y2=\"310\"/>\n    <polygon points=\"453,312 439,305 443,319\" fill=\"#ef4444\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- RIGHT TECHNICAL PANEL: 1-SECOND QUICK RELEASE MECHANISM -->\n  <!-- ============================================================== -->\n  <g id=\"quickReleasePanel\">\n    <rect x=\"560\" y=\"80\" width=\"205\" height=\"195\" fill=\"#111419\" stroke=\"#ef4444\" stroke-width=\"1\"/>\n    <rect x=\"560\" y=\"80\" width=\"205\" height=\"24\" fill=\"#241010\"/>\n    <text x=\"572\" y=\"96\" fill=\"#ef4444\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">1-SEC BREAK-THE-BACK</text>\n\n    <!-- Finger Action Principles -->\n    <text x=\"572\" y=\"122\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\" font-weight=\"bold\">칼라(뒤통수) 꺾기 원리</text>\n    <text x=\"572\" y=\"140\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">1. 매듭 뒤편 둥근 칼라 고리 확인</text>\n    <text x=\"572\" y=\"156\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">2. 엄지로 칼라를 바깥쪽으로 젖힘</text>\n    <text x=\"572\" y=\"172\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">3. 마찰 락 즉시 풀려 1초 만에 해체</text>\n\n    <!-- Mini Loupe Vector of the Release Action -->\n    <circle cx=\"660\" cy=\"225\" r=\"32\" fill=\"#080a0e\" stroke=\"#262d35\" stroke-width=\"1\"/>\n    <!-- Standing Rope in Loupe -->\n    <line x1=\"660\" y1=\"198\" x2=\"660\" y2=\"252\" stroke=\"#b45309\" stroke-width=\"7\" stroke-linecap=\"round\"/>\n    <!-- Collar Loop being bent backwards -->\n    <path d=\"M 645 225 C 645 208 675 208 675 225\" stroke=\"#22c55e\" stroke-width=\"6\" stroke-linecap=\"round\" fill=\"none\"/>\n    <!-- Thumb Push Arrow -->\n    <line x1=\"660\" y1=\"235\" x2=\"660\" y2=\"212\" stroke=\"#38bdf8\" stroke-width=\"2.2\"/>\n    <polygon points=\"660,205 654,216 666,216\" fill=\"#38bdf8\"/>\n    <text x=\"660\" y=\"248\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">PUSH UP</text>\n\n    <!-- Bottom Jam-Proof Stamp -->\n    <rect x=\"560\" y=\"250\" width=\"205\" height=\"25\" fill=\"#052e16\"/>\n    <text x=\"662\" y=\"266\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">JAM-PROOF // 칼날 불필요</text>\n  </g>\n\n  <!-- Right Safety Warning Box -->\n  <g id=\"safetyWarningBox\">\n    <rect x=\"560\" y=\"290\" width=\"205\" height=\"110\" fill=\"#140d0d\" stroke=\"#ef4444\" stroke-width=\"1\"/>\n    <rect x=\"560\" y=\"290\" width=\"205\" height=\"20\" fill=\"#2d1212\"/>\n    <text x=\"572\" y=\"304\" fill=\"#ef4444\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\">[FATAL MISTAKE 방지]</text>\n    <text x=\"572\" y=\"326\" fill=\"#fca5a5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"8.5\" font-weight=\"bold\">토끼 꼬리는 반드시 고리 안쪽!</text>\n    <text x=\"572\" y=\"344\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8\">바깥으로 노출되면 마찰에 쓸려</text>\n    <text x=\"572\" y=\"358\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8\">매듭이 저절로 풀릴 수 있습니다.</text>\n    <text x=\"572\" y=\"382\" fill=\"#22c55e\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\">INSIDE TAIL = 100% SECURE</text>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- TECHNICAL CALLOUTS & DIMENSIONS -->\n  <!-- ============================================================== -->\n  <g id=\"calloutsMaster\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">\n    <!-- Callout 1: Standing Line -->\n    <line x1=\"315\" y1=\"130\" x2=\"365\" y2=\"130\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n    <circle cx=\"315\" cy=\"130\" r=\"2.5\" fill=\"#f59e0b\"/>\n    <text x=\"375\" y=\"126\" fill=\"#ffffff\" font-weight=\"bold\">STANDING PART</text>\n    <text x=\"375\" y=\"140\" fill=\"#9ca3af\">하중을 받는 주 원줄</text>\n\n    <!-- Callout 2: Fixed Eye Loop -->\n    <line x1=\"450\" y1=\"330\" x2=\"450\" y2=\"370\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"450\" cy=\"330\" r=\"2.5\" fill=\"#38bdf8\"/>\n    <text x=\"450\" y=\"386\" fill=\"#38bdf8\" font-weight=\"bold\">FIXED EYE LOOP</text>\n    <text x=\"450\" y=\"400\" fill=\"#9ca3af\">하중에도 줄어들지 않는 고리</text>\n\n    <!-- Callout 3: Working End Tail -->\n    <line x1=\"365\" y1=\"290\" x2=\"320\" y2=\"335\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n    <circle cx=\"365\" cy=\"290\" r=\"2.5\" fill=\"#22c55e\"/>\n    <text x=\"310\" y=\"340\" fill=\"#4ade80\" font-weight=\"bold\" text-anchor=\"end\">WORKING END TAIL</text>\n    <text x=\"310\" y=\"354\" fill=\"#9ca3af\" text-anchor=\"end\">고리 안쪽으로 단단히 잠김</text>\n  </g>\n</svg>\n","content/svgs/pr07-step-01.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGrad01\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0f1216\"/>\n      <stop offset=\"100%\" stop-color=\"#0a0c0e\"/>\n    </linearGradient>\n\n    <!-- Manila Standing Rope 3D Tubular Gradient -->\n    <linearGradient id=\"ropeManila\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"25%\" stop-color=\"#b45309\"/>\n      <stop offset=\"50%\" stop-color=\"#fef3c7\"/>\n      <stop offset=\"75%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Tactical Green Working Rope 3D Gradient -->\n    <linearGradient id=\"ropeTacticalGreen\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#14532d\"/>\n      <stop offset=\"25%\" stop-color=\"#16a34a\"/>\n      <stop offset=\"50%\" stop-color=\"#bbf7d0\"/>\n      <stop offset=\"75%\" stop-color=\"#22c55e\"/>\n      <stop offset=\"100%\" stop-color=\"#052e16\"/>\n    </linearGradient>\n\n    <!-- Deep Drop Shadow Filter for Over/Under Crossing -->\n    <filter id=\"shadowDeep\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n\n    <!-- Twisted Rope Braid Pattern for Manila Rope -->\n    <pattern id=\"braidManila\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"12\" stroke=\"#451a03\" stroke-width=\"2.5\" opacity=\"0.6\"/>\n      <line x1=\"6\" y1=\"0\" x2=\"6\" y2=\"12\" stroke=\"#fef3c7\" stroke-width=\"1.5\" opacity=\"0.4\"/>\n    </pattern>\n\n    <!-- Paracord Texture Pattern for Working End -->\n    <pattern id=\"braidGreen\" width=\"8\" height=\"8\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(-45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#052e16\" stroke-width=\"2\" opacity=\"0.7\"/>\n      <line x1=\"4\" y1=\"0\" x2=\"4\" y2=\"8\" stroke=\"#bbf7d0\" stroke-width=\"1.2\" opacity=\"0.5\"/>\n    </pattern>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGrad01)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 01 // BOWLINE STEP 1: 토끼굴 고리 형성</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Background Reference Grid for Scale -->\n  <g opacity=\"0.12\" stroke=\"#4b5563\" stroke-width=\"0.5\" stroke-dasharray=\"2 4\">\n    <line x1=\"60\" y1=\"40\" x2=\"60\" y2=\"340\"/>\n    <line x1=\"200\" y1=\"40\" x2=\"200\" y2=\"340\"/>\n    <line x1=\"340\" y1=\"40\" x2=\"340\" y2=\"340\"/>\n    <line x1=\"20\" y1=\"120\" x2=\"380\" y2=\"120\"/>\n    <line x1=\"20\" y1=\"200\" x2=\"380\" y2=\"200\"/>\n    <line x1=\"20\" y1=\"280\" x2=\"380\" y2=\"280\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 1. STANDING PART (원줄 / 서 있는 나무) - 수직 황갈색 삼끈 로프 -->\n  <!-- ============================================================== -->\n  <!-- Ground contact shadow -->\n  <ellipse cx=\"200\" cy=\"335\" rx=\"16\" ry=\"5\" fill=\"#000000\" opacity=\"0.6\"/>\n\n  <!-- Standing Rope Segment: Top to Loop Entrance -->\n  <path d=\"M 200 42 L 200 120\" stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 42 L 200 120\" stroke=\"url(#ropeManila)\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 42 L 200 120\" stroke=\"url(#braidManila)\" stroke-width=\"12\" stroke-linecap=\"round\" opacity=\"0.7\"/>\n\n  <!-- Loop Body (토끼굴의 아래쪽 루프 곡선 - 숫자 6의 둥근 배) -->\n  <!-- Deep drop shadow behind loop -->\n  <path d=\"M 200 120 C 130 135 125 225 190 235 C 245 240 265 195 240 160 C 220 135 185 128 150 145\" \n        stroke=\"#000000\" stroke-width=\"20\" stroke-linecap=\"round\" fill=\"none\"/>\n  <!-- Base Manila 3D Tube -->\n  <path d=\"M 200 120 C 130 135 125 225 190 235 C 245 240 265 195 240 160 C 220 135 185 128 150 145\" \n        stroke=\"url(#ropeManila)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 200 120 C 130 135 125 225 190 235 C 245 240 265 195 240 160 C 220 135 185 128 150 145\" \n        stroke=\"url(#braidManila)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- Standing Part Continuation downwards (수직 원줄의 하단부) -->\n  <path d=\"M 190 235 L 195 330\" stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\"/>\n  <path d=\"M 190 235 L 195 330\" stroke=\"url(#ropeManila)\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n  <path d=\"M 190 235 L 195 330\" stroke=\"url(#braidManila)\" stroke-width=\"12\" stroke-linecap=\"round\" opacity=\"0.7\"/>\n\n  <!-- ============================================================== -->\n  <!-- 2. WORKING END (작동 줄 - 녹색 토끼 줄) - 원줄 \"위(OVER)\" 교차! -->\n  <!-- ============================================================== -->\n  <!-- The crossing segment with heavy physical drop shadow to prove OVER crossing -->\n  <g filter=\"url(#shadowDeep)\">\n    <!-- Black cast shadow mask -->\n    <path d=\"M 150 145 C 135 155 105 195 105 250 L 105 320\" \n          stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n    <!-- 3D Tactical Green Tube -->\n    <path d=\"M 150 145 C 135 155 105 195 105 250 L 105 320\" \n          stroke=\"url(#ropeTacticalGreen)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 150 145 C 135 155 105 195 105 250 L 105 320\" \n          stroke=\"url(#braidGreen)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n  </g>\n\n  <!-- Heat-sealed Rope End Cap (작동 줄 끝단 마감 테이프 디테일) -->\n  <line x1=\"100\" y1=\"320\" x2=\"110\" y2=\"320\" stroke=\"#ef4444\" stroke-width=\"4\" stroke-linecap=\"square\"/>\n\n  <!-- ============================================================== -->\n  <!-- 3. INSET LOUPE: OVER 교차점 3D 확대경 (인간 인지성 극대화) -->\n  <!-- ============================================================== -->\n  <!-- Inset Loupe Circular Frame at Top Right -->\n  <g transform=\"translate(300, 110)\">\n    <circle cx=\"0\" cy=\"0\" r=\"32\" fill=\"#0c0e12\" stroke=\"#22c55e\" stroke-width=\"1.8\"/>\n    <circle cx=\"0\" cy=\"0\" r=\"30\" fill=\"none\" stroke=\"#222\" stroke-width=\"1\"/>\n    \n    <!-- Underneath Manila Rope inside Zoom -->\n    <path d=\"M -30 6 L 30 -6\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n    <path d=\"M -30 6 L 30 -6\" stroke=\"url(#ropeManila)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n    \n    <!-- OVER Green Rope with Deep Cast Shadow -->\n    <path d=\"M -8 -30 L 8 30\" stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\"/>\n    <path d=\"M -8 -30 L 8 30\" stroke=\"url(#ropeTacticalGreen)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n    \n    <!-- \"OVER\" Visual Indicator inside Loupe -->\n    <rect x=\"-16\" y=\"-12\" width=\"32\" height=\"6\" fill=\"#14532d\" stroke=\"#22c55e\" stroke-width=\"0.8\"/>\n    <polygon points=\"0,-15 -4,-12 4,-12\" fill=\"#22c55e\"/>\n    \n    <!-- Loupe Leader Line connecting to actual crossing -->\n    <path d=\"M -22 22 L -100 35\" stroke=\"#22c55e\" stroke-width=\"1\" stroke-dasharray=\"2 2\" fill=\"none\"/>\n    <circle cx=\"-100\" cy=\"35\" r=\"3\" fill=\"#22c55e\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 4. MOTION & TARGET INDICATORS -->\n  <!-- ============================================================== -->\n  <!-- Number 6 Loop Target Crosshair & Circle -->\n  <circle cx=\"185\" cy=\"185\" r=\"22\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/>\n  <circle cx=\"185\" cy=\"185\" r=\"3\" fill=\"#38bdf8\"/>\n  <path d=\"M 185 155 L 185 165 M 185 205 L 185 215 M 155 185 L 165 185 M 205 185 L 215 185\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n\n  <!-- Dynamic Loop Twist Arrow (시계 방향 꼬임 가이드) -->\n  <path d=\"M 230 165 C 245 190 230 220 195 220 C 170 220 155 200 165 175\" \n        fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-dasharray=\"4 2\"/>\n  <polygon points=\"163,168 174,175 166,183\" fill=\"#f59e0b\"/>\n\n  <!-- ============================================================== -->\n  <!-- 5. CALLOUT LABELS (9대 선언적 바인딩 라벨) -->\n  <!-- ============================================================== -->\n  <!-- Label 2 & 3: Standing Part (Top Left) -->\n  <line x1=\"192\" y1=\"75\" x2=\"90\" y2=\"75\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"192\" cy=\"75\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"70\" fill=\"#fef3c7\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">STANDING PART</text>\n  <text x=\"24\" y=\"83\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">원줄 (서 있는 나무)</text>\n\n  <!-- Label 4 & 5: Rabbit Hole (Center Left) -->\n  <line x1=\"163\" y1=\"185\" x2=\"80\" y2=\"185\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <circle cx=\"163\" cy=\"185\" r=\"2.5\" fill=\"#38bdf8\"/>\n  <text x=\"24\" y=\"175\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">RABBIT HOLE (고리)</text>\n  <text x=\"24\" y=\"188\" fill=\"#bae6fd\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">숫자 6 모양의 토끼굴</text>\n\n  <!-- Label 6 & 7: Working End (Bottom Left) -->\n  <line x1=\"105\" y1=\"270\" x2=\"50\" y2=\"270\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n  <circle cx=\"105\" cy=\"270\" r=\"2.5\" fill=\"#22c55e\"/>\n  <text x=\"24\" y=\"260\" fill=\"#86efac\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">WORKING END (토끼)</text>\n  <text x=\"24\" y=\"273\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">작동 끝단이 원줄 '위'로 교차</text>\n\n  <!-- Bottom Tactical Field Note Strip -->\n  <rect x=\"18\" y=\"342\" width=\"364\" height=\"40\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"342\" width=\"4\" height=\"40\" fill=\"#22c55e\"/>\n  <!-- Label 8 & 9: Summary Instruction -->\n  <text x=\"32\" y=\"357\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\" font-weight=\"bold\">[1단계 핵심] 원줄 위에 작동 줄을 얹어 6자 루프 형성</text>\n  <text x=\"32\" y=\"371\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">작동 줄이 반드시 원줄의 위쪽에 위치해야 잠금 구조가 완성됩니다.</text>\n</svg>","content/svgs/pr07-step-02.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGrad02\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0f1216\"/>\n      <stop offset=\"100%\" stop-color=\"#0a0c0e\"/>\n    </linearGradient>\n\n    <!-- Manila Standing Rope 3D Tubular Gradient -->\n    <linearGradient id=\"ropeManila02\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"25%\" stop-color=\"#b45309\"/>\n      <stop offset=\"50%\" stop-color=\"#fef3c7\"/>\n      <stop offset=\"75%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Tactical Green Working Rope 3D Gradient -->\n    <linearGradient id=\"ropeGreen02\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#14532d\"/>\n      <stop offset=\"25%\" stop-color=\"#16a34a\"/>\n      <stop offset=\"50%\" stop-color=\"#bbf7d0\"/>\n      <stop offset=\"75%\" stop-color=\"#22c55e\"/>\n      <stop offset=\"100%\" stop-color=\"#052e16\"/>\n    </linearGradient>\n\n    <!-- Deep Drop Shadow Filter for Over/Under Crossing -->\n    <filter id=\"shadowDeep02\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"4.5\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n\n    <!-- Twisted Rope Braid Pattern for Manila Rope -->\n    <pattern id=\"braidManila02\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"12\" stroke=\"#451a03\" stroke-width=\"2.5\" opacity=\"0.6\"/>\n      <line x1=\"6\" y1=\"0\" x2=\"6\" y2=\"12\" stroke=\"#fef3c7\" stroke-width=\"1.5\" opacity=\"0.4\"/>\n    </pattern>\n\n    <!-- Paracord Texture Pattern for Working End -->\n    <pattern id=\"braidGreen02\" width=\"8\" height=\"8\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(-45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#052e16\" stroke-width=\"2\" opacity=\"0.7\"/>\n      <line x1=\"4\" y1=\"0\" x2=\"4\" y2=\"8\" stroke=\"#bbf7d0\" stroke-width=\"1.2\" opacity=\"0.5\"/>\n    </pattern>\n  </defs>\n\n  <!-- Canvas Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGrad02)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 02 // BOWLINE STEP 2: 토끼굴 상향 탈출</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Background Reference Grid -->\n  <g opacity=\"0.12\" stroke=\"#4b5563\" stroke-width=\"0.5\" stroke-dasharray=\"2 4\">\n    <line x1=\"60\" y1=\"40\" x2=\"60\" y2=\"340\"/>\n    <line x1=\"200\" y1=\"40\" x2=\"200\" y2=\"340\"/>\n    <line x1=\"340\" y1=\"40\" x2=\"340\" y2=\"340\"/>\n    <line x1=\"20\" y1=\"120\" x2=\"380\" y2=\"120\"/>\n    <line x1=\"20\" y1=\"200\" x2=\"380\" y2=\"200\"/>\n    <line x1=\"20\" y1=\"280\" x2=\"380\" y2=\"280\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 1. STANDING PART (원줄) & NUMBER 6 THROAT LOOP -->\n  <!-- ============================================================== -->\n  <!-- Top Vertical Standing Line -->\n  <path d=\"M 200 42 L 200 115\" stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 42 L 200 115\" stroke=\"url(#ropeManila02)\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 42 L 200 115\" stroke=\"url(#braidManila02)\" stroke-width=\"12\" stroke-linecap=\"round\" opacity=\"0.75\"/>\n\n  <!-- Throat Loop Back Arc (The 6-loop back) -->\n  <path d=\"M 200 115 C 135 130 130 215 190 225 C 240 230 260 190 235 155 C 215 130 185 122 150 140\" \n        stroke=\"#000000\" stroke-width=\"20\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 200 115 C 135 130 130 215 190 225 C 240 230 260 190 235 155 C 215 130 185 122 150 140\" \n        stroke=\"url(#ropeManila02)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 200 115 C 135 130 130 215 190 225 C 240 230 260 190 235 155 C 215 130 185 122 150 140\" \n        stroke=\"url(#braidManila02)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- ============================================================== -->\n  <!-- 2. MAIN EYE LOOP (최종 큰 고리가 될 밧줄 하단 루프) -->\n  <!-- ============================================================== -->\n  <!-- Standing rope going down, making the giant eye loop, and coming back up -->\n  <path d=\"M 190 225 C 190 280 150 325 110 325 C 70 325 45 270 55 210 C 65 160 110 130 150 140\" \n        stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 190 225 C 190 280 150 325 110 325 C 70 325 45 270 55 210 C 65 160 110 130 150 140\" \n        stroke=\"url(#ropeManila02)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 190 225 C 190 280 150 325 110 325 C 70 325 45 270 55 210 C 65 160 110 130 150 140\" \n        stroke=\"url(#braidManila02)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- ============================================================== -->\n  <!-- 3. WORKING END (토끼 줄) - 굴 아래에서 위로 솟구쳐 나오는 상향 관통! -->\n  <!-- ============================================================== -->\n  <!-- First part: Entering underneath the throat hole -->\n  <path d=\"M 150 140 C 160 150 175 165 185 178\" \n        stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.6\"/>\n        \n  <!-- Emerging Upward through Rabbit Hole with Deep 3D Shadow -->\n  <g filter=\"url(#shadowDeep02)\">\n    <!-- Emerging green tail shooting upward -->\n    <path d=\"M 185 185 C 195 160 215 110 225 75\" \n          stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 185 185 C 195 160 215 110 225 75\" \n          stroke=\"url(#ropeGreen02)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 185 185 C 195 160 215 110 225 75\" \n          stroke=\"url(#braidGreen02)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.85\"/>\n  </g>\n\n  <!-- Heat-sealed Red End Cap on Working Tip -->\n  <line x1=\"220\" y1=\"75\" x2=\"230\" y2=\"75\" stroke=\"#ef4444\" stroke-width=\"4\" stroke-linecap=\"square\"/>\n\n  <!-- ============================================================== -->\n  <!-- 4. 3D DIRECTIONAL & COGNITIVE CUES (땅속에서 위로 솟구침) -->\n  <!-- ============================================================== -->\n  <!-- The 3D Throat Hole Opening Indicator (Portal ellipse) -->\n  <ellipse cx=\"185\" cy=\"180\" rx=\"20\" ry=\"14\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.8\" stroke-dasharray=\"3 2\"/>\n  \n  <!-- Giant Upward 3D Vector Arrow (솟구치는 탈출 궤적) -->\n  <path d=\"M 185 200 C 190 175 200 140 210 100\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"2.5\" stroke-linecap=\"round\"/>\n  <polygon points=\"214,92 203,103 218,107\" fill=\"#ef4444\"/>\n\n\n\n  <!-- 15cm Dimension Bracket for Rabbit Head Slack -->\n  <path d=\"M 235 75 L 245 75 L 245 155 L 235 155\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <line x1=\"245\" y1=\"115\" x2=\"255\" y2=\"115\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n\n  <!-- ============================================================== -->\n  <!-- 5. CALLOUT LABELS (9대 선언적 바인딩 라벨) -->\n  <!-- ============================================================== -->\n  <!-- Label 2 & 3: Emerge from hole (Top Center/Right) -->\n  <line x1=\"220\" y1=\"85\" x2=\"270\" y2=\"85\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <circle cx=\"220\" cy=\"85\" r=\"2.5\" fill=\"#38bdf8\"/>\n  <text x=\"280\" y=\"80\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">EMERGE FROM HOLE</text>\n  <text x=\"280\" y=\"93\" fill=\"#bae6fd\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">굴 아래에서 위로 탈출</text>\n\n  <!-- Label 4 & 5: Rabbit Head 15cm Slack (Right Center) -->\n  <text x=\"260\" y=\"152\" fill=\"#fef3c7\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">토끼 머리 15cm</text>\n  <text x=\"260\" y=\"165\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">충분한 길이 인출</text>\n\n  <!-- Label 6 & 7: Main Eye Loop (Bottom Left) -->\n  <line x1=\"60\" y1=\"280\" x2=\"30\" y2=\"280\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <circle cx=\"60\" cy=\"280\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"268\" fill=\"#ffffff\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">MAIN EYE LOOP</text>\n  <text x=\"24\" y=\"281\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">최종 하중을 받을 큰 고리</text>\n\n  <!-- Bottom Tactical Field Note Strip -->\n  <rect x=\"18\" y=\"342\" width=\"364\" height=\"40\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"342\" width=\"4\" height=\"40\" fill=\"#38bdf8\"/>\n  <!-- Label 8 & 9: Summary Instruction -->\n  <text x=\"32\" y=\"357\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\" font-weight=\"bold\">[2단계 핵심] 굴 밑바닥에서 위쪽으로 토끼를 쑥 뽑아 올림</text>\n  <text x=\"32\" y=\"371\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">위에서 아래로 찌르면 매듭이 풀리는 올가미가 되므로 절대 주의하십시오.</text>\n</svg>","content/svgs/pr07-step-03.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGrad03\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0f1216\"/>\n      <stop offset=\"100%\" stop-color=\"#0a0c0e\"/>\n    </linearGradient>\n\n    <!-- Manila Standing Rope 3D Tubular Gradient -->\n    <linearGradient id=\"ropeManila03\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"25%\" stop-color=\"#b45309\"/>\n      <stop offset=\"50%\" stop-color=\"#fef3c7\"/>\n      <stop offset=\"75%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Tactical Green Working Rope 3D Gradient -->\n    <linearGradient id=\"ropeGreen03\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#14532d\"/>\n      <stop offset=\"25%\" stop-color=\"#16a34a\"/>\n      <stop offset=\"50%\" stop-color=\"#bbf7d0\"/>\n      <stop offset=\"75%\" stop-color=\"#22c55e\"/>\n      <stop offset=\"100%\" stop-color=\"#052e16\"/>\n    </linearGradient>\n\n    <!-- Deep Drop Shadow Filter for Over/Under Crossing -->\n    <filter id=\"shadowDeep03\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n\n    <!-- Twisted Rope Braid Pattern for Manila Rope -->\n    <pattern id=\"braidManila03\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"12\" stroke=\"#451a03\" stroke-width=\"2.5\" opacity=\"0.6\"/>\n      <line x1=\"6\" y1=\"0\" x2=\"6\" y2=\"12\" stroke=\"#fef3c7\" stroke-width=\"1.5\" opacity=\"0.4\"/>\n    </pattern>\n\n    <!-- Paracord Texture Pattern for Working End -->\n    <pattern id=\"braidGreen03\" width=\"8\" height=\"8\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(-45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#052e16\" stroke-width=\"2\" opacity=\"0.7\"/>\n      <line x1=\"4\" y1=\"0\" x2=\"4\" y2=\"8\" stroke=\"#bbf7d0\" stroke-width=\"1.2\" opacity=\"0.5\"/>\n    </pattern>\n  </defs>\n\n  <!-- Canvas Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGrad03)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 03 // BOWLINE STEP 3: 나무(원줄) 뒤편 선회</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Background Reference Grid -->\n  <g opacity=\"0.12\" stroke=\"#4b5563\" stroke-width=\"0.5\" stroke-dasharray=\"2 4\">\n    <line x1=\"60\" y1=\"40\" x2=\"60\" y2=\"340\"/>\n    <line x1=\"200\" y1=\"40\" x2=\"200\" y2=\"340\"/>\n    <line x1=\"340\" y1=\"40\" x2=\"340\" y2=\"340\"/>\n    <line x1=\"20\" y1=\"120\" x2=\"380\" y2=\"120\"/>\n    <line x1=\"20\" y1=\"200\" x2=\"380\" y2=\"200\"/>\n    <line x1=\"20\" y1=\"280\" x2=\"380\" y2=\"280\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 1. WORKING END (토끼 줄) BEHIND THE TREE (원줄 뒤편으로 감는 구간) -->\n  <!-- Drawn FIRST so the tree sits in FRONT of it! -->\n  <!-- ============================================================== -->\n  <!-- Loop emerging from throat hole and curving behind the tree to the left -->\n  <g opacity=\"0.95\">\n    <!-- Path behind the standing part -->\n    <path d=\"M 215 155 C 235 120 235 75 195 72 C 160 70 145 95 150 135\" \n          stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 215 155 C 235 120 235 75 195 72 C 160 70 145 95 150 135\" \n          stroke=\"url(#ropeGreen03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 215 155 C 235 120 235 75 195 72 C 160 70 145 95 150 135\" \n          stroke=\"url(#braidGreen03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 2. STANDING PART (나무 / 원줄) SITTING IN FRONT WITH HEAVY SHADOW -->\n  <!-- ============================================================== -->\n  <g filter=\"url(#shadowDeep03)\">\n    <!-- Standing Rope Main Vertical Trunk -->\n    <path d=\"M 195 42 L 195 120\" stroke=\"#000000\" stroke-width=\"20\" stroke-linecap=\"round\"/>\n    <path d=\"M 195 42 L 195 120\" stroke=\"url(#ropeManila03)\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n    <path d=\"M 195 42 L 195 120\" stroke=\"url(#braidManila03)\" stroke-width=\"14\" stroke-linecap=\"round\" opacity=\"0.75\"/>\n  </g>\n\n  <!-- Throat Loop (토끼굴 루프 - 6자 루프 구조) -->\n  <path d=\"M 195 120 C 130 135 125 215 185 225 C 235 230 255 190 230 155 C 210 130 180 122 145 140\" \n        stroke=\"#000000\" stroke-width=\"20\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 195 120 C 130 135 125 215 185 225 C 235 230 255 190 230 155 C 210 130 180 122 145 140\" \n        stroke=\"url(#ropeManila03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 195 120 C 130 135 125 215 185 225 C 235 230 255 190 230 155 C 210 130 180 122 145 140\" \n        stroke=\"url(#braidManila03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- Lower Main Eye Loop -->\n  <path d=\"M 185 225 C 185 280 145 325 105 325 C 65 325 40 270 50 210 C 60 160 105 130 145 140\" \n        stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 185 225 C 185 280 145 325 105 325 C 65 325 40 270 50 210 C 60 160 105 130 145 140\" \n        stroke=\"url(#ropeManila03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 185 225 C 185 280 145 325 105 325 C 65 325 40 270 50 210 C 60 160 105 130 145 140\" \n        stroke=\"url(#braidManila03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- ============================================================== -->\n  <!-- 3. WORKING END FRONT POINTER (굴로 다시 들어갈 준비) -->\n  <!-- ============================================================== -->\n  <!-- Green Tail emerging on the left, curving downward aiming into the hole -->\n  <g filter=\"url(#shadowDeep03)\">\n    <path d=\"M 150 135 C 152 148 165 160 175 168\" \n          stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 150 135 C 152 148 165 160 175 168\" \n          stroke=\"url(#ropeGreen03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 150 135 C 152 148 165 160 175 168\" \n          stroke=\"url(#braidGreen03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.85\"/>\n  </g>\n\n  <!-- Heat-sealed Red End Cap on Working Tip -->\n  <line x1=\"172\" y1=\"165\" x2=\"178\" y2=\"171\" stroke=\"#ef4444\" stroke-width=\"4\" stroke-linecap=\"square\"/>\n\n  <!-- ============================================================== -->\n  <!-- 4. MOTION & COGNITIVE BEHIND-THE-TREE CUES -->\n  <!-- ============================================================== -->\n  <!-- Behind-the-Tree Orbit Motion Arrow (시계 반대 방향 회전 궤적) -->\n  <path d=\"M 235 100 C 235 60 165 55 145 95 C 135 115 140 145 160 160\" \n        fill=\"none\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-dasharray=\"4 2\"/>\n  <polygon points=\"163,165 152,159 160,150\" fill=\"#ef4444\"/>\n\n\n\n  <!-- Re-entry Target Loupe Circle around throat hole -->\n  <circle cx=\"180\" cy=\"180\" r=\"18\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n\n  <!-- ============================================================== -->\n  <!-- 5. CALLOUT LABELS (9대 선언적 바인딩 라벨) -->\n  <!-- ============================================================== -->\n  <!-- Label 2 & 3: Around the tree (Top Right) -->\n  <line x1=\"225\" y1=\"95\" x2=\"265\" y2=\"95\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <circle cx=\"225\" cy=\"95\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"275\" y=\"92\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">AROUND THE TREE</text>\n  <text x=\"275\" y=\"105\" fill=\"#fef3c7\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">원줄 '뒤쪽'을 감아 돔</text>\n\n  <!-- Label 4 & 5: Tree Trunk Axis (Top Left) -->\n  <line x1=\"190\" y1=\"70\" x2=\"80\" y2=\"70\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"190\" cy=\"70\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"65\" fill=\"#ffffff\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">TREE (나무 기둥줄)</text>\n  <text x=\"24\" y=\"78\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">토끼가 돌아 나갈 중심 축</text>\n\n  <!-- Label 6 & 7: Re-entry Ready (Center Left) -->\n  <line x1=\"165\" y1=\"165\" x2=\"80\" y2=\"165\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <circle cx=\"165\" cy=\"165\" r=\"2.5\" fill=\"#38bdf8\"/>\n  <text x=\"24\" y=\"158\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">RE-ENTRY READY</text>\n  <text x=\"24\" y=\"171\" fill=\"#bae6fd\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">다시 굴로 진입할 준비</text>\n\n  <!-- Bottom Tactical Field Note Strip -->\n  <rect x=\"18\" y=\"342\" width=\"364\" height=\"40\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"342\" width=\"4\" height=\"40\" fill=\"#f59e0b\"/>\n  <!-- Label 8 & 9: Summary Instruction -->\n  <text x=\"32\" y=\"357\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\" font-weight=\"bold\">[3단계 핵심] 굴에서 나온 토끼가 원줄 뒤편을 감싸 돎</text>\n  <text x=\"32\" y=\"371\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">반드시 원줄의 '뒤'로 돌아야 단단히 조여지는 칼라(Collar) 루프가 만들어집니다.</text>\n</svg>","content/svgs/pr07-step-04.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGrad04\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0f1216\"/>\n      <stop offset=\"100%\" stop-color=\"#0a0c0e\"/>\n    </linearGradient>\n\n    <!-- Manila Standing Rope 3D Tubular Gradient -->\n    <linearGradient id=\"ropeManila04\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"25%\" stop-color=\"#b45309\"/>\n      <stop offset=\"50%\" stop-color=\"#fef3c7\"/>\n      <stop offset=\"75%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Tactical Green Working Rope 3D Gradient -->\n    <linearGradient id=\"ropeGreen04\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#14532d\"/>\n      <stop offset=\"25%\" stop-color=\"#16a34a\"/>\n      <stop offset=\"50%\" stop-color=\"#bbf7d0\"/>\n      <stop offset=\"75%\" stop-color=\"#22c55e\"/>\n      <stop offset=\"100%\" stop-color=\"#052e16\"/>\n    </linearGradient>\n\n    <!-- Deep Drop Shadow Filter for Over/Under Crossing -->\n    <filter id=\"shadowDeep04\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n\n    <!-- Twisted Rope Braid Pattern for Manila Rope -->\n    <pattern id=\"braidManila04\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"12\" stroke=\"#451a03\" stroke-width=\"2.5\" opacity=\"0.6\"/>\n      <line x1=\"6\" y1=\"0\" x2=\"6\" y2=\"12\" stroke=\"#fef3c7\" stroke-width=\"1.5\" opacity=\"0.4\"/>\n    </pattern>\n\n    <!-- Paracord Texture Pattern for Working End -->\n    <pattern id=\"braidGreen04\" width=\"8\" height=\"8\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(-45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#052e16\" stroke-width=\"2\" opacity=\"0.7\"/>\n      <line x1=\"4\" y1=\"0\" x2=\"4\" y2=\"8\" stroke=\"#bbf7d0\" stroke-width=\"1.2\" opacity=\"0.5\"/>\n    </pattern>\n  </defs>\n\n  <!-- Canvas Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGrad04)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 04 // BOWLINE STEP 4: 토끼굴 재진입</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Background Reference Grid -->\n  <g opacity=\"0.12\" stroke=\"#4b5563\" stroke-width=\"0.5\" stroke-dasharray=\"2 4\">\n    <line x1=\"60\" y1=\"40\" x2=\"60\" y2=\"340\"/>\n    <line x1=\"200\" y1=\"40\" x2=\"200\" y2=\"340\"/>\n    <line x1=\"340\" y1=\"40\" x2=\"340\" y2=\"340\"/>\n    <line x1=\"20\" y1=\"120\" x2=\"380\" y2=\"120\"/>\n    <line x1=\"20\" y1=\"200\" x2=\"380\" y2=\"200\"/>\n    <line x1=\"20\" y1=\"280\" x2=\"380\" y2=\"280\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 1. COLLAR LOOP BEHIND (원줄 뒤편을 통과해 나오는 U자 칼라) -->\n  <!-- ============================================================== -->\n  <path d=\"M 215 145 C 240 115 240 68 195 68 C 155 68 140 100 152 145\" \n        stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 215 145 C 240 115 240 68 195 68 C 155 68 140 100 152 145\" \n        stroke=\"url(#ropeGreen04)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 215 145 C 240 115 240 68 195 68 C 155 68 140 100 152 145\" \n        stroke=\"url(#braidGreen04)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n\n  <!-- ============================================================== -->\n  <!-- 2. STANDING PART (원줄 / 나무) SITTING IN FRONT -->\n  <!-- ============================================================== -->\n  <g filter=\"url(#shadowDeep04)\">\n    <!-- Standing Rope Main Vertical Trunk -->\n    <path d=\"M 195 42 L 195 120\" stroke=\"#000000\" stroke-width=\"20\" stroke-linecap=\"round\"/>\n    <path d=\"M 195 42 L 195 120\" stroke=\"url(#ropeManila04)\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n    <path d=\"M 195 42 L 195 120\" stroke=\"url(#braidManila04)\" stroke-width=\"14\" stroke-linecap=\"round\" opacity=\"0.75\"/>\n  </g>\n\n  <!-- Throat Loop (토끼굴 루프 - 6자 루프 구조) -->\n  <path d=\"M 195 120 C 130 135 125 215 185 225 C 235 230 255 190 230 155 C 210 130 180 122 145 140\" \n        stroke=\"#000000\" stroke-width=\"20\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 195 120 C 130 135 125 215 185 225 C 235 230 255 190 230 155 C 210 130 180 122 145 140\" \n        stroke=\"url(#ropeManila04)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 195 120 C 130 135 125 215 185 225 C 235 230 255 190 230 155 C 210 130 180 122 145 140\" \n        stroke=\"url(#braidManila04)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- Lower Main Eye Loop -->\n  <path d=\"M 185 225 C 185 280 145 325 105 325 C 65 325 40 270 50 210 C 60 160 105 130 145 140\" \n        stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 185 225 C 185 280 145 325 105 325 C 65 325 40 270 50 210 C 60 160 105 130 145 140\" \n        stroke=\"url(#ropeManila04)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 185 225 C 185 280 145 325 105 325 C 65 325 40 270 50 210 C 60 160 105 130 145 140\" \n        stroke=\"url(#braidManila04)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- ============================================================== -->\n  <!-- 3. PARALLEL GREEN STRANDS (굴 속으로 재진입하여 나란히 정렬) -->\n  <!-- ============================================================== -->\n  <g filter=\"url(#shadowDeep04)\">\n    <!-- Strand 1: Coming UP out of hole (From step 2) -->\n    <path d=\"M 172 205 L 172 150\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n    <path d=\"M 172 205 L 172 150\" stroke=\"url(#ropeGreen04)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n    <path d=\"M 172 205 L 172 150\" stroke=\"url(#braidGreen04)\" stroke-width=\"10\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n\n    <!-- Strand 2: Diving DOWN back into hole (From step 4) -->\n    <path d=\"M 186 145 L 186 215\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n    <path d=\"M 186 145 L 186 215\" stroke=\"url(#ropeGreen04)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n    <path d=\"M 186 145 L 186 215\" stroke=\"url(#braidGreen04)\" stroke-width=\"10\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n  </g>\n\n  <!-- Heat-sealed Red End Cap on Working Tip pointing down -->\n  <line x1=\"181\" y1=\"215\" x2=\"191\" y2=\"215\" stroke=\"#ef4444\" stroke-width=\"4\" stroke-linecap=\"square\"/>\n\n  <!-- Downward Re-entry Motion Arrow -->\n  <path d=\"M 186 130 L 186 165\" stroke=\"#ef4444\" stroke-width=\"2.5\" stroke-linecap=\"round\" fill=\"none\"/>\n  <polygon points=\"186,172 181,162 191,162\" fill=\"#ef4444\"/>\n\n  <!-- Parallel Alignment Bracket -->\n  <path d=\"M 164 165 L 160 165 L 160 195 L 164 195\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"1.2\"/>\n  <path d=\"M 194 165 L 198 165 L 198 195 L 194 195\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"1.2\"/>\n\n  <!-- ============================================================== -->\n  <!-- 4. CALLOUT LABELS (9대 선언적 바인딩 라벨) -->\n  <!-- ============================================================== -->\n  <!-- Label 2 & 3: Back Into Hole (Top Left) -->\n  <line x1=\"180\" y1=\"135\" x2=\"90\" y2=\"135\" stroke=\"#ef4444\" stroke-width=\"1\"/>\n  <circle cx=\"180\" cy=\"135\" r=\"2.5\" fill=\"#ef4444\"/>\n  <text x=\"24\" y=\"125\" fill=\"#f87171\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">BACK INTO HOLE</text>\n  <text x=\"24\" y=\"138\" fill=\"#fca5a5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">위에서 아래로 재진입</text>\n\n  <!-- Label 4 & 5: Parallel Strands (Center Right) -->\n  <line x1=\"198\" y1=\"180\" x2=\"265\" y2=\"180\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n  <circle cx=\"198\" cy=\"180\" r=\"2.5\" fill=\"#22c55e\"/>\n  <text x=\"275\" y=\"175\" fill=\"#86efac\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">PARALLEL STRANDS</text>\n  <text x=\"275\" y=\"188\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">두 가닥이 나란히 정렬</text>\n\n  <!-- Label 6 & 7: Collar Loop (Top Right) -->\n  <line x1=\"225\" y1=\"80\" x2=\"265\" y2=\"80\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <circle cx=\"225\" cy=\"80\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"275\" y=\"75\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">COLLAR LOOP</text>\n  <text x=\"275\" y=\"88\" fill=\"#fef3c7\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">나무를 감싼 뒤통수 고리</text>\n\n  <!-- Bottom Tactical Field Note Strip -->\n  <rect x=\"18\" y=\"342\" width=\"364\" height=\"40\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"342\" width=\"4\" height=\"40\" fill=\"#22c55e\"/>\n  <!-- Label 8 & 9: Summary Instruction -->\n  <text x=\"32\" y=\"357\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\" font-weight=\"bold\">[4단계 핵심] 토끼가 굴 속으로 다시 쏙 들어감</text>\n  <text x=\"32\" y=\"371\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">나무를 돌아 나온 끝단을 처음 나왔던 토끼굴에 위에서 아래로 찔러 넣습니다.</text>\n</svg>","content/svgs/pr07-step-05.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGrad05\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0f1216\"/>\n      <stop offset=\"100%\" stop-color=\"#0a0c0e\"/>\n    </linearGradient>\n\n    <!-- Manila Standing Rope 3D Tubular Gradient -->\n    <linearGradient id=\"ropeManila05\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"25%\" stop-color=\"#b45309\"/>\n      <stop offset=\"50%\" stop-color=\"#fef3c7\"/>\n      <stop offset=\"75%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Tactical Green Working Rope 3D Gradient -->\n    <linearGradient id=\"ropeGreen05\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#14532d\"/>\n      <stop offset=\"25%\" stop-color=\"#16a34a\"/>\n      <stop offset=\"50%\" stop-color=\"#bbf7d0\"/>\n      <stop offset=\"75%\" stop-color=\"#22c55e\"/>\n      <stop offset=\"100%\" stop-color=\"#052e16\"/>\n    </linearGradient>\n\n    <!-- Deep Drop Shadow Filter for Over/Under Crossing -->\n    <filter id=\"shadowDeep05\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n\n    <!-- Twisted Rope Braid Pattern for Manila Rope -->\n    <pattern id=\"braidManila05\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"12\" stroke=\"#451a03\" stroke-width=\"2.5\" opacity=\"0.6\"/>\n      <line x1=\"6\" y1=\"0\" x2=\"6\" y2=\"12\" stroke=\"#fef3c7\" stroke-width=\"1.5\" opacity=\"0.4\"/>\n    </pattern>\n\n    <!-- Paracord Texture Pattern for Working End -->\n    <pattern id=\"braidGreen05\" width=\"8\" height=\"8\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(-45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#052e16\" stroke-width=\"2\" opacity=\"0.7\"/>\n      <line x1=\"4\" y1=\"0\" x2=\"4\" y2=\"8\" stroke=\"#bbf7d0\" stroke-width=\"1.2\" opacity=\"0.5\"/>\n    </pattern>\n  </defs>\n\n  <!-- Canvas Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGrad05)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 05 // BOWLINE STEP 5: 락킹 및 1초 해체</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Background Reference Grid -->\n  <g opacity=\"0.12\" stroke=\"#4b5563\" stroke-width=\"0.5\" stroke-dasharray=\"2 4\">\n    <line x1=\"60\" y1=\"40\" x2=\"60\" y2=\"340\"/>\n    <line x1=\"200\" y1=\"40\" x2=\"200\" y2=\"340\"/>\n    <line x1=\"340\" y1=\"40\" x2=\"340\" y2=\"340\"/>\n    <line x1=\"20\" y1=\"120\" x2=\"380\" y2=\"120\"/>\n    <line x1=\"20\" y1=\"200\" x2=\"380\" y2=\"200\"/>\n    <line x1=\"20\" y1=\"280\" x2=\"380\" y2=\"280\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 1. FULLY TIGHTENED LOCKED BOWLINE KNOT (완벽 결속된 3D 매듭) -->\n  <!-- ============================================================== -->\n  <!-- Standing Part pulled upward under extreme tension -->\n  <path d=\"M 200 42 L 200 135\" stroke=\"#000000\" stroke-width=\"20\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 42 L 200 135\" stroke=\"url(#ropeManila05)\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 42 L 200 135\" stroke=\"url(#braidManila05)\" stroke-width=\"14\" stroke-linecap=\"round\" opacity=\"0.75\"/>\n\n  <!-- Rear Collar Loop (Behind Standing Line) -->\n  <path d=\"M 215 150 C 235 125 235 85 198 85 C 165 85 155 115 165 150\" \n        stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 215 150 C 235 125 235 85 198 85 C 165 85 155 115 165 150\" \n        stroke=\"url(#ropeGreen05)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 215 150 C 235 125 235 85 198 85 C 165 85 155 115 165 150\" \n        stroke=\"url(#braidGreen05)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n\n  <!-- Tightened Throat Loop (Locked Nipper Loop) -->\n  <g filter=\"url(#shadowDeep05)\">\n    <path d=\"M 200 135 C 160 145 155 195 190 202 C 225 205 235 180 220 155 C 205 138 185 135 160 148\" \n          stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 200 135 C 160 145 155 195 190 202 C 225 205 235 180 220 155 C 205 138 185 135 160 148\" \n          stroke=\"url(#ropeManila05)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 200 135 C 160 145 155 195 190 202 C 225 205 235 180 220 155 C 205 138 185 135 160 148\" \n          stroke=\"url(#braidManila05)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n  </g>\n\n  <!-- Locked Parallel Green Strands through Throat -->\n  <g filter=\"url(#shadowDeep05)\">\n    <!-- Emerging strand & Re-entered strand tightly bound together -->\n    <path d=\"M 180 185 L 180 148\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n    <path d=\"M 180 185 L 180 148\" stroke=\"url(#ropeGreen05)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n    <path d=\"M 193 145 L 193 192\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n    <path d=\"M 193 145 L 193 192\" stroke=\"url(#ropeGreen05)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n  </g>\n\n  <!-- Working Tail coming out inside the loop (Inside Tail - Correct Bowline) -->\n  <path d=\"M 193 192 C 193 210 215 220 230 220\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n  <path d=\"M 193 192 C 193 210 215 220 230 220\" stroke=\"url(#ropeGreen05)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n  <line x1=\"228\" y1=\"216\" x2=\"232\" y2=\"224\" stroke=\"#ef4444\" stroke-width=\"4\" stroke-linecap=\"square\"/>\n\n  <!-- Big Locked Main Loop (하중을 받아도 절대 줄어들지 않는 완벽 루프) -->\n  <path d=\"M 190 202 C 190 255 155 315 110 315 C 65 315 35 255 50 195 C 60 145 110 130 160 148\" \n        stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 190 202 C 190 255 155 315 110 315 C 65 315 35 255 50 195 C 60 145 110 130 160 148\" \n        stroke=\"url(#ropeManila05)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 190 202 C 190 255 155 315 110 315 C 65 315 35 255 50 195 C 60 145 110 130 160 148\" \n        stroke=\"url(#braidManila05)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- ============================================================== -->\n  <!-- 2. TENSION FORCES (사방 팽팽한 장력 화살표) -->\n  <!-- ============================================================== -->\n  <!-- Upward Force Arrow -->\n  <path d=\"M 200 70 L 200 45\" stroke=\"#ef4444\" stroke-width=\"2.5\" stroke-linecap=\"round\" fill=\"none\"/>\n  <polygon points=\"200,38 194,50 206,50\" fill=\"#ef4444\"/>\n\n  <!-- Rightward Grip Force Arrow -->\n  <path d=\"M 215 225 L 245 235\" stroke=\"#ef4444\" stroke-width=\"2.5\" stroke-linecap=\"round\" fill=\"none\"/>\n  <polygon points=\"252,237 240,230 243,242\" fill=\"#ef4444\"/>\n\n  <!-- ============================================================== -->\n  <!-- 3. INSET LOUPE: 1초 해체 (BREAK THE BACK 엄지손가락 꺾기 기법) -->\n  <!-- ============================================================== -->\n  <g transform=\"translate(85, 110)\">\n    <circle cx=\"0\" cy=\"0\" r=\"38\" fill=\"#0d1117\" stroke=\"#38bdf8\" stroke-width=\"1.8\"/>\n    <circle cx=\"0\" cy=\"0\" r=\"36\" fill=\"none\" stroke=\"#222\" stroke-width=\"1\"/>\n    \n    <!-- Standing Line inside Loupe -->\n    <line x1=\"0\" y1=\"-28\" x2=\"0\" y2=\"28\" stroke=\"#b45309\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n    \n    <!-- Collar Loop being tilted backwards -->\n    <path d=\"M 16 0 C 16 -18 -16 -18 -16 0\" stroke=\"#22c55e\" stroke-width=\"7\" stroke-linecap=\"round\" fill=\"none\"/>\n    \n    <!-- Thumb Push Force Vector (엄지 젖히기) -->\n    <path d=\"M 0 -8 C 0 -22 18 -22 22 -14\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 4. CALLOUT LABELS (12대 선언적 바인딩 라벨) -->\n  <!-- ============================================================== -->\n  <!-- Label 2, 3, 4: Quick Release Inset (Top Left) -->\n  <text x=\"24\" y=\"52\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">1-SEC QUICK RELEASE</text>\n  <text x=\"24\" y=\"65\" fill=\"#bae6fd\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">뒤통수(칼라) 꺾기 비법</text>\n  <text x=\"24\" y=\"162\" fill=\"#93c5fd\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">엄지로 칼라를 꺾으면 즉시 해체</text>\n\n  <!-- Label 5 & 6: Pull Standing (Top Right) -->\n  <line x1=\"210\" y1=\"55\" x2=\"265\" y2=\"55\" stroke=\"#ef4444\" stroke-width=\"1\"/>\n  <circle cx=\"210\" cy=\"55\" r=\"2.5\" fill=\"#ef4444\"/>\n  <text x=\"275\" y=\"50\" fill=\"#f87171\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">PULL STANDING</text>\n  <text x=\"275\" y=\"63\" fill=\"#fca5a5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">원줄을 위로 강하게 당김</text>\n\n  <!-- Label 7 & 8: Grip Together (Center Right) -->\n  <line x1=\"240\" y1=\"210\" x2=\"265\" y2=\"210\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n  <circle cx=\"240\" cy=\"210\" r=\"2.5\" fill=\"#22c55e\"/>\n  <text x=\"275\" y=\"205\" fill=\"#86efac\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">GRIP TOGETHER</text>\n  <text x=\"275\" y=\"218\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">끝단과 고리를 한 손에 쥠</text>\n\n  <!-- Label 9 & 10: Locked Fixed Loop (Bottom Left) -->\n  <line x1=\"60\" y1=\"280\" x2=\"30\" y2=\"280\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <circle cx=\"60\" cy=\"280\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"268\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">LOCKED FIXED LOOP</text>\n  <text x=\"24\" y=\"281\" fill=\"#fef3c7\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">하중을 받아도 크기 불변</text>\n\n  <!-- Bottom Tactical Field Note Strip -->\n  <rect x=\"18\" y=\"342\" width=\"364\" height=\"40\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"342\" width=\"4\" height=\"40\" fill=\"#38bdf8\"/>\n  <!-- Label 11 & 12: Summary Instruction -->\n  <text x=\"32\" y=\"357\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\" font-weight=\"bold\">[5단계 핵심] 양손으로 잡고 반대로 당겨 락킹 체결</text>\n  <text x=\"32\" y=\"371\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">풀 때는 매듭 뒤편 칼라 링을 엄지로 젖히면 칼 없이 1초 만에 풀립니다.</text>\n</svg>","content/svgs/pr08-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgOut\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0f131a\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Heavy Slate Rock Texture Gradient -->\n    <linearGradient id=\"rockOut\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#64748b\"/>\n      <stop offset=\"25%\" stop-color=\"#475569\"/>\n      <stop offset=\"65%\" stop-color=\"#334155\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n\n    <!-- Rock Side Thickness Gradient -->\n    <linearGradient id=\"rockRimOut\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#94a3b8\"/>\n      <stop offset=\"50%\" stop-color=\"#64748b\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n\n    <!-- Rock Underside Cavern Shadow Gradient -->\n    <linearGradient id=\"rockUnderOut\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"50%\" stop-color=\"#0f172a\"/>\n      <stop offset=\"100%\" stop-color=\"#020617\"/>\n    </linearGradient>\n\n    <!-- Hardwood Cylinder 3D Gradient -->\n    <linearGradient id=\"stick3D\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3d210f\"/>\n      <stop offset=\"35%\" stop-color=\"#78350f\"/>\n      <stop offset=\"70%\" stop-color=\"#a15112\"/>\n      <stop offset=\"100%\" stop-color=\"#3d210f\"/>\n    </linearGradient>\n\n    <!-- Diagonal Strut Gradient -->\n    <linearGradient id=\"strut3D\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#3d210f\"/>\n      <stop offset=\"40%\" stop-color=\"#854d0e\"/>\n      <stop offset=\"75%\" stop-color=\"#b45309\"/>\n      <stop offset=\"100%\" stop-color=\"#2d1607\"/>\n    </linearGradient>\n\n    <!-- Carved Notch Pale Wood -->\n    <linearGradient id=\"carvedOut\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\"/>\n      <stop offset=\"60%\" stop-color=\"#fde68a\"/>\n      <stop offset=\"100%\" stop-color=\"#d97706\"/>\n    </linearGradient>\n\n    <!-- Deep Ground Cast Shadow -->\n    <filter id=\"shadowOut\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"10\" stdDeviation=\"8\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"800\" height=\"450\" fill=\"url(#bgOut)\"/>\n  <rect x=\"12\" y=\"12\" width=\"776\" height=\"426\" fill=\"none\" stroke=\"#222831\" stroke-width=\"1.5\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 20 32 L 36 32 M 28 24 L 28 40\" stroke=\"#4b5563\" stroke-width=\"1.5\"/>\n  <path d=\"M 780 32 L 764 32 M 772 24 L 772 40\" stroke=\"#4b5563\" stroke-width=\"1.5\"/>\n  <path d=\"M 20 418 L 36 418 M 28 410 L 28 426\" stroke=\"#4b5563\" stroke-width=\"1.5\"/>\n  <path d=\"M 780 418 L 764 418 M 772 410 L 772 426\" stroke=\"#4b5563\" stroke-width=\"1.5\"/>\n\n  <!-- Top Technical Header Strip -->\n  <rect x=\"28\" y=\"24\" width=\"744\" height=\"34\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"28\" y=\"24\" width=\"4\" height=\"34\" fill=\"#ef4444\"/>\n  <text x=\"44\" y=\"45\" fill=\"#f8fafc\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\" letter-spacing=\"1\">TARGET OUTCOME // FIGURE-4 DEADFALL TRAP</text>\n  <text x=\"756\" y=\"45\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"end\">PR-08 // FULL ASSEMBLY OVERVIEW</text>\n\n  <!-- Ground Plane Baseline -->\n  <line x1=\"40\" y1=\"365\" x2=\"760\" y2=\"365\" stroke=\"#334155\" stroke-width=\"2\"/>\n  <path d=\"M 60 370 L 80 385 M 120 370 L 140 385 M 180 370 L 200 385 M 240 370 L 260 385 M 300 370 L 320 385 M 360 370 L 380 385 M 420 370 L 440 385 M 480 370 L 500 385 M 540 370 L 560 385 M 600 370 L 620 385 M 660 370 L 680 385\" stroke=\"#1e293b\" stroke-width=\"1.2\"/>\n\n  <!-- Ground Shadows Beneath Post and Rock Ground Base -->\n  <ellipse cx=\"243\" cy=\"368\" rx=\"40\" ry=\"8\" fill=\"#000000\" opacity=\"0.8\"/>\n  <ellipse cx=\"620\" cy=\"368\" rx=\"85\" ry=\"12\" fill=\"#000000\" opacity=\"0.85\"/>\n\n  <!-- ============================================== -->\n  <!-- 1. HEAVY 15KG SLATE ROCK (3D Propped Canopy Slab) -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowOut)\">\n    <!-- Underside Cavern Ceiling (Dark shadowed interior beneath the rock) -->\n    <polygon points=\"223,125 650,195 750,365 240,365\" fill=\"url(#rockUnderOut)\" stroke=\"#0f172a\" stroke-width=\"1.2\"/>\n    <!-- Top Face of Heavy Slate Slab (Slanted backward towards ground) -->\n    <polygon points=\"223,110 250,90 680,150 770,345 750,365 650,180\" fill=\"url(#rockOut)\" stroke=\"#1e293b\" stroke-width=\"2.2\"/>\n    <!-- Front Lifted Lip Thickness (Resting cleanly on strut tip at (223,125)) -->\n    <polygon points=\"223,125 650,195 650,180 223,110\" fill=\"#94a3b8\" stroke=\"#475569\" stroke-width=\"1\"/>\n    <!-- Rock Surface Geological Cleavage & Fractures -->\n    <path d=\"M 310 115 L 450 200 L 600 280 M 380 135 L 540 230 M 480 170 L 630 270\" stroke=\"#1e293b\" stroke-width=\"1.5\" stroke-linecap=\"round\"/>\n  </g>\n\n  <!-- ============================================== -->\n  <!-- 2. FIGURE-4 INTERLOCKING FRAME (In Foreground) -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowOut)\">\n    <!-- Stick 1: Vertical Post (세움대 - x=230 to 256, y=175 to 365) -->\n    <rect x=\"230\" y=\"175\" width=\"26\" height=\"190\" rx=\"3\" fill=\"url(#stick3D)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n    <!-- Post Chisel Top Head (납작 쐐기 - Peak at (243, 145)) -->\n    <polygon points=\"230,175 243,145 256,175\" fill=\"url(#carvedOut)\" stroke=\"#78350f\" stroke-width=\"1\"/>\n    <!-- Middle Notch in Post (네모 홈 - y=268 to 286) -->\n    <rect x=\"230\" y=\"268\" width=\"14\" height=\"18\" fill=\"url(#carvedOut)\" stroke=\"#78350f\" stroke-width=\"1\"/>\n    <!-- Wood Bark Lines -->\n    <line x1=\"237\" y1=\"210\" x2=\"237\" y2=\"250\" stroke=\"#271408\" stroke-width=\"1\"/>\n    <line x1=\"250\" y1=\"295\" x2=\"250\" y2=\"345\" stroke=\"#271408\" stroke-width=\"1\"/>\n\n    <!-- Stick 2: Diagonal Strut (Mathematically 45.0°, Top at (243, 145) down to (368, 270)) -->\n    <!-- Extends above post to (223, 125) propping up rock, and bottom lands inside Bait stick rear notch at (368, 270) -->\n    <polygon points=\"213,115 225,127 243,145 255,133 267,145 378,256 368,272 356,260 233,137 223,125 203,105\" fill=\"url(#strut3D)\" stroke=\"#271408\" stroke-width=\"1.5\"/>\n\n    <!-- Upper Strut Tip Support Notch (Props Rock at (223, 125)) -->\n    <polygon points=\"213,115 225,127 223,125\" fill=\"url(#carvedOut)\" stroke=\"#b45309\" stroke-width=\"1.2\"/>\n    <!-- Mating Notch over Post Chisel Head (243, 145) -->\n    <polygon points=\"233,137 243,145 251,137 243,141\" fill=\"url(#carvedOut)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <!-- Bottom Beveled Tip (Locks into Bait stick rear notch at y=270) -->\n    <polygon points=\"356,260 368,272 378,256 368,252\" fill=\"url(#carvedOut)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n\n    <!-- Mechanical Contact Pivot Markers -->\n    <circle cx=\"223\" cy=\"125\" r=\"5\" fill=\"#ef4444\" opacity=\"0.95\"/>\n    <circle cx=\"223\" cy=\"125\" r=\"9\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"1.2\" stroke-dasharray=\"2 2\"/>\n    <circle cx=\"243\" cy=\"145\" r=\"4.5\" fill=\"#38bdf8\" opacity=\"0.95\"/>\n    <circle cx=\"368\" cy=\"270\" r=\"4.5\" fill=\"#38bdf8\" opacity=\"0.95\"/>\n\n    <!-- Stick 3: Horizontal Bait Stick (먹이대 - x=195 horizontally through to x=460, y=270 to 286) -->\n    <!-- Extends deeply into the danger zone sheltered beneath the rock -->\n    <path d=\"M 195 270 L 435 270 L 460 278 L 435 286 L 195 286 Z\" fill=\"url(#stick3D)\" stroke=\"#271408\" stroke-width=\"1.5\"/>\n    <!-- Catch Ledge on Bait Stick (locked with post at x=230) -->\n    <polygon points=\"228,268 245,268 245,286 228,286\" fill=\"url(#carvedOut)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <!-- Rear Notch on Bait Stick (locked with strut bottom at x=360..376, y=270) -->\n    <polygon points=\"360,270 376,270 368,284\" fill=\"url(#carvedOut)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n\n    <!-- Sharp Bait Pin at Far Right (under the rock) -->\n    <polygon points=\"435,270 460,278 435,286\" fill=\"url(#carvedOut)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <!-- Juicy Red Wild Berries Bait -->\n    <circle cx=\"450\" cy=\"278\" r=\"7\" fill=\"#ef4444\"/>\n    <circle cx=\"457\" cy=\"273\" r=\"5.5\" fill=\"#dc2626\"/>\n    <circle cx=\"456\" cy=\"283\" r=\"5\" fill=\"#b91c1c\"/>\n    <circle cx=\"450\" cy=\"278\" r=\"11\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  </g>\n\n  <!-- ============================================== -->\n  <!-- TECHNICAL LABELS & POINTERS -->\n  <!-- ============================================== -->\n  <!-- 1. Rock Pointer -->\n  <line x1=\"395\" y1=\"175\" x2=\"350\" y2=\"82\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n  <circle cx=\"395\" cy=\"175\" r=\"3.5\" fill=\"#38bdf8\"/>\n  <rect x=\"235\" y=\"70\" width=\"230\" height=\"22\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"85\" fill=\"#38bdf8\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">15kg 넓적한 평평한 바위 (45도 기울임)</text>\n\n  <!-- 2. Post 1 Pointer -->\n  <line x1=\"243\" y1=\"310\" x2=\"160\" y2=\"310\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n  <circle cx=\"243\" cy=\"310\" r=\"3.5\" fill=\"#f59e0b\"/>\n  <rect x=\"35\" y=\"299\" width=\"125\" height=\"22\" fill=\"#18181b\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <text x=\"45\" y=\"314\" fill=\"#fbbf24\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\">1번 세움대 (땅에 똑바로 선 기둥)</text>\n\n  <!-- 3. Strut 2 Pointer -->\n  <line x1=\"285\" y1=\"185\" x2=\"200\" y2=\"150\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n  <circle cx=\"285\" cy=\"185\" r=\"3.5\" fill=\"#f59e0b\"/>\n  <rect x=\"35\" y=\"140\" width=\"165\" height=\"22\" fill=\"#18181b\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <text x=\"45\" y=\"155\" fill=\"#fbbf24\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\">2번 빗장대 (바위를 떠받치는 버팀목)</text>\n\n  <!-- 4. Bait Stick 3 Pointer -->\n  <line x1=\"450\" y1=\"278\" x2=\"520\" y2=\"245\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n  <circle cx=\"450\" cy=\"278\" r=\"3.5\" fill=\"#ef4444\"/>\n  <rect x=\"520\" y=\"234\" width=\"175\" height=\"22\" fill=\"#18181b\" stroke=\"#ef4444\" stroke-width=\"1\"/>\n  <text x=\"530\" y=\"249\" fill=\"#f87171\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\">3번 먹이대 (먹이를 꽂아둔 가로 막대)</text>\n\n  <!-- Bottom Right Summary Callout Box -->\n  <rect x=\"430\" y=\"335\" width=\"335\" height=\"52\" fill=\"#0d1117\" stroke=\"#21262d\" stroke-width=\"1\"/>\n  <rect x=\"430\" y=\"335\" width=\"4\" height=\"52\" fill=\"#22c55e\"/>\n  <text x=\"445\" y=\"354\" fill=\"#f8fafc\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[완성 기준] 먹이를 톡 건드리면 0.1초 만에 붕괴</text>\n  <text x=\"445\" y=\"369\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">・끈 하나 없이 세 막대의 맞물림만으로 15kg 바위를 지탱합니다.</text>\n  <text x=\"445\" y=\"381\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">・안쪽 미끼를 건드리는 즉시 뼈대가 풀려 바위가 단번에 덮칩니다.</text>\n</svg>\n","content/svgs/pr08-step-01.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Bark Wood Gradient (Outer Bark) -->\n    <linearGradient id=\"barkGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#5c3a21\"/>\n      <stop offset=\"25%\" stop-color=\"#8a532a\"/>\n      <stop offset=\"60%\" stop-color=\"#6e3f1d\"/>\n      <stop offset=\"100%\" stop-color=\"#3d210f\"/>\n    </linearGradient>\n\n    <!-- Carved Inner Wood (Pale Flesh Tone) -->\n    <linearGradient id=\"carvedWood\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\"/>\n      <stop offset=\"40%\" stop-color=\"#fef3c7\"/>\n      <stop offset=\"85%\" stop-color=\"#fde68a\"/>\n      <stop offset=\"100%\" stop-color=\"#d97706\"/>\n    </linearGradient>\n\n    <!-- Deep Drop Shadow -->\n    <filter id=\"shadowS1\" x=\"-15%\" y=\"-20%\" width=\"130%\" height=\"150%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.85\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS1)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#ef4444\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 01 // 3 STICKS ANATOMY &amp; NOTCHES</text>\n\n  <!-- Grid Guide Lines -->\n  <line x1=\"45\" y1=\"45\" x2=\"45\" y2=\"340\" stroke=\"#171f2a\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <line x1=\"355\" y1=\"45\" x2=\"355\" y2=\"340\" stroke=\"#171f2a\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n\n  <!-- ========================================== -->\n  <!-- 1. STICK 1: VERTICAL POST (세움대 20cm) -->\n  <!-- ========================================== -->\n  <g filter=\"url(#shadowS1)\">\n    <!-- Round End (Bottom Base, right side) -->\n    <ellipse cx=\"280\" cy=\"78\" rx=\"5\" ry=\"11\" fill=\"#3d210f\"/>\n    <!-- Main Cylinder Body -->\n    <path d=\"M 80 67 L 280 67 A 5 11 0 0 1 280 89 L 80 89 Z\" fill=\"url(#barkGrad)\" stroke=\"#271408\" stroke-width=\"1\"/>\n    <!-- Bark Texture Lines -->\n    <line x1=\"110\" y1=\"72\" x2=\"140\" y2=\"72\" stroke=\"#3d210f\" stroke-width=\"1\" stroke-linecap=\"round\"/>\n    <line x1=\"210\" y1=\"84\" x2=\"250\" y2=\"84\" stroke=\"#3d210f\" stroke-width=\"1\" stroke-linecap=\"round\"/>\n\n    <!-- Left Chisel Tip (납작 쐐기 깎은 단면) -->\n    <polygon points=\"80,67 52,78 80,89\" fill=\"url(#carvedWood)\" stroke=\"#92400e\" stroke-width=\"1.2\"/>\n    <line x1=\"52\" y1=\"78\" x2=\"80\" y2=\"78\" stroke=\"#b45309\" stroke-width=\"0.8\" stroke-dasharray=\"2 1\"/>\n\n    <!-- Middle Square Notch (가운데 사각 홈) -->\n    <polygon points=\"155,67 175,67 175,80 155,80\" fill=\"url(#carvedWood)\" stroke=\"#78350f\" stroke-width=\"1\"/>\n    <polygon points=\"155,80 175,80 175,82 155,82\" fill=\"#451a03\"/>\n    <!-- Graphic Notch Pointer -->\n    <path d=\"M 165 95 L 165 84\" stroke=\"#ef4444\" stroke-width=\"1.2\"/>\n    <polygon points=\"163,84 165,80 167,84\" fill=\"#ef4444\"/>\n  </g>\n\n  <!-- Label 2: Stick 1 -->\n  <text x=\"50\" y=\"58\" fill=\"#f59e0b\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">POST (1번 세움대 - 윗머리 납작 쐐기 &amp; 네모 홈)</text>\n\n  <!-- ========================================== -->\n  <!-- 2. STICK 2: DIAGONAL STRUT (빗장대 25cm) -->\n  <!-- ========================================== -->\n  <g filter=\"url(#shadowS1)\">\n    <!-- Base Cylinder -->\n    <ellipse cx=\"315\" cy=\"165\" rx=\"5\" ry=\"11\" fill=\"#3d210f\"/>\n    <path d=\"M 65 154 L 315 154 A 5 11 0 0 1 315 176 L 65 176 Z\" fill=\"url(#barkGrad)\" stroke=\"#271408\" stroke-width=\"1\"/>\n    <!-- Bark Texture -->\n    <line x1=\"120\" y1=\"160\" x2=\"160\" y2=\"160\" stroke=\"#3d210f\" stroke-width=\"1\" stroke-linecap=\"round\"/>\n\n    <!-- Left Top V-Notch (상단 45도 V자 홈) -->\n    <polygon points=\"78,154 98,154 78,174\" fill=\"url(#carvedWood)\" stroke=\"#92400e\" stroke-width=\"1.2\"/>\n    <polygon points=\"78,174 98,154 98,156 80,176\" fill=\"#451a03\"/>\n    <path d=\"M 65 154 L 78 154 L 78 174 L 65 176 Z\" fill=\"url(#carvedWood)\" stroke=\"#92400e\" stroke-width=\"0.8\"/>\n\n    <!-- Right Bottom Bevel (하단 45도 안쪽 깎기) -->\n    <polygon points=\"300,154 315,154 300,176\" fill=\"url(#carvedWood)\" stroke=\"#92400e\" stroke-width=\"1\"/>\n    <!-- Graphic V-Notch Pointer -->\n    <path d=\"M 88 188 L 88 177\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n    <polygon points=\"86,177 88,173 90,177\" fill=\"#38bdf8\"/>\n  </g>\n\n  <!-- Label 3: Stick 2 -->\n  <text x=\"50\" y=\"145\" fill=\"#f59e0b\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">STRUT (2번 빗장대 - 윗머리 V홈 &amp; 아랫머리 쐐기)</text>\n\n  <!-- ========================================== -->\n  <!-- 3. STICK 3: BAIT STICK (먹이대 30cm) -->\n  <!-- ========================================== -->\n  <g filter=\"url(#shadowS1)\">\n    <!-- Base Cylinder -->\n    <path d=\"M 60 242 L 320 242 L 350 253 L 320 264 L 60 264 Z\" fill=\"url(#barkGrad)\" stroke=\"#271408\" stroke-width=\"1\"/>\n    <!-- Bark Texture -->\n    <line x1=\"130\" y1=\"248\" x2=\"180\" y2=\"248\" stroke=\"#3d210f\" stroke-width=\"1\" stroke-linecap=\"round\"/>\n\n    <!-- Front Catch Ledge -->\n    <polygon points=\"60,242 85,242 85,251 60,251\" fill=\"url(#carvedWood)\" stroke=\"#92400e\" stroke-width=\"1.2\"/>\n    <polygon points=\"60,251 85,251 85,253 60,253\" fill=\"#451a03\"/>\n\n    <!-- Rear Notch for Strut -->\n    <polygon points=\"170,242 188,242 170,256\" fill=\"url(#carvedWood)\" stroke=\"#92400e\" stroke-width=\"1.2\"/>\n\n    <!-- Sharp Pencil Tip on Far Right -->\n    <polygon points=\"320,242 350,253 320,264\" fill=\"url(#carvedWood)\" stroke=\"#92400e\" stroke-width=\"1.2\"/>\n    <circle cx=\"348\" cy=\"253\" r=\"3.5\" fill=\"#ef4444\"/>\n    <!-- Graphic Bait Pointer -->\n    <path d=\"M 348 275 L 348 264\" stroke=\"#ef4444\" stroke-width=\"1.2\"/>\n    <polygon points=\"346,264 348,260 350,264\" fill=\"#ef4444\"/>\n  </g>\n\n  <!-- Label 4: Stick 3 -->\n  <text x=\"50\" y=\"233\" fill=\"#f59e0b\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">BAIT STICK (3번 먹이대 - 걸림턱 &amp; 홈 &amp; 뾰족한 끝)</text>\n\n  <!-- Bottom Visual Callout Box (Label 5) -->\n  <rect x=\"20\" y=\"315\" width=\"360\" height=\"58\" fill=\"#0d1117\" stroke=\"#21262d\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"315\" width=\"3\" height=\"58\" fill=\"#f59e0b\"/>\n  <text x=\"32\" y=\"348\" fill=\"#f8fafc\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[핵심] 서로 딱 물리는 직각 홈과 걸림턱 깎기</text>\n</svg>\n","content/svgs/pr08-step-02.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Bark Wood Gradient -->\n    <linearGradient id=\"barkGrad2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#451a03\"/>\n      <stop offset=\"30%\" stop-color=\"#78350f\"/>\n      <stop offset=\"70%\" stop-color=\"#92400e\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Diagonal Bark Wood Gradient -->\n    <linearGradient id=\"diagBark\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#3d210f\"/>\n      <stop offset=\"35%\" stop-color=\"#78350f\"/>\n      <stop offset=\"75%\" stop-color=\"#92400e\"/>\n      <stop offset=\"100%\" stop-color=\"#2d1607\"/>\n    </linearGradient>\n\n    <!-- Fresh Cut Inner Wood -->\n    <linearGradient id=\"cutWood2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\"/>\n      <stop offset=\"50%\" stop-color=\"#fde68a\"/>\n      <stop offset=\"100%\" stop-color=\"#d97706\"/>\n    </linearGradient>\n\n    <filter id=\"shadowS2\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"6\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS2)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#3b82f6\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 02 // TOP NOTCH INTERLOCK</text>\n\n  <!-- Ground Plane Baseline -->\n  <line x1=\"30\" y1=\"310\" x2=\"370\" y2=\"310\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <path d=\"M 50 312 L 65 322 M 100 312 L 115 322 M 150 312 L 165 322 M 200 312 L 215 322 M 250 312 L 265 322 M 300 312 L 315 322\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n\n  <!-- ============================================== -->\n  <!-- MAIN ASSEMBLY: POST 1 & STRUT 2 TOP INTERLOCK -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowS2)\">\n    <!-- 1. Stick 1: Vertical Post (x=132 to 156, y=135 to 310) -->\n    <rect x=\"132\" y=\"135\" width=\"24\" height=\"175\" rx=\"3\" fill=\"url(#barkGrad2)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n    <!-- Bark Texture Lines -->\n    <line x1=\"138\" y1=\"180\" x2=\"138\" y2=\"230\" stroke=\"#3d210f\" stroke-width=\"1\"/>\n    <line x1=\"150\" y1=\"200\" x2=\"150\" y2=\"260\" stroke=\"#3d210f\" stroke-width=\"1\"/>\n\n    <!-- Post Top Chisel Tip (납작 쐐기 - y=105 to 135, Peak at (144, 105)) -->\n    <polygon points=\"132,135 144,105 156,135\" fill=\"url(#cutWood2)\" stroke=\"#78350f\" stroke-width=\"1.2\"/>\n    <line x1=\"144\" y1=\"105\" x2=\"144\" y2=\"135\" stroke=\"#b45309\" stroke-width=\"1\" stroke-dasharray=\"2 1\"/>\n\n    <!-- 2. Stick 2: Diagonal Strut (Leaning 45 degrees, coming from (305, 266) to (144, 105)) -->\n    <!-- Direct V-notch cavity physically nesting over Chisel peak (144, 105) -->\n    <polygon points=\"130,91 144,105 158,91 172,105 315,248 297,266 154,123 144,113 134,123 116,105\" fill=\"url(#diagBark)\" stroke=\"#271408\" stroke-width=\"1.5\"/>\n\n    <!-- Inner Carved V-Notch Face (#fde68a 고대비 하이라이트) -->\n    <polygon points=\"134,123 144,105 154,123 144,113\" fill=\"url(#cutWood2)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n\n    <!-- Contact Pivot Highlight (Mechanical Axis alignment point) -->\n    <circle cx=\"144\" cy=\"105\" r=\"4.5\" fill=\"#ef4444\" opacity=\"0.95\"/>\n    <circle cx=\"144\" cy=\"105\" r=\"8\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  </g>\n\n  <!-- Force & Angle Indicators (Graphic Only) -->\n  <path d=\"M 225 150 L 165 110\" stroke=\"#38bdf8\" stroke-width=\"2.5\" stroke-linecap=\"round\"/>\n  <polygon points=\"160,107 172,111 168,118\" fill=\"#38bdf8\"/>\n  <path d=\"M 175 138 A 35 35 0 0 1 190 162\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/>\n\n  <!-- Technical Magnifier Inspection Ring (Inset Zoom) -->\n  <g transform=\"translate(45, 60)\">\n    <circle cx=\"45\" cy=\"45\" r=\"40\" fill=\"#090d16\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n    <circle cx=\"45\" cy=\"45\" r=\"44\" fill=\"none\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n    <!-- Zoom Joint Silhouette: Post Chisel nested in Strut V-Notch -->\n    <polygon points=\"35,65 45,35 55,65\" fill=\"#fde68a\" stroke=\"#78350f\" stroke-width=\"1.5\"/>\n    <polygon points=\"28,28 45,35 62,28 72,38 52,58 45,45 38,58 18,38\" fill=\"#854d0e\" stroke=\"#271408\" stroke-width=\"1.5\"/>\n    <polygon points=\"38,45 45,35 52,45 45,42\" fill=\"#fde68a\"/>\n    <!-- Lock Check Icon -->\n    <path d=\"M 38 78 L 43 83 L 53 73\" stroke=\"#22c55e\" stroke-width=\"1.8\" fill=\"none\"/>\n  </g>\n\n  <!-- Technical Label Pointers with Direct Lines to Joint -->\n  <!-- Label 2: Post Tip -->\n  <line x1=\"140\" y1=\"102\" x2=\"80\" y2=\"55\" stroke=\"#f59e0b\" stroke-width=\"1.2\"/>\n  <circle cx=\"140\" cy=\"102\" r=\"3\" fill=\"#f59e0b\"/>\n  <rect x=\"25\" y=\"45\" width=\"140\" height=\"20\" fill=\"#18181b\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <text x=\"95\" y=\"59\" fill=\"#fbbf24\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">1번 세움대 납작 윗머리</text>\n\n  <!-- Label 3: Strut V-notch (Points directly to red contact hinge circle) -->\n  <line x1=\"148\" y1=\"105\" x2=\"220\" y2=\"75\" stroke=\"#f59e0b\" stroke-width=\"1.2\"/>\n  <circle cx=\"148\" cy=\"105\" r=\"3\" fill=\"#f59e0b\"/>\n  <rect x=\"200\" y=\"65\" width=\"150\" height=\"20\" fill=\"#18181b\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <text x=\"275\" y=\"79\" fill=\"#fbbf24\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">2번 빗장대 V자 홈 결합</text>\n\n  <!-- Label 4: Angle Mating -->\n  <rect x=\"180\" y=\"165\" width=\"135\" height=\"20\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"247\" y=\"179\" fill=\"#38bdf8\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">45도 각도로 딱 맞물림</text>\n\n  <!-- Bottom Visual Callout Box (Label 5) -->\n  <rect x=\"20\" y=\"325\" width=\"360\" height=\"52\" fill=\"#0d1117\" stroke=\"#21262d\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"325\" width=\"3\" height=\"52\" fill=\"#3b82f6\"/>\n  <text x=\"32\" y=\"355\" fill=\"#f8fafc\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[핵심] 미끄러지지 않고 딱 물리는 상단 결합</text>\n</svg>\n","content/svgs/pr08-step-03.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Post Wood Gradient (Vertical) -->\n    <linearGradient id=\"postWoodS3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3d210f\"/>\n      <stop offset=\"35%\" stop-color=\"#78350f\"/>\n      <stop offset=\"70%\" stop-color=\"#92400e\"/>\n      <stop offset=\"100%\" stop-color=\"#3d210f\"/>\n    </linearGradient>\n\n    <!-- Strut Wood Gradient (Diagonal) -->\n    <linearGradient id=\"strutWoodS3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#3d210f\"/>\n      <stop offset=\"40%\" stop-color=\"#854d0e\"/>\n      <stop offset=\"75%\" stop-color=\"#b45309\"/>\n      <stop offset=\"100%\" stop-color=\"#2d1607\"/>\n    </linearGradient>\n\n    <!-- Bait Stick Wood Gradient (Horizontal) -->\n    <linearGradient id=\"baitWoodS3\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#854d0e\"/>\n      <stop offset=\"30%\" stop-color=\"#b45309\"/>\n      <stop offset=\"70%\" stop-color=\"#92400e\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Inner Carved Notches Highlight -->\n    <linearGradient id=\"notchFlesh\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\"/>\n      <stop offset=\"60%\" stop-color=\"#fde68a\"/>\n      <stop offset=\"100%\" stop-color=\"#d97706\"/>\n    </linearGradient>\n\n    <filter id=\"shadowS3\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"6\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS3)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#22c55e\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 03 // NUMBER 4 LOCK ASSEMBLY</text>\n\n  <!-- Ground Plane Baseline -->\n  <line x1=\"30\" y1=\"310\" x2=\"370\" y2=\"310\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <path d=\"M 50 312 L 65 322 M 100 312 L 115 322 M 150 312 L 165 322 M 200 312 L 215 322 M 250 312 L 265 322 M 300 312 L 315 322\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n\n  <!-- Ground Shadows Beneath Post -->\n  <ellipse cx=\"156\" cy=\"311\" rx=\"28\" ry=\"5\" fill=\"#000000\" opacity=\"0.8\"/>\n\n  <!-- ============================================== -->\n  <!-- FULL NUMERAL 4 ASSEMBLED STANDALONE FRAME -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowS3)\">\n    <!-- 1. Stick 1: Vertical Post (Straight Upright: x=145 to 167, y=125 to 310) -->\n    <rect x=\"145\" y=\"125\" width=\"22\" height=\"185\" rx=\"2.5\" fill=\"url(#postWoodS3)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n    <!-- Top Chisel Tip (Peak at (156, 95)) -->\n    <polygon points=\"145,125 156,95 167,125\" fill=\"url(#notchFlesh)\" stroke=\"#78350f\" stroke-width=\"1\"/>\n\n    <!-- Middle Notch in Post (y=192 to 208) -->\n    <rect x=\"145\" y=\"192\" width=\"12\" height=\"16\" fill=\"url(#notchFlesh)\" stroke=\"#78350f\" stroke-width=\"1\"/>\n    <!-- Post Bark Lines -->\n    <line x1=\"150\" y1=\"140\" x2=\"150\" y2=\"185\" stroke=\"#271408\" stroke-width=\"0.8\"/>\n    <line x1=\"162\" y1=\"215\" x2=\"162\" y2=\"290\" stroke=\"#271408\" stroke-width=\"0.8\"/>\n\n    <!-- 2. Stick 2: Diagonal Strut (Mathematically 45.0°, Top at (156, 95) down to (258, 196)) -->\n    <!-- Strut branch body: Width 16px, Top notch nests over chisel (156, 95), Bottom beveled tip nests inside Bait stick rear notch (258, 196) -->\n    <polygon points=\"144,83 156,95 168,83 178,93 268,183 258,196 248,186 134,73\" fill=\"url(#strutWoodS3)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n\n    <!-- Top Mating V-Notch (Nests snugly over chisel peak (156, 95)) -->\n    <polygon points=\"148,87 156,95 164,87 156,92\" fill=\"url(#notchFlesh)\" stroke=\"#b45309\" stroke-width=\"0.8\"/>\n\n    <!-- Bottom Beveled Tip (Locks flush inside Bait stick rear notch at y=192 to 198) -->\n    <polygon points=\"248,186 258,196 268,183 258,180\" fill=\"url(#notchFlesh)\" stroke=\"#b45309\" stroke-width=\"0.8\"/>\n\n    <!-- 3. Stick 3: Horizontal Bait Stick (Runs from x=110 across to x=345, y=192 to 208) -->\n    <path d=\"M 110 192 L 315 192 L 345 200 L 315 208 L 110 208 Z\" fill=\"url(#baitWoodS3)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n\n    <!-- Catch Ledge on Bait Stick (Locked into Post middle notch at x=145..157) -->\n    <polygon points=\"145,192 157,192 157,208 145,208\" fill=\"url(#notchFlesh)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n\n    <!-- Rear Notch on Bait Stick (Receives Strut bottom tip at x=250..266, y=192..204) -->\n    <polygon points=\"250,192 266,192 258,204\" fill=\"url(#notchFlesh)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n\n    <!-- Sharp Bait Pin at Far Right -->\n    <polygon points=\"315,192 345,200 315,208\" fill=\"url(#notchFlesh)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <!-- Red Wild Berry Bait -->\n    <circle cx=\"343\" cy=\"200\" r=\"4.5\" fill=\"#ef4444\"/>\n    <circle cx=\"343\" cy=\"200\" r=\"8\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  </g>\n\n  <!-- Key Interlock Joint Markers & Badges -->\n  <!-- Joint A: Post & Bait Stick (Label 2) -->\n  <circle cx=\"151\" cy=\"200\" r=\"5\" fill=\"#ef4444\" opacity=\"0.9\"/>\n  <circle cx=\"151\" cy=\"200\" r=\"9\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  <line x1=\"151\" y1=\"190\" x2=\"115\" y2=\"155\" stroke=\"#ef4444\" stroke-width=\"1.2\"/>\n  <rect x=\"40\" y=\"138\" width=\"115\" height=\"18\" fill=\"#1c1917\" stroke=\"#ef4444\" stroke-width=\"1\"/>\n  <text x=\"97\" y=\"150\" fill=\"#fca5a5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"bold\">세움대-먹이대 맞물림 턱</text>\n\n  <!-- Joint B: Strut & Bait Stick (Label 3) -->\n  <circle cx=\"258\" cy=\"196\" r=\"5\" fill=\"#38bdf8\" opacity=\"0.9\"/>\n  <circle cx=\"258\" cy=\"196\" r=\"9\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  <line x1=\"258\" y1=\"187\" x2=\"285\" y2=\"155\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <rect x=\"235\" y=\"138\" width=\"115\" height=\"18\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"292\" y=\"150\" fill=\"#bae6fd\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"bold\">빗장대-먹이대 뒷홈 걸림</text>\n\n  <!-- Top Center Self-Standing Badge (Label 4) -->\n  <rect x=\"130\" y=\"55\" width=\"140\" height=\"22\" fill=\"#14532d\" stroke=\"#22c55e\" stroke-width=\"1.2\"/>\n  <text x=\"200\" y=\"70\" fill=\"#86efac\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"bold\">끈 없이 혼자 서는 숫자 4</text>\n\n  <!-- Bottom Visual Callout Box (Label 5) -->\n  <rect x=\"20\" y=\"325\" width=\"360\" height=\"52\" fill=\"#0d1117\" stroke=\"#21262d\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"325\" width=\"3\" height=\"52\" fill=\"#22c55e\"/>\n  <text x=\"32\" y=\"355\" fill=\"#f8fafc\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[핵심] 세 막대가 서로 밀어내며 스스로 자립</text>\n</svg>\n","content/svgs/pr08-step-04.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Heavy Slate Rock Texture Gradient -->\n    <linearGradient id=\"rockGradS4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#64748b\"/>\n      <stop offset=\"35%\" stop-color=\"#475569\"/>\n      <stop offset=\"70%\" stop-color=\"#334155\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n\n    <!-- Rock Underside Cavern Shadow Gradient -->\n    <linearGradient id=\"rockUnderGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"50%\" stop-color=\"#0f172a\"/>\n      <stop offset=\"100%\" stop-color=\"#020617\"/>\n    </linearGradient>\n\n    <!-- Rock Rim 3D Gradient -->\n    <linearGradient id=\"rockRimS4\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#94a3b8\"/>\n      <stop offset=\"50%\" stop-color=\"#64748b\"/>\n      <stop offset=\"100%\" stop-color=\"#334155\"/>\n    </linearGradient>\n\n    <!-- Wood Bark Gradient -->\n    <linearGradient id=\"woodBarkS4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#451a03\"/>\n      <stop offset=\"35%\" stop-color=\"#78350f\"/>\n      <stop offset=\"70%\" stop-color=\"#92400e\"/>\n      <stop offset=\"100%\" stop-color=\"#3d210f\"/>\n    </linearGradient>\n\n    <!-- Diagonal Strut Gradient -->\n    <linearGradient id=\"strutBarkS4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#3d210f\"/>\n      <stop offset=\"40%\" stop-color=\"#854d0e\"/>\n      <stop offset=\"75%\" stop-color=\"#b45309\"/>\n      <stop offset=\"100%\" stop-color=\"#2d1607\"/>\n    </linearGradient>\n\n    <!-- Carved Inner Wood Notch -->\n    <linearGradient id=\"carvedWoodS4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\"/>\n      <stop offset=\"50%\" stop-color=\"#fde68a\"/>\n      <stop offset=\"100%\" stop-color=\"#d97706\"/>\n    </linearGradient>\n\n    <!-- Motion Blur Ghost Fill for Falling Rock -->\n    <linearGradient id=\"rockGhostS4\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\" stop-opacity=\"0.35\"/>\n      <stop offset=\"100%\" stop-color=\"#0284c7\" stop-opacity=\"0.08\"/>\n    </linearGradient>\n\n    <filter id=\"shadowS4\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"6\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS4)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#f59e0b\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 04 // ROCK LOAD &amp; 0.1S COLLAPSE</text>\n\n  <!-- Ground Plane Baseline -->\n  <line x1=\"25\" y1=\"310\" x2=\"375\" y2=\"310\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <path d=\"M 35 312 L 50 322 M 70 312 L 85 322 M 105 312 L 120 322 M 140 312 L 155 322 M 175 312 L 190 322 M 210 312 L 225 322 M 245 312 L 260 322 M 280 312 L 295 322 M 315 312 L 330 322 M 350 312 L 365 322\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n\n  <!-- Ground Shadows -->\n  <ellipse cx=\"156\" cy=\"311\" rx=\"28\" ry=\"5\" fill=\"#000000\" opacity=\"0.8\"/>\n  <ellipse cx=\"320\" cy=\"311\" rx=\"45\" ry=\"6\" fill=\"#000000\" opacity=\"0.9\"/>\n\n  <!-- ============================================== -->\n  <!-- 0.1s COLLAPSE MOTION GHOST (Falling Rock Trajectory) -->\n  <!-- ============================================== -->\n  <!-- Ghost Rock Dropped Flat on Ground Crushing Bait Area -->\n  <polygon points=\"135,308 355,308 350,282 140,282\" fill=\"url(#rockGhostS4)\" stroke=\"#38bdf8\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <!-- Downward Impact Motion Trajectory Arrows -->\n  <path d=\"M 180 120 L 180 270 M 235 135 L 235 270 M 285 145 L 285 270\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <polygon points=\"177,270 180,277 183,270\" fill=\"#38bdf8\"/>\n  <polygon points=\"232,270 235,277 238,270\" fill=\"#38bdf8\"/>\n  <polygon points=\"282,270 285,277 288,270\" fill=\"#38bdf8\"/>\n\n  <!-- ============================================== -->\n  <!-- 1. HEAVY 15KG SLATE ROCK (3D Propped Canopy Slab) -->\n  <!-- ============================================== -->\n  <!-- The massive stone slab is lifted at front lip (138,77) by the Strut tip, forming a wide open overhead roof. -->\n  <!-- The back edge rests on the ground (150..390, 308). The entire bait stick is sheltered inside the deep cavern. -->\n  <g filter=\"url(#shadowS4)\">\n    <!-- Underside Cavern Ceiling (Dark shadowed interior beneath the rock) -->\n    <polygon points=\"138,77 350,125 390,308 150,308\" fill=\"url(#rockUnderGrad)\" stroke=\"#0f172a\" stroke-width=\"1\"/>\n    <!-- Top Face of Heavy Slate Slab (Slanted backward towards ground) -->\n    <polygon points=\"138,65 156,50 370,95 400,290 390,308 350,113\" fill=\"url(#rockGradS4)\" stroke=\"#1e293b\" stroke-width=\"1.8\"/>\n    <!-- Front Lifted Lip Thickness (Resting cleanly on Strut top notch at (138,77)) -->\n    <polygon points=\"138,77 350,125 350,113 138,65\" fill=\"#94a3b8\" stroke=\"#475569\" stroke-width=\"0.8\"/>\n    <!-- Top Face Geological Cleavage Lines -->\n    <path d=\"M 180 62 L 270 140 L 370 220 M 230 75 L 320 160 M 300 95 L 380 190\" stroke=\"#1e293b\" stroke-width=\"1.2\" stroke-linecap=\"round\"/>\n  </g>\n\n  <!-- ============================================== -->\n  <!-- 2. FIGURE-4 STICK TRIGGER MECHANISM (In Foreground) -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowS4)\">\n    <!-- Stick 1: Vertical Post (세움대 - Stands upright at x=145 to 167, y=125 to 310) -->\n    <rect x=\"145\" y=\"125\" width=\"22\" height=\"185\" rx=\"2.5\" fill=\"url(#woodBarkS4)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n    <!-- Post Top Chisel Head (납작 쐐기 - Peak at (156, 95)) -->\n    <polygon points=\"145,125 156,95 167,125\" fill=\"url(#carvedWoodS4)\" stroke=\"#78350f\" stroke-width=\"1\"/>\n    <!-- Post Middle Notch (네모 홈 - y=192 to 208) -->\n    <rect x=\"145\" y=\"192\" width=\"12\" height=\"16\" fill=\"url(#carvedWoodS4)\" stroke=\"#78350f\" stroke-width=\"0.8\"/>\n    <!-- Post Bark Lines -->\n    <line x1=\"150\" y1=\"140\" x2=\"150\" y2=\"185\" stroke=\"#271408\" stroke-width=\"0.8\"/>\n    <line x1=\"162\" y1=\"215\" x2=\"162\" y2=\"290\" stroke=\"#271408\" stroke-width=\"0.8\"/>\n\n    <!-- Stick 2: Diagonal Strut (Mathematically 45.0°, Top at (156, 95) down to (258, 196)) -->\n    <!-- Extends above post to (138, 77) where it directly props up the rock's front underside lip -->\n    <polygon points=\"128,67 140,79 156,95 168,83 178,93 268,183 258,196 248,186 148,87 138,77 118,57\" fill=\"url(#strutBarkS4)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n\n    <!-- Upper Support Tip Notch (Props Rock at (138, 77)) -->\n    <polygon points=\"128,67 140,79 138,77\" fill=\"url(#carvedWoodS4)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <!-- Mating Notch over Post Chisel (156, 95) -->\n    <polygon points=\"148,87 156,95 164,87 156,92\" fill=\"url(#carvedWoodS4)\" stroke=\"#b45309\" stroke-width=\"0.8\"/>\n    <!-- Bottom Beveled Tip (Locks into Bait stick rear notch at y=192 to 198) -->\n    <polygon points=\"248,186 258,196 268,183 258,180\" fill=\"url(#carvedWoodS4)\" stroke=\"#b45309\" stroke-width=\"0.8\"/>\n\n    <!-- Critical Mechanical Contact Pivots -->\n    <circle cx=\"138\" cy=\"77\" r=\"4.5\" fill=\"#ef4444\" opacity=\"0.95\"/>\n    <circle cx=\"138\" cy=\"77\" r=\"8\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n    <circle cx=\"156\" cy=\"95\" r=\"3.5\" fill=\"#38bdf8\" opacity=\"0.9\"/>\n    <circle cx=\"258\" cy=\"196\" r=\"3.5\" fill=\"#38bdf8\" opacity=\"0.9\"/>\n\n    <!-- Stick 3: Horizontal Bait Stick (Runs from x=110 across to x=280, y=192 to 208) -->\n    <!-- Extends deeply into the sheltered cavern under the rock, bait clearly inside the fall zone -->\n    <path d=\"M 110 192 L 260 192 L 280 200 L 260 208 L 110 208 Z\" fill=\"url(#woodBarkS4)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n    <!-- Front Ledge on Bait Stick (Locked into Post middle notch) -->\n    <polygon points=\"145,192 157,192 157,208 145,208\" fill=\"url(#carvedWoodS4)\" stroke=\"#b45309\" stroke-width=\"0.8\"/>\n    <!-- Rear Catch Notch on Bait Stick (Locked with Strut bottom) -->\n    <polygon points=\"250,192 266,192 258,204\" fill=\"url(#carvedWoodS4)\" stroke=\"#b45309\" stroke-width=\"0.8\"/>\n    <!-- Pointed Inner Bait Pin under the Rock -->\n    <polygon points=\"260,192 280,200 260,208\" fill=\"url(#carvedWoodS4)\" stroke=\"#b45309\" stroke-width=\"0.8\"/>\n    <!-- Juicy Red Wild Berries Bait (Deep inside cavern, 80px away from rock edge) -->\n    <circle cx=\"275\" cy=\"200\" r=\"5\" fill=\"#ef4444\"/>\n    <circle cx=\"281\" cy=\"197\" r=\"4\" fill=\"#dc2626\"/>\n    <circle cx=\"275\" cy=\"200\" r=\"8\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  </g>\n\n  <!-- Prey Touch Action Trigger Pointer -->\n  <path d=\"M 320 175 C 305 175 297 190 287 198\" stroke=\"#ef4444\" stroke-width=\"1.8\" fill=\"none\" stroke-linecap=\"round\"/>\n  <polygon points=\"285,195 281,203 289,200\" fill=\"#ef4444\"/>\n\n  <!-- ============================================== -->\n  <!-- TECHNICAL LABELS & POINTERS -->\n  <!-- ============================================== -->\n  <!-- Label 2: Heavy Rock -->\n  <line x1=\"230\" y1=\"100\" x2=\"270\" y2=\"65\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <circle cx=\"230\" cy=\"100\" r=\"3\" fill=\"#38bdf8\"/>\n  <rect x=\"200\" y=\"55\" width=\"150\" height=\"20\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"275\" y=\"69\" fill=\"#38bdf8\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">15kg 평평한 바위 안착</text>\n\n  <!-- Label 3: Bait Mount (Points directly to berries inside the drop zone) -->\n  <line x1=\"275\" y1=\"210\" x2=\"275\" y2=\"245\" stroke=\"#f59e0b\" stroke-width=\"1.2\"/>\n  <circle cx=\"275\" cy=\"210\" r=\"3\" fill=\"#f59e0b\"/>\n  <rect x=\"205\" y=\"245\" width=\"140\" height=\"20\" fill=\"#18181b\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <text x=\"275\" y=\"259\" fill=\"#fbbf24\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">먹이대 끝 미끼 장착</text>\n\n  <!-- Label 4: Instant Collapse -->\n  <line x1=\"180\" y1=\"210\" x2=\"135\" y2=\"225\" stroke=\"#ef4444\" stroke-width=\"1.2\"/>\n  <circle cx=\"180\" cy=\"210\" r=\"3\" fill=\"#ef4444\"/>\n  <rect x=\"25\" y=\"215\" width=\"155\" height=\"20\" fill=\"#1c1917\" stroke=\"#ef4444\" stroke-width=\"1\"/>\n  <text x=\"102\" y=\"229\" fill=\"#f87171\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">톡 건드리면 0.1초 만에 바위 낙하</text>\n\n  <!-- Bottom Visual Callout Box (Label 5) -->\n  <rect x=\"20\" y=\"325\" width=\"360\" height=\"52\" fill=\"#0d1117\" stroke=\"#21262d\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"325\" width=\"3\" height=\"52\" fill=\"#f59e0b\"/>\n  <text x=\"32\" y=\"355\" fill=\"#f8fafc\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[핵심] 스치기만 해도 와르르 무너지는 민감도</text>\n</svg>\n","content/svgs/pr09-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgOut9\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1218\"/>\n      <stop offset=\"100%\" stop-color=\"#050709\"/>\n    </linearGradient>\n\n    <!-- Soil Strata -->\n    <linearGradient id=\"soilCutOut\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#3b2314\"/>\n      <stop offset=\"50%\" stop-color=\"#241409\"/>\n      <stop offset=\"100%\" stop-color=\"#140a04\"/>\n    </linearGradient>\n\n    <!-- Mud Kiln Mound -->\n    <linearGradient id=\"moundGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3e2314\"/>\n      <stop offset=\"35%\" stop-color=\"#593b26\"/>\n      <stop offset=\"70%\" stop-color=\"#412918\"/>\n      <stop offset=\"100%\" stop-color=\"#2d1607\"/>\n    </linearGradient>\n\n    <!-- Turf Grass Layer -->\n    <linearGradient id=\"turfGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#2d4a22\"/>\n      <stop offset=\"50%\" stop-color=\"#4d7c0f\"/>\n      <stop offset=\"100%\" stop-color=\"#365314\"/>\n    </linearGradient>\n\n    <!-- Pyrolysis Glow in Kiln Interior -->\n    <radialGradient id=\"pyrolysisGlow\" cx=\"50%\" cy=\"80%\" r=\"70%\">\n      <stop offset=\"0%\" stop-color=\"#ea580c\" stop-opacity=\"0.75\"/>\n      <stop offset=\"35%\" stop-color=\"#b45309\" stop-opacity=\"0.45\"/>\n      <stop offset=\"70%\" stop-color=\"#78350f\" stop-opacity=\"0.2\"/>\n      <stop offset=\"100%\" stop-color=\"#07080a\" stop-opacity=\"0\"/>\n    </radialGradient>\n\n    <!-- Blue Pyrolysis Smoke Stream -->\n    <radialGradient id=\"bluePlume\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\" stop-opacity=\"0.85\"/>\n      <stop offset=\"35%\" stop-color=\"#0284c7\" stop-opacity=\"0.5\"/>\n      <stop offset=\"75%\" stop-color=\"#0369a1\" stop-opacity=\"0.15\"/>\n      <stop offset=\"100%\" stop-color=\"#07080a\" stop-opacity=\"0\"/>\n    </radialGradient>\n\n    <!-- Carbon Charcoal Texture -->\n    <linearGradient id=\"charcoalGloss\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#334155\"/>\n      <stop offset=\"30%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"70%\" stop-color=\"#0f172a\"/>\n      <stop offset=\"100%\" stop-color=\"#020617\"/>\n    </linearGradient>\n\n    <!-- Silver Sheen Highlight -->\n    <linearGradient id=\"silverGloss\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#475569\"/>\n      <stop offset=\"50%\" stop-color=\"#cbd5e1\"/>\n      <stop offset=\"100%\" stop-color=\"#334155\"/>\n    </linearGradient>\n\n    <filter id=\"shadowOut9\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"6\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"800\" height=\"450\" fill=\"url(#bgOut9)\"/>\n  <rect x=\"12\" y=\"12\" width=\"776\" height=\"426\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 20 28 L 36 28 M 28 20 L 28 36\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 780 28 L 764 28 M 772 20 L 772 36\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 20 422 L 36 422 M 28 414 L 28 430\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 780 422 L 764 422 M 772 414 L 772 430\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Technical Header Strip -->\n  <rect x=\"28\" y=\"22\" width=\"744\" height=\"24\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"28\" y=\"22\" width=\"4\" height=\"24\" fill=\"#f97316\"/>\n  <text x=\"42\" y=\"38\" fill=\"#e2e8f0\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" font-weight=\"bold\" letter-spacing=\"0.5\">PR-09 // PIT CHARCOAL KILN (원시 지하 숯가마 구조 &amp; 고순도 탄소 숯 완성 단면)</text>\n\n  <!-- Left: Underground Kiln Cross Section -->\n  <!-- Ground Level & Earth -->\n  <path d=\"M 35 190 L 80 190 L 140 375 L 35 375 Z\" fill=\"url(#soilCutOut)\" opacity=\"0.65\"/>\n  <path d=\"M 450 190 L 390 190 L 330 375 L 450 375 Z\" fill=\"url(#soilCutOut)\" opacity=\"0.65\"/>\n\n  <!-- Pit Interior Chamber (Cone Shape) -->\n  <path d=\"M 80 190 Q 235 200 390 190 L 330 375 Q 235 380 140 375 Z\" fill=\"#140a04\" stroke=\"#452715\" stroke-width=\"1.5\"/>\n\n  <!-- Heat/Pyrolysis Glow inside Kiln -->\n  <path d=\"M 140 375 Q 235 380 330 375 L 310 260 Q 235 270 160 260 Z\" fill=\"url(#pyrolysisGlow)\"/>\n\n  <!-- Stood Oak Logs inside (Pyrolyzing to Black Charcoal) -->\n  <g filter=\"url(#shadowOut9)\">\n    <!-- Log 1 -->\n    <rect x=\"155\" y=\"205\" width=\"22\" height=\"160\" rx=\"3\" fill=\"#1e130b\" stroke=\"#0a0502\" stroke-width=\"1\"/>\n    <!-- Log 2 -->\n    <rect x=\"185\" y=\"195\" width=\"25\" height=\"175\" rx=\"3\" fill=\"#24170d\" stroke=\"#0a0502\" stroke-width=\"1\"/>\n    <!-- Log 3 (Center) -->\n    <rect x=\"220\" y=\"190\" width=\"30\" height=\"182\" rx=\"3\" fill=\"#2a1b10\" stroke=\"#0a0502\" stroke-width=\"1\"/>\n    <!-- Log 4 -->\n    <rect x=\"260\" y=\"195\" width=\"26\" height=\"175\" rx=\"3\" fill=\"#24170d\" stroke=\"#0a0502\" stroke-width=\"1\"/>\n    <!-- Log 5 -->\n    <rect x=\"295\" y=\"205\" width=\"22\" height=\"160\" rx=\"3\" fill=\"#1e130b\" stroke=\"#0a0502\" stroke-width=\"1\"/>\n    <!-- Wedge branches -->\n    <line x1=\"180\" y1=\"210\" x2=\"182\" y2=\"350\" stroke=\"#78350f\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n    <line x1=\"215\" y1=\"205\" x2=\"216\" y2=\"355\" stroke=\"#78350f\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n    <line x1=\"254\" y1=\"205\" x2=\"253\" y2=\"355\" stroke=\"#78350f\" stroke-width=\"5.5\" stroke-linecap=\"round\"/>\n    <line x1=\"290\" y1=\"210\" x2=\"288\" y2=\"350\" stroke=\"#78350f\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n  </g>\n\n  <!-- Glowing Embers Bed at Bottom -->\n  <g>\n    <ellipse cx=\"235\" cy=\"372\" rx=\"75\" ry=\"8\" fill=\"#ea580c\"/>\n    <circle cx=\"185\" cy=\"370\" r=\"5\" fill=\"#fef08a\"/>\n    <circle cx=\"215\" cy=\"373\" r=\"6\" fill=\"#fde047\"/>\n    <circle cx=\"255\" cy=\"371\" r=\"5\" fill=\"#fef08a\"/>\n    <circle cx=\"285\" cy=\"372\" r=\"5\" fill=\"#fde047\"/>\n  </g>\n\n  <!-- Kiln Dome: Mud & Sod Seal (10cm) -->\n  <g filter=\"url(#shadowOut9)\">\n    <path d=\"M 65 190 Q 235 110 405 190 Q 235 160 65 190 Z\" fill=\"url(#moundGrad)\" stroke=\"#593b26\" stroke-width=\"1.5\"/>\n    <path d=\"M 72 189 Q 235 113 398 189 Q 235 130 72 189 Z\" fill=\"url(#turfGrad)\" opacity=\"0.85\"/>\n  </g>\n\n  <!-- Center Chimney -->\n  <g filter=\"url(#shadowOut9)\">\n    <path d=\"M 220 126 L 220 105 Q 235 102 250 105 L 250 126 Z\" fill=\"#3e2314\" stroke=\"#5c381e\" stroke-width=\"1.2\"/>\n    <ellipse cx=\"235\" cy=\"105\" rx=\"15\" ry=\"4\" fill=\"#0c0603\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Billowing Faint Blue Pyrolysis Smoke Stream -->\n  <g>\n    <circle cx=\"235\" cy=\"85\" r=\"14\" fill=\"url(#bluePlume)\"/>\n    <circle cx=\"222\" cy=\"65\" r=\"18\" fill=\"url(#bluePlume)\"/>\n    <circle cx=\"245\" cy=\"55\" r=\"22\" fill=\"url(#bluePlume)\"/>\n    <circle cx=\"230\" cy=\"35\" r=\"26\" fill=\"url(#bluePlume)\"/>\n  </g>\n\n  <!-- Air Intake Arrows -->\n  <g>\n    <!-- Left Intake -->\n    <ellipse cx=\"78\" cy=\"195\" rx=\"4\" ry=\"7\" fill=\"#0a0502\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <path d=\"M 45 195 L 68 195\" stroke=\"#38bdf8\" stroke-width=\"1.6\" stroke-dasharray=\"3 2\"/>\n    <polygon points=\"73,195 66,192 66,198\" fill=\"#38bdf8\"/>\n    <!-- Right Intake -->\n    <ellipse cx=\"392\" cy=\"195\" rx=\"4\" ry=\"7\" fill=\"#0a0502\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <path d=\"M 425 195 L 402 195\" stroke=\"#38bdf8\" stroke-width=\"1.6\" stroke-dasharray=\"3 2\"/>\n    <polygon points=\"397,195 404,192 404,198\" fill=\"#38bdf8\"/>\n  </g>\n\n  <!-- Annotations on Kiln Diagram -->\n  <rect x=\"42\" y=\"75\" width=\"135\" height=\"18\" fill=\"#0b1320\" rx=\"3\" stroke=\"#1e3a5f\" stroke-width=\"1\"/>\n  <text x=\"109\" y=\"88\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">상단 굴뚝: 푸른 연기 배출</text>\n\n  <rect x=\"42\" y=\"145\" width=\"135\" height=\"18\" fill=\"#141f0d\" rx=\"3\" stroke=\"#4d7c0f\" stroke-width=\"1\"/>\n  <text x=\"109\" y=\"158\" fill=\"#bef264\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">10cm 점토 &amp; 잔디 뗏장 덮개</text>\n\n  <rect x=\"28\" y=\"275\" width=\"115\" height=\"18\" fill=\"#1c0f05\" rx=\"3\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n  <text x=\"85\" y=\"288\" fill=\"#fb923c\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">50cm 원뿔 구덩이</text>\n\n  <!-- Right: Harvested Charcoal Specification & Performance Panel -->\n  <g filter=\"url(#shadowOut9)\">\n    <rect x=\"480\" y=\"62\" width=\"292\" height=\"325\" fill=\"#0b0f17\" rx=\"6\" stroke=\"#1e293b\" stroke-width=\"1.5\"/>\n    <rect x=\"480\" y=\"62\" width=\"292\" height=\"26\" fill=\"#111827\" rx=\"6\" stroke=\"#1f2937\" stroke-width=\"1\"/>\n    <text x=\"626\" y=\"79\" fill=\"#f8fafc\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10.5\" font-weight=\"bold\" text-anchor=\"middle\">수확된 고급 참나무 숯 제원 (SPECIFICATION)</text>\n\n    <!-- Harvested Charcoal Vector Art Illustration -->\n    <!-- Large Charcoal Log Chunk -->\n    <g>\n      <polygon points=\"560,165 620,120 710,130 735,175 660,215 570,205\" fill=\"url(#charcoalGloss)\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n      <!-- Silver Sheen Facet -->\n      <polygon points=\"620,120 710,130 675,170 595,155\" fill=\"url(#silverGloss)\" opacity=\"0.3\"/>\n      <!-- Cleavage Lines -->\n      <line x1=\"635\" y1=\"135\" x2=\"670\" y2=\"195\" stroke=\"#020617\" stroke-width=\"1.8\"/>\n      <line x1=\"590\" y1=\"170\" x2=\"640\" y2=\"205\" stroke=\"#020617\" stroke-width=\"1.4\"/>\n      <!-- Metallic Bell Sound Waves -->\n      <path d=\"M 725 140 A 12 12 0 0 1 740 155\" fill=\"none\" stroke=\"#e2e8f0\" stroke-width=\"1.5\"/>\n      <path d=\"M 732 132 A 20 20 0 0 1 752 158\" fill=\"none\" stroke=\"#94a3b8\" stroke-width=\"1.2\"/>\n    </g>\n\n    <!-- Micro Pores Callout Inset Circle -->\n    <circle cx=\"535\" cy=\"180\" r=\"28\" fill=\"#090d16\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n    <!-- Micro Pores Pattern -->\n    <circle cx=\"525\" cy=\"172\" r=\"2\" fill=\"#38bdf8\"/>\n    <circle cx=\"540\" cy=\"170\" r=\"2.5\" fill=\"#38bdf8\"/>\n    <circle cx=\"530\" cy=\"184\" r=\"1.8\" fill=\"#38bdf8\"/>\n    <circle cx=\"545\" cy=\"182\" r=\"2.2\" fill=\"#38bdf8\"/>\n    <circle cx=\"536\" cy=\"192\" r=\"1.5\" fill=\"#38bdf8\"/>\n    <line x1=\"563\" y1=\"180\" x2=\"585\" y2=\"180\" stroke=\"#38bdf8\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n    <text x=\"535\" y=\"220\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" font-weight=\"bold\" text-anchor=\"middle\">다공성 활성 구조</text>\n\n    <!-- Technical Specs Table Rows -->\n    <g>\n      <!-- Row 1: Carbon Purity -->\n      <rect x=\"495\" y=\"235\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"251\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">탄소 순도 (Carbon Purity)</text>\n      <text x=\"745\" y=\"251\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">85 ~ 90% (고밀도 탄화)</text>\n\n      <!-- Row 2: Calorific Value & Smokeless -->\n      <rect x=\"495\" y=\"265\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"281\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">연소 온도 &amp; 연기 유무</text>\n      <text x=\"745\" y=\"281\" fill=\"#f59e0b\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">400~500℃ / 연기 0%</text>\n\n      <!-- Row 3: Multipurpose Utility -->\n      <rect x=\"495\" y=\"295\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"311\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">생존 다목적 활용</text>\n      <text x=\"745\" y=\"311\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">식수 여과 / 불씨 보관</text>\n\n      <!-- Row 4: Acoustic Ring Test -->\n      <rect x=\"495\" y=\"325\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"341\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">완성 판정 (Acoustic Ring)</text>\n      <text x=\"745\" y=\"341\" fill=\"#e2e8f0\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">맑은 쇳소리 &amp; 은빛 광택</text>\n\n      <!-- Row 5: Yield per Batch -->\n      <rect x=\"495\" y=\"355\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"371\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">1회 가동 수확량</text>\n      <text x=\"745\" y=\"371\" fill=\"#a78bfa\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">고급 숯 3~5kg (참나무)</text>\n    </g>\n  </g>\n\n  <!-- Bottom Core Summary Banner -->\n  <rect x=\"28\" y=\"398\" width=\"744\" height=\"28\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"28\" y=\"398\" width=\"4\" height=\"28\" fill=\"#10b981\" rx=\"1\"/>\n  <text x=\"400\" y=\"416\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10.5\" font-weight=\"bold\" text-anchor=\"middle\">[핵심 공학] 흙구덩이 속 95% 공기 차단 ➔ 수분·타르만 방출하여 연기 없는 500℃ 고열 숯 생산</text>\n</svg>\n","content/svgs/pr09-step-01.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Soil Strata Gradient -->\n    <linearGradient id=\"soilCutGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#3e2723\"/>\n      <stop offset=\"40%\" stop-color=\"#2d1d18\"/>\n      <stop offset=\"100%\" stop-color=\"#1b120c\"/>\n    </linearGradient>\n\n    <!-- Pit Interior Shadow Gradient -->\n    <linearGradient id=\"pitWallGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#140d07\"/>\n      <stop offset=\"50%\" stop-color=\"#26170d\"/>\n      <stop offset=\"100%\" stop-color=\"#140d07\"/>\n    </linearGradient>\n\n    <!-- Ember & Fire Glow Radial Gradient -->\n    <radialGradient id=\"emberGlow\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#ff7a00\" stop-opacity=\"0.9\"/>\n      <stop offset=\"30%\" stop-color=\"#e63900\" stop-opacity=\"0.6\"/>\n      <stop offset=\"70%\" stop-color=\"#b31e00\" stop-opacity=\"0.2\"/>\n      <stop offset=\"100%\" stop-color=\"#140d07\" stop-opacity=\"0\"/>\n    </radialGradient>\n\n    <!-- Hot Charcoal Glow -->\n    <radialGradient id=\"charcoalRed\" cx=\"40%\" cy=\"40%\" r=\"60%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\"/>\n      <stop offset=\"25%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"65%\" stop-color=\"#dc2626\"/>\n      <stop offset=\"100%\" stop-color=\"#450a0a\"/>\n    </radialGradient>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowS1\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"3\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS1)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#f97316\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 01 // PIT EXCAVATION &amp; PRE-DRYING</text>\n\n  <!-- Ground Level Line & Soil Cross Section -->\n  <!-- Left Ground Surface -->\n  <path d=\"M 20 120 L 70 120\" stroke=\"#78716c\" stroke-width=\"2\"/>\n  <!-- Right Ground Surface -->\n  <path d=\"M 330 120 L 380 120\" stroke=\"#78716c\" stroke-width=\"2\"/>\n  <!-- Grass Blades on Surface -->\n  <path d=\"M 28 120 L 32 112 M 45 120 L 48 114 M 345 120 L 348 113 M 365 120 L 369 111\" stroke=\"#4ade80\" stroke-width=\"1.5\" stroke-linecap=\"round\"/>\n\n  <!-- Surrounding Soil Mass -->\n  <path d=\"M 20 120 L 70 120 L 130 310 L 20 310 Z\" fill=\"url(#soilCutGrad)\" opacity=\"0.6\"/>\n  <path d=\"M 380 120 L 330 120 L 270 310 L 380 310 Z\" fill=\"url(#soilCutGrad)\" opacity=\"0.6\"/>\n\n  <!-- Pit Excavation Cavity (Cone Shape) -->\n  <path d=\"M 70 120 Q 200 135 330 120 L 270 310 Q 200 315 130 310 Z\" fill=\"url(#pitWallGrad)\" stroke=\"#573824\" stroke-width=\"1.5\"/>\n\n  <!-- Pit Top Opening Rim Ellipse Guide -->\n  <ellipse cx=\"200\" cy=\"120\" rx=\"130\" ry=\"20\" fill=\"none\" stroke=\"#ea580c\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/>\n\n  <!-- Dimension Indicator: Top Diameter 60cm (Label 2) -->\n  <g>\n    <line x1=\"70\" y1=\"88\" x2=\"330\" y2=\"88\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n    <path d=\"M 70 85 L 63 88 L 70 91 Z\" fill=\"#38bdf8\"/>\n    <path d=\"M 330 85 L 337 88 L 330 91 Z\" fill=\"#38bdf8\"/>\n    <line x1=\"70\" y1=\"83\" x2=\"70\" y2=\"115\" stroke=\"#38bdf8\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"/>\n    <line x1=\"330\" y1=\"83\" x2=\"330\" y2=\"115\" stroke=\"#38bdf8\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"/>\n    <rect x=\"100\" y=\"76\" width=\"200\" height=\"15\" fill=\"#0b1320\" rx=\"3\" stroke=\"#1e3a5f\" stroke-width=\"1\"/>\n    <text x=\"200\" y=\"87\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">상부 지름 60cm 원뿔형 흙구덩이</text>\n  </g>\n\n  <!-- Dimension Indicator: Depth 50cm & Bottom Diameter 30cm (Label 3) -->\n  <g>\n    <!-- Vertical Depth Line on Left -->\n    <line x1=\"45\" y1=\"120\" x2=\"45\" y2=\"310\" stroke=\"#f59e0b\" stroke-width=\"1.2\"/>\n    <path d=\"M 42 120 L 45 113 L 48 120 Z\" fill=\"#f59e0b\"/>\n    <path d=\"M 42 310 L 45 317 L 48 310 Z\" fill=\"#f59e0b\"/>\n    <line x1=\"40\" y1=\"120\" x2=\"68\" y2=\"120\" stroke=\"#f59e0b\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"/>\n    <line x1=\"40\" y1=\"310\" x2=\"128\" y2=\"310\" stroke=\"#f59e0b\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"/>\n    <!-- Bottom Rim Guide -->\n    <ellipse cx=\"200\" cy=\"310\" rx=\"70\" ry=\"10\" fill=\"none\" stroke=\"#d97706\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n    <rect x=\"52\" y=\"205\" width=\"168\" height=\"15\" fill=\"#1c1308\" rx=\"3\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <text x=\"136\" y=\"216\" fill=\"#f59e0b\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">깊이 50cm (바닥 지름 30cm)</text>\n  </g>\n\n  <!-- Bottom Pre-Drying Fire & Embers Bed -->\n  <!-- Fire Glow Backdrop -->\n  <ellipse cx=\"200\" cy=\"295\" rx=\"80\" ry=\"35\" fill=\"url(#emberGlow)\"/>\n\n  <!-- Burning Twigs & Glowing Charcoal Chunks -->\n  <g filter=\"url(#shadowS1)\">\n    <!-- Twigs -->\n    <line x1=\"145\" y1=\"305\" x2=\"255\" y2=\"295\" stroke=\"#78350f\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n    <line x1=\"155\" y1=\"290\" x2=\"245\" y2=\"308\" stroke=\"#451a03\" stroke-width=\"4.5\" stroke-linecap=\"round\"/>\n    <line x1=\"170\" y1=\"310\" x2=\"230\" y2=\"288\" stroke=\"#9a3412\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n\n    <!-- Glowing Embers -->\n    <circle cx=\"175\" cy=\"298\" r=\"7\" fill=\"url(#charcoalRed)\"/>\n    <circle cx=\"195\" cy=\"302\" r=\"9\" fill=\"url(#charcoalRed)\"/>\n    <circle cx=\"215\" cy=\"295\" r=\"8\" fill=\"url(#charcoalRed)\"/>\n    <circle cx=\"188\" cy=\"289\" r=\"6\" fill=\"#fde047\"/>\n    <circle cx=\"205\" cy=\"291\" r=\"5\" fill=\"#fef08a\"/>\n\n    <!-- Flame Tongues -->\n    <path d=\"M 180 290 Q 185 270 190 282 Q 195 260 200 285 Q 205 265 212 288 Z\" fill=\"#f97316\" opacity=\"0.85\"/>\n    <path d=\"M 188 288 Q 193 273 197 282 Q 202 271 206 287 Z\" fill=\"#fef08a\" opacity=\"0.95\"/>\n  </g>\n\n  <!-- Heat Waves Rising -->\n  <path d=\"M 185 265 Q 180 245 190 230 Q 200 215 195 195\" fill=\"none\" stroke=\"#fb923c\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\" opacity=\"0.6\"/>\n  <path d=\"M 215 265 Q 220 245 210 230 Q 200 215 205 195\" fill=\"none\" stroke=\"#fb923c\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\" opacity=\"0.6\"/>\n\n  <!-- Label 4: Embers & Pre-Drying Bed -->\n  <g>\n    <path d=\"M 245 300 L 290 270\" stroke=\"#f97316\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n    <circle cx=\"245\" cy=\"300\" r=\"2.5\" fill=\"#f97316\"/>\n    <rect x=\"180\" y=\"258\" width=\"200\" height=\"15\" fill=\"#1c0f05\" rx=\"3\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <text x=\"280\" y=\"269\" fill=\"#fb923c\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">바닥 초벌 건조 잔가지 &amp; 숯불 밑천</text>\n  </g>\n\n  <!-- Bottom Core Insight Briefing Box (Label 5) -->\n  <rect x=\"20\" y=\"348\" width=\"360\" height=\"26\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"20\" y=\"348\" width=\"4\" height=\"26\" fill=\"#10b981\" rx=\"1\"/>\n  <text x=\"200\" y=\"364\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">[핵심] 흙 습기 완전 건조 및 고온 불씨 형성</text>\n</svg>\n","content/svgs/pr09-step-02.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Bark Gradient for Logs -->\n    <linearGradient id=\"oakBark\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#2d1d13\"/>\n      <stop offset=\"25%\" stop-color=\"#593b26\"/>\n      <stop offset=\"65%\" stop-color=\"#412918\"/>\n      <stop offset=\"100%\" stop-color=\"#1f130a\"/>\n    </linearGradient>\n\n    <!-- Log Top End Grain -->\n    <radialGradient id=\"oakEndGrain\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#e5c596\"/>\n      <stop offset=\"50%\" stop-color=\"#c99f67\"/>\n      <stop offset=\"85%\" stop-color=\"#936232\"/>\n      <stop offset=\"100%\" stop-color=\"#412918\"/>\n    </radialGradient>\n\n    <!-- Pit Wall Cutout -->\n    <linearGradient id=\"pitWall2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#140d07\"/>\n      <stop offset=\"50%\" stop-color=\"#22140a\"/>\n      <stop offset=\"100%\" stop-color=\"#140d07\"/>\n    </linearGradient>\n\n    <!-- Heat Radial from Bottom -->\n    <radialGradient id=\"heatBottom\" cx=\"50%\" cy=\"100%\" r=\"70%\">\n      <stop offset=\"0%\" stop-color=\"#ea580c\" stop-opacity=\"0.8\"/>\n      <stop offset=\"35%\" stop-color=\"#c2410c\" stop-opacity=\"0.4\"/>\n      <stop offset=\"70%\" stop-color=\"#7c2d12\" stop-opacity=\"0.15\"/>\n      <stop offset=\"100%\" stop-color=\"#07080a\" stop-opacity=\"0\"/>\n    </radialGradient>\n\n    <filter id=\"shadowS2\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"3\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS2)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#f97316\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 02 // DENSE VERTICAL TIMBER STACK</text>\n\n  <!-- Soil Cross Section & Pit Boundary -->\n  <path d=\"M 20 100 L 65 100 L 125 315 L 20 315 Z\" fill=\"#24150c\" opacity=\"0.6\"/>\n  <path d=\"M 380 100 L 335 100 L 275 315 L 380 315 Z\" fill=\"#24150c\" opacity=\"0.6\"/>\n  <path d=\"M 65 100 Q 200 115 335 100 L 275 315 Q 200 320 125 315 Z\" fill=\"url(#pitWall2)\" stroke=\"#452715\" stroke-width=\"1.2\"/>\n\n  <!-- Heat Glow from Bottom Embers -->\n  <path d=\"M 125 315 Q 200 320 275 315 L 260 250 Q 200 255 140 250 Z\" fill=\"url(#heatBottom)\"/>\n\n  <!-- ============================================== -->\n  <!-- VERTICAL LOGS (수직 적재 참나무 장작들) -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowS2)\">\n    <!-- Back Layer Logs -->\n    <!-- Log B1 -->\n    <g>\n      <rect x=\"110\" y=\"125\" width=\"22\" height=\"175\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"0.8\"/>\n      <ellipse cx=\"121\" cy=\"125\" rx=\"11\" ry=\"4\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.6\"/>\n    </g>\n    <!-- Log B2 -->\n    <g>\n      <rect x=\"155\" y=\"120\" width=\"26\" height=\"185\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"0.8\"/>\n      <ellipse cx=\"168\" cy=\"120\" rx=\"13\" ry=\"5\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.6\"/>\n    </g>\n    <!-- Log B3 -->\n    <g>\n      <rect x=\"215\" y=\"122\" width=\"25\" height=\"182\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"0.8\"/>\n      <ellipse cx=\"227\" cy=\"122\" rx=\"12.5\" ry=\"4.5\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.6\"/>\n    </g>\n    <!-- Log B4 -->\n    <g>\n      <rect x=\"268\" y=\"128\" width=\"22\" height=\"172\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"0.8\"/>\n      <ellipse cx=\"279\" cy=\"128\" rx=\"11\" ry=\"4\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.6\"/>\n    </g>\n\n    <!-- Front Layer Main Logs (Prominent Wrist-Thick Oak) -->\n    <!-- Front Log 1 -->\n    <g>\n      <rect x=\"80\" y=\"135\" width=\"28\" height=\"165\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"1\"/>\n      <ellipse cx=\"94\" cy=\"135\" rx=\"14\" ry=\"5\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.8\"/>\n      <!-- Bark Details -->\n      <line x1=\"88\" y1=\"160\" x2=\"88\" y2=\"240\" stroke=\"#1f1207\" stroke-width=\"1.2\"/>\n      <line x1=\"98\" y1=\"180\" x2=\"98\" y2=\"270\" stroke=\"#1f1207\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Front Log 2 -->\n    <g>\n      <rect x=\"128\" y=\"130\" width=\"30\" height=\"175\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"1\"/>\n      <ellipse cx=\"143\" cy=\"130\" rx=\"15\" ry=\"5.5\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.8\"/>\n      <line x1=\"136\" y1=\"150\" x2=\"136\" y2=\"230\" stroke=\"#1f1207\" stroke-width=\"1.2\"/>\n      <line x1=\"148\" y1=\"170\" x2=\"148\" y2=\"260\" stroke=\"#1f1207\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Front Log 3 (Center) -->\n    <g>\n      <rect x=\"182\" y=\"125\" width=\"32\" height=\"182\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"1\"/>\n      <ellipse cx=\"198\" cy=\"125\" rx=\"16\" ry=\"6\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.8\"/>\n      <ellipse cx=\"198\" cy=\"125\" rx=\"8\" ry=\"3\" fill=\"none\" stroke=\"#78350f\" stroke-width=\"0.6\"/>\n      <line x1=\"190\" y1=\"155\" x2=\"190\" y2=\"250\" stroke=\"#1f1207\" stroke-width=\"1.2\"/>\n      <line x1=\"202\" y1=\"175\" x2=\"202\" y2=\"265\" stroke=\"#1f1207\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Front Log 4 -->\n    <g>\n      <rect x=\"238\" y=\"132\" width=\"30\" height=\"173\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"1\"/>\n      <ellipse cx=\"253\" cy=\"132\" rx=\"15\" ry=\"5.5\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.8\"/>\n      <line x1=\"246\" y1=\"155\" x2=\"246\" y2=\"235\" stroke=\"#1f1207\" stroke-width=\"1.2\"/>\n      <line x1=\"258\" y1=\"175\" x2=\"258\" y2=\"265\" stroke=\"#1f1207\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Front Log 5 (Right edge) -->\n    <g>\n      <rect x=\"290\" y=\"138\" width=\"26\" height=\"162\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"1\"/>\n      <ellipse cx=\"303\" cy=\"138\" rx=\"13\" ry=\"5\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.8\"/>\n      <line x1=\"298\" y1=\"165\" x2=\"298\" y2=\"245\" stroke=\"#1f1207\" stroke-width=\"1.2\"/>\n    </g>\n\n    <!-- ============================================== -->\n    <!-- SLENDER PACKING WEDGES (틈새 메운 잔가지들) -->\n    <!-- ============================================== -->\n    <!-- Wedge 1 (between 1 and 2) -->\n    <line x1=\"119\" y1=\"140\" x2=\"121\" y2=\"280\" stroke=\"#a16207\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n    <ellipse cx=\"119\" cy=\"140\" rx=\"3\" ry=\"1.5\" fill=\"#fef08a\"/>\n\n    <!-- Wedge 2 (between 2 and 3) -->\n    <line x1=\"172\" y1=\"135\" x2=\"175\" y2=\"285\" stroke=\"#a16207\" stroke-width=\"7\" stroke-linecap=\"round\"/>\n    <ellipse cx=\"172\" cy=\"135\" rx=\"3.5\" ry=\"1.8\" fill=\"#fef08a\"/>\n\n    <!-- Wedge 3 (between 3 and 4) -->\n    <line x1=\"227\" y1=\"138\" x2=\"225\" y2=\"282\" stroke=\"#a16207\" stroke-width=\"6.5\" stroke-linecap=\"round\"/>\n    <ellipse cx=\"227\" cy=\"138\" rx=\"3.2\" ry=\"1.6\" fill=\"#fef08a\"/>\n\n    <!-- Wedge 4 (between 4 and 5) -->\n    <line x1=\"280\" y1=\"142\" x2=\"278\" y2=\"278\" stroke=\"#a16207\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n    <ellipse cx=\"280\" cy=\"142\" rx=\"3\" ry=\"1.5\" fill=\"#fef08a\"/>\n  </g>\n\n  <!-- Lower Embers (Igniting the Base of Logs) -->\n  <g>\n    <circle cx=\"150\" cy=\"308\" r=\"6\" fill=\"#dc2626\"/>\n    <circle cx=\"185\" cy=\"312\" r=\"7\" fill=\"#ea580c\"/>\n    <circle cx=\"215\" cy=\"310\" r=\"8\" fill=\"#f59e0b\"/>\n    <circle cx=\"245\" cy=\"309\" r=\"6\" fill=\"#dc2626\"/>\n    <path d=\"M 175 310 Q 185 295 195 308\" fill=\"#fef08a\" opacity=\"0.8\"/>\n    <path d=\"M 205 310 Q 215 292 225 308\" fill=\"#fef08a\" opacity=\"0.8\"/>\n  </g>\n\n  <!-- Callout Label 2: Wrist-Thick Oak Stacking -->\n  <g>\n    <line x1=\"94\" y1=\"135\" x2=\"60\" y2=\"75\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n    <circle cx=\"94\" cy=\"135\" r=\"2.5\" fill=\"#38bdf8\"/>\n    <rect x=\"20\" y=\"65\" width=\"220\" height=\"16\" fill=\"#0b1320\" rx=\"3\" stroke=\"#1e3a5f\" stroke-width=\"1\"/>\n    <text x=\"130\" y=\"77\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">손목 굵기(5~8cm) 참나무 수직 적재</text>\n  </g>\n\n  <!-- Callout Label 3: Packing Wedges in Gaps -->\n  <g>\n    <line x1=\"172\" y1=\"170\" x2=\"275\" y2=\"85\" stroke=\"#facc15\" stroke-width=\"1.2\"/>\n    <circle cx=\"172\" cy=\"170\" r=\"2.5\" fill=\"#facc15\"/>\n    <rect x=\"200\" y=\"75\" width=\"180\" height=\"16\" fill=\"#1c1608\" rx=\"3\" stroke=\"#854d0e\" stroke-width=\"1\"/>\n    <text x=\"290\" y=\"87\" fill=\"#fde047\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">빈틈을 쐐기처럼 메운 잔가지</text>\n  </g>\n\n  <!-- Callout Label 4: Bottom Ember Heat Spreading -->\n  <g>\n    <line x1=\"200\" y1=\"305\" x2=\"270\" y2=\"285\" stroke=\"#fb923c\" stroke-width=\"1.2\"/>\n    <circle cx=\"200\" cy=\"305\" r=\"2.5\" fill=\"#fb923c\"/>\n    <rect x=\"180\" y=\"275\" width=\"190\" height=\"16\" fill=\"#1c0f05\" rx=\"3\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <text x=\"275\" y=\"287\" fill=\"#fb923c\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">하단 초벌 불씨에서 번지는 열기</text>\n  </g>\n\n  <!-- Bottom Core Insight Briefing Box (Label 5) -->\n  <rect x=\"20\" y=\"348\" width=\"360\" height=\"26\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"20\" y=\"348\" width=\"4\" height=\"26\" fill=\"#10b981\" rx=\"1\"/>\n  <text x=\"200\" y=\"364\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">[핵심] 빈틈 최소화로 무산소 탄화 밀도 극대화</text>\n</svg>\n","content/svgs/pr09-step-03.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Clay & Mud Mound Gradient -->\n    <linearGradient id=\"mudSealGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#543823\"/>\n      <stop offset=\"40%\" stop-color=\"#3b2314\"/>\n      <stop offset=\"100%\" stop-color=\"#241409\"/>\n    </linearGradient>\n\n    <!-- Sod / Turf Grass Texture -->\n    <linearGradient id=\"sodGrassGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#2d4a22\"/>\n      <stop offset=\"50%\" stop-color=\"#3f6212\"/>\n      <stop offset=\"100%\" stop-color=\"#2d4a22\"/>\n    </linearGradient>\n\n    <!-- Early White Steam Smoke Radial -->\n    <radialGradient id=\"whiteSmoke\" cx=\"50%\" cy=\"80%\" r=\"70%\">\n      <stop offset=\"0%\" stop-color=\"#f1f5f9\" stop-opacity=\"0.85\"/>\n      <stop offset=\"50%\" stop-color=\"#cbd5e1\" stop-opacity=\"0.5\"/>\n      <stop offset=\"80%\" stop-color=\"#94a3b8\" stop-opacity=\"0.2\"/>\n      <stop offset=\"100%\" stop-color=\"#07080a\" stop-opacity=\"0\"/>\n    </radialGradient>\n\n    <filter id=\"shadowS3\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.85\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS3)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#f97316\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 03 // MULTI-LAYER ANAEROBIC SEAL</text>\n\n  <!-- Ground Line & Surrounding Earth -->\n  <path d=\"M 20 185 L 65 185 L 125 325 L 20 325 Z\" fill=\"#20130a\" opacity=\"0.6\"/>\n  <path d=\"M 380 185 L 335 185 L 275 325 L 380 325 Z\" fill=\"#20130a\" opacity=\"0.6\"/>\n\n  <!-- Pit Cavity & Smoldering Internal Wood Stack -->\n  <path d=\"M 65 185 L 125 325 Q 200 330 275 325 L 335 185 Z\" fill=\"#140a04\" stroke=\"#3d210f\" stroke-width=\"1.2\"/>\n  <!-- Internal Timber Silhouettes (Dim Smoldering) -->\n  <path d=\"M 135 320 L 130 190 L 160 190 L 165 320 Z\" fill=\"#2a1608\" opacity=\"0.7\"/>\n  <path d=\"M 175 322 L 175 190 L 205 190 L 205 322 Z\" fill=\"#381d0b\" opacity=\"0.8\"/>\n  <path d=\"M 220 322 L 225 190 L 255 190 L 250 322 Z\" fill=\"#2a1608\" opacity=\"0.7\"/>\n  <!-- Internal Ember Glow at bottom -->\n  <ellipse cx=\"200\" cy=\"320\" rx=\"60\" ry=\"8\" fill=\"#ea580c\" opacity=\"0.4\"/>\n\n  <!-- ============================================== -->\n  <!-- MULTI-LAYER SEAL SYSTEM (상부 덮개 구조) -->\n  <!-- ============================================== -->\n\n  <!-- Layer 1: Wood Lattice Frame (격자 나뭇가지틀) -->\n  <g stroke=\"#854d0e\" stroke-width=\"5\" stroke-linecap=\"round\">\n    <!-- Horizontal Crossbars -->\n    <line x1=\"75\" y1=\"188\" x2=\"325\" y2=\"188\"/>\n    <line x1=\"85\" y1=\"180\" x2=\"315\" y2=\"180\"/>\n    <!-- Angled Cross Beams -->\n    <line x1=\"110\" y1=\"193\" x2=\"160\" y2=\"175\"/>\n    <line x1=\"180\" y1=\"193\" x2=\"230\" y2=\"175\"/>\n    <line x1=\"250\" y1=\"193\" x2=\"300\" y2=\"175\"/>\n  </g>\n\n  <!-- Layer 2: Broad Leaves Layer (넓은 나뭇잎 차단층) -->\n  <g fill=\"#4d7c0f\" opacity=\"0.85\">\n    <ellipse cx=\"105\" cy=\"178\" rx=\"25\" ry=\"7\" transform=\"rotate(-5 105 178)\"/>\n    <ellipse cx=\"145\" cy=\"174\" rx=\"28\" ry=\"8\" transform=\"rotate(3 145 174)\"/>\n    <ellipse cx=\"195\" cy=\"172\" rx=\"30\" ry=\"8\"/>\n    <ellipse cx=\"245\" cy=\"174\" rx=\"28\" ry=\"8\" transform=\"rotate(-3 245 174)\"/>\n    <ellipse cx=\"285\" cy=\"178\" rx=\"25\" ry=\"7\" transform=\"rotate(5 285 178)\"/>\n  </g>\n\n  <!-- Layer 3: Thick Mud & Clay Mound with Turf Grass on Top -->\n  <g filter=\"url(#shadowS3)\">\n    <!-- Domed Mud Seal (10cm thick mound) -->\n    <path d=\"M 50 185 Q 200 120 350 185 Q 200 160 50 185 Z\" fill=\"url(#mudSealGrad)\" stroke=\"#452715\" stroke-width=\"1.5\"/>\n\n    <!-- Sod / Turf Grass Layer on the Dome Surface -->\n    <path d=\"M 55 184 Q 200 122 345 184 Q 200 135 55 184 Z\" fill=\"url(#sodGrassGrad)\" opacity=\"0.9\"/>\n    <!-- Grass Fringe along Dome -->\n    <path d=\"M 75 175 L 77 167 M 105 160 L 108 152 M 140 146 L 142 138 M 255 146 L 257 138 M 290 160 L 292 153 M 325 175 L 327 168\" stroke=\"#86efac\" stroke-width=\"1.5\" stroke-linecap=\"round\"/>\n  </g>\n\n  <!-- Center Chimney Vent (중앙 배기 굴뚝) -->\n  <g filter=\"url(#shadowS3)\">\n    <!-- Chimney Collar (진흙 굴뚝 테두리) -->\n    <path d=\"M 182 134 L 182 118 Q 200 115 218 118 L 218 134 Z\" fill=\"#3e2314\" stroke=\"#5c381e\" stroke-width=\"1.2\"/>\n    <ellipse cx=\"200\" cy=\"118\" rx=\"18\" ry=\"5\" fill=\"#140a04\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Billowing White Smoke from Chimney -->\n  <g>\n    <!-- Smoke Puffs -->\n    <circle cx=\"200\" cy=\"98\" r=\"14\" fill=\"url(#whiteSmoke)\"/>\n    <circle cx=\"212\" cy=\"78\" r=\"20\" fill=\"url(#whiteSmoke)\"/>\n    <circle cx=\"192\" cy=\"60\" r=\"26\" fill=\"url(#whiteSmoke)\"/>\n    <circle cx=\"218\" cy=\"42\" r=\"32\" fill=\"url(#whiteSmoke)\"/>\n  </g>\n\n  <!-- Air Intake Vents (하단 흡기 구멍 2개) -->\n  <!-- Left Intake -->\n  <g>\n    <ellipse cx=\"68\" cy=\"190\" rx=\"5\" ry=\"8\" fill=\"#090502\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <!-- Air Flow Arrow Inward -->\n    <path d=\"M 32 190 L 58 190\" stroke=\"#38bdf8\" stroke-width=\"1.8\" stroke-dasharray=\"3 2\"/>\n    <polygon points=\"63,190 56,187 56,193\" fill=\"#38bdf8\"/>\n  </g>\n  <!-- Right Intake -->\n  <g>\n    <ellipse cx=\"332\" cy=\"190\" rx=\"5\" ry=\"8\" fill=\"#090502\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <!-- Air Flow Arrow Inward -->\n    <path d=\"M 368 190 L 342 190\" stroke=\"#38bdf8\" stroke-width=\"1.8\" stroke-dasharray=\"3 2\"/>\n    <polygon points=\"337,190 344,187 344,193\" fill=\"#38bdf8\"/>\n  </g>\n\n  <!-- ============================================== -->\n  <!-- CALLOUT LABELS (2, 3, 4, 5) -->\n  <!-- ============================================== -->\n\n  <!-- Label 2: Lattice & Leaf Support Layer -->\n  <g>\n    <line x1=\"110\" y1=\"180\" x2=\"60\" y2=\"235\" stroke=\"#a3e635\" stroke-width=\"1.2\"/>\n    <circle cx=\"110\" cy=\"180\" r=\"2.5\" fill=\"#a3e635\"/>\n    <rect x=\"20\" y=\"235\" width=\"180\" height=\"16\" fill=\"#141f0d\" rx=\"3\" stroke=\"#4d7c0f\" stroke-width=\"1\"/>\n    <text x=\"110\" y=\"247\" fill=\"#bef264\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">격자 가지틀 + 넓은 잎 지지층</text>\n  </g>\n\n  <!-- Label 3: 10cm Mud & Turf Sod Seal -->\n  <g>\n    <line x1=\"280\" y1=\"150\" x2=\"310\" y2=\"95\" stroke=\"#facc15\" stroke-width=\"1.2\"/>\n    <circle cx=\"280\" cy=\"150\" r=\"2.5\" fill=\"#facc15\"/>\n    <rect x=\"180\" y=\"85\" width=\"200\" height=\"16\" fill=\"#1c1608\" rx=\"3\" stroke=\"#854d0e\" stroke-width=\"1\"/>\n    <text x=\"280\" y=\"97\" fill=\"#fde047\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">10cm 젖은 진흙 &amp; 잔디 뗏장 덮개</text>\n  </g>\n\n  <!-- Label 4: Two Intake Vents (Finger-thick) -->\n  <g>\n    <line x1=\"68\" y1=\"198\" x2=\"100\" y2=\"280\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n    <circle cx=\"68\" cy=\"198\" r=\"2.5\" fill=\"#38bdf8\"/>\n    <rect x=\"20\" y=\"280\" width=\"195\" height=\"16\" fill=\"#081524\" rx=\"3\" stroke=\"#0284c7\" stroke-width=\"1\"/>\n    <text x=\"117\" y=\"292\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">하단 흡기 구멍 2개 (손가락 굵기)</text>\n  </g>\n\n  <!-- Label 5: Center Chimney Vent -->\n  <g>\n    <line x1=\"218\" y1=\"125\" x2=\"270\" y2=\"235\" stroke=\"#fb923c\" stroke-width=\"1.2\"/>\n    <circle cx=\"218\" cy=\"125\" r=\"2.5\" fill=\"#fb923c\"/>\n    <rect x=\"210\" y=\"235\" width=\"170\" height=\"16\" fill=\"#1c0f05\" rx=\"3\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <text x=\"295\" y=\"247\" fill=\"#fb923c\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">중앙 배기 굴뚝 (주먹 크기)</text>\n  </g>\n\n  <!-- Bottom Core Insight Briefing Box (Label 6) -->\n  <rect x=\"20\" y=\"348\" width=\"360\" height=\"26\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"20\" y=\"348\" width=\"4\" height=\"26\" fill=\"#10b981\" rx=\"1\"/>\n  <text x=\"200\" y=\"364\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">[핵심] 산소 95% 차단 불완전 연소 가마 완성</text>\n</svg>\n","content/svgs/pr09-step-04.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Thick White Steam Smoke -->\n    <radialGradient id=\"denseWhiteSmoke\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#ffffff\" stop-opacity=\"0.95\"/>\n      <stop offset=\"50%\" stop-color=\"#e2e8f0\" stop-opacity=\"0.7\"/>\n      <stop offset=\"85%\" stop-color=\"#94a3b8\" stop-opacity=\"0.3\"/>\n      <stop offset=\"100%\" stop-color=\"#07080a\" stop-opacity=\"0\"/>\n    </radialGradient>\n\n    <!-- Faint Pure Blue Pyrolysis Smoke -->\n    <radialGradient id=\"faintBlueSmoke\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\" stop-opacity=\"0.8\"/>\n      <stop offset=\"40%\" stop-color=\"#0284c7\" stop-opacity=\"0.45\"/>\n      <stop offset=\"80%\" stop-color=\"#0369a1\" stop-opacity=\"0.15\"/>\n      <stop offset=\"100%\" stop-color=\"#07080a\" stop-opacity=\"0\"/>\n    </radialGradient>\n\n    <!-- Metallic Carbon Charcoal Gradient -->\n    <linearGradient id=\"charcoalLump\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#334155\"/>\n      <stop offset=\"25%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"60%\" stop-color=\"#0f172a\"/>\n      <stop offset=\"100%\" stop-color=\"#020617\"/>\n    </linearGradient>\n\n    <!-- Charcoal Silver Sheen -->\n    <linearGradient id=\"silverSheen\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#475569\"/>\n      <stop offset=\"50%\" stop-color=\"#94a3b8\"/>\n      <stop offset=\"100%\" stop-color=\"#334155\"/>\n    </linearGradient>\n\n    <filter id=\"shadowS4\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS4)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#f97316\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 04 // SMOKE PHASE &amp; CHARCOAL HARVEST</text>\n\n  <!-- ============================================== -->\n  <!-- TOP HALF: SMOKE PHASE COMPARISON PANEL -->\n  <!-- ============================================== -->\n  <!-- Left Side: Phase 1 Dense White Steam Smoke -->\n  <g>\n    <!-- Background Box -->\n    <rect x=\"20\" y=\"44\" width=\"175\" height=\"110\" fill=\"#0b1017\" rx=\"4\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n    <!-- Chimney Mini Silhouette -->\n    <path d=\"M 85 140 L 85 125 L 115 125 L 115 140 Z\" fill=\"#2d1d13\" stroke=\"#452715\" stroke-width=\"1\"/>\n    <ellipse cx=\"100\" cy=\"125\" rx=\"15\" ry=\"4\" fill=\"#140a04\"/>\n\n    <!-- Billowing Dense White Steam Clouds -->\n    <circle cx=\"100\" cy=\"105\" r=\"14\" fill=\"url(#denseWhiteSmoke)\"/>\n    <circle cx=\"85\" cy=\"85\" r=\"18\" fill=\"url(#denseWhiteSmoke)\"/>\n    <circle cx=\"115\" cy=\"80\" r=\"16\" fill=\"url(#denseWhiteSmoke)\"/>\n    <circle cx=\"95\" cy=\"62\" r=\"20\" fill=\"url(#denseWhiteSmoke)\"/>\n\n    <!-- Label 2: Phase 1 White Smoke -->\n    <rect x=\"24\" y=\"48\" width=\"167\" height=\"15\" fill=\"#030712\" rx=\"3\" stroke=\"#475569\" stroke-width=\"1\"/>\n    <text x=\"107\" y=\"59\" fill=\"#f8fafc\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" font-weight=\"bold\" text-anchor=\"middle\">1단계: 짙은 백색 연기 (수분 증발)</text>\n  </g>\n\n  <!-- Transition Arrow -->\n  <g>\n    <path d=\"M 198 95 L 206 95\" stroke=\"#f97316\" stroke-width=\"2\"/>\n    <polygon points=\"208,95 204,91 204,99\" fill=\"#f97316\"/>\n  </g>\n\n  <!-- Right Side: Phase 2 Faint Blue Pyrolysis Smoke -->\n  <g>\n    <!-- Background Box -->\n    <rect x=\"210\" y=\"44\" width=\"170\" height=\"110\" fill=\"#081422\" rx=\"4\" stroke=\"#0369a1\" stroke-width=\"1\"/>\n    <!-- Chimney Mini Silhouette -->\n    <path d=\"M 280 140 L 280 125 L 310 125 L 310 140 Z\" fill=\"#2d1d13\" stroke=\"#452715\" stroke-width=\"1\"/>\n    <ellipse cx=\"295\" cy=\"125\" rx=\"15\" ry=\"4\" fill=\"#140a04\"/>\n\n    <!-- Delicate Wisps of Blue Pyrolysis Smoke -->\n    <circle cx=\"295\" cy=\"108\" r=\"12\" fill=\"url(#faintBlueSmoke)\"/>\n    <circle cx=\"282\" cy=\"88\" r=\"15\" fill=\"url(#faintBlueSmoke)\"/>\n    <circle cx=\"308\" cy=\"85\" r=\"14\" fill=\"url(#faintBlueSmoke)\"/>\n    <circle cx=\"292\" cy=\"65\" r=\"16\" fill=\"url(#faintBlueSmoke)\"/>\n\n    <!-- Label 3: Phase 2 Blue Smoke -->\n    <rect x=\"214\" y=\"48\" width=\"162\" height=\"15\" fill=\"#021d33\" rx=\"3\" stroke=\"#0284c7\" stroke-width=\"1\"/>\n    <text x=\"295\" y=\"59\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" font-weight=\"bold\" text-anchor=\"middle\">2단계: 옅은 청색 연기 (탄화 완료)</text>\n  </g>\n\n  <!-- ============================================== -->\n  <!-- MIDDLE: HERMETIC MUD PLUG SEAL -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowS4)\">\n    <!-- Plugged Kiln Dome Mound -->\n    <path d=\"M 40 215 Q 200 170 360 215 L 330 255 Q 200 260 70 255 Z\" fill=\"#2d1a0e\" stroke=\"#452715\" stroke-width=\"1.2\"/>\n\n    <!-- Mud Plug Ball on Chimney (진흙 반죽으로 꽉 틀어막은 마개) -->\n    <circle cx=\"200\" cy=\"188\" r=\"16\" fill=\"#543823\" stroke=\"#854d0e\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"200\" cy=\"185\" rx=\"14\" ry=\"10\" fill=\"#3e2314\"/>\n    <!-- Sealed Air Intake Plugs -->\n    <ellipse cx=\"65\" cy=\"225\" rx=\"7\" ry=\"10\" fill=\"#543823\" stroke=\"#854d0e\" stroke-width=\"1\"/>\n    <ellipse cx=\"335\" cy=\"225\" rx=\"7\" ry=\"10\" fill=\"#543823\" stroke=\"#854d0e\" stroke-width=\"1\"/>\n\n    <!-- Lock Clamps / Cooling Ice Thermometer Icon Vector -->\n    <rect x=\"188\" y=\"178\" width=\"24\" height=\"20\" rx=\"3\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"1\" opacity=\"0.9\"/>\n    <!-- Padlock Shackle / 100% Hermetic Symbol -->\n    <path d=\"M 194 178 L 194 172 A 6 6 0 0 1 206 172 L 206 178\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n    <circle cx=\"200\" cy=\"187\" r=\"2\" fill=\"#38bdf8\"/>\n  </g>\n\n  <!-- Label 4: Hermetic Mud Seal & Cooling -->\n  <g>\n    <rect x=\"75\" y=\"215\" width=\"250\" height=\"16\" fill=\"#180e06\" rx=\"3\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <text x=\"200\" y=\"227\" fill=\"#fbbf24\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">모든 구멍 진흙 밀폐 후 완전 냉각</text>\n  </g>\n\n  <!-- ============================================== -->\n  <!-- BOTTOM: HARVESTED METALLIC HARDWOOD CHARCOAL -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowS4)\">\n    <!-- Charcoal Log Chunk 1 (Large Center) -->\n    <g>\n      <polygon points=\"120,305 155,275 220,280 235,310 180,335 130,330\" fill=\"url(#charcoalLump)\" stroke=\"#475569\" stroke-width=\"1\"/>\n      <!-- Carbonized Facets & Silver Sheen Reflections -->\n      <polygon points=\"155,275 220,280 200,305 145,298\" fill=\"url(#silverSheen)\" opacity=\"0.25\"/>\n      <line x1=\"165\" y1=\"285\" x2=\"195\" y2=\"320\" stroke=\"#020617\" stroke-width=\"1.5\"/>\n      <line x1=\"140\" y1=\"305\" x2=\"175\" y2=\"325\" stroke=\"#020617\" stroke-width=\"1.2\"/>\n      <!-- Metallic Ring Sound Wave Icon -->\n      <path d=\"M 235,285 A 8 8 0 0 1 245,295\" fill=\"none\" stroke=\"#e2e8f0\" stroke-width=\"1.2\"/>\n      <path d=\"M 240,280 A 14 14 0 0 1 254,298\" fill=\"none\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Charcoal Chunk 2 (Left) -->\n    <g>\n      <polygon points=\"65,315 95,295 130,305 120,335 80,340\" fill=\"url(#charcoalLump)\" stroke=\"#475569\" stroke-width=\"1\"/>\n      <polygon points=\"95,295 130,305 115,320 85,312\" fill=\"url(#silverSheen)\" opacity=\"0.3\"/>\n      <line x1=\"85\" y1=\"310\" x2=\"105\" y2=\"335\" stroke=\"#020617\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Charcoal Chunk 3 (Right) -->\n    <g>\n      <polygon points=\"230,310 265,290 305,302 295,335 250,338\" fill=\"url(#charcoalLump)\" stroke=\"#475569\" stroke-width=\"1\"/>\n      <polygon points=\"265,290 305,302 285,320 250,310\" fill=\"url(#silverSheen)\" opacity=\"0.3\"/>\n      <line x1=\"260\" y1=\"305\" x2=\"280\" y2=\"330\" stroke=\"#020617\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Porous Micro-pores Detail (다공성 미세기공 점들) -->\n    <circle cx=\"170\" cy=\"310\" r=\"1\" fill=\"#475569\"/>\n    <circle cx=\"185\" cy=\"305\" r=\"1.2\" fill=\"#475569\"/>\n    <circle cx=\"195\" cy=\"315\" r=\"1\" fill=\"#475569\"/>\n    <circle cx=\"105\" cy=\"320\" r=\"1\" fill=\"#475569\"/>\n    <circle cx=\"270\" cy=\"318\" r=\"1\" fill=\"#475569\"/>\n  </g>\n\n  <!-- Label 5: Harvested Metallic Dense Oak Charcoal -->\n  <g>\n    <rect x=\"75\" y=\"270\" width=\"250\" height=\"16\" fill=\"#090d16\" rx=\"3\" stroke=\"#334155\" stroke-width=\"1\"/>\n    <text x=\"200\" y=\"282\" fill=\"#e2e8f0\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">쇳소리 나는 고밀도 참나무 숯 수확</text>\n  </g>\n\n  <!-- Bottom Core Insight Briefing Box (Label 6) -->\n  <rect x=\"20\" y=\"348\" width=\"360\" height=\"26\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"20\" y=\"348\" width=\"4\" height=\"26\" fill=\"#10b981\" rx=\"1\"/>\n  <text x=\"200\" y=\"364\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">[핵심] 푸른 연기 즉시 밀폐 &amp; 잔열 완전 냉각</text>\n</svg>\n","content/svgs/step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg class=\"w-full max-w-[320px] h-auto\" viewBox=\"0 0 280 190\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Grid background lines -->\n  <line x1=\"20\" y1=\"20\" x2=\"260\" y2=\"20\" stroke=\"#222\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></line>\n  <line x1=\"20\" y1=\"95\" x2=\"260\" y2=\"95\" stroke=\"#222\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></line>\n  <line x1=\"20\" y1=\"170\" x2=\"260\" y2=\"170\" stroke=\"#222\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></line>\n  <line x1=\"140\" y1=\"10\" x2=\"140\" y2=\"180\" stroke=\"#222\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></line>\n\n  <!-- Bottle / Cylinder Cone Outer Contour -->\n  <path d=\"M70 25 L210 25 L180 145 L155 165 L125 165 L100 145 Z\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" fill=\"#161616\"></path>\n\n  <!-- Flow direction arrows on top (Raw water input) -->\n  <path d=\"M140 8 L140 22 M136 18 L140 22 L144 18\" stroke=\"#FFFFFF\" stroke-width=\"1.2\"></path>\n  <text x=\"148\" y=\"18\" fill=\"#AAAAAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\">흙탕물 붓기</text>\n\n  <!-- Layer 1: Pebbles (Top) -->\n  <path d=\"M74 38 L206 38 L197 62 L83 62 Z\" fill=\"#222222\" stroke=\"#444\" stroke-width=\"0.75\"></path>\n  <!-- Gravel particles -->\n  <circle cx=\"100\" cy=\"48\" r=\"4.5\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <circle cx=\"120\" cy=\"52\" r=\"5\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <circle cx=\"140\" cy=\"46\" r=\"4\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <circle cx=\"160\" cy=\"53\" r=\"5.5\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <circle cx=\"180\" cy=\"47\" r=\"4\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <!-- Text label -->\n  <line x1=\"196\" y1=\"50\" x2=\"202\" y2=\"50\" stroke=\"#777\" stroke-width=\"0.8\"></line>\n  <text x=\"275\" y=\"46\" fill=\"#EEEEEE\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\" text-anchor=\"end\">1. 자갈 (큰 먼지 걸러냄)</text>\n\n  <!-- Layer 2: Fine Sand -->\n  <path d=\"M83 62 L197 62 L189 95 L91 95 Z\" fill=\"#1b1b1b\" stroke=\"#444\" stroke-width=\"0.75\"></path>\n  <!-- Sand stippling lines -->\n  <line x1=\"100\" y1=\"72\" x2=\"180\" y2=\"72\" stroke=\"#666\" stroke-width=\"0.8\" stroke-dasharray=\"1 3\"></line>\n  <line x1=\"96\" y1=\"80\" x2=\"184\" y2=\"80\" stroke=\"#666\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"></line>\n  <line x1=\"102\" y1=\"88\" x2=\"178\" y2=\"88\" stroke=\"#666\" stroke-width=\"0.8\" stroke-dasharray=\"1 3\"></line>\n  <!-- Text label -->\n  <line x1=\"75\" y1=\"78\" x2=\"88\" y2=\"78\" stroke=\"#777\" stroke-width=\"0.8\"></line>\n  <text x=\"5\" y=\"74\" fill=\"#EEEEEE\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\">2. 고운 모래 (작은 먼지)</text>\n\n  <!-- Layer 3: Charcoal Powder -->\n  <path d=\"M91 95 L189 95 L180 132 L100 132 Z\" fill=\"#080808\" stroke=\"#555\" stroke-width=\"0.75\"></path>\n  <!-- Charcoal hatch pattern -->\n  <line x1=\"105\" y1=\"104\" x2=\"175\" y2=\"104\" stroke=\"#444\" stroke-width=\"1.2\"></line>\n  <line x1=\"108\" y1=\"113\" x2=\"172\" y2=\"113\" stroke=\"#444\" stroke-width=\"1.2\"></line>\n  <line x1=\"112\" y1=\"122\" x2=\"168\" y2=\"122\" stroke=\"#444\" stroke-width=\"1.2\"></line>\n  <rect x=\"128\" y=\"102\" width=\"24\" height=\"20\" stroke=\"#FFF\" stroke-width=\"0.8\" fill=\"none\"></rect>\n  <text x=\"131\" y=\"115\" fill=\"#FFF\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\" font-weight=\"bold\">숯가루</text>\n  <!-- Text label -->\n  <line x1=\"185\" y1=\"115\" x2=\"195\" y2=\"115\" stroke=\"#777\" stroke-width=\"0.8\"></line>\n  <text x=\"275\" y=\"111\" fill=\"#EEEEEE\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\" text-anchor=\"end\">3. 숯가루 (독소·냄새 제거)</text>\n\n  <!-- Layer 4: Cloth Mesh Base -->\n  <path d=\"M100 132 L180 132 L165 152 L115 152 Z\" fill=\"#2d2d2d\" stroke=\"#666\" stroke-width=\"0.75\"></path>\n  <path d=\"M110 142 L170 142\" stroke=\"#FFF\" stroke-width=\"1\" stroke-dasharray=\"2 1\"></path>\n  <!-- Text label -->\n  <line x1=\"108\" y1=\"145\" x2=\"35\" y2=\"145\" stroke=\"#777\" stroke-width=\"0.8\"></line>\n  <text x=\"5\" y=\"148\" fill=\"#EEEEEE\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\">4. 천·이끼 마개 (입구 막기)</text>\n\n  <!-- Dripping water drops (Clear water output) -->\n  <line x1=\"140\" y1=\"165\" x2=\"140\" y2=\"178\" stroke=\"#FFFFFF\" stroke-width=\"1.2\" stroke-dasharray=\"2 2\"></line>\n  <circle cx=\"140\" cy=\"183\" r=\"2.5\" fill=\"#FFFFFF\"></circle>\n</svg>","content/svgs/step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg class=\"w-full max-w-[320px] h-auto\" viewBox=\"0 0 280 150\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Vessel receiving unfiltered and discarding 1st flush -->\n  <!-- Bucket 1 (Discard - Turbid) -->\n  <rect x=\"35\" y=\"65\" width=\"70\" height=\"60\" stroke=\"#666\" stroke-width=\"1.2\" fill=\"#141414\"></rect>\n  <line x1=\"35\" y1=\"95\" x2=\"105\" y2=\"95\" stroke=\"#444\" stroke-width=\"1\"></line>\n  <path d=\"M40 100 Q70 105 100 100\" stroke=\"#777\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></path>\n  <text x=\"42\" y=\"85\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\">[첫 1~2컵 버리기]</text>\n  <text x=\"44\" y=\"115\" fill=\"#777\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\">검은 숯가루 섞인 물</text>\n  <line x1=\"70\" y1=\"40\" x2=\"70\" y2=\"60\" stroke=\"#E02424\" stroke-width=\"1.2\" stroke-dasharray=\"2 2\"></line>\n  <path d=\"M68 55 L70 60 L72 55\" stroke=\"#E02424\" stroke-width=\"1.2\"></path>\n\n  <!-- Flow divider symbol -->\n  <text x=\"125\" y=\"85\" fill=\"#FFF\" font-family=\"'JetBrains Mono', monospace\" font-size=\"12\">→</text>\n\n  <!-- Bucket 2 (Keep - Clean Pre-filtered) -->\n  <rect x=\"165\" y=\"65\" width=\"75\" height=\"60\" stroke=\"#FFF\" stroke-width=\"1.5\" fill=\"#181818\"></rect>\n  <line x1=\"165\" y1=\"90\" x2=\"240\" y2=\"90\" stroke=\"#888\" stroke-width=\"1\"></line>\n  <!-- Water level indicator -->\n  <line x1=\"170\" y1=\"105\" x2=\"235\" y2=\"105\" stroke=\"#FFF\" stroke-width=\"0.75\" stroke-dasharray=\"3 2\"></line>\n  <line x1=\"170\" y1=\"115\" x2=\"235\" y2=\"115\" stroke=\"#FFF\" stroke-width=\"0.75\" stroke-dasharray=\"3 2\"></line>\n  <text x=\"175\" y=\"82\" fill=\"#FFFFFF\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\">[맑은 물 받아 쓰기]</text>\n  <text x=\"175\" y=\"135\" fill=\"#999\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\">투명해진 깨끗한 물</text>\n  <line x1=\"202\" y1=\"40\" x2=\"202\" y2=\"60\" stroke=\"#FFFFFF\" stroke-width=\"1.2\"></line>\n  <path d=\"M200 55 L202 60 L204 55\" stroke=\"#FFFFFF\" stroke-width=\"1.2\"></path>\n\n  <!-- Drip speed gauge -->\n  <text x=\"15\" y=\"25\" fill=\"#AAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" text-anchor=\"start\">떨어지는 속도: 1초에 1~2방울</text>\n  <circle cx=\"202\" cy=\"22\" r=\"3\" fill=\"#FFF\"></circle>\n</svg>","content/svgs/step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg class=\"w-full max-w-[320px] h-auto\" viewBox=\"0 0 280 155\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Boiling Pot Diagram -->\n  <rect x=\"30\" y=\"45\" width=\"80\" height=\"60\" stroke=\"#FFF\" stroke-width=\"1.5\" fill=\"#181818\"></rect>\n  <line x1=\"20\" y1=\"55\" x2=\"30\" y2=\"55\" stroke=\"#FFF\" stroke-width=\"1.5\"></line>\n  <line x1=\"110\" y1=\"55\" x2=\"120\" y2=\"55\" stroke=\"#FFF\" stroke-width=\"1.5\"></line>\n  <!-- Rolling boil violent bubbles -->\n  <circle cx=\"50\" cy=\"75\" r=\"4\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <circle cx=\"70\" cy=\"65\" r=\"5\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <circle cx=\"90\" cy=\"72\" r=\"3.5\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <circle cx=\"60\" cy=\"85\" r=\"3\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <circle cx=\"80\" cy=\"88\" r=\"4.5\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <!-- Steam waves -->\n  <path d=\"M50 35 Q55 25 50 15\" stroke=\"#888\" stroke-width=\"1\"></path>\n  <path d=\"M70 35 Q75 25 70 15\" stroke=\"#888\" stroke-width=\"1\"></path>\n  <path d=\"M90 35 Q95 25 90 15\" stroke=\"#888\" stroke-width=\"1\"></path>\n  <!-- Campfire underneath -->\n  <path d=\"M40 115 L70 106 L100 115\" stroke=\"#E02424\" stroke-width=\"1.5\"></path>\n  <path d=\"M55 125 L70 110 L85 125\" stroke=\"#E02424\" stroke-width=\"1.5\"></path>\n  <text x=\"70\" y=\"137\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" text-anchor=\"middle\">100°C 불에 끓이기</text>\n\n  <!-- Threshold timer graph on right -->\n  <line x1=\"145\" y1=\"120\" x2=\"255\" y2=\"120\" stroke=\"#555\" stroke-width=\"1\"></line>\n  <line x1=\"145\" y1=\"25\" x2=\"145\" y2=\"120\" stroke=\"#555\" stroke-width=\"1\"></line>\n  \n  <!-- Curve -->\n  <path d=\"M145 110 Q175 95 190 40 L250 40\" stroke=\"#FFFFFF\" stroke-width=\"1.5\" fill=\"none\"></path>\n  <line x1=\"190\" y1=\"20\" x2=\"190\" y2=\"120\" stroke=\"#E02424\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"></line>\n  \n  <text x=\"148\" y=\"35\" fill=\"#AAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\">100°C</text>\n  <text x=\"192\" y=\"32\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" font-weight=\"bold\">3분 이상 끓이기</text>\n  <text x=\"255\" y=\"65\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" text-anchor=\"end\">세균 99.9% 제거</text>\n  \n  <text x=\"200\" y=\"133\" fill=\"#888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\" text-anchor=\"middle\">팔팔 끓이는 시간 (분)</text>\n</svg>","NEXT_TOPIC_PROMPT.md":"# 📌 차기 생존 프로토콜 기획서: PR-10 - 소나무 송진을 녹여 굳히는 상처 소독 연고 및 만능 방수 접착제 (원시 송진 정제법)\n\n- **도메인**: 야전 의약 & 천연 화학 위생 공학 > 테르펜 항균 정제 및 천연 방수 수지 결속 (Tier 1)\n- **위급도**: HIGH\n- **결핍 상황**: 야생에서 나뭇가지나 돌날에 손을 베였을 때 소독하지 못하면 세균 감염으로 곪거나 패혈증에 걸려 목숨을 잃습니다. 또한 돌도끼 자루나 뼈 바늘, 토기 틈새를 단단하고 물이 새지 않게 메워줄 천연 접착제가 절실합니다. 소나무가 상처를 보호하기 위해 내뿜는 송진을 정제하면, 야생의 천연 항생제 연고이자 돌처럼 단단하게 굳는 만능 방수 수지가 됩니다.\n- **과학 원리**: 소나무 수지(Resin)의 피넨(Pinene) 등 테르펜 성분은 강력한 항균·항진균 작용을 하여 세균 증식을 원천 차단합니다. 송진을 얕은 열로 녹여 불순물을 거르고 숯가루(미세 탄소)를 1:1로 섞어 반죽하면, 식으면서 수축 없이 돌처럼 단단해지는 방수 천연 수지 에폭시(Pitch Glue)가 완성됩니다.\n- **투입 자연물**:\n  - 소나무 상처 부위에서 긁어모은 굳은 생송진 덩어리 (주먹 크기)\n  - 잎사귀를 깐 나뭇가지 거름망\n  - 송진을 녹여 담을 오목한 돌 접시 또는 조개껍데기\n  - 미세하게 빻은 참나무 숯가루 (경화제 역할)\n  - 뭉근하게 달군 숯불 열기 (직화 금지)\n\n---\n\n## 🖼️ [필수 사전 프리뷰] 16:9 초고화질 완성 결과물 도면 (Target Outcome)\n- **도면 파일명**: `pr10-outcome.svg` (16:9 와이드스크린, 800×450)\n- **도면 내용**: 오목한 돌 솥에서 정제되어 굳어가는 황금빛 송진 연고와 숯가루를 배합해 만든 검은색 방수 수지 막대(Pitch Stick)의 완성 전경. 송진의 테르펜 항균 분자 보호막 원리 및 돌도끼 자루 결속 방수 단면도를 모노라인/3D 입체 셰이딩으로 표현.\n\n---\n\n## 📋 4단계 도면 및 실행 지침\n\n### [Step 01] 노송(소나무) 상처 부위에서 마른 호박색 생송진 덩어리 긁어모으기\n- **실행**: 소나무 줄기나 부러진 가지 주변에 끈적하게 굳어있는 호박색(Amber) 송진 덩어리를 뾰족한 돌칼이나 나뭇가지로 조심스럽게 긁어모읍니다. 나무껍질이 너무 많이 섞이지 않은 투명하고 딱딱한 덩어리를 골라 주먹 1개 분량을 채취합니다.\n- **도면 파일명**: `pr10-step-01.svg`\n- **도면 초점**: 소나무 수피에 응고된 눈물방울 모양 호박색 생송진 덩어리 채취 투시도\n\n### [Step 02] 오목한 돌판에 담아 간접 숯불 열기로 은근하게 녹이기 (직화 금지)\n- **실행**: 오목한 조개껍데기나 넓적한 돌판 위에 송진 덩어리를 얹고, 빨갛게 피어난 숯불 옆에 살포시 올려놓습니다. 송진은 기름 성분이라 직접 화염(직화)이 닿으면 순식간에 불이 붙어 타버리므로, 은근한 숯불 열기로만 맑은 액체 상태가 될 때까지 천천히 녹여줍니다.\n- **도면 파일명**: `pr10-step-02.svg`\n- **도면 초점**: 오목한 돌판 위의 맑은 액상 송진 용융 과정 및 직화 방지 간접 숯불 열기선\n\n### [Step 03] 잔가지 빗으로 나무껍질 불순물을 걸러내고 순수 항균 연고 분리하기\n- **실행**: 완전히 녹아 물처럼 된 송진 속의 굵은 나무껍질과 흙을 잔가지로 빗질하듯 건져내 맑은 액체만 남깁니다. 이 중 1/3을 얇은 조개껍데기에 따로 덜어내어 식히면 상처에 얇게 바를 수 있는 천연 항균 보호 연고가 완성됩니다.\n- **도면 파일명**: `pr10-step-03.svg`\n- **도면 초점**: 잔가지 거름망으로 불순물을 건져내고 맑은 항균 송진액을 덜어내는 정제 공정\n\n### [Step 04] 미세 숯가루를 1:1로 섞어 돌처럼 굳는 방수 결속 막대(Pitch Stick) 만들기\n- **실행**: 돌판에 남은 뜨거운 액상 송진에 미세하게 빻은 참나무 숯가루를 1:1 비율로 조금씩 넣으며 나뭇가지로 빠르게 저어 반죽합니다. 반죽이 엿처럼 끈적해지면 나뭇가지 끝에 둥글게 뭉쳐 사탕처럼 감아올립니다. 상온에서 식으면 돌처럼 단단해지며, 필요할 때마다 불씨로 끝을 살짝 녹여 돌도끼 틈새나 방수 봉합에 바릅니다.\n- **도면 파일명**: `pr10-step-04.svg`\n- **도면 초점**: 숯가루 배합 교반 과정 및 나뭇가지 끝에 굳힌 검은색 방수 결속 수지 막대(Pitch Stick)\n\n---\n\n## ⚠️ 꼭 피해야 할 실수 (Fatal Mistake)\n- **흔한 실수**: 송진을 빨리 녹이려고 모닥불 화염 위에 직접 올려놓는 실수\n- **위험한 결과**: 송진에 함유된 고인화성 테르펜 증기에 불이 붙어 폭발적으로 타오르며 송진 전체가 전소되고 심한 화상을 입음\n- **핵심 주의사항**: 절대 불꽃(화염)이 직접 닿지 않게 하고 오직 숯불의 잔열과 원적외선으로만 은근하게 녹여야 함\n\n---\n\n## 🎨 도면 및 이미지 생성용 마스터 프롬프트\n\n### A. 스티치(Stitch) 벡터 도면용 프롬프트 (publish-protocol)\n```text\nA precise field blueprint drawn with charcoal and graphite on dark slate, illustrating Pine Resin Extraction & Pitch Glue Processing.\n- Target Outcome (16:9 Widescreen): Cross-section of concave stone melting dish with clarified amber pine resin, charred oak powder admixture, finished solid pitch glue stick, and arrow/axe lashing seal detail.\n- Step 1: Amber crystalline pine resin nodules collected from scored pine bark.\n- Step 2: Indirect gentle ember heating of resin in a concave stone dish (flame-free).\n- Step 3: Skimming tree bark impurities with twig comb to isolate antiseptic amber ointment.\n- Step 4: 1:1 blending with pulverized charcoal powder to form a rock-hard waterproof pitch stick.\nUtilitarian Brutalism style, pure monochrome technical linework, zero text collision, strict physics accuracy.\n```\n\n### B. 제미나이 3D 포토리얼리스틱 실물 이미지용 프롬프트 (publish-protocol-image)\n```text\nCinematic tactical survival field photograph of pine resin purification and natural epoxy making.\n- Target Outcome (16:9 Widescreen): Macro view of a smooth concave river slate resting beside red-hot charcoal embers, holding bubbling golden translucent melted pine resin. A wooden stick wrapped with hardened glossy black pitch glue resting on dark soil in the foreground, showing extreme texture detail. Studio side-lighting, 8k, authentic textures, NO modern objects, NO text.\n- Step 01: Macro shot of amber teardrop resin lumps resting on natural textured pine tree bark.\n- Step 02: Amber resin melting into translucent syrup inside a shallow concave stone warmed by ember glow.\n- Step 03: Twig skimming dark bark debris from radiant golden liquid resin.\n- Step 04: Finished black carbon pitch glue stick hardened like obsidian around a wooden handle.\n```\n"};

export function ensureContentAvailable() {
  const defaultProtocolsDir = path.join(projectRoot, 'content/protocols');
  const defaultLocalesDir = path.join(projectRoot, 'content/protocols/locales');
  if (
    fs.existsSync(defaultProtocolsDir) &&
    fs.readdirSync(defaultProtocolsDir).some((f) => f.endsWith('.json')) &&
    fs.existsSync(defaultLocalesDir) &&
    fs.readdirSync(defaultLocalesDir).some((f) => f.endsWith('.es.json'))
  ) {
    return projectRoot;
  }

  const fallbackRoot = path.join(os.tmpdir(), 'survival-bundled-root');
  for (const [relPath, content] of Object.entries(EMBEDDED_CONTENT)) {
    const targetPath = path.join(fallbackRoot, relPath);
    fs.mkdirSync(path.dirname(targetPath), { recursive: true });
    fs.writeFileSync(targetPath, content, 'utf-8');
  }
  process.env.SURVIVAL_ROOT_DIR = fallbackRoot;
  return fallbackRoot;
}
